INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('14', '2taw', '2 Tawarikh', 3, 16, 'Lalu dibuatnya untaian rantai yang dipasangnya sebagai kalung di atas kepala tiang-tiang itu, dan dibuatnya seratus buah delima yang dipasangnya pada untaian rantai itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 17, 'Tiang-tiang itu didirikannya di depan Bait Suci, yang satu di sebelah kanan dan yang lain di sebelah kiri; tiang kanan dinamainya Yakhin, dan tiang kiri Boas.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 1, 'Lalu ia membuat mezbah tembaga yang dua puluh hasta panjangnya, dan dua puluh hasta lebarnya dan sepuluh hasta tingginya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 2, 'Kemudian dibuatnyalah "laut" tuangan yang sepuluh hasta dari tepi ke tepi, bundar keliling, lima hasta tingginya, dan yang dapat dililit berkeliling oleh tali yang tiga puluh hasta panjangnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 3, 'Di sebelah bawah tepinya ada gambar lembu-lembu yang mengelilinginya sama sekali, sepuluh dalam sehasta, merangkum "laut" itu berkeliling; lembu itu dua jajar, dituang setuangan dengan bejana itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 4, '"Laut" itu menumpang di atas dua belas lembu, tiga menghadap ke utara dan tiga menghadap ke barat, tiga menghadap ke selatan dan tiga menghadap ke timur; "laut" itu menumpang di atasnya, sedang segala buntut lembu itu menuju ke dalam.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 5, 'Tebal "laut" itu setapak tangan dan tepinya serupa tepi piala, seperti bunga bakung yang berkembang. "Laut" itu dapat memuat tiga ribu bat air.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 6, 'Lagipula dibuatnya sepuluh bejana pembasuhan dan ditaruhnya lima pada sisi kanan dan lima pada sisi kiri sebagai tempat pembasuhan; di situ orang membasuh apa yang diperlukan untuk korban bakaran, sedang "laut" itu adalah untuk para imam sebagai tempat membasuh.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 7, 'Ia membuat sepuluh kandil emas sesuai dengan rancangannya dan menaruhnya di dalam Bait Suci, lima di sebelah kanan dan lima di sebelah kiri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 8, 'Selanjutnya ia membuat sepuluh meja dan menempatkannya di dalam Bait Suci, lima di sebelah kanan dan lima di sebelah kiri; ia membuat pula seratus bokor penyiraman dari emas.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 9, 'Ia membuat juga pelataran para imam, halaman besar dan pintu-pintu halaman itu; pintu-pintu itu dilapisinya dengan tembaga.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 10, '"Laut" itu ditaruhnya pada sisi kanan, arah tenggara.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 11, 'Dan Huram membuat juga kuali-kuali, penyodok-penyodok dan bokor-bokor penyiraman. Demikianlah Huram menyelesaikan pekerjaan yang harus dilakukannya bagi raja Salomo di rumah Allah,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 12, 'yakni kedua tiang, dengan kedua bulatan ganja di kepala tiang itu, kedua jala-jala yang menutup kedua bulatan ganja itu;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 13, 'keempat ratus buah delima untuk kedua jala-jala itu, dua jajar buah delima untuk satu jala-jala guna menutupi kedua bulatan ganja yang di atas tiang itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 14, 'Juga telah dibuatnya kereta-kereta penopang dan bejana-bejana pembasuhan yang di atas kereta-kereta itu;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 15, '"laut" yang satu itu dan kedua belas lembu di bawahnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 16, 'Kuali-kuali, penyodok-penyodok, garpu-garpu dan segala perlengkapan lain yang dibuat Huram-Abi bagi raja Salomo untuk rumah TUHAN adalah dari tembaga upaman.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 17, 'Raja menuang semuanya itu di Lembah Yordan di dalam tanah liat antara Sukot dan Zereda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 18, 'Salomo membuat segala perlengkapan itu dalam jumlah yang amat besar, sehingga berat tembaga itu tidaklah terhitung.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 19, 'Salomo membuat juga segala perlengkapan yang ada di rumah Allah, yakni mezbah dan meja-meja tempat menaruh roti sajian,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 20, 'lagipula kandil-kandil dari emas murni dengan pelita-pelitanya, untuk dinyalakan di depan ruang belakang sesuai dengan peraturan;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 21, 'kembang-kembangnya, pelita-pelitanya dan sepit-sepitnya, dari emas, semuanya dari emas murni;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 4, 22, 'pisau-pisaunya, bokor-bokor penyiramannya, cawan-cawannya dan perbaraan-perbaraannya, dari emas murni; juga pintu masuk rumah itu, dan pintu-pintu yang di sebelah dalam ke tempat maha kudus, dan pintu-pintu ke ruang besar Bait Suci, semuanya dari emas.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 1, 'Maka selesailah segala pekerjaan yang dilakukan Salomo untuk rumah TUHAN itu. Kemudian Salomo memasukkan barang-barang kudus Daud, ayahnya, dan menaruh perak, emas dan barang-barang itu dalam perbendaharaan rumah Allah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 2, 'Pada waktu itu Salomo menyuruh para tua-tua Israel dan semua kepala suku, para pemimpin puak orang Israel, berkumpul di Yerusalem, untuk mengangkut tabut perjanjian TUHAN dari kota Daud, yaitu Sion.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 3, 'Maka pada hari raya di bulan ketujuh berkumpullah di hadapan raja semua orang Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 4, 'Setelah semua tua-tua orang Israel datang, maka orang-orang Lewi mengangkat tabut itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 5, 'Mereka mengangkut tabut itu dan Kemah Pertemuan dan segala barang kudus yang ada dalam kemah itu; semuanya itu diangkut oleh imam-imam dan orang-orang Lewi.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 6, 'Tetapi raja Salomo dan segenap umat Israel yang sudah berkumpul di hadapannya, berdiri di depan tabut itu, dan mempersembahkan kambing domba dan lembu sapi yang tidak terhitung dan tidak terbilang banyaknya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 7, 'Kemudian imam-imam membawa tabut perjanjian TUHAN itu ke tempatnya, di ruang belakang rumah itu, di tempat maha kudus, tepat di bawah sayap kerub-kerub;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 8, 'jadi kerub-kerub itu mengembangkan kedua sayapnya di atas tempat tabut itu, sehingga kerub-kerub itu menudungi tabut serta kayu-kayu pengusungnya dari atas.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 9, 'Kayu-kayu pengusung itu demikian panjangnya, sehingga ujungnya kelihatan dari tempat kudus, yang di depan ruang belakang itu, tetapi tidak kelihatan dari luar; dan di situlah tempatnya sampai hari ini.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 10, 'Dalam tabut itu tidak ada apa-apa selain dari kedua loh yang ditaruh Musa ke dalamnya di gunung Horeb, ketika TUHAN mengikat perjanjian dengan orang Israel pada waktu perjalanan mereka keluar dari Mesir.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 11, 'Lalu para imam keluar dari tempat kudus. Para imam yang ada pada waktu itu semuanya telah menguduskan diri, lepas dari giliran rombongan masing-masing.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 12, 'Demikian pula para penyanyi orang Lewi semuanya hadir, yakni Asaf, Heman, Yedutun, beserta anak-anak dan saudara-saudaranya. Mereka berdiri di sebelah timur mezbah, berpakaian lenan halus dan dengan ceracap, gambus dan kecapinya, bersama-sama seratus dua puluh imam peniup nafiri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 13, 'Lalu para peniup nafiri dan para penyanyi itu serentak memperdengarkan paduan suaranya untuk menyanyikan puji-pujian dan syukur kepada TUHAN. Mereka menyaringkan suara dengan nafiri, ceracap dan alat-alat musik sambil memuji TUHAN dengan ucapan: "Sebab Ia baik! Bahwasanya untuk selama-lamanya kasih setia-Nya." Pada ketika itu rumah itu, yakni rumah TUHAN, dipenuhi awan,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 5, 14, 'sehingga imam-imam itu tidak tahan berdiri untuk menyelenggarakan kebaktian oleh karena awan itu, sebab kemuliaan TUHAN memenuhi rumah Allah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 1, 'Pada waktu itu berkatalah Salomo: "TUHAN telah memutuskan untuk diam dalam kekelaman.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 2, 'Sekarang, aku telah mendirikan rumah kediaman bagi-Mu, tempat Engkau menetap selama-lamanya."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 3, 'Kemudian berpalinglah raja lalu memberkati seluruh jemaah Israel, sedang segenap jemaah Israel berdiri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 4, 'Ia berkata: "Terpujilah TUHAN, Allah orang Israel, yang telah menyelesaikan dengan tangan-Nya apa yang difirmankan-Nya dengan mulut-Nya kepada Daud, ayahku, demikian:', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 5, 'Sejak Aku membawa umat-Ku keluar dari tanah Mesir, tidak ada kota yang Kupilih di antara segala suku Israel untuk mendirikan rumah di sana sebagai tempat kediaman nama-Ku, dan tidak ada orang yang Kupilih untuk menjadi raja atas umat-Ku Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 6, 'Tetapi kemudian Aku memilih Yerusalem sebagai tempat kediaman nama-Ku dan memilih Daud untuk berkuasa atas umat-Ku Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 7, 'Ketika Daud, ayahku, bermaksud mendirikan rumah untuk nama TUHAN, Allah Israel,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 8, 'berfirmanlah TUHAN kepadanya: Engkau bermaksud mendirikan rumah untuk nama-Ku, dan maksudmu itu memanglah baik;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 9, 'hanya, bukanlah engkau yang akan mendirikan rumah itu, melainkan anak kandungmu yang akan lahir kelak, dialah yang akan mendirikan rumah itu untuk nama-Ku.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 10, 'Jadi TUHAN telah menepati janji yang telah diucapkan-Nya; aku telah bangkit menggantikan Daud, ayahku, dan telah duduk di atas takhta kerajaan Israel, seperti yang difirmankan TUHAN; aku telah mendirikan rumah ini untuk nama TUHAN, Allah Israel,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 11, 'dan telah menempatkan di sana tabut, yang memuat perjanjian yang telah diikat TUHAN dengan orang Israel."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 12, 'Kemudian berdirilah ia di depan mezbah TUHAN di hadapan segenap jemaah Israel, lalu menadahkan tangannya;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 13, '?karena Salomo telah membuat sebuah mimbar tembaga yang panjangnya lima hasta, lebarnya lima hasta dan tingginya tiga hasta, yang ditaruhnya di halaman?;ia berdiri di atasnya lalu berlutut di hadapan segenap jemaah Israel dan menadahkan tangannya ke langit,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 14, 'sambil berkata: "Ya TUHAN, Allah Israel! Tidak ada Allah seperti Engkau di langit dan di bumi; Engkau yang memelihara perjanjian dan kasih setia kepada hamba-hamba-Mu yang dengan segenap hatinya hidup di hadapan-Mu;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 15, 'Engkau yang tetap berpegang pada janji-Mu terhadap hamba-Mu Daud, ayahku, dan yang telah menggenapi dengan tangan-Mu apa yang Kaufirmankan dengan mulut-Mu, seperti yang terjadi pada hari ini.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 16, 'Maka sekarang, ya TUHAN, Allah Israel, peliharalah apa yang Kaujanjikan kepada hamba-Mu Daud, ayahku, dengan berkata: Keturunanmu takkan terputus di hadapan-Ku dan tetap akan duduk di atas takhta kerajaan Israel, asal anak-anakmu tetap hidup menurut hukum-Ku sama seperti engkau hidup di hadapan-Ku.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 17, 'Maka sekarang, ya TUHAN, Allah Israel, biarlah terbukti kebenaran firman-Mu yang telah Kauucapkan kepada hamba-Mu Daud.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 18, 'Tetapi benarkah Allah hendak diam bersama dengan manusia di atas bumi? Sesungguhnya langit, bahkan langit yang mengatasi segala langitpun tidaklah dapat memuat Engkau, terlebih lagi rumah yang kudirikan ini.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 19, 'Maka berpalinglah kepada doa dan permohonan hamba-Mu ini, ya TUHAN Allahku, dengarkanlah seruan dan doa yang hamba-Mu panjatkan di hadapan-Mu ini!', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 20, 'Kiranya mata-Mu terbuka terhadap rumah ini, siang dan malam, terhadap tempat yang Kaukatakan akan menjadi kediaman nama-Mu?dengarkanlah doa yang hamba-Mu panjatkan di tempat ini.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 21, 'Dan dengarkanlah permohonan hamba-Mu dan umat-Mu Israel yang mereka panjatkan di tempat ini; bahwa Engkau juga yang mendengarnya dari tempat kediaman-Mu, dari sorga; dan apabila Engkau mendengarnya, maka Engkau akan mengampuni.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 22, 'Jika seseorang telah berdosa kepada temannya, lalu diwajibkan mengangkat sumpah dengan mengutuk dirinya, dan ia datang bersumpah ke depan mezbah-Mu di dalam rumah ini,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 23, 'maka Engkaupun hendaklah mendengar dari sorga dan bertindak serta mengadili hamba-hamba-Mu, yakni membalas perbuatan orang bersalah dengan menanggungkannya kepada orang itu sendiri, tetapi membenarkan orang yang benar dengan membalaskan kepadanya sesuai dengan kebenarannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 24, 'Apabila umat-Mu Israel terpukul kalah oleh musuhnya karena mereka berdosa kepada-Mu, kemudian mereka berbalik dan mengakui nama-Mu, dan mereka berdoa dan memohon di hadapan-Mu di rumah ini,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 25, 'maka Engkaupun kiranya mendengar dari sorga dan mengampuni dosa umat-Mu Israel dan mengembalikan mereka ke tanah yang telah Kauberikan kepada mereka dan nenek moyang mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 26, 'Apabila langit tertutup, sehingga tidak ada hujan, sebab mereka berdosa kepada-Mu, lalu mereka berdoa di tempat ini dan mengakui nama-Mu dan mereka berbalik dari dosanya, sebab Engkau telah menindas mereka,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 27, 'maka Engkaupun kiranya mendengarkannya di sorga dan mengampuni dosa hamba-hamba-Mu, umat-Mu Israel, ?karena Engkaulah yang menunjukkan kepada mereka jalan yang baik yang harus mereka jalani?dan Engkau kiranya memberikan hujan kepada tanah-Mu yang telah Kauberikan kepada umat-Mu menjadi milik pusaka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 28, 'Apabila ada kelaparan di negeri ini, apabila ada penyakit sampar, hama dan penyakit gandum, belalang dan belalang pelahap, apabila musuh menyesakkan mereka di salah satu kota mereka, apabila ada tulah atau penyakit apapun,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 29, 'lalu seseorang atau segenap umat-Mu Israel memanjatkan doa dan permohonan di rumah ini dengan menadahkan tangannya?karena mereka masing-masing mengenal tulahnya dan penderitaannya sendiri?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 30, 'maka Engkaupun kiranya mendengar dari sorga, tempat kediaman-Mu yang tetap, dan kiranya Engkau mengampuni, dan membalas kepada setiap orang sesuai dengan segala perbuatannya, karena Engkau mengenal hatinya?sebab Engkau sajalah yang mengenal hati anak-anak manusia, ?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 31, 'supaya mereka takut akan Engkau dan mengikuti segala jalan yang Engkau tunjukkan selama mereka hidup di atas tanah yang telah Kauberikan kepada nenek moyang kami.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 32, 'Juga apabila seorang asing, yang tidak termasuk umat-Mu Israel, datang dari negeri jauh oleh karena nama-Mu yang besar, tangan-Mu yang kuat dan lengan-Mu yang teracung, dan ia datang berdoa di rumah ini,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 33, 'maka Engkaupun kiranya mendengar dari sorga, dari tempat kediaman-Mu yang tetap, dan kiranya Engkau bertindak sesuai dengan segala yang diserukan kepada-Mu oleh orang asing itu, supaya segala bangsa di bumi mengenal nama-Mu, sehingga mereka takut akan Engkau sama seperti umat-Mu Israel, dan sehingga mereka tahu, bahwa nama-Mu telah diserukan atas rumah yang telah kudirikan ini.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 34, 'Apabila umat-Mu keluar untuk berperang melawan musuh-musuhnya, ke arah manapun Engkau menyuruh mereka, dan apabila mereka berdoa kepada-Mu dengan berkiblat ke kota yang telah Kaupilih ini dan ke rumah yang telah kudirikan bagi nama-Mu,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 35, 'maka Engkau kiranya mendengar dari sorga doa dan permohonan mereka dan Engkau kiranya memberikan keadilan kepada mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 36, 'Apabila mereka berdosa kepada-Mu?karena tidak ada manusia yang tidak berdosa?dan Engkau murka kepada mereka dan menyerahkan mereka kepada musuh, sehingga mereka diangkut tertawan ke negeri yang jauh atau yang dekat,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 37, 'dan apabila mereka sadar kembali dalam hatinya di negeri tempat mereka tertawan, dan mereka berbalik, dan memohon kepada-Mu di negeri tempat mereka tertawan, dengan berkata: Kami telah berdosa, bersalah, dan berbuat fasik,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 38, 'apabila mereka berbalik kepada-Mu dengan segenap hatinya dan dengan segenap jiwanya di negeri orang-orang yang mengangkut mereka tertawan, dan apabila mereka berdoa kepada-Mu dengan berkiblat ke negeri mereka yang telah Kauberikan kepada nenek moyang mereka, ke kota yang telah Kaupilih dan ke rumah yang telah kudirikan bagi nama-Mu,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 39, 'maka Engkau kiranya mendengarkan dari sorga, dari tempat kediaman-Mu yang tetap, kepada doa dan segala permohonan mereka dan kiranya Engkau memberikan keadilan kepada mereka, dan Engkau kiranya mengampuni umat-Mu yang telah berdosa kepada-Mu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 40, 'Sebab itu, ya Allahku, kiranya mata-Mu terbuka dan telinga-Mu menaruh perhatian kepada doa yang dipanjatkan di tempat ini.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 41, 'Dan sekarang, bangunlah ya TUHAN Allah, dan pergilah ke tempat perhentian-Mu, Engkau serta tabut kekuatan-Mu! Kiranya, ya TUHAN Allah, imam-imam-Mu berpakaian keselamatan, dan orang-orang yang Kaukasihi bersukacita karena kebaikan-Mu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 6, 42, 'Ya TUHAN Allah, janganlah Engkau menolak orang yang telah Kauurapi, ingatlah akan segala kasih setia-Mu kepada Daud, hamba-Mu itu."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 1, 'Setelah Salomo mengakhiri doanya, apipun turun dari langit memakan habis korban bakaran dan korban-korban sembelihan itu, dan kemuliaan TUHAN memenuhi rumah itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 2, 'Para imam tidak dapat memasuki rumah TUHAN itu, karena kemuliaan TUHAN memenuhi rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 3, 'Ketika segenap orang Israel melihat api itu turun dan kemuliaan TUHAN meliputi rumah itu, berlututlah mereka di atas lantai dengan muka mereka sampai ke tanah, lalu sujud menyembah dan menyanyikan syukur bagi TUHAN: "Sebab Ia baik! Bahwasanya untuk selama-lamanya kasih setia-Nya."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 4, 'Lalu raja bersama-sama seluruh bangsa mempersembahkan korban sembelihan di hadapan TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 5, 'Sebagai korban sembelihan raja Salomo mempersembahkan dua puluh dua ribu ekor lembu sapi dan seratus dua puluh ribu ekor kambing domba. Demikianlah raja dan seluruh bangsa mentahbiskan rumah Allah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 6, 'Para imam telah siap berdiri pada tempat mereka. Begitu pula orang-orang Lewi telah siap dengan alat-alat musik untuk memuliakan TUHAN, yakni alat-alat musik yang dibuat raja Daud untuk mengiringi nyanyian syukur bagi TUHAN: "Bahwasanya untuk selama-lamanya kasih setia-Nya!" setiap kali mereka ditugaskan Daud menyanyikan puji-pujian. Dalam pada itu para imam berdiri berhadapan dengan mereka sambil meniup nafiri, sedang segenap orang Israel berdiri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 7, 'Lalu Salomo menguduskan pertengahan pelataran yang di depan rumah TUHAN, sebab di situlah diolahnya segala korban bakaran dan lemak korban keselamatan, sebab mezbah tembaga yang dibuat Salomo tidak dapat memuat korban bakaran dan korban sajian dan segala lemak korban.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 8, 'Dan pada waktu itu juga Salomo mengadakan perayaan Pondok Daun selama tujuh hari, bersama-sama dengan seluruh Israel, suatu jemaah yang amat besar, dari jalan masuk ke Hamat sampai ke sungai Mesir.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 9, 'Pada hari yang kedelapan mereka mengadakan perkumpulan raya, karena mereka telah merayakan pentahbisan mezbah selama tujuh hari, dan perayaan Pondok Daun selama tujuh hari.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 10, 'Pada hari yang kedua puluh tiga, bulan ketujuh, disuruhnya bangsa itu pulang ke kemah-kemah mereka sambil bersukacita dan bergembira atas kebaikan yang telah dilakukan TUHAN kepada Daud, kepada Salomo, dan kepada orang Israel, umat-Nya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 11, 'Demikianlah Salomo menyelesaikan rumah TUHAN dan istana raja, dan berhasil melaksanakan dalam rumah TUHAN dan dalam istananya segala sesuatu yang timbul dalam hatinya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 12, 'Kemudian TUHAN menampakkan diri kepada Salomo pada malam hari dan berfirman kepadanya: "Telah Kudengar doamu dan telah Kupilih tempat ini bagi-Ku sebagai rumah persembahan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 13, 'Bilamana Aku menutup langit, sehingga tidak ada hujan, dan bilamana Aku menyuruh belalang memakan habis hasil bumi, dan bilamana Aku melepaskan penyakit sampar di antara umat-Ku,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 14, 'dan umat-Ku, yang atasnya nama-Ku disebut, merendahkan diri, berdoa dan mencari wajah-Ku, lalu berbalik dari jalan-jalannya yang jahat, maka Aku akan mendengar dari sorga dan mengampuni dosa mereka, serta memulihkan negeri mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 15, 'Sekarang mata-Ku terbuka dan telinga-Ku menaruh perhatian kepada doa dari tempat ini.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 16, 'Sekarang telah Kupilih dan Kukuduskan rumah ini, supaya nama-Ku tinggal di situ untuk selama-lamanya, maka mata-Ku dan hati-Ku akan ada di situ sepanjang masa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 17, 'Mengenai engkau, jika engkau hidup di hadapan-Ku sama seperti Daud, ayahmu, dan berbuat sesuai dengan segala yang Kuperintahkan kepadamu, dan jika engkau tetap mengikuti segala ketetapan dan peraturan-Ku,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 18, 'maka Aku akan meneguhkan takhta kerajaanmu sesuai dengan perjanjian yang telah Kuikat dengan Daud, ayahmu, dengan berkata: Takkan terputus keturunanmu yang memerintah atas Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 19, 'Tetapi jika kamu ini berbalik dan meninggalkan segala ketetapan dan perintah-Ku yang telah Kuberikan kepadamu, dan pergi beribadah kepada allah lain dan sujud menyembah kepadanya,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 20, 'maka Aku akan mencabut kamu dari tanah-Ku yang telah Kuberikan kepadamu, dan rumah ini yang telah Kukuduskan bagi nama-Ku, akan Kubuang dari hadapan-Ku, dan akan Kujadikan kiasan dan sindiran di antara segala bangsa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 21, 'Dan setiap orang yang lewat rumah yang amat ditinggikan ini, akan tertegun dan berkata: Apakah sebabnya TUHAN berbuat yang demikian kepada negeri ini dan kepada rumah ini?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 7, 22, 'Maka orang akan berkata: Sebab mereka meninggalkan TUHAN, Allah nenek moyang mereka, yang membawa mereka keluar dari tanah Mesir, dan sebab mereka berpegang pada allah lain dan sujud menyembah kepadanya dan beribadah kepadanya. Itulah sebabnya Ia mendatangkan segala malapetaka ini ke atas mereka."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 1, 'Setelah lewat dua puluh tahun selesailah Salomo mendirikan rumah TUHAN dan istananya sendiri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 2, 'Maka Salomo memperkuat kota-kota yang diberikan Huram kepadanya, dan menyuruh orang Israel menetap di sana.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 3, 'Lalu Salomo pergi ke Hamat-Zoba dan menaklukkannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 4, 'Kemudian ia memperkuat Tadmor di padang gurun dan semua kota perbekalan yang didirikannya di Hamat.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 5, 'Ia memperkuat juga Bet-Horon Hulu dan Bet-Horon Hilir menjadi kota kubu yang bertembok, berpintu gerbang dan berpalang,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 6, 'dan juga Baalat, dan segala kota perbekalan kepunyaan Salomo, segala kota tempat kereta, kota-kota tempat orang berkuda dan apa saja yang Salomo ingin mendirikannya di Yerusalem, atau di gunung Libanon, atau di segenap negeri kekuasaannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 7, 'Semua orang yang masih tinggal dari orang Het, orang Amori, orang Feris, orang Hewi dan orang Yebus, yang tidak termasuk orang Israel,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 8, 'yakni keturunan bangsa-bangsa yang masih tinggal di negeri itu dan yang tidak dibinasakan oleh orang Israel, merekalah yang dikerahkan Salomo untuk menjadi orang rodi; demikianlah mereka sampai hari ini.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 9, 'Tetapi orang Israel tidak ada yang dijadikan budak oleh Salomo untuk pekerjaannya, melainkan mereka menjadi prajurit, atau perwira pasukan berkuda, atau panglima atas pasukan kereta dan pasukan berkuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 10, 'Dan inilah pemimpin-pemimpin umum raja Salomo: dua ratus lima puluh orang yang memerintah rakyat.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 11, 'Dan Salomo memindahkan anak Firaun dari kota Daud ke rumah yang didirikannya baginya, karena katanya: "Tidak boleh seorang isteriku tinggal dalam istana Daud, raja Israel, karena tempat-tempat yang telah dimasuki tabut TUHAN adalah kudus."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 12, 'Lalu Salomo mempersembahkan korban-korban bakaran bagi TUHAN di atas mezbah TUHAN yang didirikannya di depan balai Bait Suci,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 13, 'sesuai dengan apa yang menurut perintah Musa ditetapkan sebagai korban untuk setiap hari, yakni pada hari-hari Sabat, pada bulan-bulan baru, dan tiga kali setahun pada hari-hari raya: pada hari raya Roti Tidak Beragi, pada hari raya Tujuh Minggu dan pada hari raya Pondok Daun.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 14, 'Dan menurut peraturan Daud, ayahnya, ia menetapkan rombongan para imam dalam tugas jabatan mereka, dan orang-orang Lewi dalam tugas menyanyikan puji-pujian dan menyelenggarakan ibadah di hadapan para imam, setiap hari menurut yang ditetapkan untuk hari itu, dan juga penunggu-penunggu pintu gerbang dalam rombongan mereka untuk setiap pintu gerbang. Karena demikianlah perintah Daud, abdi Allah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 15, 'Mereka tidak menyimpang dari perintah raja mengenai para imam dan orang-orang Lewi dalam perkara apapun, juga mengenai perbendaharaan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 16, 'Maka terlaksanalah segala pekerjaan Salomo, dari hari dasar rumah TUHAN diletakkan sampai kepada hari rumah itu selesai. Dengan demikian selesailah sudah rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 17, 'Kemudian Salomo pergi ke Ezion-Geber dan ke Elot, yang letaknya di tepi laut, di tanah Edom.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 8, 18, 'Dengan perantaraan anak buahnya Huram mengirim kapal-kapal kepadanya dan anak buah yang tahu tentang laut. Bersama-sama anak buah Salomo mereka sampai ke Ofir dan dari sana mereka mengambil empat ratus lima puluh talenta emas, yang mereka bawa kepada raja Salomo.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 1, 'Ketika ratu negeri Syeba mendengar kabar tentang Salomo, maka dengan pasukan pengiring yang sangat besar dan dengan unta-unta yang membawa rempah-rempah, banyak emas dan batu permata yang mahal-mahal datanglah ia ke Yerusalem hendak menguji Salomo dengan teka-teki. Setelah ia sampai kepada Salomo, dipercakapkannyalah segala yang ada dalam hatinya dengan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 2, 'Dan Salomo menjawab segala pertanyaan ratu itu; bagi Salomo tidak ada yang tersembunyi, yang tidak dapat dijawabnya untuk ratu itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 3, 'Ketika ratu negeri Syeba melihat hikmat Salomo dan rumah yang telah didirikannya,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 4, 'makanan di mejanya, cara duduk pegawai-pegawainya, cara pelayan-pelayannya melayani dan berpakaian, juru-juru minumannya dan pakaian mereka, dan korban bakaran yang biasa dipersembahkannya di rumah TUHAN, maka tercenganglah ratu itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 5, 'Dan ia berkata kepada raja: "Benar juga kabar yang kudengar di negeriku tentang engkau dan tentang hikmatmu,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 6, 'tetapi aku tidak percaya perkataan-perkataan mereka sampai aku datang dan melihatnya dengan mataku sendiri; sungguh, setengah dari hikmatmu yang besar itu belum diberitahukan kepadaku; engkau melebihi kabar yang kudengar.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 7, 'Berbahagialah orang-orangmu, dan berbahagialah para pegawaimu ini yang selalu melayani engkau dan menyaksikan hikmatmu!', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 8, 'Terpujilah TUHAN, Allahmu, yang telah berkenan kepadamu sedemikian, hingga Ia mendudukkan engkau di atas takhta-Nya sebagai raja untuk TUHAN, Allahmu! Karena Allahmu mengasihi orang Israel, maka Ia menetapkan mereka untuk selama-lamanya, dan menjadikan engkau raja atas mereka untuk melakukan keadilan dan kebenaran."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 9, 'Lalu diberikan kepada raja seratus dua puluh talenta emas, dan sangat banyak rempah-rempah dan batu permata yang mahal-mahal; tidak pernah lagi ada rempah-rempah seperti yang diberikan ratu negeri Syeba kepada raja Salomo itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 10, 'Lagipula hamba-hamba Huram dan hamba-hamba Salomo, yang membawa emas dari Ofir, membawa juga kayu cendana dan batu permata yang mahal-mahal.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 11, 'Raja mengerjakan kayu cendana itu menjadi tangga-tangga untuk rumah TUHAN dan istana raja, dan juga menjadi kecapi dan gambus untuk para penyanyi. Hal seperti itu tidak pernah kelihatan sebelumnya di tanah Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 12, 'Raja Salomo memberikan kepada ratu negeri Syeba segala yang dikehendakinya dan yang dimintanya, melebihi yang dibawa ratu itu untuk raja. Lalu ratu itu berangkat pulang ke negerinya bersama-sama dengan pegawai-pegawainya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 13, 'Adapun berat emas, yang dibawa kepada Salomo dalam satu tahun ialah seberat enam ratus enam puluh enam talenta,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 14, 'belum terhitung yang dibawa oleh saudagar-saudagar dan pedagang-pedagang; juga semua raja Arab dan bupati-bupati di negeri itu membawa emas dan perak kepada Salomo.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 15, 'Raja Salomo membuat dua ratus perisai besar dari emas tempaan, enam ratus syikal emas tempaan dipakainya untuk setiap perisai besar;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 16, 'ia membuat juga tiga ratus perisai kecil dari emas tempaan, tiga ratus syikal emas dipakainya untuk setiap perisai kecil; lalu raja menaruh semuanya itu di dalam gedung "Hutan Libanon".', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 17, 'Juga raja membuat takhta besar dari gading, yang disalutnya dengan emas murni.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 18, 'Takhta itu enam tingkatnya, dan tumpuan kakinya dari emas, yang dipautkan pada takhta itu, dan pada kedua sisi tempat duduk ada kelek-kelek. Di samping kelek-kelek itu berdiri dua singa,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 19, 'sedang dua belas singa berdiri di atas keenam tingkat itu sebelah-menyebelah; belum pernah diperbuat yang demikian bagi sesuatu kerajaan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 20, 'Segala perkakas minuman raja Salomo dari emas dan segala barang di gedung "Hutan Libanon" itu dari emas murni; perak tidak dianggap berharga pada zaman Salomo.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 21, 'Sebab raja mempunyai kapal-kapal yang berlayar ke Tarsis bersama-sama dengan orang-orang Huram; dan sekali tiga tahun kapal-kapal Tarsis itu datang membawa emas dan perak serta gading; juga kera dan burung merak.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 22, 'Raja Salomo melebihi semua raja di bumi dalam hal kekayaan dan hikmat.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 23, 'Semua raja di bumi berikhtiar menghadap Salomo untuk menyaksikan hikmat yang telah ditaruh Allah di dalam hatinya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 24, 'Mereka datang masing-masing membawa persembahannya, yakni barang-barang perak dan barang-barang emas, pakaian, senjata, rempah-rempah, kuda dan bagal, dan begitulah tahun demi tahun.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 25, 'Salomo mempunyai juga empat ribu kandang untuk kuda-kudanya dan kereta-keretanya dan dua belas ribu orang berkuda, yang ditempatkan dalam kota-kota kereta dan dekat raja di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 26, 'Dan ia memerintah atas semua raja mulai dari sungai Efrat sampai negeri orang Filistin dan sampai ke tapal batas Mesir.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 27, 'Raja membuat banyaknya perak di Yerusalem sama seperti batu, dan banyaknya pohon kayu aras sama seperti pohon ara yang tumbuh di Daerah Bukit.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 28, 'Kuda untuk Salomo didatangkan dari Misraim dan dari segala negeri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 29, 'Selebihnya dari riwayat Salomo dari awal sampai akhir, bukankah semuanya itu tertulis dalam riwayat nabi Natan dan dalam nubuat Ahia, orang Silo itu, dan dalam penglihatan-penglihatan Ido, pelihat itu, tentang Yerobeam bin Nebat?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 30, 'Salomo memerintah di Yerusalem atas seluruh Israel empat puluh tahun lamanya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 9, 31, 'Kemudian Salomo mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di kota Daud, ayahnya. Maka Rehabeam, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 1, 'Kemudian Rehabeam pergi ke Sikhem, sebab seluruh Israel telah datang ke Sikhem untuk menobatkan dia menjadi raja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 2, 'Segera sesudah hal itu kedengaran kepada Yerobeam bin Nebat?ia ada di Mesir, sebab ia melarikan diri ke sana dari hadapan raja Salomo?maka kembalilah ia dari Mesir.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 3, 'Orang menyuruh memanggil dia, lalu datanglah Yerobeam dengan seluruh orang Israel dan berkata kepada Rehabeam:', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 4, '"Ayahmu telah memberatkan tanggungan kami, maka sekarang ringankanlah pekerjaan yang sukar yang dibebankan ayahmu dan tanggungan yang berat yang dipikulkannya kepada kami, supaya kami menjadi hambamu."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 5, 'Tetapi ia menjawab mereka: "Datanglah kembali kepadaku lusa." Lalu pergilah rakyat itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 6, 'Sesudah itu Rehabeam meminta nasihat dari para tua-tua yang selama hidup Salomo mendampingi Salomo, ayahnya, katanya: "Apakah nasihatmu untuk menjawab rakyat itu?"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 7, 'Mereka berkata kepadanya: "Jika engkau mau berlaku ramah terhadap rakyat itu, mau menyenangkan mereka dan mengatakan kata-kata yang baik kepada mereka, maka mereka menjadi hamba-hambamu sepanjang waktu."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 8, 'Tetapi ia mengabaikan nasihat yang diberikan para tua-tua itu, lalu ia meminta nasihat kepada orang-orang muda yang sebaya dengan dia dan yang mendampinginya,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 9, 'katanya kepada mereka: "Apakah nasihatmu, supaya kita dapat menjawab rakyat yang mengatakan kepadaku: Ringankanlah tanggungan yang dipikulkan kepada kami oleh ayahmu?"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 10, 'Lalu orang-orang muda yang sebaya dengan dia itu berkata: "Beginilah harus kaukatakan kepada rakyat yang telah berkata kepadamu: Ayahmu telah memberatkan tanggungan kami, tetapi engkau ini, berilah keringanan kepada kami?beginilah harus kaukatakan kepada mereka: Kelingkingku lebih besar dari pada pinggang ayahku!', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 11, 'Maka sekarang, ayahku telah membebankan kepada kamu tanggungan yang berat, tetapi aku akan menambah tanggungan kamu; ayahku telah menghajar kamu dengan cambuk, tetapi aku akan menghajar kamu dengan cambuk yang berduri besi."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 12, 'Lusanya datanglah Yerobeam dengan segenap rakyat kepada Rehabeam, seperti yang dikatakan raja: "Kembalilah kepadaku lusa."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 13, 'Raja Rehabeam menjawab mereka dengan keras; ia telah mengabaikan nasihat para tua-tua;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 14, 'ia mengatakan kepada mereka menurut nasihat orang-orang muda: "Ayahku telah memberatkan tanggungan kamu, tetapi aku akan menambahnya; ayahku telah menghajar kamu dengan cambuk, tetapi aku akan menghajar kamu dengan cambuk yang berduri besi."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 15, 'Jadi raja tidak mendengarkan permintaan rakyat, sebab hal itu merupakan perubahan yang disebabkan Allah, supaya TUHAN menepati firman yang diucapkan-Nya dengan perantaraan Ahia, orang Silo, kepada Yerobeam bin Nebat.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 16, 'Setelah seluruh Israel melihat, bahwa raja tidak mendengarkan permintaan mereka, maka rakyat menjawab raja: "Bagian apakah kita dapat dari pada Daud? Kita tidak memperoleh warisan dari anak Isai itu! Masing-masing ke kemahmu, hai orang Israel! Uruslah sekarang rumahmu sendiri, hai Daud!" Maka pergilah seluruh orang Israel ke kemahnya,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 17, 'sehingga Rehabeam menjadi raja hanya atas orang Israel yang diam di kota-kota Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 18, 'Kemudian raja Rehabeam mengutus Hadoram yang menjadi kepala rodi, tetapi orang-orang Israel melontari dia dengan batu, sehingga mati, bahkan raja Rehabeam hampir-hampir tidak dapat menaiki keretanya untuk melarikan diri ke Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 10, 19, 'Demikianlah mulanya orang Israel memberontak terhadap keluarga Daud sampai hari ini.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 1, 'Ketika Rehabeam datang ke Yerusalem, ia mengumpulkan kaum Yehuda dan Benyamin, seratus delapan puluh ribu teruna yang sanggup berperang untuk memerangi orang Israel dengan maksud mengembalikan kerajaan itu kepadanya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 2, 'Tetapi datanglah firman TUHAN kepada Semaya, abdi Allah, demikian:', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 3, '"Katakanlah kepada Rehabeam, anak Salomo, raja Yehuda, dan kepada segenap orang Israel di Yehuda dan di Benyamin, demikian:', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 4, 'Beginilah firman TUHAN: Janganlah kamu maju dan janganlah kamu berperang melawan saudara-saudaramu. Pulanglah masing-masing ke rumahnya, sebab Akulah yang menyebabkan hal ini terjadi." Maka mereka mendengarkan firman TUHAN dan pulang dengan tidak pergi menyerang Yerobeam.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 5, 'Rehabeam diam di Yerusalem dan memperkuat kota-kota kubu di Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 6, 'Ia memperkuat Betlehem, Etam, Tekoa,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 7, 'Bet-Zur, Sokho, Adulam,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 8, 'Gat, Mares, Zif,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 9, 'Adoraim, Lakhis, Azeka,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 10, 'Zora, Ayalon dan Hebron, yang terletak di Yehuda dan di Benyamin, sebagai kota-kota berkubu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 11, 'Ia memperkokoh kota-kota kubu itu dan menempatkan di situ kepala-kepala pasukan dengan persediaan makanan, minyak dan anggur;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 12, 'perisai dan tombakpun disediakan di tiap-tiap kota. Ia membuat kota-kota itu amat kokoh. Demikianlah Yehuda dan Benyamin menjadi daerah kekuasaannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 13, 'Para imam dan orang Lewi di seluruh Israel datang menggabungkan diri dengan dia dari daerah-daerah kediaman mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 14, 'Sebab orang Lewi meninggalkan tanah penggembalaan dan milik mereka, lalu pergi ke Yehuda dan Yerusalem, oleh karena Yerobeam dan anak-anaknya melarang mereka memegang jabatan imam TUHAN,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 15, 'dan mengangkat bagi dirinya imam-imam untuk bukit-bukit pengorbanan untuk jin-jin dan untuk anak-anak lembu jantan yang dibuatnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 16, 'Dari segenap suku Israel orang datang ke Yerusalem mengikuti orang-orang Lewi itu, yakni orang yang telah membulatkan hatinya untuk mencari TUHAN Allah Israel; dan mereka datang untuk mempersembahkan korban kepada TUHAN, Allah nenek moyang mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 17, 'Demikianlah mereka memperkokoh kerajaan Yehuda dan memperkuat pemerintahan Rehabeam bin Salomo selama tiga tahun, karena selama tiga tahun mereka hidup mengikuti jejak Daud dan Salomo.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 18, 'Rehabeam mengambil Mahalat, anak Yerimot bin Daud dan Abihail binti Elhiab bin Isai, menjadi isterinya,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 19, 'yang melahirkan baginya anak-anak lelaki ini: Yeush, Semarya dan Zaham.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 20, 'Sesudah Mahalat ia mengambil Maakha, anak Absalom, menjadi isterinya, yang melahirkan baginya Abia, Atai, Ziza dan Selomit.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 21, 'Rehabeam mencintai Maakha, anak Absalom itu, lebih dari pada semua isteri dan gundiknya?ia mengambil delapan belas isteri dan enam puluh gundik dan memperanakkan dua puluh delapan anak laki-laki dan enam puluh anak perempuan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 22, 'Rehabeam mengangkat Abia, anak Maakha, sebagai pemuka, yakni sebagai pemimpin di antara saudara-saudaranya, karena ia bermaksud menjadikan dia raja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 11, 23, 'Oleh sebab itu ia mengambil kebijaksanaan untuk menyebarkan semua anaknya yang lain ke seluruh daerah Yehuda dan Benyamin, ke segala kota kubu. Ia memberikan mereka makanan dengan limpahnya dan menyediakan bagi mereka banyak isteri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 1, 'Rehabeam beserta seluruh Israel meninggalkan hukum TUHAN, ketika kerajaannya menjadi kokoh dan kekuasaannya menjadi teguh.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 2, 'Tetapi pada tahun kelima zaman raja Rehabeam, majulah Sisak, raja Mesir, menyerang Yerusalem?karena mereka berubah setia terhadap TUHAN?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 3, 'dengan seribu dua ratus kereta dan enam puluh ribu orang berkuda, sedang rakyat yang mengikutinya dari Mesir, yakni orang Libia, orang Suki dan orang Etiopia, tidak terhitung banyaknya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 4, 'Ia merebut kota-kota benteng yang di Yehuda, bahkan mendekati Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 5, 'Nabi Semaya datang kepada Rehabeam dan pemimpin-pemimpin Yehuda yang berkumpul di Yerusalem berhubung dengan ancaman Sisak, dan berkata kepada mereka: "Beginilah firman TUHAN: Kamu telah meninggalkan Aku, oleh sebab itu Akupun meninggalkan kamu juga dalam kuasa Sisak."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 6, 'Maka pemimpin-pemimpin Israel dan raja merendahkan diri dan berkata: "Tuhanlah yang benar!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 7, 'Ketika TUHAN melihat bahwa mereka merendahkan diri, datanglah firman TUHAN kepada Semaya, bunyinya: "Mereka telah merendahkan diri, oleh sebab itu Aku tidak akan memusnahkan mereka. Aku segera akan meluputkan mereka dan kehangatan murka-Ku tidak akan dicurahkan atas Yerusalem dengan perantaraan Sisak.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 8, 'Tetapi mereka akan menjadi hamba-hambanya, supaya mereka tahu membedakan antara mengabdi kepada-Ku dan mengabdi kepada kerajaan-kerajaan duniawi."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 9, 'Maka majulah Sisak, raja Mesir itu, menyerang Yerusalem. Ia merampas barang-barang perbendaharaan rumah TUHAN dan barang-barang perbendaharaan rumah raja; semuanya dirampasnya. Ia merampas juga perisai-perisai emas yang dibuat Salomo.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 10, 'Sebagai gantinya raja Rehabeam membuat perisai-perisai tembaga, yang dipercayakannya kepada pemimpin-pemimpin bentara yang menjaga pintu istana raja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 11, 'Setiap kali raja masuk ke rumah TUHAN, bentara-bentara datang membawa masuk perisai-perisai itu, dan mereka pula yang mengembalikannya ke kamar jaga para bentara.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 12, 'Oleh sebab raja merendahkan diri, surutlah murka TUHAN dari padanya, sehingga ia tidak dimusnahkan-Nya sama sekali. Lagipula masih terdapat hal-hal yang baik di Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 13, 'Raja Rehabeam menunjukkan dirinya kuat dalam pemerintahannya di Yerusalem. Rehabeam berumur empat puluh satu tahun pada waktu ia menjadi raja, dan tujuh belas tahun lamanya ia memerintah di Yerusalem, kota yang dipilih TUHAN dari antara segala suku Israel untuk membuat nama-Nya tinggal di sana. Nama ibunya ialah Naama, seorang perempuan Amon.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 14, 'Ia berbuat yang jahat, karena ia tidak tekun mencari TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 15, 'Bukankah riwayat Rehabeam dari awal sampai akhir semuanya tertulis dalam riwayat Semaya, nabi itu, dan Ido, pelihat itu, ?yang juga memuat daftar silsilah. Antara Rehabeam dan Yerobeam terus-menerus ada perang.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 12, 16, 'Kemudian Rehabeam mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di kota Daud. Maka Abia, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 1, 'Dalam tahun kedelapan belas zaman raja Yerobeam menjadi rajalah Abia atas Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 2, 'Tiga tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Mikhaya, anak Uriel dari Gibea. Dan ada perang antara Abia dan Yerobeam.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 3, 'Abia memulai perang dengan pasukan pahlawan-pahlawan perang, yang jumlahnya empat ratus ribu orang pilihan, sedangkan Yerobeam mengatur barisan perangnya melawan dia dengan delapan ratus ribu orang pilihan, pahlawan-pahlawan yang gagah perkasa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 4, 'Lalu Abia berdiri di atas gunung Zemaraim, yang termasuk pegunungan Efraim, dan berkata: "Dengarlah kepadaku, Yerobeam dan seluruh Israel!', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 5, 'Tidakkah kamu tahu, bahwa TUHAN Allah Israel telah memberikan kuasa kerajaan atas Israel kepada Daud dan anak-anaknya untuk selama-lamanya dengan suatu perjanjian garam?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 6, 'Tetapi Yerobeam bin Nebat, hamba Salomo bin Daud, telah bangkit memberontak melawan tuannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 7, 'Petualang-petualang, orang-orang dursila, berhimpun padanya; mereka terlalu kuat bagi Rehabeam bin Salomo, yang masih muda dan belum teguh hati, dan yang tidak dapat mempertahankan diri terhadap mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 8, 'Tentu kamu menyangka, bahwa kamu dapat mempertahankan diri terhadap kerajaan TUHAN, yang dipegang keturunan Daud, karena jumlah kamu besar dan karena pada kamu ada anak lembu emas yang dibuat Yerobeam untuk kamu menjadi allah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 9, 'Bukankah kamu telah menyingkirkan imam-imam TUHAN, anak-anak Harun itu, dan orang-orang Lewi, lalu mengangkat imam-imam menurut kebiasaan bangsa-bangsa negeri-negeri lain, sehingga setiap orang yang datang untuk ditahbiskan dengan seekor lembu jantan muda dan tujuh ekor domba jantan, dijadikan imam untuk sesuatu yang bukan Allah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 10, 'Tetapi kami ini, Tuhanlah Allah kami, dan kami tidak meninggalkan-Nya. Dan anak-anak Harunlah yang melayani TUHAN sebagai imam, sedang orang Lewi menunaikan tugasnya,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 11, 'yakni setiap pagi dan setiap petang mereka membakar bagi TUHAN korban bakaran dan ukupan dari wangi-wangian, menyusun roti sajian di atas meja yang tahir, dan mengatur kandil emas dengan pelita-pelitanya untuk dinyalakan setiap petang, karena kamilah yang memelihara kewajiban kami terhadap TUHAN, Allah kami, tetapi kamulah yang meninggalkan-Nya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 12, 'Lihatlah, pada pihak kami Allah yang memimpin, sedang imam-imam-Nya siap meniup tanda serangan terhadap kamu dengan nafiri isyarat-isyarat. Hai orang Israel, jangan kamu berperang melawan TUHAN, Allah nenek moyangmu, karena kamu tidak akan beruntung!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 13, 'Tetapi Yerobeam mengirim suatu pasukan penghadang yang harus membuat gerakan keliling supaya sampai di belakang mereka, sehingga induk pasukannya berada di depan Yehuda dan pasukan-pasukan penghadang di belakang mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 14, 'Ketika Yehuda menoleh ke belakang, lihatlah, mereka harus menghadapi pertempuran dari depan dan dari belakang. Mereka berteriak kepada TUHAN, sedang para imam meniup nafiri,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 15, 'dan orang-orang Yehuda memekikkan pekik perang. Pada saat orang-orang Yehuda itu memekikkan pekik perang, Allah memukul kalah Yerobeam dan segenap orang Israel oleh Abia dan Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 16, 'Orang Israel lari dari depan Yehuda, tetapi Allah menyerahkan mereka ke dalam tangan Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 17, 'Abia dengan laskarnya mendatangkan kekalahan yang besar kepada mereka. Dari orang Israel mati terbunuh lima ratus ribu orang pilihan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 18, 'Demikianlah orang Israel ditundukkan pada waktu itu, sedang orang Yehuda menjadi kokoh, karena mereka mengandalkan diri kepada TUHAN, Allah nenek moyang mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 19, 'Abia mengejar Yerobeam dan merebut dari padanya beberapa kota, yakni Betel dengan segala anak kotanya, Yesana dengan segala anak kotanya dan Efron dengan segala anak kotanya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 20, 'Tak pernah lagi Yerobeam mendapat kekuatan di zaman Abia. TUHAN memukul dia, sehingga ia mati.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 21, 'Abia menunjukkan dirinya kuat. Ia mengambil empat belas isteri dan memperanakkan dua puluh dua anak laki-laki dan enam belas anak perempuan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 13, 22, 'Selebihnya dari riwayat Abia, langkah-langkahnya dan titah-titahnya, tertulis dalam kitab sejarah nabi Ido.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 1, 'Kemudian Abia mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di kota Daud. Maka Asa, anaknya, menjadi raja menggantikan dia. Pada zaman pemerintahannya negeri itu aman selama sepuluh tahun.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 2, 'Asa melakukan apa yang baik dan yang benar di mata TUHAN, Allahnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 3, 'Ia menjauhkan mezbah-mezbah asing dan bukit-bukit pengorbanan, memecahkan tugu-tugu berhala, dan menghancurkan tiang-tiang berhala.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 4, 'Ia memerintahkan orang Yehuda supaya mereka mencari TUHAN, Allah nenek moyang mereka, dan mematuhi hukum dan perintah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 5, 'Ia menjauhkan bukit-bukit pengorbanan dan pedupaan-pedupaan dari segala kota di Yehuda. Dan kerajaanpun aman di bawah pemerintahannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 6, 'Karena negeri itu aman dan tidak ada yang memeranginya di tahun-tahun itu, ia dapat membangun kota-kota benteng di Yehuda; TUHAN telah mengaruniakan keamanan kepadanya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 7, 'Katanya kepada orang Yehuda: "Marilah kita memperkuat kota-kota ini dan mengelilinginya dengan tembok beserta menara-menaranya, pintu-pintunya dan palang-palangnya. Negeri ini masih dalam tangan kita, karena kita mencari TUHAN Allah kita dan Ia mencari kita serta mengaruniakan keamanan kepada kita di segala penjuru." Maka mereka melaksanakan pembangunan itu dengan berhasil.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 8, 'Pasukan-pasukan Asa yang dari Yehuda jumlahnya tiga ratus ribu orang yang membawa perisai besar dan tombak, dan yang dari Benyamin jumlahnya dua ratus delapan puluh ribu orang yang membawa perisai kecil, sebagai pemanah. Mereka semua pahlawan-pahlawan yang gagah perkasa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 9, 'Zerah, orang Etiopia itu, maju berperang melawan mereka dengan tentara sebanyak sejuta orang dan tiga ratus kereta. Ia sampai ke Maresa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 10, 'Lalu Asa maju menghadapinya. Mereka mengatur barisan perangnya di lembah Zefata dekat Maresa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 11, 'Kemudian Asa berseru kepada TUHAN, Allahnya: "Ya TUHAN, selain dari pada Engkau, tidak ada yang dapat menolong yang lemah terhadap yang kuat. Tolonglah kami ya TUHAN, Allah kami, karena kepada-Mulah kami bersandar dan dengan nama-Mu kami maju melawan pasukan yang besar jumlahnya ini. Ya TUHAN, Engkau Allah kami, jangan biarkan seorang manusia mempunyai kekuatan untuk melawan Engkau!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 12, 'Dan TUHAN memukul kalah orang-orang Etiopia itu di hadapan Asa dan Yehuda. Orang-orang Etiopia itu lari,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 13, 'lalu dikejar oleh Asa dan laskarnya sampai ke Gerar. Dari orang-orang Etiopia itu amat banyak yang tewas, sehingga tidak ada yang tinggal hidup, karena mereka hancur di hadapan TUHAN dan tentaranya. Orang-orang Yehuda memperoleh jarahan yang sangat besar.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 14, 'Mereka mengalahkan semua kota di sekeliling Gerar, karena ketakutan yang dari TUHAN menimpa penduduknya. Mereka menjarahi semua kota itu, karena jarahan yang besar terdapat di situ.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 14, 15, 'Tenda-tenda pemilik ternakpun direbut mereka, dan banyak kambing domba dan unta diangkutnya sebagai jarahan, lalu mereka kembali ke Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 1, 'Azarya bin Oded dihinggapi Roh Allah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 2, 'Ia pergi menemui Asa dan berkata kepadanya: "Dengarlah kepadaku, Asa dan seluruh Yehuda dan Benyamin! TUHAN beserta dengan kamu bilamana kamu beserta dengan Dia. Bilamana kamu mencari-Nya, Ia berkenan ditemui olehmu, tetapi bilamana kamu meninggalkan-Nya, kamu akan ditinggalkan-Nya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 3, 'Lama sekali Israel tanpa Allah yang benar, tanpa ajaran dari pada imam dan tanpa hukum.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 4, 'Tetapi dalam kesesakan mereka berbalik kepada TUHAN, Allah orang Israel. Mereka mencari-Nya, dan Ia berkenan ditemui oleh mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 5, 'Pada zaman itu tidak dapat orang pergi dan pulang dengan selamat, karena terdapat kekacauan yang besar di antara segenap penduduk daerah-daerah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 6, 'Bangsa menghancurkan bangsa, kota menghancurkan kota, karena Allah mengacaukan mereka dengan berbagai-bagai kesesakan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 7, 'Tetapi kamu ini, kuatkanlah hatimu, jangan lemah semangatmu, karena ada upah bagi usahamu!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 8, 'Ketika Asa mendengar perkataan nubuat yang diucapkan oleh nabi Azarya bin Oded itu, ia menguatkan hatinya dan menyingkirkan dewa-dewa kejijikan dari seluruh tanah Yehuda dan Benyamin dan dari kota-kota yang direbutnya di pegunungan Efraim. Ia membaharui mezbah TUHAN yang ada di depan balai Bait Suci TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 9, 'Ia mengumpulkan seluruh Yehuda dan Benyamin dan orang-orang Efraim, Manasye dan Simeon yang tinggal di antara mereka sebagai orang asing. Sebab dari Israel banyak yang menyeberang memihak kepadanya ketika mereka melihat bahwa TUHAN, Allahnya, beserta dengan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 10, 'Mereka berkumpul di Yerusalem pada bulan ketiga tahun kelima belas dari pemerintahan Asa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 11, 'Pada hari itu mereka mempersembahkan kepada TUHAN tujuh ratus lembu sapi dan tujuh ribu kambing domba dari jarahan yang mereka bawa pulang.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 12, 'Mereka mengadakan perjanjian untuk mencari TUHAN, Allah nenek moyang mereka, dengan segenap hati dan jiwa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 13, 'Setiap orang, baik anak-anak atau orang dewasa, baik laki-laki atau perempuan, yang tidak mencari TUHAN, Allah Israel, harus dihukum mati.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 14, 'Mereka bersumpah setia kepada TUHAN dengan suara yang nyaring, dengan sorak-sorai dan dengan tiupan nafiri dan sangkakala.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 15, 'Seluruh Yehuda bersukaria atas sumpah itu, karena dengan segenap hati mereka bersumpah setia dan dengan kehendak yang bulat mereka mencari TUHAN. TUHAN berkenan ditemui oleh mereka dan mengaruniakan keamanan kepada mereka di segala penjuru.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 16, 'Bahkan raja Asa memecat Maakha, neneknya, dari pangkat ibu suri, karena neneknya itu membuat patung Asyera yang keji. Asa merobohkan patung yang keji itu, menumbuknya sampai halus dan membakarnya di lembah Kidron.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 17, 'Sekalipun bukit-bukit pengorbanan tidak dijauhkan dari Israel, namun hati Asa tulus ikhlas sepanjang umurnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 18, 'Ia membawa persembahan-persembahan kudus ayahnya dan persembahan-persemba kudusnya sendiri ke rumah Allah, yakni emas dan perak serta barang-barang lain.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 15, 19, 'Tidak ada perang sampai pada tahun ketiga puluh lima pemerintahan Asa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 1, 'Pada tahun ketiga puluh enam pemerintahan Asa majulah Baesa, raja Israel, hendak berperang melawan Yehuda. Ia memperkuat Rama dengan maksud mencegah lalu lintas kepada Asa, raja Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 2, 'Lalu Asa mengeluarkan emas dan perak dari perbendaharaan rumah TUHAN dan dari perbendaharaan rumah raja dan mengirimnya kepada Benhadad, raja Aram yang diam di Damsyik dengan pesan:', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 3, '"Ada perjanjian antara aku dan engkau, antara ayahku dan ayahmu. Ini kukirim emas dan perak kepadamu. Marilah, batalkanlah perjanjianmu dengan Baesa, raja Israel, supaya ia undur dari padaku."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 4, 'Lalu Benhadad mendengarkan permintaan raja Asa; ia menyuruh panglima-panglimanya menyerang kota-kota Israel. Dan mereka memukul kalah Iyon, Dan, Abel-Maim dan segala tempat perbekalan kota-kota di Naftali.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 5, 'Segera sesudah Baesa mendengar hal itu, ia berhenti memperkuat Rama; ia menghentikan usahanya itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 6, 'Tetapi raja Asa mengerahkan segenap orang Yehuda, yang harus mengangkat batu dan kayu yang dipergunakan Baesa untuk memperkuat Rama itu. Ia mempergunakannya untuk memperkuat Geba dan Mizpa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 7, 'Pada waktu itu datanglah Hanani, pelihat itu, kepada Asa, raja Yehuda, katanya kepadanya: "Karena engkau bersandar kepada raja Aram dan tidak bersandar kepada TUHAN Allahmu, oleh karena itu terluputlah tentara raja Aram dari tanganmu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 8, 'Bukankah tentara orang Etiopia dan Libia besar jumlahnya, kereta dan orang berkudanya sangat banyak? Namun TUHAN telah menyerahkan mereka ke dalam tanganmu, karena engkau bersandar kepada-Nya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 9, 'Karena mata TUHAN menjelajah seluruh bumi untuk melimpahkan kekuatan-Nya kepada mereka yang bersungguh hati terhadap Dia. Dalam hal ini engkau telah berlaku bodoh, oleh sebab itu mulai sekarang ini engkau akan mengalami peperangan."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 10, 'Maka sakit hatilah Asa karena perkataan pelihat itu, sehingga ia memasukkannya ke dalam penjara, sebab memang ia sangat marah terhadap dia karena perkara itu. Pada waktu itu Asa menganiaya juga beberapa orang dari rakyat.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 11, 'Sesungguhnya riwayat Asa dari awal sampai akhir tertulis dalam kitab raja-raja Yehuda dan Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 12, 'Pada tahun ketiga puluh sembilan pemerintahannya Asa menderita sakit pada kakinya yang kemudian menjadi semakin parah. Namun dalam kesakitannya itu ia tidak mencari pertolongan TUHAN, tetapi pertolongan tabib-tabib.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 13, 'Kemudian Asa mendapat perhentian bersama-sama nenek moyangnya. Ia mati pada tahun keempat puluh satu pemerintahannya,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 16, 14, 'dan dikuburkan di kuburan yang telah digali baginya di kota Daud. Mereka membaringkannya di atas petiduran yang penuh dengan rempah-rempah dan segala macam rempah-rempah campuran yang dicampur menurut cara pencampur rempah-rempah, lalu menyalakan api yang sangat besar untuk menghormatinya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 1, 'Maka Yosafat, anaknya, menjadi raja menggantikan dia. Sebagai pemimpin Israel ia memperkuat dirinya', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 2, 'dengan menempatkan tentara di semua kota yang berkubu di Yehuda dan pasukan-pasukan pendudukan di tanah Yehuda serta di kota-kota Efraim yang direbut oleh Asa, ayahnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 3, 'Dan TUHAN menyertai Yosafat, karena ia hidup mengikuti jejak yang dahulu dari Daud, bapa leluhurnya, dan tidak mencari Baal-baal,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 4, 'melainkan mencari Allah ayahnya. Ia hidup menurut perintah-perintah-Nya dan tidak berbuat seperti Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 5, 'Oleh sebab itu TUHAN mengokohkan kerajaan yang ada di bawah kekuasaannya. Seluruh Yehuda memberikan persembahan kepada Yosafat, sehingga ia menjadi kaya dan sangat terhormat.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 6, 'Dengan tabah hati ia hidup menurut jalan yang ditunjukkan TUHAN. Pula ia menjauhkan dari Yehuda segala bukit pengorbanan dan tiang berhala.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 7, 'Pada tahun ketiga pemerintahannya ia mengutus beberapa pembesarnya, yakni Benhail, Obaja, Zakharia, Netaneel dan Mikha untuk mengajar di kota-kota Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 8, 'Bersama-sama mereka turut juga beberapa orang Lewi, yakni Semaya, Netanya, Zebaja, Asael, Semiramot, Yonatan, Adonia, Tobia dan Tob-Adonia disertai imam-imam Elisama dan Yoram.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 9, 'Mereka memberikan pelajaran di Yehuda dengan membawa kitab Taurat TUHAN. Mereka mengelilingi semua kota di Yehuda sambil mengajar rakyat.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 10, 'Ketakutan yang dari TUHAN menimpa semua kerajaan di negeri-negeri sekeliling Yehuda, sehingga mereka tidak berani berperang melawan Yosafat.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 11, 'Dari antara orang-orang Filistin ada yang membawa kepada Yosafat persembahan, dan perak sebagai upeti. Juga orang-orang Arab membawa kepadanya kambing domba, domba jantan tujuh ribu tujuh ratus ekor dan kambing jantan tujuh ribu tujuh ratus ekor.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 12, 'Yosafat makin lama makin kuat, menjadi luar biasa kuat. Di Yehuda ia membangun benteng-benteng dan kota-kota perbekalan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 13, 'Banyak perbekalannya di kota-kota Yehuda. Orang-orang perangnya ada di Yerusalem, semuanya pahlawan yang gagah perkasa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 14, 'Inilah daftar kesatuan mereka menurut puak-puak mereka; panglima-panglima dari Yehuda ialah panglima Adna dengan tiga ratus ribu pahlawan yang gagah perkasa;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 15, 'di samping dia panglima Yohanan dengan dua ratus delapan puluh ribu orang;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 16, 'dan di samping dia Amasia bin Zikhri, yang dengan sukarela telah menyerahkan dirinya kepada TUHAN, dengan dua ratus ribu pahlawan yang gagah perkasa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 17, 'Dan dari Benyamin ialah Elyada, seorang pahlawan yang gagah perkasa, dengan dua ratus ribu orang yang bersenjatakan busur dan perisai.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 18, 'Di samping dia Yozabad, dengan seratus delapan puluh ribu orang yang bersenjata untuk berperang.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 17, 19, 'Mereka itulah yang bertugas pada raja, selain dari pada mereka yang ditempatkan raja di kota-kota yang berkubu di seluruh Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 1, 'Ketika Yosafat kaya dan sangat terhormat, ia menjadi besan Ahab.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 2, 'Beberapa tahun kemudian, pergilah ia kepada Ahab di Samaria. Ahab menyembelih banyak kambing domba dan lembu sapi untuk dia dan rombongannya, dan mengajaknya untuk menyerang Ramot-Gilead.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 3, 'Berkatalah Ahab, raja Israel, kepada Yosafat, raja Yehuda: "Maukah engkau pergi ke Ramot-Gilead bersama-sama aku?" Jawabnya kepadanya: "Kita sama-sama, aku dan engkau, rakyatmu dan rakyatku, aku akan bersama-sama engkau di dalam perang."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 4, 'Tetapi Yosafat berkata kepada raja Israel: "Baiklah tanyakan dahulu firman TUHAN."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 5, 'Lalu raja Israel mengumpulkan para nabi, empat ratus orang banyaknya, kemudian bertanyalah ia kepada mereka: "Apakah kami boleh pergi berperang melawan Ramot-Gilead atau aku membatalkannya?" Jawab mereka: "Majulah! Allah akan menyerahkannya ke dalam tangan raja."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 6, 'Tetapi Yosafat bertanya: "Tidak adakah lagi di sini seorang nabi TUHAN, supaya dengan perantaraannya kita dapat meminta petunjuk?"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 7, 'Jawab raja Israel kepada Yosafat: "Masih ada seorang lagi yang dengan perantaraannya dapat diminta petunjuk TUHAN. Tetapi aku membenci dia, sebab tidak pernah ia menubuatkan yang baik tentang aku, melainkan selalu malapetaka. Orang itu ialah Mikha bin Yimla." Kata Yosafat: "Janganlah raja berkata demikian."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 8, 'Kemudian raja Israel memanggil seorang pegawai istana, katanya: "Jemputlah Mikha bin Yimla dengan segera!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 9, 'Sementara raja Israel dan Yosafat, raja Yehuda, duduk masing-masing di atas takhtanya dengan pakaian kebesaran, di suatu tempat pengirikan di depan pintu gerbang Samaria, sedang semua nabi itu bernubuat di depan mereka,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 10, 'maka Zedekia bin Kenaana membuat tanduk-tanduk besi, lalu berkata: "Beginilah firman TUHAN: Dengan ini engkau akan menanduk Aram sampai engkau menghabiskan mereka."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 11, 'Juga semua nabi itu bernubuat demikian, katanya: "Majulah ke Ramot-Gilead, dan engkau akan beruntung; TUHAN akan menyerahkannya ke dalam tangan raja."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 12, 'Suruhan yang pergi memanggil Mikha itu berkata kepadanya: "Ketahuilah, nabi-nabi itu sudah sepakat meramalkan yang baik bagi raja, hendaklah engkau juga berbicara seperti salah seorang dari pada mereka dan meramalkan yang baik."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 13, 'Tetapi Mikha menjawab: "Demi TUHAN yang hidup, sesungguhnya, apa yang akan difirmankan Allahku, itulah yang akan kukatakan."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 14, 'Setelah ia sampai kepada raja, bertanyalah raja kepadanya: "Mikha, apakah kami boleh pergi berperang melawan Ramot-Gilead atau aku membatalkannya?" Jawabnya: "Majulah dan kamu akan beruntung, sebab mereka akan diserahkan ke dalam tanganmu!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 15, 'Tetapi raja berkata kepadanya: "Sampai berapa kali aku menyuruh engkau bersumpah, supaya engkau mengatakan kepadaku tidak lain dari kebenaran?"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 16, 'Lalu jawabnya: "Telah kulihat seluruh Israel bercerai-berai di gunung-gunung seperti kambing domba yang tidak mempunyai gembala, sebab itu TUHAN berfirman: Mereka ini tidak punya tuan; baiklah masing-masing pulang ke rumahnya dengan selamat."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 17, 'Kemudian raja Israel berkata kepada Yosafat: "Bukankah telah kukatakan kepadamu: Tidak pernah ia menubuatkan yang baik tentang aku, melainkan hanya malapetaka?"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 18, 'Kata Mikha: "Sebab itu dengarkanlah firman TUHAN. Aku telah melihat TUHAN sedang duduk di atas takhta-Nya dan segenap tentara sorga berdiri di sebelah kanan-Nya dan di sebelah kiri-Nya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 19, 'Dan TUHAN berfirman: Siapakah yang akan membujuk Ahab, raja Israel, untuk maju berperang, supaya ia tewas di Ramot-Gilead? Maka yang seorang berkata begini, yang lain berkata begitu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 20, 'Kemudian tampillah suatu roh, lalu berdiri di hadapan TUHAN. Ia berkata: Aku ini akan membujuknya. TUHAN bertanya kepadanya: Dengan apa?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 21, 'Jawabnya: Aku akan keluar dan menjadi roh dusta dalam mulut semua nabinya. Ia berfirman: Biarlah engkau membujuknya, dan engkau akan berhasil pula. Keluarlah dan perbuatlah demikian!', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 22, 'Karena itu, sesungguhnya TUHAN telah menaruh roh dusta ke dalam mulut nabi-nabimu ini, sebab TUHAN telah menetapkan untuk menimpakan malapetaka kepadamu."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 23, 'Sesudah itu tampillah Zedekia bin Kenaana; ditamparnyalah pipi Mikha serta berkata: "Bagaimana mungkin Roh TUHAN pindah dari padaku untuk berbicara kepadamu?"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 24, 'Tetapi Mikha menjawab: "Sesungguhnya engkau akan melihatnya pada hari engkau lari dari satu kamar ke kamar yang lain untuk menyembunyikan diri."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 25, 'Berkatalah raja Israel: "Tangkaplah Mikha, bawa dia kembali kepada Amon, penguasa kota, dan kepada Yoas, anak raja,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 26, 'dan katakan: Beginilah titah raja: Masukkan orang ini dalam penjara dan beri dia makan roti dan minum air serba sedikit sampai aku pulang dengan selamat."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 27, 'Tetapi jawab Mikha: "Jika benar-benar engkau pulang dengan selamat, tentulah TUHAN tidak berfirman dengan perantaraanku!" Lalu disambungnya: "Dengarlah, hai bangsa-bangsa sekalian!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 28, 'Sesudah itu majulah raja Israel dengan Yosafat, raja Yehuda, ke Ramot-Gilead.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 29, 'Raja Israel berkata kepada Yosafat: "Aku akan menyamar dan masuk pertempuran, tetapi engkau, pakailah pakaian kebesaranmu." Lalu menyamarlah raja Israel, kemudian mereka masuk ke pertempuran.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 30, 'Adapun raja negeri Aram telah memberi perintah kepada para panglima pasukan keretanya demikian: "Janganlah kamu berperang melawan sembarang orang, melainkan melawan raja Israel saja."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 31, 'Segera sesudah para panglima pasukan kereta itu melihat Yosafat, mereka berkata: "Itu raja Israel!" Lalu mereka mengepung dia, untuk menyerang dia, tetapi Yosafat berteriak dan TUHAN menolongnya. Allah membujuk mereka pergi dari padanya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 32, 'Segera sesudah para panglima pasukan kereta itu melihat, bahwa dia bukanlah raja Israel, maka undurlah mereka dari padanya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 33, 'Tetapi seseorang menarik panahnya dan menembak dengan sembarangan saja, dan mengenai raja Israel di antara sambungan baju zirahnya. Kemudian ia berkata kepada pengemudi keretanya: "Putar! Bawa aku keluar dari pertempuran, sebab aku sudah luka."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 18, 34, 'Tetapi pertempuran itu bertambah seru pada hari itu, dan raja Israel tetap berdiri di dalam kereta berhadapan dengan orang Aram itu sampai petang. Ia mati ketika matahari terbenam.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 19, 1, 'Yosafat, raja Yehuda, pulang dengan selamat ke istananya di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 19, 2, 'Ketika itu Yehu bin Hanani, pelihat itu, pergi menemuinya dan berkata kepada raja Yosafat: "Sewajarnyakah engkau menolong orang fasik dan bersahabat dengan mereka yang membenci TUHAN? Karena hal itu TUHAN murka terhadap engkau.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 19, 3, 'Namun masih terdapat hal-hal yang baik padamu, karena engkau menghapuskan tiang-tiang berhala dari negeri ini dan mencari Allah dengan tekun."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 19, 4, 'Yosafat diam di Yerusalem. Ia mengadakan kunjungan pula ke daerah-daerah, dari Bersyeba sampai ke pegunungan Efraim, sambil menyuruh rakyat berbalik kepada TUHAN, Allah nenek moyang mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 19, 5, 'Ia mengangkat juga hakim-hakim di seluruh negeri, yakni di semua kota yang berkubu di Yehuda, di tiap-tiap kota.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 19, 6, 'Berpesanlah ia kepada hakim-hakim itu: "Pertimbangkanlah apa yang kamu buat, karena bukanlah untuk manusia kamu memutuskan hukum, melainkan untuk TUHAN, yang ada beserta kamu, bila kamu memutuskan hukum.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 19, 7, 'Sebab itu, kiranya kamu diliputi oleh rasa takut kepada TUHAN. Bertindaklah dengan seksama, karena berlaku curang, memihak ataupun menerima suap tidak ada pada TUHAN, Allah kita."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 19, 8, 'Juga di Yerusalem Yosafat mengangkat beberapa orang dari antara orang Lewi, dari antara para imam dan dari antara para kepala puak Israel untuk memberi keputusan dalam hal hukum TUHAN dan dalam hal perselisihan. Mereka berkedudukan di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 19, 9, 'Ia memerintahkan mereka: "Kamu harus bertindak dengan takut akan TUHAN, dengan setia dan dengan tulus hati, demikian:', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 19, 10, 'Dalam setiap perkara, yang disampaikan kepada kamu oleh rekan-rekanmu yang tinggal di kota-kota, yakni perkara-perkara mengenai penumpahan darah atau mengenai hukum, perintah, ketetapan-ketetapan dan peraturan-peraturan hendaklah kamu memperingatkan mereka, supaya mereka jangan bersalah terhadap TUHAN, sehingga murka-Nya menimpa kamu dan rekan-rekanmu. Hendaklah kamu berbuat demikian, dan kamu tidak akan bersalah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 19, 11, 'Dengan ini imam kepala Amarya diangkat sebagai ketuamu dalam segala perkara ketuhanan dan Zebaja bin Ismael, pemuka kaum Yehuda, dalam segala perkara kerajaan, sedang orang Lewi akan melayani kamu sebagai pengatur. Bertindaklah dengan tegas! Kiranya TUHAN menyertai orang yang tulus ikhlas."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 1, 'Setelah itu bani Moab dan bani Amon datang berperang melawan Yosafat bersama-sama sepasukan orang Meunim.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 2, 'Datanglah orang memberitahukan Yosafat: "Suatu laskar yang besar datang dari seberang Laut Asin, dari Edom, menyerang tuanku. Sekarang mereka di Hazezon-Tamar," yakni En-Gedi.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 3, 'Yosafat menjadi takut, lalu mengambil keputusan untuk mencari TUHAN. Ia menyerukan kepada seluruh Yehuda supaya berpuasa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 4, 'Dan Yehuda berkumpul untuk meminta pertolongan dari pada TUHAN. Mereka datang dari semua kota di Yehuda untuk mencari TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 5, 'Lalu Yosafat berdiri di tengah-tengah jemaah Yehuda dan Yerusalem di rumah TUHAN, di muka pelataran yang baru', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 6, 'dan berkata: "Ya TUHAN, Allah nenek moyang kami, bukankah Engkau Allah di dalam sorga? Bukankah Engkau memerintah atas segenap kerajaan bangsa? Kuasa dan keperkasaan ada di dalam tangan-Mu, sehingga tidak ada orang yang dapat bertahan melawan Engkau.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 7, 'Bukankah Engkau Allah kami yang menghalau penduduk tanah ini dari depan umat-Mu Israel, dan memberikannya kepada keturunan Abraham, sahabat-Mu itu, untuk selama-lamanya?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 8, 'Lalu mereka mendiami tanah itu, dan mendirikan bagi-Mu tempat kudus untuk nama-Mu. Kata mereka:', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 9, 'Bila sesuatu malapetaka menimpa kami, yakni pedang, penghukuman, penyakit sampar atau kelaparan, kami akan berdiri di muka rumah ini, di hadapan-Mu, karena nama-Mu tinggal di dalam rumah ini. Dan kami akan berseru kepada-Mu di dalam kesesakan kami, sampai Engkau mendengar dan menyelamatkan kami.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 10, 'Sekarang, lihatlah, bani Amon dan Moab, dan orang-orang dari pegunungan Seir ini! Ketika orang Israel datang dari tanah Mesir, Engkau melarang mereka memasuki negerinya. Oleh sebab itu mereka menjauhinya dan tidak memusnahkannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 11, 'Lihatlah, sebagai pembalasan mereka datang mengusir kami dari tanah milik yang telah Engkau wariskan kepada kami.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 12, 'Ya Allah kami, tidakkah Engkau akan menghukum mereka? Karena kami tidak mempunyai kekuatan untuk menghadapi laskar yang besar ini, yang datang menyerang kami. Kami tidak tahu apa yang harus kami lakukan, tetapi mata kami tertuju kepada-Mu."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 13, 'Sementara itu seluruh Yehuda berdiri di hadapan TUHAN, juga segenap keluarga mereka dengan isteri dan anak-anak mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 14, 'Lalu Yahaziel bin Zakharia bin Benaya bin Matanya, seorang Lewi dari bani Asaf, dihinggapi Roh TUHAN di tengah-tengah jemaah,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 15, 'dan berseru: "Camkanlah, hai seluruh Yehuda dan penduduk Yerusalem dan tuanku raja Yosafat, beginilah firman TUHAN kepadamu: Janganlah kamu takut dan terkejut karena laskar yang besar ini, sebab bukan kamu yang akan berperang melainkan Allah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 16, 'Besok haruslah kamu turun menyerang mereka. Mereka akan mendaki pendakian Zis, dan kamu akan mendapati mereka di ujung lembah, di muka padang gurun Yeruel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 17, 'Dalam peperangan ini tidak usah kamu bertempur. Hai Yehuda dan Yerusalem, tinggallah berdiri di tempatmu, dan lihatlah bagaimana TUHAN memberikan kemenangan kepadamu. Janganlah kamu takut dan terkejut. Majulah besok menghadapi mereka, TUHAN akan menyertai kamu."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 18, 'Lalu berlututlah Yosafat dengan mukanya ke tanah. Seluruh Yehuda dan penduduk Yerusalempun sujud di hadapan TUHAN dan menyembah kepada-Nya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 19, 'Kemudian orang Lewi dari bani Kehat dan bani Korah bangkit berdiri untuk menyanyikan puji-pujian bagi TUHAN, Allah Israel, dengan suara yang sangat nyaring.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 20, 'Keesokan harinya pagi-pagi mereka maju menuju padang gurun Tekoa. Ketika mereka hendak berangkat, berdirilah Yosafat, dan berkata: "Dengar, hai Yehuda dan penduduk Yerusalem! Percayalah kepada TUHAN, Allahmu, dan kamu akan tetap teguh! Percayalah kepada nabi-nabi-Nya, dan kamu akan berhasil!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 21, 'Setelah ia berunding dengan rakyat, ia mengangkat orang-orang yang akan menyanyi nyanyian untuk TUHAN dan memuji TUHAN dalam pakaian kudus yang semarak pada waktu mereka keluar di muka orang-orang bersenjata, sambil berkata: "Nyanyikanlah nyanyian syukur bagi TUHAN, bahwasanya untuk selama-lamanya kasih setia-Nya!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 22, 'Ketika mereka mulai bersorak-sorai dan menyanyikan nyanyian pujian, dibuat Tuhanlah penghadangan terhadap bani Amon dan Moab, dan orang-orang dari pegunungan Seir, yang hendak menyerang Yehuda, sehingga mereka terpukul kalah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 23, 'Lalu bani Amon dan Moab berdiri menentang penduduk pegunungan Seir hendak menumpas dan memunahkan mereka. Segera sesudah mereka membinasakan penduduk Seir, mereka saling bunuh-membunuh.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 24, 'Ketika orang Yehuda tiba di tempat peninjauan di padang gurun, mereka menengok ke tempat laskar itu. Tampaklah semua telah menjadi bangkai berhantaran di tanah, tidak ada yang terluput.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 25, 'Lalu Yosafat dan orang-orangnya turun untuk menjarah barang-barang mereka. Mereka menemukan banyak ternak, harta milik, pakaian dan barang-barang berharga. Yang mereka rampas itu lebih banyak dari pada yang dapat dibawa. Tiga hari lamanya mereka menjarah barang-barang itu, karena begitu banyaknya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 26, 'Pada hari keempat mereka berkumpul di Lembah Pujian. Di sanalah mereka memuji TUHAN, dan itulah sebabnya orang menamakan tempat itu Lembah Pujian hingga sekarang.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 27, 'Lalu pulanglah sekalian orang Yehuda dan Yerusalem dengan Yosafat di depan. Mereka kembali ke Yerusalem dengan sukacita, karena TUHAN telah membuat mereka bersukacita karena kekalahan musuh mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 28, 'Mereka masuk ke Yerusalem dengan gambus dan kecapi dan nafiri, lalu menuju rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 29, 'Ketakutan yang dari Allah menghinggapi semua kerajaan negeri-negeri lain, ketika mereka mendengar, bahwa TUHAN yang berperang melawan musuh-musuh Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 30, 'Dan kerajaan Yosafat amanlah, karena Allahnya mengaruniakan keamanan kepadanya di segala penjuru.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 31, 'Yosafat memerintah atas Yehuda. Ia berumur tiga puluh lima tahun pada waktu ia menjadi raja dan dua puluh lima tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Azuba, anak Silhi.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 32, 'Ia hidup mengikuti jejak Asa, ayahnya; ia tidak menyimpang dari padanya, dan melakukan apa yang benar di mata TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 33, 'Hanya bukit-bukit pengorbanan tidak dijauhkan. Bangsa itu belum mengarahkan hatinya kepada Allah nenek moyang mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 34, 'Selebihnya dari riwayat Yosafat, dari awal sampai akhir, sesungguhnya semuanya itu tertulis di dalam riwayat Yehu bin Hanani, yang tercantum di dalam kitab raja-raja Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 35, 'Kemudian Yosafat, raja Yehuda, bersekutu dengan Ahazia, raja Israel, yang fasik perbuatannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 36, 'Ia bersekutu dengan Ahazia untuk membuat kapal-kapal yang dapat berlayar ke Tarsis. Kapal-kapal itu dibuat mereka di Ezion-Geber.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 20, 37, 'Tetapi Eliezer bin Dodawa dari Maresa bernubuat terhadap Yosafat, katanya: "Karena engkau bersekutu dengan Ahazia, maka TUHAN akan merobohkan pekerjaanmu." Lalu kapal-kapal itu pecah, dan tak dapat berlayar ke Tarsis.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 1, 'Kemudian Yosafat mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di samping nenek moyangnya di kota Daud. Maka Yoram, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 2, 'Saudara-saudaranya, anak-anak Yosafat, ialah: Azarya, Yehiel, Zakharia, Azariahu, Mikhael dan Sefaca. Mereka semua anak-anak Yosafat, raja Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 3, 'Ayahnya memberikan kepada mereka banyak pemberian, berupa emas dan perak dan barang-barang berharga, juga kota-kota berkubu di Yehuda. Tetapi kedudukan raja diberikannya kepada Yoram, karena dialah anak sulungnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 4, 'Sesudah Yoram memegang pemerintahan atas kerajaan ayahnya dan merasa dirinya kuat, ia membunuh dengan pedang semua saudaranya dan juga beberapa pembesar Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 5, 'Yoram berumur tiga puluh dua tahun pada waktu ia menjadi raja dan delapan tahun lamanya ia memerintah di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 6, 'Ia hidup menurut kelakuan raja-raja Israel seperti yang dilakukan keluarga Ahab, sebab yang menjadi isterinya adalah anak Ahab. Ia melakukan apa yang jahat di mata TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 7, 'Namun demikian, TUHAN tidak mau memusnahkan keluarga Daud oleh karena perjanjian yang diikat-Nya dengan Daud, sesuai dengan yang dijanjikan-Nya, bahwa Ia hendak memberikan keturunan kepadanya dan kepada anak-anaknya untuk selama-lamanya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 8, 'Pada zamannya memberontaklah Edom terhadap kekuasaan Yehuda dan mereka mengangkat seorang raja atas mereka sendiri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 9, 'Maka majulah Yoram dengan panglima-panglimanya serta seluruh keretanya; pada waktu malam bangunlah ia, lalu bersama-sama dengan para panglima pasukan kereta ia menerobos barisan orang Edom yang mengepung dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 10, 'Demikianlah Edom memberontak kekuasaan Yehuda dan terlepas sampai sekarang ini. Lalu Libnapun memberontak terhadap kekuasaannya pada masa itu juga. Itu disebabkan karena ia telah meninggalkan TUHAN, Allah nenek moyangnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 11, 'Lagipula ia membuat bukit-bukit pengorbanan di gunung-gunung Yehuda. Ia membujuk penduduk Yerusalem untuk berzinah dan ia menyesatkan Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 12, 'Lalu sampailah kepadanya sebuah surat dari nabi Elia yang bunyinya: "Beginilah firman TUHAN, Allah Daud, bapa leluhurmu: Karena engkau tidak hidup mengikuti jejak Yosafat, ayahmu, dan Asa, raja Yehuda,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 13, 'melainkan hidup menurut kelakuan raja-raja Israel dan membujuk Yehuda dan penduduk-penduduk Yerusalem untuk berzinah, sama seperti yang dilakukan keluarga Ahab, dan juga karena engkau telah membunuh saudara-saudaramu, seluruh keluarga ayahmu yang lebih baik dari padamu,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 14, 'maka TUHAN akan mendatangkan tulah besar atas rakyatmu, anak-anakmu, isteri-isterimu, dan atas semua harta milikmu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 15, 'Dan engkau sendiri akan menderita penyakit yang dahsyat, suatu penyakit usus, hingga selang beberapa waktu ususmu keluar oleh karena penyakit itu."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 16, 'Lalu TUHAN menggerakkan hati orang Filistin dan orang Arab yang tinggal berdekatan dengan orang Etiopia untuk melawan Yoram.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 17, 'Maka mereka maju melawan Yehuda, memasukinya dan mengangkut segala harta milik yang terdapat di dalam istana raja sebagai jarahan, juga anak-anak dan isteri-isterinya, sehingga tidak ada seorang anak yang tinggal padanya kecuali Yoahas, anaknya yang bungsu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 18, 'Sesudah semuanya ini TUHAN menulahinya dengan penyakit usus yang tidak dapat sembuh.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 19, 'Beberapa waktu berselang, kira-kira sesudah lewat dua tahun, keluarlah ususnya karena penyakitnya itu, lalu ia mati dengan penderitaan yang hebat. Rakyatnya tidak menyalakan api baginya seperti yang diperbuat mereka bagi nenek moyangnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 21, 20, 'Ia berumur tiga puluh dua tahun pada waktu ia menjadi raja dan delapan tahun lamanya ia memerintah di Yerusalem. Ia meninggal dengan tidak dicintai orang. Ia dikuburkan di kota Daud, tetapi tidak di dalam pekuburan raja-raja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 22, 1, 'Lalu penduduk Yerusalem mengangkat Ahazia, anaknya yang bungsu, menjadi raja menggantikan dia, karena semua anaknya yang lebih tua umurnya telah dibunuh oleh gerombolan yang datang ke tempat perkemahan bersama-sama orang-orang Arab. Dengan demikian Ahazia, anak Yoram raja Yehuda, menjadi raja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 22, 2, 'Ahazia berumur empat puluh dua tahun pada waktu ia menjadi raja dan setahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Atalya, cucu Omri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 22, 3, 'Iapun hidup menurut kelakuan keluarga Ahab, karena ibunya menasihatinya untuk melakukan yang jahat.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 22, 4, 'Ia melakukan apa yang jahat di mata TUHAN sama seperti keluarga Ahab, sebab sesudah ayahnya mati mereka menjadi penasihat-penasihatnya yang mencelakakannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 22, 5, 'Atas nasihat mereka pula ia pergi bersama-sama Yoram bin Ahab, raja Israel, untuk berperang melawan Hazael, raja Aram, di Ramot-Gilead. Tetapi orang-orang Aram melukai Yoram.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 22, 6, 'Kemudian pulanglah ia ke Yizreel untuk diobati oleh karena luka-luka yang didapatnya di Rama pada waktu ia berperang melawan Hazael, raja Aram. Dan Ahazia, anak Yoram raja Yehuda, pergi menjenguk Yoram bin Ahab di Yizreel, karena dia sakit.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 22, 7, 'Telah ditentukan Allah, bahwa Ahazia akan menemui ajalnya pada waktu ia mengunjungi Yoram; maka ketika Ahazia datang, pergilah ia bersama-sama Yoram mendapatkan Yehu, cucu Nimsi, yang telah diurapi TUHAN, supaya dialah yang melenyapkan keluarga Ahab.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 22, 8, 'Sementara Yehu melakukan penghukuman atas keluarga Ahab, ia menjumpai pembesar-pembesar Yehuda dan anak-anak saudara-saudara Ahazia, yang melayani Ahazia. Juga mereka dibunuhnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 22, 9, 'Lalu ia mencari Ahazia; Ahazia tertangkap ketika ia bersembunyi di Samaria. Ia dibawa kepada Yehu, lalu dibunuh, tetapi dikuburkan juga, karena kata orang: "Dia ini cucu Yosafat, yang mencari TUHAN dengan segenap hatinya." Dari keluarga Ahazia tidak ada lagi yang sanggup memerintah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 22, 10, 'Ketika Atalya, ibu Ahazia, melihat bahwa anaknya sudah mati, maka bangkitlah ia membinasakan semua keturunan raja dari kaum Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 22, 11, 'Tetapi Yosabat, anak perempuan raja, mengambil Yoas bin Ahazia, menculik dia dari tengah-tengah anak-anak raja yang hendak dibunuh itu, memasukkan dia dengan inang penyusunya ke dalam gudang tempat tidur. Demikianlah Yosabat, anak perempuan raja Yoram, isteri imam Yoyada, ?ia adalah saudara perempuan Ahazia?menyembunyikan dia terhadap Atalya, sehingga ia tidak dibunuh Atalya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 22, 12, 'Maka tinggallah Yoas enam tahun lamanya bersama-sama mereka dengan bersembunyi di rumah Allah, sementara Atalya memerintah negeri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 1, 'Tetapi dalam tahun ketujuh Yoyada memberanikan diri dan ia mengadakan persepakatan dengan para kepala pasukan seratus, yakni: Azarya bin Yeroham, Ismael bin Yohanan, Azarya bin Obed. Maaseya bin Adaya, dan Elisafat bin Zikhri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 2, 'Mereka mengelilingi Yehuda dan mengumpulkan orang-orang Lewi dari semua kota di Yehuda serta kepala-kepala puak orang Israel, dan mereka semua datang ke Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 3, 'Lalu seluruh jemaah itu mengikat perjanjian dengan raja di rumah Allah. Kata Yoyada kepada mereka: "Lihatlah, anak raja! Biarlah ia memerintah, seperti yang telah difirmankan TUHAN tentang anak-anak Daud!', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 4, 'Inilah yang harus kamu lakukan: sepertiga dari kamu, yakni yang selesai bertugas pada hari Sabat, baik imam maupun orang Lewi, haruslah menjadi penunggu pintu,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 5, 'sepertiga lagi haruslah berada di istana raja, dan sepertiga pula di pintu gerbang Dasar, sedang seluruh rakyat haruslah berada di pelataran rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 6, 'Siapapun tidak boleh memasuki rumah TUHAN selain dari pada para imam dan orang-orang Lewi yang bertugas. Mereka boleh masuk, karena mereka kudus, tetapi seluruh rakyat haruslah mentaati peraturan TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 7, 'Dalam pada itu orang-orang Lewi haruslah mengelilingi raja dari segala penjuru, masing-masing dengan senjatanya di tangannya, dan siapa yang memasuki rumah itu haruslah dibunuh. Dan baiklah kamu menyertai raja setiap kali ia keluar atau masuk."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 8, 'Orang-orang Lewi dan seluruh Yehuda melakukan tepat seperti yang diperintahkan imam Yoyada. Masing-masing mengambil orang-orangnya yang selesai bertugas pada hari Sabat bersama-sama dengan orang-orang yang masuk bertugas pada hari itu, karena imam Yoyada tidak membebaskan rombongan-rombongan itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 9, 'Lalu imam Yoyada memberikan kepada para kepala pasukan seratus itu tombak-tombak, utar-utar dan perisai-perisai kepunyaan raja Daud yang ada di rumah Allah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 10, 'Ia menempatkan seluruh rakyat, masing-masing dengan lembing di tangannya, di lambung kanan sampai ke lambung kiri rumah itu, dengan mengelilingi mezbah dan rumah itu untuk melindungi raja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 11, 'Sesudah itu Yoyada dan anak-anaknya membawa anak raja itu ke luar, mengenakan jejamang kepadanya dan memberikan hukum Allah kepadanya. Mereka menobatkan dia menjadi raja serta mengurapinya, lalu berserulah rakyat: "Hiduplah raja!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 12, 'Ketika Atalya mendengar pekik rakyat yang berlari-lari menyambut raja dan memuji-muji dia, pergilah ia mendapatkan rakyat itu ke dalam rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 13, 'Lalu dilihatnyalah raja berdiri dekat tiangnya pada jalan masuk, sedang para pemimpin dengan para pemegang nafiri ada dekat raja. Dan seluruh rakyat negeri bersukaria sambil meniup nafiri, sedang para penyanyi dengan alat-alat musik mereka, memimpin nyanyian puji-pujian. Maka Atalya mengoyakkan pakaiannya sambil berkata: "Khianat, khianat!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 14, 'Tetapi imam Yoyada menyuruh keluar para kepala pasukan seratus, yakni orang-orang yang mengepalai tentara, katanya kepada mereka: "Bawalah dia keluar dari antara barisan! Siapa yang memihak kepadanya harus dibunuh dengan pedang!" Sebab imam itu telah berkata tadinya: "Jangan kamu membunuhnya di rumah TUHAN!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 15, 'Lalu mereka menangkap perempuan itu. Pada waktu ia sampai ke jalan masuk istana raja pada pintu gerbang Kuda, dibunuhlah ia di situ.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 16, 'Kemudian Yoyada mengikat perjanjian antara dia dengan segenap rakyat dan raja, bahwa mereka menjadi umat TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 17, 'Sesudah itu masuklah seluruh rakyat ke rumah Baal, lalu merobohkannya; mereka memecahkan mezbah-mezbahnya dan patung-patungnya dan membunuh Matan, imam Baal, di depan mezbah-mezbah itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 18, 'Kemudian Yoyada menyerahkan pengawasan atas rumah TUHAN kepada imam-imam dan orang-orang Lewi, yang telah dibagi-bagi dalam rombongan oleh Daud untuk bertugas di dalam rumah TUHAN, yakni untuk mempersembahkan korban bakaran kepada TUHAN?seperti tertulis di dalam Taurat Musa?dengan sukaria dan dengan nyanyian menurut petunjuk Daud.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 19, 'Juga ditempatkannya penunggu-penunggu pintu pada pintu-pintu gerbang rumah TUHAN, supaya dalam hal apapun juga jangan masuk seseorang yang najis.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 20, 'Sesudah itu ia mengajak para kepala pasukan seratus, para pemuka, para pemerintah rakyat dan seluruh rakyat negeri, lalu membawa raja turun dari rumah TUHAN; mereka masuk ke istana raja melalui pintu gerbang Atas, lalu mendudukkan raja ke atas takhta kerajaan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 23, 21, 'Bersukarialah seluruh rakyat negeri dan amanlah kota itu, setelah Atalya mati dibunuh dengan pedang.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 1, 'Yoas berumur tujuh tahun pada waktu ia menjadi raja, dan empat puluh tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Zibya, dari Bersyeba.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 2, 'Yoas melakukan apa yang benar di mata TUHAN selama hidup imam Yoyada.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 3, 'Yoyada mengambil dua orang isteri bagi dia; dari mereka ia mendapat anak laki-laki dan anak perempuan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 4, 'Kemudian Yoas bermaksud untuk membaharui rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 5, 'Ia mengumpulkan para imam dan orang Lewi dan berkata kepada mereka: "Pergilah kamu ke kota-kota Yehuda dan kumpulkanlah uang dari seluruh orang Israel untuk memperbaiki rumah Allahmu setiap tahun. Lakukanlah hal itu dengan segera!" Tetapi orang Lewi itu tidak melakukannya dengan segera.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 6, 'Lalu raja memanggil imam kepala Yoyada dan bertanya kepadanya: "Mengapa engkau tidak menuntut kepada orang-orang Lewi untuk membawa dari Yehuda dan dari Yerusalem pajak yang dikenakan Musa, hamba Allah itu, kepada jemaah Israel untuk Kemah tempat hukum Allah?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 7, 'Sebab anak-anak Atalya, perempuan fasik itu, telah membongkar rumah Allah, bahkan memakai barang-barang kudus rumah TUHAN untuk para Baal."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 8, 'Sesudah itu raja memerintahkan supaya dibuat sebuah peti dan ditempatkan di depan pintu gerbang rumah TUHAN,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 9, 'lalu menyuruh mengumumkan di Yehuda dan di Yerusalem, bahwa orang harus membawa bagi TUHAN pajak yang dikenakan Musa, hamba Allah itu, kepada orang Israel di padang gurun.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 10, 'Maka bersukacitalah semua pemimpin dan seluruh rakyat; mereka datang membawa pajaknya dan memasukkannya ke dalam peti itu sampai penuh.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 11, 'Setiap kali peti itu dibawa masuk untuk diperiksa oleh orang-orang Lewi atas nama raja, dan apabila mereka melihat bahwa sudah banyak uang di dalamnya, maka datanglah panitera raja dan kuasa usaha imam kepala mengeluarkan isi peti itu; kemudian mereka mengangkat peti itu, lalu menaruhnya pula di tempatnya. Demikianlah mereka lakukan setiap kali, dan banyaklah uang yang dikumpulkan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 12, 'Raja dan Yoyada menyerahkan uang itu kepada mereka yang memanduri pekerjaan pada rumah TUHAN. Mereka ini mengupah tukang-tukang pahat dan tukang-tukang kayu untuk membaharui rumah TUHAN; juga tukang-tukang besi dan tembaga untuk memperbaiki rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 13, 'Setelah itu mulailah tukang-tukang itu bekerja; pekerjaan perbaikan maju di bawah tangan mereka. Mereka membangun kembali rumah Allah menurut keadaannya semula dan mengokohkannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 14, 'Setelah mereka selesai, mereka membawa uang yang kelebihan kepada raja dan Yoyada. Uang itu dipakai untuk membuat perkakas-perkakas rumah TUHAN, yakni: perkakas-perkakas untuk penyelenggaraan kebaktian, perkakas-perkakas untuk korban bakaran, juga cawan-cawan dan perkakas-perkakas emas dan perak. Sepanjang umur Yoyada korban bakaran tetap dipersembahkan dalam rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 15, 'Yoyada menjadi tua, dan lanjut umur, lalu matilah ia. Seratus tiga puluh tahun umurnya ketika ia mati.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 16, 'Ia dikuburkan di kota Daud di samping raja-raja, karena perbuatan-perbuat yang baik di Israel terhadap Allah dan rumah-Nya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 17, 'Sesudah Yoyada mati, pemimpin-pemimpin Yehuda datang menyembah kepada raja. Sejak itu raja mendengarkan mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 18, 'Mereka meninggalkan rumah TUHAN, Allah nenek moyang mereka, lalu beribadah kepada tiang-tiang berhala dan patung-patung berhala. Oleh karena kesalahan itu Yehuda dan Yerusalem tertimpa murka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 19, 'Namun TUHAN mengutus nabi-nabi kepada mereka, supaya mereka berbalik kepada-Nya. Nabi-nabi itu sungguh-sungguh memperingatkan mereka, tetapi mereka tidak mau mendengarkannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 20, 'Lalu Roh Allah menguasai Zakharia, anak imam Yoyada. Ia tampil di depan rakyat, dan berkata kepada mereka: "Beginilah firman Allah: Mengapa kamu melanggar perintah-perintah TUHAN, sehingga kamu tidak beruntung? Oleh karena kamu meninggalkan TUHAN, Iapun meninggalkan kamu!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 21, 'Tetapi mereka mengadakan persepakatan terhadap dia, dan atas perintah raja mereka melontari dia dengan batu di pelataran rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 22, 'Raja Yoas tidak mengingat kesetiaan yang ditunjukkan Yoyada, ayah Zakharia itu, terhadap dirinya. Ia membunuh anak Yoyada itu, yang pada saat kematiannya berseru: "Semoga TUHAN melihatnya dan menuntut balas!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 23, 'Pada pergantian tahun tentara Aram maju menyerang Yoas dan masuk ke Yehuda dan Yerusalem. Dari bangsa itu semua pemimpin habis dibunuh mereka dan segala jarahan dikirim mereka kepada raja negeri Damsyik.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 24, 'Walaupun tentara Aram itu datang dengan sedikit orang, namun TUHAN menyerahkan tentara yang sangat besar kepada mereka, karena orang Yehuda telah meninggalkan TUHAN, Allah nenek moyang mereka. Demikianlah orang Aram melakukan penghukuman kepada Yoas.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 25, 'Ketika mereka pergi dari padanya, ?mereka meninggalkannya dengan luka-luka berat?pegawai-pegawainya mengadakan persepakatan terhadap dia karena darah anak imam Yoyada itu, lalu membunuhnya di atas tempat tidurnya. Ia mati dan dikuburkan di kota Daud, tetapi tidak di pekuburan raja-raja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 26, 'Mereka yang mengadakan persepakatan terhadap dia ialah: Zabad, anak Simeat perempuan Amon, dan Yozabad, anak Simrit perempuan Moab.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 24, 27, 'Tentang anak-anaknya dan ucapan-ucapan ilahi yang banyak terhadap dia, serta tentang perbaikan rumah Allah, semua itu tertulis dalam tafsiran kitab raja-raja. Maka Amazia, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 1, 'Amazia berumur dua puluh lima tahun pada waktu ia menjadi raja dan dua puluh sembilan tahun lamanya ia memerintah di Yerusalem; nama ibunya ialah Yoadan, dari Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 2, 'Ia melakukan apa yang benar di mata TUHAN, hanya tidak dengan segenap hati.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 3, 'Segera sesudah kuasa kerajaan itu kokoh di tangannya, dibunuhnyalah pegawai-pegawainya yang telah membunuh raja, yaitu ayahnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 4, 'Tetapi anak-anak mereka tidak dihukum mati olehnya, melainkan ia bertindak sesuai dengan apa yang tertulis dalam Taurat, yakni kitab Musa, di mana TUHAN telah memberi perintah: "Janganlah ayah mati karena anaknya, janganlah juga anak mati karena ayahnya, melainkan setiap orang harus mati karena dosanya sendiri."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 5, 'Lalu Amazia mengumpulkan orang Yehuda dan menyuruh mereka, yakni seluruh orang Yehuda dan Benyamin, berdiri menurut puak-puaknya di bawah kepala-kepala pasukan seribu dan kepala-kepala pasukan seratus. Ketika ia menghitung mereka yang berumur dua puluh tahun ke atas, didapatinya tiga ratus ribu teruna yang sanggup keluar berperang dengan tombak dan perisai.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 6, 'Selain itu ia menyewa seratus ribu pahlawan yang gagah perkasa dari Israel dengan bayaran seratus talenta perak.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 7, 'Tetapi seorang abdi Allah datang kepadanya dan berkata: "Ya raja, janganlah tentara Israel dibiarkan bergabung kepada tuanku, karena TUHAN tidak menyertai Israel, yakni semua bani Efraim ini.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 8, 'Dan jikalau mereka bergabung juga, bagaimanapun juga perbuatan dan kekuatanmu di dalam perang, Allah akan menggelincirkan engkau di depan musuh, sebab Allah mempunyai kuasa untuk menolong dan menggelincirkan!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 9, 'Lalu kata Amazia kepada abdi Allah itu: "Bagaimana dengan seratus talenta yang telah kuberikan kepada pasukan-pasukan Israel itu?" Jawab abdi Allah itu: "TUHAN dapat memberikan lebih dari pada itu kepadamu!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 10, 'Kemudian Amazia memisahkan pasukan yang datang bergabung kepadanya dari Efraim, supaya mereka kembali ke tempat tinggalnya. Maka sangat marahlah mereka terhadap Yehuda. Mereka kembali ke tempat tinggalnya dengan marah yang menyala-nyala.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 11, 'Amazia mendapat keberanian lalu memimpin rakyatnya ke Lembah Asin dan memukul kalah sepuluh ribu orang dari bani Seir.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 12, 'Selain itu sepuluh ribu orang ditawan hidup-hidup oleh bani Yehuda dan dibawa ke suatu puncak bukit batu, lalu mereka dicampakkan dari puncak bukit batu itu, sehingga hancurlah mereka semua.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 13, 'Tetapi orang-orang dari pasukan yang dipulangkan Amazia, dan yang tidak diperbolehkan ikut berperang dengan dia, menyerbu kota-kota di Yehuda dari jurusan Samaria sampai ke Bet-Horon, dan menewaskan tiga ribu orang penduduknya dan merampas banyak jarahan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 14, 'Ketika Amazia kembali, setelah mengalahkan orang-orang Edom itu, ia mendirikan para allah bani Seir, yang dibawanya pulang, sebagai allahnya. Ia sujud menyembah kepada allah-allah itu dan membakar korban untuk mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 15, 'Maka bangkitlah murka TUHAN terhadap Amazia; Ia menyuruh seorang nabi kepadanya yang berkata: "Mengapa engkau mencari allah sesuatu bangsa yang tidak dapat melepaskan bangsanya sendiri dari tanganmu?"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 16, 'Waktu nabi sedang berbicara, berkatalah Amazia kepadanya: "Apakah kami telah mengangkat engkau menjadi penasihat raja? Diamlah! Apakah engkau mau dibunuh?" Lalu diamlah nabi itu setelah berkata: "Sekarang aku tahu, bahwa Allah telah menentukan akan membinasakan engkau, karena engkau telah berbuat hal ini, dan tidak mendengarkan nasihatku!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 17, 'Kemudian Amazia, raja Yehuda, mengadakan perundingan, lalu menyuruh orang kepada Yoas bin Yoahas bin Yehu, raja Israel, mengatakan: "Mari kita mengadu tenaga!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 18, 'Tetapi Yoas, raja Israel, menyuruh orang kepada Amazia, raja Yehuda, mengatakan: "Onak yang di gunung Libanon mengirim pesan kepada pohon aras yang di gunung Libanon, bunyinya: Berikanlah anakmu perempuan kepada anakku laki-laki menjadi isterinya. Tetapi binatang-binatang hutan yang ada di gunung Libanon itu berjalan lewat dari sana, lalu menginjak onak itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 19, 'Pikirmu, engkau sudah mengalahkan Edom, sebab itu hatimu mengangkat-angkat dirimu untuk mendapat kehormatan. Sekarang, tinggal saja di rumah. Untuk apa engkau menantang malapetaka, sehingga engkau jatuh dan Yehuda bersama-sama engkau?"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 20, 'Tetapi Amazia tidak mau mendengarkan; sebab hal itu telah ditetapkan Allah yang hendak menyerahkan mereka ke dalam tangan Yoas, karena mereka telah mencari allah orang Edom.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 21, 'Sebab itu majulah Yoas, raja Israel, lalu mengadu tenagalah mereka, ia dan Amazia, raja Yehuda, di Bet-Semes yang termasuk wilayah Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 22, 'Yehuda terpukul kalah oleh Israel, sehingga masing-masing lari ke kemahnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 23, 'Yoas, raja Israel, menangkap Amazia, raja Yehuda, anak Yoas bin Yoahas, di Bet-Semes. Lalu Yoas membawa dia ke Yerusalem. Ia membongkar tembok Yerusalem dari Pintu Gerbang Efraim sampai ke Pintu Gerbang Sudut, empat ratus hasta panjangnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 24, 'Sesudah itu ia mengambil segala emas dan perak dan segala perkakas yang terdapat dalam rumah Allah dan yang berada di bawah pengawasan keluarga Obed-Edom, juga perbendaharaan istana raja dan orang-orang sandera, kemudian pulanglah ia ke Samaria.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 25, 'Amazia bin Yoas, raja Yehuda, masih hidup lima belas tahun lamanya sesudah Yoas bin Yoahas, raja Israel, mati.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 26, 'Selebihnya dari riwayat Amazia, dari awal sampai akhir, bukankah semuanya itu tertulis dalam kitab raja-raja Yehuda dan Israel?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 27, 'Sejak Amazia menjauhi TUHAN, orang mengadakan persepakatan melawan dia di Yerusalem, sebab itu larilah ia ke Lakhis. Tetapi mereka menyuruh mengejar dia ke Lakhis, lalu dibunuhlah ia di sana.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 25, 28, 'Ia diangkut dengan kuda, lalu dikuburkan di samping nenek moyangnya di kota Daud.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 1, 'Segenap bangsa Yehuda mengambil Uzia, yang masih berumur enam belas tahun dan menobatkan dia menjadi raja menggantikan ayahnya, Amazia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 2, 'Ia memperkuat Elot dan mengembalikannya kepada Yehuda, sesudah raja mendapat perhentian bersama-sama dengan nenek moyangnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 3, 'Uzia berumur enam belas tahun pada waktu ia menjadi raja dan lima puluh dua tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Yekholya, dari Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 4, 'Ia melakukan apa yang benar di mata TUHAN, tepat seperti yang dilakukan Amazia, ayahnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 5, 'Ia mencari Allah selama hidup Zakharia, yang mengajarnya supaya takut akan Allah. Dan selama ia mencari TUHAN, Allah membuat segala usahanya berhasil.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 6, 'Maka majulah ia berperang melawan orang-orang Filistin dan membongkar tembok Gat, Yabne dan Asdod, lalu mendirikan kota-kota di sekitar Asdod dan di lain-lain wilayah orang Filistin.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 7, 'Allah menolongnya terhadap orang Filistin, dan terhadap orang Arab yang tinggal di Gur-Baal, dan terhadap orang Meunim.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 8, 'Orang-orang Amon membayar upeti kepada Uzia. Namanya termasyhur sampai ke Mesir, karena kekuatannya yang besar.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 9, 'Uzia mendirikan menara di Yerusalem di atas Pintu Gerbang Sudut di atas Pintu Gerbang Lebak dan di atas Penjuru, serta mengokohkannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 10, 'Ia mendirikan juga menara-menara di padang gurun dan menggali banyak sumur, karena banyak ternaknya, baik di Dataran Rendah maupun di Dataran Tinggi. Juga ia mempunyai petani-petani dan penjaga-penjaga kebun anggur, di gunung-gunung dan di tanah yang subur, karena ia suka pada pertanian.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 11, 'Selain itu Uzia mempunyai tentara yang sanggup berperang, yang maju berperang dalam laskar-laskar menurut jumlah anak buah yang dicatat oleh panitera Yeiel dan penata usaha Maaseya, di bawah pimpinan Hananya, salah seorang panglima raja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 12, 'Kepala-kepala puak pahlawan-pahlawan yang gagah perkasa itu seluruhnya berjumlah dua ribu enam ratus orang.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 13, 'Di bawah pimpinan mereka terdapat satu balatentara, terdiri dari tiga ratus tujuh ribu lima ratus orang yang gagah perkasa dalam berperang, untuk membantu raja dalam menghadapi musuh.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 14, 'Uzia memperlengkapi seluruh tentara itu dengan perisai, tombak, ketopong, baju zirah, busur dan batu umban.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 15, 'Ia membuat juga di Yerusalem alat-alat perang, ciptaan seorang ahli, yang dapat menembakkan anak panah dan batu besar, untuk ditempatkan di atas menara-menara dan penjuru-penjuru. Nama raja itu termasyhur sampai ke negeri-negeri yang jauh, karena ia ditolong dengan ajaib sehingga menjadi kuat.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 16, 'Setelah ia menjadi kuat, ia menjadi tinggi hati sehingga ia melakukan hal yang merusak. Ia berubah setia kepada TUHAN, Allahnya, dan memasuki bait TUHAN untuk membakar ukupan di atas mezbah pembakaran ukupan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 17, 'Tetapi imam Azarya mengikutinya dari belakang bersama-sama delapan puluh imam TUHAN, orang-orang yang tegas;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 18, 'mereka berdiri di depan raja Uzia dan berkata kepadanya: "Hai, Uzia, engkau tidak berhak membakar ukupan kepada TUHAN, hanyalah imam-imam keturunan Harun yang telah dikuduskan yang berhak membakar ukupan! Keluarlah dari tempat kudus ini, karena engkau telah berubah setia! Engkau tidak akan memperoleh kehormatan dari TUHAN Allah karena hal ini."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 19, 'Tetapi Uzia, dengan bokor ukupan di tangannya untuk dibakar menjadi marah. Sementara amarahnya meluap terhadap para imam, timbullah penyakit kusta pada dahinya di hadapan para imam di rumah TUHAN, dekat mezbah pembakaran ukupan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 20, 'Imam kepala Azarya dan semua imam lainnya memandang kepadanya, dan sesungguhnya, ia sakit kusta pada dahinya. Cepat-cepat mereka mengusirnya dari sana, dan ia sendiri tergesa-gesa keluar, karena TUHAN telah menimpakan tulah kepadanya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 21, 'Raja Uzia sakit kusta sampai kepada hari matinya, dan sebagai orang yang sakit kusta ia tinggal dalam sebuah rumah pengasingan, karena ia dikucilkan dari rumah TUHAN. Dan Yotam, anaknya, mengepalai istana raja dan menjalankan pemerintahan atas rakyat negeri itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 22, 'Selebihnya dari riwayat Uzia, dari awal sampai akhir, ditulis oleh nabi Yesaya bin Amos.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 26, 23, 'Kemudian Uzia mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di samping nenek moyangnya di ladang dekat pekuburan raja-raja, karena ia berpenyakit kusta, kata orang. Maka Yotam, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 27, 1, 'Yotam berumur dua puluh lima tahun pada waktu ia menjadi raja dan enam belas tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Yerusa, anak Zadok.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 27, 2, 'Ia melakukan apa yang benar di mata TUHAN, tepat seperti yang dilakukan Uzia, ayahnya, hanya ia tidak memasuki Bait TUHAN. Tetapi rakyat masih saja melakukan hal yang merusak.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 27, 3, 'Ia mendirikan Pintu Gerbang Tinggi di rumah TUHAN dan mengadakan banyak pembangunan pada tembok Ofel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 27, 4, 'Ia mendirikan juga kota-kota di pegunungan Yehuda dan benteng-benteng serta menara-menara di hutan-hutan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 27, 5, 'Ia berperang melawan raja bani Amon dan mengalahkannya, sehingga pada tahun itu juga bani Amon membayar kepadanya seratus talenta perak, sepuluh ribu kor gandum dan sepuluh ribu kor jelai. Juga pada tahun kedua dan ketiga bani Amon membawa upeti itu kepadanya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 27, 6, 'Yotam menjadi kuat, karena ia mengarahkan hidupnya kepada TUHAN, Allahnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 27, 7, 'Selebihnya dari riwayat Yotam, segala peperangan dan tingkah langkahnya, sesungguhnya semuanya itu tertulis dalam kitab raja-raja Israel dan Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 27, 8, 'Ia berumur dua puluh lima tahun pada waktu ia menjadi raja dan enam belas tahun lamanya ia memerintah di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 27, 9, 'Kemudian Yotam mendapat perhentian bersama-sama nenek moyangnya, dan ia dikuburkan di kota Daud. Maka Ahas, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 1, 'Ahas berumur dua puluh tahun pada waktu ia menjadi raja dan enam belas tahun lamanya ia memerintah di Yerusalem. Ia tidak melakukan apa yang benar di mata TUHAN seperti Daud, bapa leluhurnya,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 2, 'tetapi ia hidup menurut kelakuan raja-raja Israel, bahkan ia membuat patung-patung tuangan untuk para Baal.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 3, 'Ia membakar juga korban di Lebak Ben-Hinom dan membakar anak-anaknya sebagai korban dalam api, sesuai dengan perbuatan keji bangsa-bangsa yang telah dihalaukan TUHAN dari depan orang Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 4, 'Ia mempersembahkan dan membakar korban di bukit-bukit pengorbanan dan di atas tempat-tempat yang tinggi dan di bawah setiap pohon yang rimbun.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 5, 'Sebab itu TUHAN, Allahnya, menyerahkannya ke dalam tangan raja orang Aram. Mereka mengalahkan dia dan menawan banyak orang dari padanya, yang diangkut ke Damsyik. Kemudian ia diserahkan pula ke dalam tangan raja Israel dan mengalami kekalahan yang besar.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 6, 'Sebab dalam sehari Pekah bin Remalya menewaskan di Yehuda seratus dua puluh ribu orang, semuanya orang-orang yang tangkas, oleh karena mereka telah meninggalkan TUHAN, Allah nenek moyang mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 7, 'Dan Zikhri, pahlawan dari Efraim, membunuh Maaseya, anak raja, Azrikam, kepala istana, dan Elkana orang kedua di bawah raja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 8, 'Orang Israel menawan dari saudara-saudaranya dua ratus ribu orang, yakni perempuan-perempuan serta anak-anak lelaki dan anak-anak perempuan. Mereka merampas juga banyak harta milik dari pada orang-orang itu, dan membawa rampasan itu ke Samaria.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 9, 'Tetapi di sana ada seorang nabi TUHAN yang bernama Oded. Ia pergi menemui tentara yang pulang ke Samaria dan berkata kepada mereka: "Lihatlah, karena kehangatan murka-Nya kepada Yehuda, TUHAN, Allah nenek moyangmu, menyerahkan mereka ke dalam tanganmu, dan kamu telah mengadakan pembunuhan di antara mereka dengan kegeraman yang sampai ke langit.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 10, 'Dan sekarang kamu bermaksud menaklukkan orang Yehuda dan Yerusalem menjadi hambamu laki-laki dan perempuan. Tidak adakah pada kamu sendiri kesalahan yang besar terhadap TUHAN, Allahmu?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 11, 'Maka sekarang, dengarkanlah kataku ini: kembalikanlah orang-orang yang kamu tawan dari saudara-saudaramu itu, karena murka Allah menyala-nyala terhadap kamu."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 12, 'Lalu bangkitlah beberapa pemimpin bani Efraim, yakni: Azarya bin Yohanan, Berekhya bin Mesilemot, Yehizkia bin Salum dan Amasa bin Hadlai menghadapi orang-orang yang pulang dari perang,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 13, 'dan berkata kepada mereka: "Jangan bawa tawanan-tawanan itu ke mari, sebab maksudmu itu menjadikan kita bersalah terhadap TUHAN dan menambah dosa dan kesalahan kita! Sudah cukup besar kesalahan kita, dan murka yang menyala-nyala telah menimpa Israel."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 14, 'Lalu orang-orang yang bersenjata itu meninggalkan tawanan dan barang-barang rampasannya di muka para pemimpin dan seluruh jemaah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 15, 'Dan orang-orang yang ditunjuk dengan disebut namanya bangkit, lalu menjemput para tawanan itu. Semua orang yang telanjang mereka berikan pakaian dari rampasan itu. Orang-orang itu diberi pakaian, kasut, makanan dan minuman. Mereka diurapi dengan minyak dan semua yang terlalu payah untuk berjalan diangkut dengan keledai, dan dibawa ke Yerikho, ke kota pohon korma, dekat saudara-saudara mereka. Sesudah itu orang Israel itu pulang ke Samaria.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 16, 'Pada waktu itu raja Ahas menyuruh utusan kepada raja negeri Asyur untuk memohon bantuan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 17, 'Karena orang Edom telah datang pula dan mengalahkan Yehuda serta mengangkut tawanan-tawanan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 18, 'Orang-orang Filistin juga telah menyerbu kota-kota di Daerah Bukit dan di Tanah Negeb Yehuda. Merekapun merebut Bet-Semes, Ayalon, Gederot, Sokho dengan segala anak kotanya, Timna dengan segala anak kotanya dan Gomzo dengan segala anak kotanya, dan menetap di kota-kota itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 19, 'Demikianlah TUHAN merendahkan Yehuda oleh karena Ahas, raja Israel itu, membiarkan kebiadaban berlaku di Yehuda dan berubah setia kepada TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 20, 'Maka datanglah Tilgat-Pilneser, raja negeri Asyur, kepadanya, hanya bukan membantu dia, melainkan menyesakkannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 21, 'Walaupun Ahas merampas barang-barang dari rumah TUHAN, dari rumah raja dan dari rumah-rumah para pemimpin dan menyerahkan semua itu kepada raja negeri Asyur, namun perbuatannya itu tidak menguntungkan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 22, 'Dalam keadaan terdesak itu raja Ahas ini, malah semakin berubah setia terhadap TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 23, 'Ia mempersembahkan korban kepada para allah orang Damsyik yang telah mengalahkan dia. Pikirnya: "Yang membantu raja-raja orang Aram adalah para allah mereka; kepada merekalah aku akan mempersembahkan korban, supaya mereka membantu aku juga." Tetapi allah-allah itulah yang menjadi sebab keruntuhan bagi dia dan bersama-sama dengan dia bagi seluruh Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 24, 'Ahas mengumpulkan perkakas-perkakas rumah Allah dan menghancurkannya. Ia menutup pintu rumah TUHAN, lalu membuat mezbah-mezbah bagi dirinya di segenap penjuru Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 25, 'Di tiap-tiap kota di Yehuda ia membuat bukit-bukit pengorbanan untuk membakar korban bagi allah lain. Dengan demikian ia menyakiti hati TUHAN, Allah nenek moyangnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 26, 'Selebihnya dari riwayatnya dan seluruh tingkah langkahnya, dari awal sampai akhir, sesungguhnya semuanya itu tertulis dalam kitab raja-raja Yehuda dan Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 28, 27, 'Kemudian Ahas mendapat perhentian bersama-sama dengan nenek moyangnya, dan dikuburkan di dalam kota, di Yerusalem; tetapi ia tidak dibawa ke pekuburan raja-raja Israel. Maka Hizkia, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 1, 'Hizkia berumur dua puluh lima tahun pada waktu ia menjadi raja dan dua puluh sembilan tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Abia, anak Zakharia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 2, 'Ia melakukan apa yang benar di mata TUHAN, tepat seperti yang dilakukan Daud, bapa leluhurnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 3, 'Pada tahun pertama pemerintahannya, dalam bulan yang pertama, ia membuka pintu-pintu rumah TUHAN dan memperbaikinya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 4, 'Ia mendatangkan para imam dan orang-orang Lewi, dan mengumpulkan mereka di halaman sebelah timur.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 5, 'Katanya kepada mereka: "Dengarlah, hai orang-orang Lewi! Sekarang kuduskanlah dirimu dan kuduskanlah rumah TUHAN, Allah nenek moyangmu! Keluarkanlah kecemaran dari tempat kudus!', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 6, 'Karena nenek moyang kita telah berubah setia. Mereka melakukan apa yang jahat di mata TUHAN, Allah kita, telah meninggalkan-Nya, mereka telah memalingkan muka dari kediaman TUHAN dan membelakangi-Nya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 7, 'Bahkan mereka menutup pintu-pintu balai rumah TUHAN dan memadamkan segala pelita. Mereka tidak membakar korban ukupan dan tidak mempersembahkan korban bakaran bagi Allah orang Israel di tempat kudus,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 8, 'sehingga murka TUHAN menimpa Yehuda dan Yerusalem. Ia membuat mereka menjadi kengerian, kedahsyatan dan sasaran suitan seperti yang kamu lihat dengan matamu sendiri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 9, 'Karena hal itulah nenek moyang kita tewas oleh pedang, dan anak-anak lelaki dan anak-anak perempuan kita beserta isteri-isteri kita menjadi tawanan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 10, 'Sekarang aku bermaksud mengikat perjanjian dengan TUHAN, Allah Israel, supaya murka-Nya yang menyala-nyala itu undur dari pada kita.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 11, 'Anak-anakku, sekarang janganlah kamu lengah, karena kamu telah dipilih TUHAN untuk berdiri di hadapan-Nya untuk melayani Dia, untuk menyelenggarakan kebaktian dan membakar korban bagi-Nya."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 12, 'Lalu bangunlah orang-orang Lewi itu, yakni dari bani Kehat: Mahat bin Amasai dan Yoel bin Azaria, dari bani Merari: Kish bin Abdi dan Azaria bin Yehaleleel, dari orang Gerson: Yoah bin Zima dan Eden bin Yoah,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 13, 'dari bani Elisafan: Simri dan Yeiel, dari bani Asaf: Zakharia dan Matanya,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 14, 'dari bani Heman: Yehiel dan Simei, dan dari bani Yedutun: Semaya dan Uziel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 15, 'Mereka mengumpulkan saudara-saudaranya dan menguduskan dirinya. Kemudian mereka datang menurut perintah raja, sesuai dengan firman TUHAN, lalu mentahirkan rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 16, 'Sesudah itu masuklah para imam ke bagian dalam rumah TUHAN untuk mentahirkannya. Semua yang najis, yang didapati mereka di dalam bait TUHAN, dibawa ke pelataran rumah TUHAN; orang-orang Lewi menerimanya untuk diangkut ke luar, ke lembah Kidron.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 17, 'Pekerjaan menguduskan itu dimulai pada tanggal satu bulan yang pertama. Pada hari kedelapan bulan itu mereka sampai ke balai rumah TUHAN dan menguduskan seluruh rumah TUHAN dalam delapan hari. Mereka selesai pada hari keenam belas bulan pertama.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 18, 'Lalu masuklah mereka menghadap raja Hizkia dan berkata: "Kami telah mentahirkan seluruh rumah TUHAN, juga mezbah korban bakaran dengan segala perkakasnya dan meja roti sajian dengan segala perkakasnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 19, 'Dan segala perkakas, yang dibuang raja Ahas, ketika ia berubah setia pada masa pemerintahannya, telah kami sediakan dan kami kuduskan. Sekarang semuanya itu ada di depan mezbah TUHAN!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 20, 'Maka pagi-pagi raja Hizkia mengumpulkan pemimpin-pemimpin kota, dan pergi ke rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 21, 'Mereka membawa tujuh ekor lembu jantan, tujuh ekor domba jantan, tujuh ekor domba muda dan tujuh ekor kambing jantan sebagai korban penghapus dosa untuk keluarga raja, untuk tempat kudus dan untuk Yehuda. Ia memerintahkan anak-anak Harun, yakni para imam, untuk mempersembahkannya di atas mezbah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 22, 'Lalu mereka menyembelih lembu-lembu itu; para imam menerima darahnya dan menyiramkannya pada mezbah. Kemudian mereka, menyembelih domba-domba jantan dan menyiramkan darahnya pada mezbah. Sesudah itu mereka menyembelih domba-domba muda dan menyiramkan darahnya pada mezbah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 23, 'Selanjutnya mereka membawa kambing-kambing jantan yang akan menjadi korban penghapus dosa ke hadapan raja dan jemaah. Mereka meletakkan tangannya ke atas kambing-kambing itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 24, 'Dan para imam menyembelihnya dan mempersembahkan darahnya di atas mezbah sebagai korban penghapus dosa untuk mengadakan pendamaian bagi seluruh Israel. Sebab raja telah memerintahkan untuk mempersembahkan korban bakaran dan korban penghapus dosa itu bagi seluruh Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 25, 'Ia menempatkan orang-orang Lewi di rumah TUHAN dengan ceracap, gambus, dan kecapi sesuai dengan perintah Daud dan Gad, pelihat raja, dan nabi Natan, karena dari Tuhanlah perintah itu, dengan perantaraan nabi-nabi-Nya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 26, 'Maka berdirilah orang-orang Lewi dengan alat-alat musik Daud, demikian pula para imam dengan nafiri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 27, 'Lalu Hizkia memerintahkan untuk mempersembahkan korban bakaran di atas mezbah. Pada saat persembahan korban bakaran dimulai, mulailah pula dinyanyikan nyanyian bagi TUHAN dan dibunyikan nafiri, dengan iringan alat-alat musik Daud, raja Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 28, 'Seluruh jemaah sujud menyembah sementara nyanyian dinyanyikan dan nafiri dibunyikan. Semuanya itu berlangsung sampai korban bakaran habis terbakar.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 29, 'Sehabis korban bakaran dipersembahkan, raja dan semua orang yang hadir bersama-sama dia berlutut dan sujud menyembah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 30, 'Lalu raja Hizkia dan para pemimpin memerintahkan orang-orang Lewi menyanyikan puji-pujian untuk TUHAN dengan kata-kata Daud dan Asaf, pelihat itu. Maka mereka menyanyikan puji-pujian dengan sukaria, lalu berlutut dan sujud menyembah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 31, 'Kemudian berbicaralah Hizkia: "Sekarang kamu telah mentahbiskan dirimu untuk TUHAN. Mendekatlah dan bawalah korban-korban sembelihan dan korban-korban syukur ke rumah TUHAN!" Lalu jemaah membawa korban-korban sembelihan dan korban-korban puji-pujian; setiap orang yang rela hati membawa juga korban-korban bakaran.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 32, 'Jumlah korban bakaran yang dibawa jemaah ialah: lembu tujuh puluh ekor, domba jantan seratus ekor dan domba muda dua ratus ekor. Semuanya sebagai korban bakaran bagi TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 33, 'Persembahan-persembahan kudus terdiri dari: lembu sapi enam ratus ekor dan kambing domba tiga ribu ekor.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 34, 'Tetapi jumlah imam terlalu sedikit, sehingga mereka tidak sanggup menguliti semua korban bakaran. Oleh sebab itu saudara-saudara mereka, orang-orang Lewi, membantu mereka sampai pekerjaan itu selesai dan sampai para imam menguduskan dirinya. Sebab orang-orang Lewi itu lebih bersungguh-sungguh menguduskan dirinya dari pada para imam.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 35, 'Lagipula korban bakaran itu banyak, dengan segala lemak korban keselamatan dan segala korban curahan pada korban-korban bakaran itu. Demikianlah ibadah di rumah TUHAN ditetapkan kembali.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 29, 36, 'Hizkia dan seluruh rakyat bersukacita akan apa yang telah ditetapkan Allah bagi bangsa itu, karena hal itu terjadi dengan tak disangka-sangka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 1, 'Kemudian Hizkia mengirim pesan kepada seluruh Israel dan Yehuda, bahkan menulis surat kepada Efraim dan Manasye supaya mereka datang merayakan Paskah bagi TUHAN, Allah orang Israel, di rumah TUHAN di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 2, 'Raja bersama-sama para pemimpin dan seluruh jemaah di Yerusalem merancangkan untuk merayakan Paskah pada bulan kedua,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 3, 'karena mereka tidak dapat merayakannya pada waktunya, sebab para imam belum menguduskan diri dalam jumlah yang cukup dan rakyat belum terkumpul di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 4, 'Rancangan itu diterima baik oleh raja dan seluruh jemaah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 5, 'Mereka memutuskan untuk menyiarkan maklumat di seluruh Israel, dari Bersyeba sampai Dan, supaya masing-masing datang ke Yerusalem merayakan Paskah bagi TUHAN, Allah Israel, karena mereka belum merayakannya secara umum seperti yang ada tertulis.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 6, 'Maka berangkatlah pesuruh-pesuruh cepat ke seluruh Israel dan Yehuda membawa surat dari raja dan para pemimpin, dan mengatakan sesuai dengan perintah raja: "Hai, orang Israel, kembalilah kepada TUHAN, Allah Abraham, Ishak dan Israel, maka Ia akan kembali kepada yang tertinggal dari pada kamu, yakni mereka yang terluput dari tangan raja-raja Asyur.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 7, 'Janganlah berlaku seperti nenek moyangmu dan saudara-saudaramu yang berubah setia terhadap TUHAN, Allah nenek moyang mereka, sehingga Ia membuat mereka menjadi kedahsyatan seperti yang kamu lihat sendiri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 8, 'Sekarang, janganlah tegar tengkuk seperti nenek moyangmu. Serahkanlah dirimu kepada TUHAN dan datanglah ke tempat kudus yang telah dikuduskan-Nya untuk selama-lamanya, serta beribadahlah kepada TUHAN, Allahmu, supaya murka-Nya yang menyala-nyala undur dari padamu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 9, 'Karena bilamana kamu kembali kepada TUHAN, maka saudara-saudaramu dan anak-anakmu akan mendapat belas kasihan dari orang-orang yang menawan mereka, sehingga mereka kembali ke negeri ini. Sebab TUHAN, Allahmu, pengasih dan penyayang: Ia tidak akan memalingkan wajah-Nya dari pada kamu, bilamana kamu kembali kepada-Nya!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 10, 'Ketika pesuruh-pesuruh cepat itu pergi dari kota ke kota, melintasi tanah Efraim dan Manasye sampai ke Zebulon, mereka ditertawakan dan diolok-olok.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 11, 'Namun beberapa orang dari Asyer, Manasye dan Zebulon merendahkan diri, dan datang ke Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 12, 'Di Yehuda nyata pula tangan Allah yang membulatkan hati mereka untuk melakukan perintah raja dan para pemimpin sesuai dengan firman TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 13, 'Maka berkumpullah di Yerusalem banyak orang, suatu jemaah yang sangat besar, untuk merayakan hari raya Roti Tidak Beragi pada bulan yang kedua.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 14, 'Lalu bangunlah mereka menjauhkan mezbah-mezbah yang ada di Yerusalem; juga semua mezbah korban ukupan disingkirkan dan dibuang ke lembah Kidron.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 15, 'Kemudian disembelihlah domba Paskah pada tanggal empat belas bulan kedua. Maka para imam dan orang-orang Lewi merasa malu, lalu menguduskan dirinya dan membawa korban bakaran ke rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 16, 'Mereka berdiri pada tempatnya menurut peraturan yang berlaku bagi mereka masing-masing, sesuai dengan Taurat Musa, abdi Allah itu; para imam menyiramkan darah yang diterimanya dari orang-orang Lewi.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 17, 'Sebab ada banyak di antara jemaah yang tidak menguduskan dirinya, sehingga menjadi tugas orang Lewi untuk menyembelih domba-domba Paskah bagi setiap orang yang tidak dapat menguduskannya bagi TUHAN karena ia tidak tahir.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 18, 'Sebab sebagian besar dari rakyat?terutama dari Efraim, Manasye, Isakhar dan Zebulon?tidak mentahirkan diri. Namun mereka memakan Paskah, walaupun tidak sesuai dengan apa yang ada tertulis. Tetapi Hizkia berdoa untuk mereka, katanya: "TUHAN, yang baik itu, kiranya mengadakan pendamaian bagi semua orang,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 19, 'yang sungguh-sungguh berhasrat mencari Allah, yakni TUHAN, Allah nenek moyangnya, walaupun ketahiran mereka tidak sesuai dengan tempat kudus."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 20, 'TUHAN mendengar Hizkia dan membiarkan bangsa itu selamat.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 21, 'Tujuh hari lamanya orang Israel yang berada di Yerusalem merayakan hari raya Roti Tidak Beragi dengan kesukaan yang besar, sedang orang-orang Lewi dan para imam setiap hari menyanyikan puji-pujian bagi TUHAN dengan sekuat tenaga.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 22, 'Hizkia mengucapkan kata-kata pujian kepada semua orang Lewi yang menunjukkan akal budi yang baik dalam melayani TUHAN. Demikianlah orang memakan makanan perayaan selama tujuh hari, sambil mempersembahkan korban keselamatan dan mengucapkan syukur kepada TUHAN, Allah nenek moyang mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 23, 'Kemudian seluruh jemaah sepakat untuk berhari raya tujuh hari lagi. Lalu mereka berhari raya tujuh hari lagi dengan sukaria.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 24, 'Sebab Hizkia, raja Yehuda, telah menyumbangkan kepada jemaah seribu ekor lembu jantan dan tujuh ribu kambing domba. Juga para pemimpin menyumbangkan kepada jemaah seribu ekor lembu jantan dan sepuluh ribu ekor kambing domba. Dan sebagian besar para imam telah menguduskan diri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 25, 'Seluruh jemaah Yehuda bersukaria, juga para imam dan orang-orang Lewi, dan seluruh jemaah yang datang dari Israel, serta orang-orang asing, baik yang datang dari tanah Israel, maupun yang tinggal di Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 26, 'Maka besarlah kesukaan di Yerusalem, karena sejak Salomo bin Daud, raja Israel, tidak pernah terjadi peristiwa semacam itu di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 30, 27, 'Sesudah itu para imam Lewi bangun berdiri dan memberkati rakyat. Suara mereka didengar TUHAN dan doa mereka sampai ke tempat kediaman-Nya yang kudus di sorga.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 1, 'Setelah semuanya ini diakhiri, seluruh orang Israel yang hadir pergi ke kota-kota di Yehuda, lalu meremukkan segala tugu berhala, menghancurkan segala tiang berhala, dan merobohkan segala bukit pengorbanan dan mezbah di seluruh Yehuda dan Benyamin, juga di Efraim dan Manasye, sampai musnah semuanya. Kemudian pulanglah seluruh orang Israel ke kota-kotanya, ke miliknya masing-masing.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 2, 'Hizkia menetapkan rombongan para imam dan orang-orang Lewi, rombongan demi rombongan, masing-masing menurut tugas jabatannya sebagai imam atau sebagai orang Lewi, untuk mempersembahkan korban bakaran dan korban keselamatan, untuk mengucap syukur dan menyanyikan puji-pujian dan untuk melayani di pintu-pintu gerbang di tempat perkemahan TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 3, 'Raja memberi sumbangan dari harta miliknya untuk korban bakaran, yakni: korban bakaran pada waktu pagi dan pada waktu petang, korban bakaran pada hari-hari Sabat dan pada bulan-bulan baru dan pada hari-hari raya, yang semuanya tertulis di dalam Taurat TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 4, 'Ia memerintahkan rakyat, yakni penduduk Yerusalem, untuk memberikan sumbangan yang menjadi bagian para imam dan orang-orang Lewi, supaya mereka dapat mencurahkan tenaganya untuk melaksanakan Taurat TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 5, 'Segera setelah perintah ini tersiar, orang Israel membawa dalam jumlah yang besar hasil pertama dari pada gandum, anggur, minyak, madu dan segala macam hasil bumi. Mereka membawa juga persembahan persepuluhan dari segala sesuatu dalam jumlah yang besar.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 6, 'Orang Israel dan orang Yehuda yang tinggal di kota-kota Yehuda juga membawa persembahan persepuluhan yang terdiri dari lembu sapi dan kambing domba, dan persembahan persepuluhan yang terdiri dari persembahan kudus yang telah dikuduskan bagi TUHAN Allah mereka. Semuanya itu diletakkan mereka bertimbun-timbun.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 7, 'Mereka mulai membuat timbunan itu pada bulan yang ketiga, dan mereka selesai pada bulan yang ketujuh.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 8, 'Hizkia dan para pemimpin datang melihat timbunan itu, dan mereka memuji TUHAN dan umat-Nya, orang Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 9, 'Hizkia menanyakan para imam dan orang-orang Lewi tentang timbunan itu,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 10, 'dan dijawab oleh Azarya, imam kepala keturunan Zadok demikian: "Sejak persembahan khusus mulai dibawa ke rumah TUHAN, kami telah makan sekenyang-kenyangnya, namun sisanya masih banyak. Sebab TUHAN telah memberkati umat-Nya, sehingga tinggal sisa yang banyak ini."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 11, 'Kemudian Hizkia menyuruh menyediakan bilik-bilik di rumah TUHAN dan mereka menyediakannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 12, 'Dan dengan setia mereka membawa segala persembahan khusus, persembahan persepuluhan dan persembahan-persembahan kudus itu ke sana. Konanya, seorang Lewi, mengawasi semuanya, dan Simei, saudaranya, adalah orang kedua,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 13, 'sedang Yehiel, Azazya, Nahat, Asael, Yerimot, Yozabad, Eliel, Yismakhya, Mahat dan Benanya adalah penilik di bawah Konanya dan Simei, saudaranya itu, sesuai dengan petunjuk raja Hizkia dan Azarya, kepala rumah Allah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 14, 'Dan Kore bin Yimna, seorang Lewi, penunggu pintu gerbang di sebelah timur, mengawasi pemberian-pemberian sukarela untuk Allah, serta membagi-bagikan persembahan khusus yang untuk TUHAN dan persembahan-persembahan maha kudus.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 15, 'Di kota-kota imam ia dibantu dengan setia oleh Eden, Minyamin, Yesua, Semaya, Amarya dan Sekhanya dalam pembagian itu kepada saudara-saudara mereka menurut rombongan, kepada orang dewasa dan anak-anak,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 16, 'kecuali kepada setiap orang yang masuk ke rumah TUHAN, menurut hari-hari yang ditetapkan, menurut tugas jabatan yang ditugaskan kepadanya, dan menurut rombongannya, yakni mereka yang tercatat dalam daftar sebagai laki-laki yang berumur tiga tahun ke atas.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 17, 'Para imam dicatat dalam daftar menurut puak-puak mereka, sedang orang-orang Lewi yang berumur dua puluh tahun ke atas dicatat menurut tugas dan rombongan mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 18, 'Para imam terdaftar dengan seluruh keluarga mereka, yakni isteri, anak laki-laki dan perempuan, seluruh kaum itu, karena dengan setia mereka menguduskan diri untuk persembahan kudus.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 19, 'Bagi keturunan Harun, yakni imam-imam, yang tinggal di padang-padang penggembalaan sekitar kota-kota mereka, di setiap kota ada orang-orang yang ditunjuk dengan disebut namanya, untuk mengadakan pembagian kepada setiap orang laki-laki dari keluarga imam dan kepada setiap orang Lewi yang terdaftar.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 20, 'Demikianlah perbuatan Hizkia di seluruh Yehuda. Ia melakukan apa yang baik, apa yang jujur, dan apa yang benar di hadapan TUHAN, Allahnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 31, 21, 'Dalam setiap usaha yang dimulainya untuk pelayanannya terhadap rumah Allah, dan untuk pelaksanaan Taurat dan perintah Allah, ia mencari Allahnya. Semuanya dilakukannya dengan segenap hati, sehingga segala usahanya berhasil.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 1, 'Setelah peristiwa yang menunjukkan kesetiaan Hizkia itu datanglah Sanherib, raja Asyur, menyerbu Yehuda. Ia mengepung kota-kota berkubu, dan berniat merebutnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 2, 'Ketika Hizkia mengetahui, bahwa Sanherib datang hendak memerangi Yerusalem,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 3, 'ia berunding dengan para panglima dan pahlawannya untuk menutup segala mata air yang terdapat di luar kota dan mereka itu bersedia membantunya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 4, 'Maka berkumpullah banyak orang. Mereka menutup semua mata air dan sungai yang mengalir dari tengah-tengah negeri itu. Kata mereka: "Mengapa raja-raja Asyur harus mendapat banyak air, kalau mereka datang?"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 5, 'Dengan sekuat tenaga Hizkia membangun kembali seluruh tembok yang telah terbongkar, mendirikan menara-menara di atasnya dan tembok yang lain di luarnya. Ia memperkuat juga Milo di kota Daud dan membuat lembing dan perisai dalam jumlah yang besar.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 6, 'Ia mengangkat panglima-panglima perang yang mengepalai rakyat, menyuruh mereka berkumpul kepadanya di halaman pintu gerbang kota dan menenangkan hati mereka dengan kata-kata:', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 7, '"Kuatkanlah dan teguhkanlah hatimu! Janganlah takut dan terkejut terhadap raja Asyur serta seluruh laskar yang menyertainya, karena yang menyertai kita lebih banyak dari pada yang menyertai dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 8, 'Yang menyertai dia adalah tangan manusia, tetapi yang menyertai kita adalah TUHAN, Allah kita, yang membantu kita dan melakukan peperangan kita." Oleh kata-kata Hizkia, raja Yehuda itu, rakyat mendapat kepercayaannya kembali.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 9, 'Sesudah itu Sanherib, raja Asyur, yang sedang mengepung Lakhis dengan seluruh kekuatan tentaranya, mengutus beberapa pegawai ke Yerusalem, kepada Hizkia, raja Yehuda, dan kepada semua orang Yehuda yang ada di Yerusalem, dengan pesan:', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 10, '"Beginilah titah Sanherib, raja Asyur: Apakah yang kamu harapkan, maka kamu tinggal saja di Yerusalem yang terkepung ini?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 11, 'Bukankah Hizkia memperdayakan kamu, supaya kamu mati kelaparan dan kehausan, dengan mengatakan: TUHAN, Allah kita, akan melepaskan kita dari tangan raja Asyur?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 12, 'Bukankah Hizkia ini yang menjauhkan segala bukit pengorbanan dan mezbah TUHAN itu, dan berkata kepada Yehuda dan Yerusalem: Hanya di depan satu mezbah kamu harus sujud menyembah dan membakar korban di atasnya?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 13, 'Tidakkah kamu ketahui apa yang aku dan nenek moyangku lakukan terhadap semua bangsa negeri-negeri lain? Apakah para allah bangsa-bangsa segala negeri itu pernah berhasil melepaskan negeri mereka dari tanganku?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 14, 'Siapa dari pada semua allah bangsa-bangsa yang sudah ditumpas nenek moyangku itu dapat melepaskan bangsanya dari tanganku? Masakan Allahmu dapat melepaskan kamu dari tanganku?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 15, 'Sekarang, janganlah Hizkia memperdayakan dan membujuk kamu seperti ini! Janganlah percaya kepadanya, karena tidak ada allah dari bangsa atau kerajaan manapun yang dapat melepaskan bangsanya dari tanganku dan dari tangan nenek moyangku, lebih-lebih lagi Allahmu itu takkan dapat melepaskan kamu dari tanganku!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 16, 'Dan masih banyak lagi yang diucapkan pegawai-pegawai Sanherib itu menentang TUHAN Allah dan menentang Hizkia, hamba-Nya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 17, 'Ia menulis juga surat yang penuh cela dan hujat terhadap TUHAN, Allah Israel, bunyinya: "Sebagaimana para allah bangsa-bangsa segala negeri lain tidak dapat melepaskan bangsanya dari tanganku, demikian pula Allah Hizkia takkan dapat melepaskan bangsa-Nya dari tanganku."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 18, 'Dan mereka berseru dengan suara nyaring dalam bahasa Yehuda kepada rakyat Yerusalem yang ada di atas tembok, untuk menakutkan dan mengejutkan mereka, supaya mereka dapat merebut kota itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 19, 'Mereka berbicara tentang Allah Yerusalem seperti tentang para allah bangsa-bangsa di dunia, adalah buatan tangan manusia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 20, 'Tetapi oleh karena itu raja Hizkia dan nabi Yesaya bin Amos berdoa dan berseru kepada sorga.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 21, 'Lalu TUHAN mengirim malaikat yang melenyapkan semua pahlawan yang gagah perkasa, pemuka dan panglima yang ada di perkemahan raja Asyur, sehingga ia kemalu-maluan kembali ke negerinya. Kemudian ia ditewaskan dengan pedang oleh anak-anak kandungnya sendiri ketika ia memasuki rumah allahnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 22, 'Demikianlah TUHAN menyelamatkan Hizkia dan penduduk Yerusalem dari tangan Sanherib, raja Asyur, dan dari tangan semua musuhnya. Dan Ia mengaruniakan keamanan kepada mereka di segala penjuru.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 23, 'Banyak orang membawa persembahan ke Yerusalem untuk TUHAN dan barang-barang berharga untuk Hizkia, raja Yehuda itu. Sejak itu ia diagungkan oleh semua bangsa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 24, 'Pada hari-hari itu Hizkia jatuh sakit, sehingga hampir mati. Ia berdoa kepada TUHAN, dan TUHAN berfirman kepadanya dan memberikannya suatu tanda ajaib.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 25, 'Tetapi Hizkia tidak berterima kasih atas kebaikan yang ditunjukkan kepadanya, karena ia menjadi angkuh, sehingga ia dan Yehuda dan Yerusalem ditimpa murka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 26, 'Tetapi ia sadar akan keangkuhannya itu dan merendahkan diri bersama-sama dengan penduduk Yerusalem, sehingga murka TUHAN tidak menimpa mereka pada zaman Hizkia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 27, 'Hizkia mendapat kekayaan dan kemuliaan yang sangat besar. Ia membuat perbendaharaan-perbendaharaan untuk emas, perak, batu permata yang mahal-mahal, rempah-rempah, perisai-perisai dan segala macam barang yang indah-indah,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 28, 'juga tempat perbekalan untuk hasil gandum, untuk anggur dan minyak, dan kandang-kandang untuk berbagai jenis hewan besar dan kandang-kandang untuk kawanan kambing domba.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 29, 'Ia mendirikan kota-kota, memperoleh banyak kambing domba dan lembu sapi, karena Allah mengaruniakan dia harta milik yang amat besar.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 30, 'Hizkia ini juga telah membendung aliran Gihon di sebelah hulu, dan menyalurkannya ke hilir, ke sebelah barat, ke kota Daud. Hizkia berhasil dalam segala usahanya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 31, 'Demikianlah juga ketika utusan-utusan raja-raja Babel datang kepadanya untuk menanyakan tentang tanda ajaib yang telah terjadi di negeri, ketika itu Allah meninggalkan dia untuk mencobainya, supaya diketahui segala isi hatinya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 32, 'Selebihnya dari riwayat Hizkia dan perbuatan-perbuatannya yang setia, sesungguhnya semuanya itu tertulis dalam penglihatan nabi Yesaya bin Amos, dalam kitab raja-raja Yehuda dan Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 32, 33, 'Kemudian Hizkia mendapat perhentian bersama-sama dengan nenek moyangnya, dan dikuburkan di pendakian ke pekuburan anak-anak Daud. Pada waktu kematiannya seluruh Yehuda dan penduduk Yerusalem memberi penghormatan kepadanya. Maka Manasye, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 1, 'Manasye berumur dua belas tahun pada waktu ia menjadi raja dan lima puluh lima tahun lamanya ia memerintah di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 2, 'Ia melakukan apa yang jahat di mata TUHAN, sesuai dengan perbuatan keji bangsa-bangsa yang telah dihalaukan TUHAN dari depan orang Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 3, 'Ia mendirikan kembali bukit-bukit pengorbanan yang telah dirobohkan oleh Hizkia, ayahnya; ia membangun mezbah-mezbah untuk para Baal, membuat patung-patung Asyera dan sujud menyembah kepada segenap tentara langit dan beribadah kepadanya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 4, 'Ia mendirikan mezbah-mezbah di rumah TUHAN, walaupun sehubungan dengan rumah itu TUHAN telah berfirman: "Di Yerusalem nama-Ku akan tinggal untuk selama-lamanya!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 5, 'Dan ia mendirikan juga mezbah-mezbah bagi segenap tentara langit di kedua pelataran rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 6, 'Bahkan, ia mempersembahkan anak-anaknya sebagai korban dalam api di Lebak Ben-Hinom; ia melakukan ramal, telaah dan sihir, dan menghubungi para pemanggil arwah dan para pemanggil roh peramal. Ia melakukan banyak yang jahat di mata TUHAN, sehingga ia menimbulkan sakit hati-Nya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 7, 'Ia menaruh juga patung berhala yang telah dibuatnya dalam rumah Allah, walaupun Allah telah berfirman kepada Daud dan kepada Salomo, anaknya: "Dalam rumah ini dan di Yerusalem, yang telah Kupilih dari antara segala suku Israel, Aku akan menaruh nama-Ku untuk selama-lamanya!', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 8, 'Aku tidak akan membuat pula orang Israel berjejak ke luar dari tanah yang telah Kutentukan untuk nenek moyangmu, asal saja mereka melakukan dengan setia segala yang telah Kuperintahkan kepada mereka dengan perantaraan Musa, yakni segala hukum, ketetapan dan peraturan."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 9, 'Tetapi Manasye menyesatkan Yehuda dan penduduk Yerusalem, sehingga mereka melakukan yang jahat lebih dari pada bangsa-bangsa yang telah dipunahkan TUHAN dari depan orang Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 10, 'Kemudian berfirmanlah TUHAN kepada Manasye dan rakyatnya, tetapi mereka tidak menghiraukannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 11, 'Oleh sebab itu TUHAN mendatangkan kepada mereka panglima-panglima tentara raja Asyur yang menangkap Manasye dengan kaitan, membelenggunya dengan rantai tembaga dan membawanya ke Babel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 12, 'Dalam keadaan yang terdesak ini, ia berusaha melunakkan hati TUHAN, Allahnya; ia sangat merendahkan diri di hadapan Allah nenek moyangnya,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 13, 'dan berdoa kepada-Nya. Maka TUHAN mengabulkan doanya, dan mendengarkan permohonannya. Ia membawanya kembali ke Yerusalem dan memulihkan kedudukannya sebagai raja. Dan Manasye mengakui, bahwa TUHAN itu Allah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 14, 'Kemudian ia mendirikan tembok luar pada kota Daud, di sebelah Barat Gihon, di lembah, sampai dekat Pintu Gerbang Ikan, mengelilingi Ofel. Tembok itu dibuatnya sangat tinggi. Ia menempatkan juga panglima-panglima perang di tiap kota kubu di Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 15, 'Ia menjauhkan allah-allah asing dan berhala dari rumah TUHAN, juga segala mezbah yang didirikannya di atas gunung rumah TUHAN dan di Yerusalem, dan membuangnya ke luar kota.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 16, 'Ia menegakkan kembali mezbah TUHAN, mempersembahkan korban keselamatan dan korban syukur di atasnya, menyerukan kepada Yehuda untuk beribadah kepada TUHAN, Allah Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 17, 'Walaupun demikian, rakyat masih mempersembahkan korban di bukit-bukit pengorbanan, tetapi hanya kepada TUHAN, Allah mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 18, 'Selebihnya dari riwayat Manasye, doanya kepada Allahnya, dan ucapan-ucapan para pelihat yang berkata-kata kepadanya dengan nama TUHAN, Allah Israel, sesungguhnya semuanya itu terdapat dalam riwayat raja-raja Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 19, 'Doanya dan pengabulan doanya, segala dosa dan ketidaksetiaannya, semua tempat di mana ia telah membangun bukit-bukit pengorbanan serta mendirikan tiang-tiang berhala dan patung-patung sebelum ia merendahkan diri, sesungguhnya semuanya itu tertulis dalam riwayat para pelihat.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 20, 'Kemudian Manasye mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di dalam istananya. Maka Amon, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 21, 'Amon berumur dua puluh dua tahun pada waktu ia menjadi raja dan dua tahun lamanya ia memerintah di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 22, 'Ia melakukan apa yang jahat di mata TUHAN seperti yang telah dilakukan Manasye, ayahnya. Amon mempersembahkan korban kepada segala patung yang dibuat Manasye, ayahnya, dan beribadah kepada patung-patung itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 23, 'Tetapi ia tidak merendahkan diri di hadapan TUHAN seperti Manasye, ayahnya, merendahkan diri, malah Amon makin banyak kesalahannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 24, 'Maka pegawai-pegawainya mengadakan persepakatan melawan dia, dan membunuhnya di istananya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 33, 25, 'Tetapi rakyat negeri itu membunuh semua orang yang mengadakan persepakatan melawan raja Amon; dan rakyat negeri itu mengangkat Yosia, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 1, 'Yosia berumur delapan tahun pada waktu ia menjadi raja dan tiga puluh satu tahun lamanya ia memerintah di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 2, 'Ia melakukan apa yang benar di mata TUHAN dan hidup seperti Daud, bapa leluhurnya, dan tidak menyimpang ke kanan atau ke kiri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 3, 'Pada tahun kedelapan dari pemerintahannya, ketika ia masih muda belia, ia mulai mencari Allah Daud, bapa leluhurnya, dan pada tahun kedua belas ia mulai mentahirkan Yehuda dan Yerusalem dari pada bukit-bukit pengorbanan, tiang-tiang berhala, patung-patung pahatan dan patung-patung tuangan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 4, 'Mezbah-mezbah para Baal dirobohkan di hadapannya; ia menghancurkan pedupaan-pedupaan yang ada di atasnya; ia meremukkan dan menghancurluluhkan tiang-tiang berhala, patung-patung pahatan dan patung-patung tuangan, dan menghamburkannya ke atas kuburan orang-orang yang mempersembahkan korban kepada berhala-berhala itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 5, 'Tulang-tulang para imam dibakarnya di atas mezbah-mezbah mereka. Demikianlah ia mentahirkan Yehuda dan Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 6, 'Juga di kota-kota Manasye, Efraim dan Simeon, sampai di kota-kota Naftali, yang di mana-mana telah menjadi reruntuhan,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 7, 'ia merobohkan segala mezbah dan tiang berhala, meremukkan segala patung pahatan serta menghancurluluhkannya, dan menghancurkan semua pedupaan di seluruh tanah Israel. Sesudah itu ia kembali ke Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 8, 'Pada tahun kedelapan belas dari pemerintahannya, setelah selesai mentahirkan negeri dan rumah TUHAN, ia menyuruh Safan bin Azalya, dan Maaseya, penguasa kota, serta Yoah bin Yoahas, bendahara negara, untuk memperbaiki rumah TUHAN, Allahnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 9, 'Maka datanglah mereka kepada imam besar Hilkia dan menyerahkan kepadanya uang yang telah dibawa ke rumah Allah dan yang telah dikumpulkan oleh orang-orang Lewi, yakni oleh para penjaga pintu, dari orang-orang Manasye dan Efraim, dan dari semua orang yang masih tinggal dari Israel, pula dari seluruh orang Yehuda dan Benyamin, dan dari penduduk Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 10, 'Uang itu diberikan mereka ke tangan para pekerja yang diangkat untuk mengawasi rumah TUHAN; dan mereka itu, yang bekerja dalam rumah TUHAN, mengeluarkannya untuk membetulkan dan memperbaiki rumah itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 11, 'Mereka memberikannya kepada tukang-tukang kayu dan tukang-tukang bangunan, supaya tukang-tukang itu membeli batu pahat dan kayu untuk tupai-tupai dan untuk memasang balok-balok pada gedung-gedung, yang oleh raja-raja Yehuda dibiarkan roboh.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 12, 'Orang-orang itu melakukan pekerjaan itu dengan setia. Orang-orang yang diangkat menjadi pengawas mereka ialah: Yahat dan Obaja, orang-orang Lewi dari bani Merari, sedangkan Zakharia dan Mesulam dari bani Kehat mengepalai semua. Dan semua orang Lewi yang pandai memainkan alat-alat musik,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 13, 'mengepalai kuli-kuli dan mengiringi semua tukang dalam pekerjaan apapun. Dari antara orang-orang Lewi itu ada yang menjadi panitera, pengatur atau penunggu pintu gerbang.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 14, 'Ketika mereka mengeluarkan uang yang telah dibawa ke rumah TUHAN, imam Hilkia menemukan kitab Taurat TUHAN, yang diberikan dengan perantaraan Musa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 15, 'Maka berkatalah Hilkia kepada Safan, panitera negara itu: "Aku telah menemukan kitab Taurat di rumah TUHAN!" Lalu Hilkia memberikan kitab itu kepada Safan,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 16, 'dan Safan membawa kitab itu kepada raja. Ia juga menyampaikan kabar kepada raja: "Segala sesuatu yang ditugaskan kepada hamba-hambamu, telah mereka laksanakan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 17, 'Mereka telah mengambil seluruh uang yang terdapat di rumah TUHAN dan memberikannya ke tangan para pengawas dan para pekerja."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 18, 'Safan, panitera negara itu, memberitahukan juga kepada raja: "Imam Hilkia telah memberikan kitab kepadaku," lalu Safan membacakan sebagian di depan raja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 19, 'Segera sesudah raja mendengar perkataan Taurat itu, dikoyakkannyalah pakaiannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 20, 'Kemudian raja memberi perintah kepada Hilkia, kepada Ahikam bin Safan, kepada Abdon bin Mikha, kepada Safan, panitera negara itu, dan kepada Asaya, hamba raja, katanya:', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 21, '"Pergilah, mintalah petunjuk TUHAN bagiku, bagi yang masih tinggal di Israel dan di Yehuda tentang perkataan kitab yang ditemukan ini, sebab hebat kehangatan murka TUHAN yang dicurahkan kepada kita, oleh karena nenek moyang kita tidak memelihara firman TUHAN dengan berbuat tepat seperti yang tertulis dalam kitab ini!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 22, 'Maka pergilah Hilkia dengan orang-orang yang disuruh raja kepada nabiah Hulda, isteri seorang yang mengurus pakaian-pakaian, yaitu Salum bin Tokhat bin Hasra, penunggu pakaian-pakaian; nabiah itu tinggal di Yerusalem, di perkampungan baru. Mereka berbicara kepadanya sebagaimana yang diperintahkan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 23, 'Perempuan itu menjawab mereka: "Beginilah firman TUHAN, Allah Israel! Katakanlah kepada orang yang menyuruh kamu kepada-Ku!', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 24, 'Beginilah firman TUHAN: Sesungguhnya Aku akan mendatangkan malapetaka atas tempat ini dan atas penduduknya, yakni segala kutuk yang tertulis dalam kitab yang telah dibacakan di depan raja Yehuda,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 25, 'karena mereka meninggalkan Aku dan membakar korban kepada allah lain dengan maksud menimbulkan sakit hati-Ku dengan segala pekerjaan tangan mereka; sebab itu nyala murka-Ku akan dicurahkan ke tempat ini dengan tidak padam-padam.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 26, 'Tetapi kepada raja Yehuda yang telah menyuruh kamu untuk meminta petunjuk TUHAN, harus kamu katakan demikian: Beginilah firman TUHAN, Allah Israel: Mengenai perkataan yang telah kaudengar itu,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 27, 'oleh karena engkau sudah menyesal dan engkau merendahkan diri di hadapan Allah pada waktu engkau mendengar firman-Nya terhadap tempat ini dan terhadap penduduknya, oleh karena engkau merendahkan diri di hadapan-Ku, mengoyakkan pakaianmu dan menangis di hadapan-Ku, Akupun telah mendengarnya, demikianlah firman TUHAN,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 28, 'maka sesungguhnya Aku akan mengumpulkan engkau kepada nenek moyangmu, dan engkau akan dikebumikan ke dalam kuburmu dengan damai, dan matamu tidak akan melihat segala malapetaka yang akan Kudatangkan atas tempat ini dan atas penduduknya." Lalu mereka menyampaikan jawab itu kepada raja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 29, 'Sesudah itu raja menyuruh orang mengumpulkan semua tua-tua Yehuda dan Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 30, 'Kemudian pergilah raja ke rumah TUHAN bersama-sama semua orang Yehuda dan penduduk Yerusalem, para imam, orang-orang Lewi, dan seluruh orang awam, baik yang besar maupun yang masih kecil. Dengan didengar mereka ia membacakan segala perkataan dari kitab perjanjian yang ditemukan di rumah TUHAN itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 31, 'Sesudah itu berdirilah raja pada tempatnya dan diikatnyalah perjanjian di hadapan TUHAN untuk hidup dengan mengikuti TUHAN, dan tetap menuruti perintah-perintah-Nya, peraturan-peraturan-Nya dan ketetapan-ketetapan-Nya dengan segenap hatinya dan dengan segenap jiwanya dan untuk melakukan perkataan perjanjian yang tertulis dalam kitab itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 32, 'Ia menyuruh semua orang yang berada di Yerusalem dan Benyamin ikut serta dalam perjanjian itu. Dan penduduk Yerusalem berbuat menurut perjanjian Allah, yakni Allah nenek moyang mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 34, 33, 'Yosia menjauhkan segala dewa kekejian dari semua daerah orang Israel dan menyuruh semua orang yang ada di Israel beribadah kepada TUHAN, Allah mereka. Maka sepanjang hidup Yosia mereka tidak menyimpang mengikuti TUHAN, Allah nenek moyang mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 1, 'Kemudian Yosia merayakan Paskah bagi TUHAN di Yerusalem. Domba Paskah disembelih pada tanggal empat belas bulan yang pertama.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 2, 'Ia menetapkan tugas para imam, dan mendorong mereka menunaikan tugas jabatannya dalam rumah TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 3, 'Berkatalah ia kepada orang-orang Lewi yang adalah pengajar seluruh Israel dan orang-orang kudus TUHAN: "Tempatkanlah tabut kudus itu di dalam rumah yang telah didirikan Salomo bin Daud, raja Israel. Tidak usah lagi kamu mengusungnya. Sekarang layanilah TUHAN, Allahmu, dan Israel, umat-Nya!', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 4, 'Bersiaplah menurut puak-puakmu dan menurut rombonganmu sebagaimana yang dituliskan Daud, raja Israel, dan Salomo, anaknya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 5, 'Berdirilah di halaman tempat kudus menurut golongan puak saudara-saudaramu yang lain, yakni kaum awam, dengan satu rombongan puak orang Lewi untuk tiap golongan saudara-saudaramu itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 6, 'Sembelihlah domba Paskah, kuduskanlah dirimu, dan adakanlah persiapan bagi saudara-saudaramu, supaya dilakukan apa yang difirmankan TUHAN dengan perantaraan Musa."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 7, 'Yosia menyumbangkan kepada kaum awam sejumlah tiga puluh ribu ekor kambing domba, yakni domba-domba dan kambing-kambing jantan yang muda, semuanya sebagai korban Paskah bagi semua orang yang hadir. Selain itu disumbangkannya tiga ribu ekor lembu. Semuanya itu dari harta milik raja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 8, 'Juga para panglimanya memberi sumbangan sukarela kepada rakyat, para imam, dan orang-orang Lewi. Kemudian Hilkia, Zakharia dan Yehiel, para pemuka rumah Allah, memberi kepada para imam dua ribu enam ratus ekor kambing domba sebagai korban Paskah dan selain itu tiga ratus ekor lembu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 9, 'Lalu Konanya dan kedua saudaranya, Semaya dan Netaneel, serta Hasabya, Yeiel dan Yozabad, para pemimpin orang-orang Lewi, menyumbangkan kepada orang-orang Lewi lima ribu ekor kambing domba sebagai korban Paskah dan selain itu lima ratus ekor lembu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 10, 'Setelah upacara ibadah disiapkan, berdirilah para imam pada tempatnya dan orang-orang Lewi menurut rombongannya sesuai dengan perintah raja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 11, 'Maka disembelihlah domba Paskah, dan para imam menyiramkan darah yang mereka terima dari orang-orang Lewi, sedang orang-orang Lewi menguliti domba itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 12, 'Tetapi mereka memisahkan korban bakaran untuk diserahkan kepada kaum awam menurut golongan puak mereka, supaya dipersembahkan kepada TUHAN sebagaimana tertulis dalam kitab Musa. Demikian pula dilakukan mereka dengan lembu-lembu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 13, 'Kemudian mereka memasak domba Paskah di atas api sesuai dengan peraturan, sedang persembahan-persembahan kudus mereka masak dalam kuali, belanga dan pinggan, lalu membawanya cepat-cepat kepada segenap kaum awam.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 14, 'Kemudian mereka menyediakannya bagi dirinya dan bagi para imam, karena para imam, yakni anak-anak Harun, sampai malam hari sibuk mempersembahkan korban bakaran dan segala lemak. Oleh sebab itu orang-orang Lewi menyediakannya bagi dirinya dan bagi para imam, yakni anak-anak Harun.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 15, 'Para penyanyi, yakni bani Asaf, ada pada tempat mereka sesuai dengan perintah Daud, Asaf, Heman dan Yedutun, pelihat raja itu; juga para penunggu pintu gerbang ada pada tiap-tiap pintu gerbang. Mereka tidak usah meninggalkan tugas mereka, karena saudara-saudara mereka, orang-orang Lewi, menyediakannya untuk mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 16, 'Demikianlah seluruh upacara ibadah bagi TUHAN disiapkan pada hari itu untuk merayakan Paskah dan untuk mempersembahkan korban bakaran di atas mezbah TUHAN sesuai dengan perintah raja Yosia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 17, 'Pada waktu itu orang Israel yang hadir di situ merayakan Paskah dan hari raya Roti Tidak Beragi selama tujuh hari.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 18, 'Paskah semacam itu tidak pernah lagi dirayakan di Israel sejak nabi Samuel. Seorangpun di antara raja-raja orang Israel tidak pernah merayakan Paskah seperti yang dirayakan Yosia dengan para imam dan orang-orang Lewi, dengan seluruh orang Yehuda dan Israel yang dapat hadir, dan dengan penduduk Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 19, 'Paskah itu dirayakan pada tahun kedelapan belas pemerintahan Yosia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 20, 'Kemudian dari pada semua ini, setelah Yosia memperbaiki rumah TUHAN, majulah Nekho, raja Mesir, hendak berperang di Karkemis di tepi sungai Efrat. Yosia keluar menghadapinya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 21, 'Ia mengirim utusan kepada Yosia, dengan pesan: "Apakah urusanmu dengan aku, raja Yehuda? Saat ini aku tidak datang melawan engkau, tetapi melawan keluarga raja yang sedang kuperangi. Allah memerintahkan aku supaya segera bertindak. Hentikanlah niatmu menentang Allah yang menyertai aku, supaya engkau jangan dimusnahkan-Nya!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 22, 'Tetapi Yosia tidak berpaling dari padanya, melainkan menyamar untuk berperang melawan dia. Ia tidak mengindahkan kata-kata Nekho, yang merupakan pesan Allah, lalu berperang di lembah Megido.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 23, 'Maka pemanah-pemanah menembaki raja Yosia, dan raja berseru kepada orang-orangnya: "Bawa aku dari sini, karena aku luka parah!"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 24, 'Orang-orangnya mengangkatnya dari keretanya, lalu mengangkutnya dengan kereta cadangannya lalu membawanya ke Yerusalem. Kemudian matilah ia, lalu dikuburkan di pekuburan nenek moyangnya. Seluruh Yehuda dan Yerusalem berkabung karena Yosia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 25, 'Yeremia membuat suatu syair ratapan mengenai Yosia. Dan sampai sekarang ini semua penyanyi laki-laki dan penyanyi perempuan menyanyikan syair-syair ratapan mengenai Yosia, dan mereka jadikan itu suatu kebiasaan di Israel. Semuanya itu tertulis dalam Syair-syair Ratapan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 26, 'Selebihnya dari riwayat Yosia dan perbuatan-perbuatannya yang saleh yang sesuai dengan yang ada tertulis dalam Taurat TUHAN,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 35, 27, 'yakni, riwayatnya dari awal sampai akhir, sesungguhnya semuanya itu tertulis dalam kitab raja-raja Israel dan Yehuda.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 1, 'Rakyat negeri menjemput Yoahas anak Yosia, dan mengangkat dia menjadi raja di Yerusalem menggantikan ayahnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 2, 'Yoahas berumur dua puluh tiga tahun pada waktu ia menjadi raja dan tiga bulan lamanya ia memerintah di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 3, 'Raja Mesir memecatnya dari pemerintahannya di Yerusalem dan mendenda negeri itu seratus talenta perak dan satu talenta emas.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 4, 'Kemudian raja Mesir itu mengangkat Elyakim, saudara Yoahas, menjadi raja atas Yehuda dan Yerusalem, dan menukar namanya dengan Yoyakim. Tetapi Yoahas, saudaranya itu, ditawan oleh Nekho, dan dibawa ke Mesir.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 5, 'Yoyakim berumur dua puluh lima tahun pada waktu ia menjadi raja dan sebelas tahun lamanya ia memerintah di Yerusalem. Ia melakukan apa yang jahat di mata TUHAN, Allahnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 6, 'Nebukadnezar, raja Babel, maju melawan dia, membelenggunya dengan rantai tembaga untuk membawanya ke Babel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 7, 'Juga beberapa perkakas rumah TUHAN dibawa Nebukadnezar ke Babel dan ditempatkan di istananya di Babel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 8, 'Selebihnya dari riwayat Yoyakim, segala kekejian yang dilakukannya dan kesalahan yang ada padanya, sesungguhnya semuanya itu tertulis dalam kitab raja-raja Israel dan Yehuda. Maka Yoyakhin, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 9, 'Yoyakhin berumur delapan belas tahun pada waktu ia menjadi raja dan tiga bulan sepuluh hari lamanya ia memerintah di Yerusalem. Ia melakukan apa yang jahat di mata TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 10, 'Pada pergantian tahun raja Nebukadnezar menyuruh membawa dia ke Babel beserta perkakas-perkakas yang indah-indah dari rumah TUHAN dan Zedekia, saudara ayah Yoyakhin, menjadi raja atas Yehuda dan Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 11, 'Zedekia berumur dua puluh satu tahun pada waktu ia menjadi raja dan sebelas tahun lamanya ia memerintah di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 12, 'Ia melakukan apa yang jahat di mata TUHAN, Allahnya, dan tidak merendahkan diri di hadapan nabi Yeremia, yang datang membawa pesan TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 13, 'Lagipula ia memberontak terhadap raja Nebukadnezar, yang telah menyuruhnya bersumpah demi Allah. Ia menegarkan tengkuknya dan mengeraskan hatinya dan tidak berbalik kepada TUHAN, Allah Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 14, 'Juga semua pemimpin di antara para imam dan rakyat berkali-kali berubah setia dengan mengikuti segala kekejian bangsa-bangsa lain. Rumah yang dikuduskan TUHAN di Yerusalem itu dinajiskan mereka.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 15, 'Namun TUHAN, Allah nenek moyang mereka, berulang-ulang mengirim pesan melalui utusan-utusan-Nya, karena Ia sayang kepada umat-Nya dan tempat kediaman-Nya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 16, 'Tetapi mereka mengolok-olok utusan-utusan Allah itu, menghina segala firman-Nya, dan mengejek nabi-nabi-Nya. Oleh sebab itu murka TUHAN bangkit terhadap umat-Nya, sehingga tidak mungkin lagi pemulihan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 17, 'TUHAN menggerakkan raja orang Kasdim melawan mereka. Raja itu membunuh teruna mereka dengan pedang dalam rumah kudus mereka, dan tidak menyayangkan teruna atau gadis, orang tua atau orang ubanan?semua diserahkan TUHAN ke dalam tangannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 18, 'Seluruh perkakas rumah Allah, yang besar dan yang kecil, serta harta benda dari rumah TUHAN, harta benda raja dan harta benda para panglimanya, semuanya dibawanya ke Babel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 19, 'Mereka membakar rumah Allah, merobohkan tembok Yerusalem dan membakar segala puri dalam kota itu dengan api, sehingga musnahlah segala perabotannya yang indah-indah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 20, 'Mereka yang masih tinggal dan yang luput dari pedang diangkutnya ke Babel dan mereka menjadi budaknya dan budak anak-anaknya sampai kerajaan Persia berkuasa.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 21, 'Dengan demikian genaplah firman TUHAN yang diucapkan Yeremia, sampai tanah itu pulih dari akibat dilalaikannya tahun-tahun sabatnya, karena tanah itu tandus selama menjalani sabat, hingga genaplah tujuh puluh tahun.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 22, 'Pada tahun pertama zaman Koresh, raja negeri Persia, TUHAN menggerakkan hati Koresh, raja Persia itu untuk menggenapkan firman yang diucapkan oleh Yeremia, sehingga disiarkan di seluruh kerajaan Koresh secara lisan dan tulisan pengumuman ini:', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 36, 23, '"Beginilah perintah Koresh, raja Persia: Segala kerajaan di bumi telah dikaruniakan kepadaku oleh TUHAN, Allah semesta langit. Ia menugaskan aku untuk mendirikan rumah bagi-Nya di Yerusalem, yang terletak di Yehuda. Siapa di antara kamu termasuk umat-Nya, TUHAN, Allahnya, menyertainya, dan biarlah ia berangkat pulang!"', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 1, 1, 'Pada tahun pertama zaman Koresh, raja negeri Persia, TUHAN menggerakkan hati Koresh, raja Persia itu untuk menggenapkan firman yang diucapkan oleh Yeremia, sehingga disiarkan di seluruh kerajaan Koresh secara lisan dan tulisan pengumuman ini:', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 1, 2, '"Beginilah perintah Koresh, raja Persia: Segala kerajaan di bumi telah dikaruniakan kepadaku oleh TUHAN, Allah semesta langit. Ia menugaskan aku untuk mendirikan rumah bagi-Nya di Yerusalem, yang terletak di Yehuda.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 1, 3, 'Siapa di antara kamu termasuk umat-Nya, Allahnya menyertainya! Biarlah ia berangkat pulang ke Yerusalem, yang terletak di Yehuda, dan mendirikan rumah TUHAN. Allah Israel, yakni Allah yang diam di Yerusalem.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 1, 4, 'Dan setiap orang yang tertinggal, di manapun ia ada sebagai pendatang, harus disokong oleh penduduk setempat dengan perak dan emas, harta benda dan ternak, di samping persembahan sukarela bagi rumah Allah yang ada di Yerusalem."', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 1, 5, 'Maka berkemaslah kepala-kepala kaum keluarga orang Yehuda dan orang Benyamin, serta para imam dan orang-orang Lewi, yakni setiap orang yang hatinya digerakkan Allah untuk berangkat pulang dan mendirikan rumah TUHAN yang ada di Yerusalem.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 1, 6, 'Dan segala orang di sekeliling mereka membantu mereka dengan barang-barang perak, dengan emas, harta benda dan ternak dan dengan pemberian yang indah-indah, selain dari segala sesuatu yang dipersembahkan dengan sukarela.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 1, 7, 'Pula raja Koresh menyuruh mengeluarkan perlengkapan rumah TUHAN yang telah diangkut Nebukadnezar dari Yerusalem dan yang ditaruhnya di dalam kuil allahnya.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 1, 8, 'Koresh, raja Persia itu, menyuruh mengeluarkan semuanya itu di bawah pengawasan Mitredat, bendahara raja, yang menghitung seluruhnya bagi Sesbazar, pembesar di Yehuda.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 1, 9, 'Inilah daftarnya: tiga puluh bokor emas, seribu bokor perak, dua puluh sembilan pisau,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 1, 10, 'tiga puluh piala emas, pula empat ratus sepuluh piala perak, seribu buah barang-barang lain.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 1, 11, 'Barang-barang emas dan perak itu seluruhnya berjumlah lima ribu empat ratus. Semuanya itu dibawa oleh Sesbazar sewaktu orang-orang buangan itu dibawa pulang dari negeri Babel ke Yerusalem.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 1, 'Inilah orang-orang propinsi Yehuda yang berangkat pulang dari pembuangan, yakni para tawanan, yang dahulu diangkut ke Babel oleh Nebukadnezar, raja Babel, dan yang kembali ke Yerusalem dan ke Yehuda, masing-masing ke kotanya.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 2, 'Mereka datang bersama-sama Zerubabel, Yesua, Nehemia, Seraya, Reelaya, Mordekhai, Bilsan, Mispar, Bigwai, Rehum dan Baana. Inilah daftar orang-orang bangsa Israel:', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 3, 'bani Paros: dua ribu seratus tujuh puluh dua orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 4, 'bani Sefaca: tiga ratus tujuh puluh dua orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 5, 'bani Arah: tujuh ratus tujuh puluh lima orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 6, 'bani Pahat-Moab, yakni anak-anak Yesua dan Yoab: dua ribu delapan ratus dua belas orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 7, 'bani Elam: seribu dua ratus lima puluh empat orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 8, 'bani Zatu: sembilan ratus empat puluh lima orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 9, 'bani Zakai: tujuh ratus enam puluh orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 10, 'bani Bani: enam ratus empat puluh dua orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 11, 'bani Bebai: enam ratus dua puluh tiga orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 12, 'bani Azgad: seribu dua ratus dua puluh dua orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 13, 'bani Adonikam: enam ratus enam puluh enam orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 14, 'bani Bigwai: dua ribu lima puluh enam orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 15, 'bani Adin: empat ratus lima puluh empat orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 16, 'bani Ater, yakni bani Hizkia: sembilan puluh delapan orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 17, 'bani Bezai: tiga ratus dua puluh tiga orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 18, 'bani Yora: seratus dua belas orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 19, 'bani Hasum: dua ratus dua puluh tiga orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 20, 'bani Gibar: sembilan puluh lima orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 21, 'dari Betlehem: seratus dua puluh tiga orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 22, 'orang-orang Netofa: lima puluh enam orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 23, 'orang-orang Anatot: seratus dua puluh delapan orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 24, 'dari Asmawet: empat puluh dua orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 25, 'dari Kiryat-Arim, Kefira dan Beerot: tujuh ratus empat puluh tiga orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 26, 'dari Rama dan Gaba: enam ratus dua puluh satu orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 27, 'orang-orang Mikhmas: seratus dua puluh dua orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 28, 'orang-orang Betel dan Ai: dua ratus dua puluh tiga orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 29, 'dari Nebo: lima puluh dua orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 30, 'bani Magbis: seratus lima puluh enam orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 31, 'bani Elam, yakni Elam yang lain: seribu dua ratus lima puluh empat orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 32, 'bani Harim: tiga ratus dua puluh orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 33, 'orang-orang dari Lod, Hadid dan Ono: tujuh ratus dua puluh lima orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 34, 'dari Yerikho: tiga ratus empat puluh lima orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 35, 'bani Senaa: tiga ribu enam ratus tiga puluh orang.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 36, 'Inilah para imam: bani Yedaya, yakni kaum keluarga Yesua: sembilan ratus tujuh puluh tiga orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 37, 'bani Imer: seribu lima puluh dua orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 38, 'bani Pasyhur: seribu dua ratus empat puluh tujuh orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 39, 'bani Harim: seribu tujuh belas orang.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 40, 'Inilah orang-orang Lewi: bani Yesua dan Kadmiel, yakni bani Hodawya: tujuh puluh empat orang.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 41, 'Inilah para penyanyi: bani Asaf: seratus dua puluh delapan orang.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 42, 'Inilah kaum penunggu pintu gerbang: bani Salum, bani Ater, bani Talmon, bani Akub, bani Hatita, bani Sobai, semuanya seratus tiga puluh sembilan orang.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 43, 'Inilah para budak di bait Allah: bani Ziha, bani Hasufa, bani Tabaot;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 44, 'bani Keros, bani Siaha, bani Padon;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 45, 'bani Lebana, bani Hagaba, bani Akub;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 46, 'bani Hagab, bani Samlai, bani Hanan;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 47, 'bani Gidel, bani Gahar, bani Reaya;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 48, 'bani Rezin, bani Nekoda, bani Gazam;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 49, 'bani Uza, bani Paseah, bani Besai;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 50, 'bani Asna, bani Meunim, bani Nefusim;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 51, 'bani Bakbuk, bani Hakufa, bani Harhur;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 52, 'bani Bazlut, bani Mehida, bani Harsa;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 53, 'bani Barkos, bani Sisera, bani Temah;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 54, 'bani Neziah, bani Hatifa.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 55, 'Inilah keturunan para hamba Salomo: bani Sotai, bani Soferet, bani Peruda;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 56, 'bani Yaala, bani Darkon, bani Gidel;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 57, 'bani Sefaca, bani Hatil, bani Pokheret-Hazebaim, bani Ami.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 58, 'Seluruh budak di bait Allah dan keturunan para hamba Salomo ada tiga ratus sembilan puluh dua orang.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 59, 'Inilah orang-orang yang berangkat pulang dari Tel-Melah, Tel-Harsa, Kerub, Adan dan Imer, tetapi mereka tidak dapat menyatakan apakah kaum keluarga dan asal usul mereka termasuk bangsa Israel:', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 2, 60, 'bani Delaya, bani Tobia, bani Nekoda, enam ratus lima puluh dua orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 3, 1, 'Ketika tiba bulan yang ketujuh, setelah orang Israel menetap di kota-kotanya, maka serentak berkumpullah seluruh rakyat di Yerusalem.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 3, 2, 'Maka mulailah Yesua bin Yozadak beserta saudara-saudaranya, para imam itu, dan Zerubabel bin Sealtiel beserta saudara-saudaranya membangun mezbah Allah Israel untuk mempersembahkan korban bakaran di atasnya, sesuai dengan yang ada tertulis dalam kitab Taurat Musa, abdi Allah.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 3, 3, 'Mereka mendirikan mezbah itu di tempatnya semula, sungguhpun mereka ketakutan terhadap penduduk negeri, lalu mereka mempersembahkan di atasnya korban bakaran kepada TUHAN, korban bakaran waktu pagi dan waktu petang.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 3, 4, 'Mereka juga mengadakan hari raya Pondok Daun, sesuai dengan yang ada tertulis, dan mempersembahkan korban bakaran hari demi hari menurut jumlah yang sesuai dengan peraturan, yakni setiap hari menurut yang ditetapkan untuk hari itu.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 3, 5, 'Dan sejak itu diadakanlah korban bakaran yang tetap, juga korban bakaran pada bulan baru dan pada setiap hari raya yang kudus bagi TUHAN, dan setiap kali orang mempersembahkan persembahan sukarela kepada TUHAN.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 3, 6, 'Sejak hari pertama bulan yang ketujuh mereka mulai mempersembahkan korban bakaran kepada TUHAN, namun dasar bait suci TUHAN belum juga diletakkan.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 3, 7, 'Lalu mereka memberikan uang kepada tukang batu dan tukang kayu, sedang kepada orang Sidon dan Tirus makanan dan minuman dan minyak, supaya orang-orang itu membawa kayu aras dari Libanon sampai ke laut dekat Yafo, seperti yang telah diizinkan kepada mereka oleh Koresh, raja negeri Persia.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 3, 8, 'Pada tahun yang kedua sesudah mereka sampai ke rumah Allah di Yerusalem, dalam bulan yang kedua, maka Zerubabel bin Sealtiel dan Yesua bin Yozadak beserta saudara-saudara mereka yang lain, yakni para imam dan orang-orang Lewi, dan semua orang yang pulang ke Yerusalem dari tempat tawanan memulai pekerjaan itu. Mereka menugaskan orang-orang Lewi yang berumur dua puluh tahun ke atas untuk mengawasi pekerjaan membangun rumah TUHAN.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 3, 9, 'Lalu Yesua serta anak-anak dan saudara-saudaranya dan Kadmiel serta anak-anaknya, orang-orang Yehuda bersama-sama bertindak mengawasi orang-orang yang melakukan pekerjaan membangun rumah Allah. Demikian juga bani Henadad, anak-anak dan saudara-saudara mereka, orang-orang Lewi itu.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 3, 10, 'Pada waktu dasar bait suci TUHAN diletakkan oleh tukang-tukang bangunan, maka tampillah para imam dengan memakai pakaian jabatan dan membawa nafiri, dan orang-orang Lewi, bani Asaf, dengan membawa ceracap, untuk memuji-muji TUHAN, menurut petunjuk Daud, raja Israel.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 3, 11, 'Secara berbalas-balasan mereka menyanyikan bagi TUHAN nyanyian pujian dan syukur: "Sebab Ia baik! Bahwasanya untuk selama-lamanya kasih setia-Nya kepada Israel!" Dan seluruh umat bersorak-sorai dengan nyaring sambil memuji-muji TUHAN, oleh karena dasar rumah TUHAN telah diletakkan.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 3, 12, 'Tetapi banyak di antara para imam, orang-orang Lewi dan kepala-kepala kaum keluarga, orang tua-tua yang pernah melihat rumah yang dahulu, menangis dengan suara nyaring, ketika perletakan dasar rumah ini dilakukan di depan mata mereka, sedang banyak orang bersorak-sorai dengan suara nyaring karena kegirangan.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 3, 13, 'Orang tidak dapat lagi membedakan mana bunyi sorak-sorai kegirangan dan mana bunyi tangis rakyat, karena rakyat bersorak-sorai dengan suara yang nyaring, sehingga bunyinya kedengaran sampai jauh.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 1, 'Ketika lawan orang Yehuda dan Benyamin mendengar, bahwa orang-orang yang pulang dari pembuangan itu sedang membangun bait suci bagi TUHAN, Allah Israel,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 2, 'maka mereka mendekati Zerubabel serta para kepala kaum keluarga dan berkata kepada mereka: "Biarlah kami turut membangun bersama-sama dengan kamu, karena kamipun berbakti kepada Allahmu sama seperti kamu; lagipula kami selalu mempersembahkan korban kepada-Nya sejak zaman Esar-Hadon, raja Asyur, yang memindahkan kami ke mari."', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 3, 'Tetapi Zerubabel, Yesua dan para kepala kaum keluarga orang Israel yang lain berkata kepada mereka: "Bukanlah urusan kita bersama, sehingga kamu dan kami membangun rumah bagi Allah kami, karena kami sendirilah yang hendak membangun bagi TUHAN, Allah Israel, seperti yang diperintahkan kepada kami oleh Koresh, raja negeri Persia."', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 4, 'Maka penduduk negeri itu melemahkan semangat orang-orang Yehuda dan membuat mereka takut membangun.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 5, 'Bahkan, selama zaman Koresh, raja negeri Persia, sampai zaman pemerintahan Darius, raja negeri Persia, mereka menyogok para penasihat untuk melawan orang-orang Yehuda itu dan menggagalkan rancangan mereka.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 6, 'Pada zaman pemerintahan Ahasyweros, pada permulaan pemerintahannya, mereka menulis surat tuduhan terhadap orang-orang yang telah menetap di Yehuda dan di Yerusalem.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 7, 'Dan pada zaman Artahsasta ditulislah surat oleh Bislam, Mitredat dan Tabeel serta rekan-rekannya yang lain kepada Artahsasta, raja negeri Persia. Naskah surat itu ditulis dalam bahasa Aram dengan terjemahannya. (Dalam bahasa Aram:)', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 8, 'Rehum, bupati, dan Simsai, panitera, telah menulis surat terhadap Yerusalem kepada raja Artahsasta, yang isinya sebagai berikut.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 9, '?Pada waktu itu ditulislah surat itu oleh Rehum, bupati, dan Simsai, panitera, serta rekan-rekan mereka yang lain, para hakim dan punggawa dan pegawai-pegawai, orang Persia, orang-orang dari Erekh, dari Babel serta orang-orang dari Susan, yaitu orang-orang Elam,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 10, 'dan bangsa-bangsa lain, yang oleh Asnapar yang agung dan mulia itu dipindahkan dan disuruh menetap di kota Samaria dan di daerah yang lain sebelah barat sungai Efrat.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 11, 'Inilah salinan surat yang dikirim mereka kepadanya: "Ke hadapan raja Artahsasta dari hamba-hamba tuanku, orang-orang di daerah sebelah barat sungai Efrat. Maka', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 12, 'kiranya raja maklum, bahwa orang-orang Yahudi, yang berangkat dari tuanku ke tempat kami, telah tiba di Yerusalem. Mereka sedang membangun kembali kota yang durhaka dan jahat itu; mereka menyelesaikan pembangunan tembok-tembok dan memperbaiki dasarnya.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 13, 'Kiranya raja maklum, bahwa jikalau kota itu sudah dibangun dan tembok-temboknya sudah selesai, orang tidak lagi membayar pajak, upeti atau bea, sehingga kota itu akhirnya mendatangkan kerugian kepada raja-raja.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 14, 'Sekarang, oleh karena kami mempunyai hubungan dengan raja dan tidak patut bagi kami melihat raja kena cela, maka oleh sebab itu kami menyuruh orang memberitahukan hal itu kepada raja,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 15, 'supaya diadakan penyelidikan dalam kitab riwayat nenek moyang tuanku. Di dalam kitab riwayat itu tuanku akan mendapati dan mengetahui, bahwa kota itu kota durhaka, yang selalu mendatangkan kerugian kepada raja-raja dan daerah-daerah, dan bahwa orang selalu mengadakan pemberontakan di dalamnya sejak zaman dahulu. Itulah sebabnya maka kota itu dibinasakan.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 16, 'Kami ini memberitahukan kepada raja, bahwa jikalau kota itu sudah dibangun kembali dan tembok-temboknya sudah selesai, maka bagi tuanku kelak tidak ada lagi milik di daerah sebelah barat sungai Efrat."', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 17, 'Maka raja mengirim surat jawaban ini: "Kepada Rehum, bupati, dan Simsai, panitera, serta rekan-rekan mereka yang lain, yang tinggal di Samaria dan di daerah yang lain seberang sungai Efrat. Salam! Maka sekarang,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 18, 'surat yang kamu kirim kepada kami, telah dibacakan kepadaku dengan jelas.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 19, 'Lalu atas perintahku telah diadakan penyelidikan, dan didapati, bahwa kota itu sejak zaman dahulu selalu bangkit melawan raja-raja dan bahwa penduduknya selalu mendurhaka dan memberontak.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 20, 'Lagipula dahulu ada raja-raja yang berkuasa atas Yerusalem, yang memerintah seluruh daerah seberang sungai Efrat, dan kepada mereka dibayarlah pajak, upeti dan bea.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 21, 'Oleh sebab itu, keluarkanlah perintah, untuk menghentikan orang-orang itu, supaya kota itu jangan dibangun kembali, sebelum aku mengeluarkan perintah.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 22, 'Dan ingatlah baik-baik supaya jangan kamu perbuat suatu kelalaian dalam perkara ini. Apakah gunanya kerusakan yang menjadi kerugian raja-raja itu bertambah besar?"', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 23, 'Maka setelah salinan surat raja Artahsasta dibacakan kepada Rehum, dan Simsai, panitera, serta rekan-rekan mereka, berangkatlah mereka dengan segera ke Yerusalem mendapatkan orang-orang Yahudi, dan dengan kekerasan mereka memaksa orang-orang itu menghentikan pekerjaan itu.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 4, 24, 'Pada waktu itu terhentilah pekerjaan membangun rumah Allah yang di Yerusalem, dan tetap terhenti sampai tahun yang kedua zaman pemerintahan Darius, raja negeri Persia.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 1, 'Tetapi nabi Hagai dan Zakharia bin Ido, kedua nabi itu, bernubuat terhadap orang-orang Yahudi yang tinggal di Yehuda dan di Yerusalem dalam nama Allah Israel, yang menyertai mereka.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 2, 'Pada waktu itu mulailah Zerubabel bin Sealtiel dan Yesua bin Yozadak membangun rumah Allah yang ada di Yerusalem. Mereka didampingi dan dibantu oleh nabi-nabi Allah.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 3, 'Tetapi pada waktu itu juga datanglah kepada mereka Tatnai, bupati daerah sebelah barat sungai Efrat, bersama-sama dengan Syetar-Boznai dan rekan-rekan mereka, dan beginilah katanya kepada mereka: "Siapakah yang memberi perintah kepadamu untuk membangun rumah ini dan menyelesaikan tembok ini?"', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 4, 'Lalu katanya pula kepada mereka: "Siapakah nama-nama orang yang mendirikan bangunan ini?"', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 5, 'Tetapi mata Allah mengamat-amati para tua-tua orang Yahudi, sehingga mereka tidak dipaksa berhenti oleh orang-orang itu sampai ada berita diterima oleh Darius dan kemudian dikirim kembali surat jawaban mengenai hal itu.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 6, 'Inilah salinan surat yang dikirim Tatnai, bupati daerah sebelah barat sungai Efrat, bersama-sama dengan Syetar-Boznai dan rekan-rekannya, para punggawa daerah sebelah barat sungai Efrat, kepada raja Darius.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 7, 'Mereka mengirim laporan tertulis kepadanya yang bunyinya sebagai berikut: "Ke hadapan raja Darius. Salam sejahtera!', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 8, 'Kiranya raja maklum, bahwa kami datang ke daerah Yehuda, ke rumah Allah yang maha besar. Rumah itu sedang dibangun dengan batu yang besar-besar, sedang dindingnya dilapis dengan kayu, dan pekerjaan itu dikerjakan dengan seksama dan berjalan lancar di tangan mereka.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 9, 'Kemudian kami menanyai para tua-tua itu dan beginilah kata kami kepada mereka: Siapakah yang memberi perintah kepadamu untuk membangun rumah ini dan menyelesaikan tembok ini?', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 10, 'Lagipula kami tanyakan kepada mereka nama-nama mereka, untuk memberitahukannya kepada tuanku, dengan mencatat nama orang-orang yang mengepalai mereka.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 11, 'Inilah jawaban yang diberikan mereka kepada kami: Kami adalah hamba-hamba Allah semesta langit dan bumi, dan kami membangun kembali rumah, yang telah didirikan bertahun-tahun sebelumnya, didirikan dan diselesaikan oleh seorang raja Israel yang agung.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 12, 'Tetapi sesudah nenek moyang kami membangkitkan murka Allah semesta langit, mereka diserahkan-Nya ke dalam tangan Nebukadnezar, raja negeri Babel, orang Kasdim, yang merusak rumah itu dan mengangkut bangsa itu sebagai tawanan ke negeri Babel.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 13, 'Akan tetapi pada tahun pertama zaman Koresh, raja negeri Babel, dikeluarkanlah perintah oleh raja Koresh untuk membangun rumah Allah ini.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 14, 'Juga perlengkapan emas dan perak dari rumah Allah, yang telah diambil oleh Nebukadnezar dari bait suci yang di Yerusalem dan dibawa ke dalam bait suci yang di Babel, diambil pula oleh raja Koresh dari bait suci yang di Babel itu, dan diserahkan kepada seorang yang bernama Sesbazar yang telah diangkatnya menjadi bupati.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 15, 'Perintahnya kepadanya: Ambillah perlengkapan ini, pergilah dan taruhlah itu di dalam bait suci yang di Yerusalem, dan biarlah rumah Allah dibangun di tempatnya yang semula.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 16, 'Kemudian datanglah Sesbazar, meletakkan dasar rumah Allah yang ada di Yerusalem, dan sejak waktu itu sampai sekarang dikerjakanlah pembangunannya, hanya belum selesai.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 5, 17, 'Oleh sebab itu, jikalau dianggap baik oleh raja, maka hendaklah diadakan penyelidikan di dalam gedung perbendaharaan raja, di sana, di Babel, apakah pernah dikeluarkan perintah oleh raja Koresh untuk membangun kembali rumah Allah yang di Yerusalem itu. Kemudian keputusan raja tentang hal itu kiranya dikirimkan kepada kami."', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 1, 'Sesudah itu atas perintah raja Darius diadakanlah penyelidikan di perbendaharaan di Babel, di tempat naskah-naskah disimpan.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 2, 'Kemudian di Ahmeta, benteng yang di propinsi Media, didapati sebuah gulungan, yang isinya sebagai berikut: "Piagam:', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 3, 'Pada tahun pertama zaman raja Koresh dikeluarkanlah perintah oleh raja Koresh: Mengenai rumah Allah di Yerusalem. Rumah itu haruslah dibangun kembali sebagai tempat orang mempersembahkan korban sembelihan dan korban api-apian; haruslah tingginya enam puluh hasta dan lebarnya enam puluh hasta.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 4, 'Dan haruslah dipasang tiga lapis batu besar-besar dan satu lapis kayu. Biayanya harus dibayar dari perbendaharaan kerajaan.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 5, 'Dan juga perlengkapan emas dan perak rumah Allah yang diambil oleh Nebukadnezar dari bait suci yang di Yerusalem dan dibawa ke Babel itu haruslah dikembalikan, supaya kembali pula ke dalam bait suci yang di Yerusalem, ke tempatnya yang semula; dan engkau haruslah menaruhnya di dalam rumah Allah."', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 6, '"Oleh sebab itu, hai Tatnai, bupati daerah seberang sungai Efrat, dan Syetar-Boznai serta rekan-rekanmu, para punggawa daerah seberang sungai Efrat, hendaklah kamu menjauhkan diri dari sana.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 7, 'Biarkanlah pekerjaan membangun rumah Allah itu. Bupati dan para tua-tua orang Yahudi boleh membangun rumah Allah itu di tempatnya yang semula.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 8, 'Lagipula telah dikeluarkan perintah olehku tentang apa yang harus kamu perbuat terhadap para tua-tua orang Yahudi mengenai pembangunan rumah Allah itu, yakni dari pada penghasilan kerajaan, dari pada upeti daerah seberang sungai Efrat, haruslah dengan seksama dan dengan tidak bertangguh diberi biaya kepada orang-orang itu.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 9, 'Dan apa yang diperlukan, yakni lembu jantan muda, domba jantan, anak domba untuk korban bakaran bagi Allah semesta langit, juga gandum, garam, anggur dan minyak, menurut petunjuk para imam yang di Yerusalem, semuanya itu harus diberikan kepada mereka hari demi hari tanpa kelalaian,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 10, 'supaya mereka selalu mempersembahkan korban yang menyenangkan kepada Allah semesta langit dan mendoakan raja serta anak-anaknya.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 11, 'Selanjutnya telah dikeluarkan perintah olehku, supaya setiap orang yang melanggar keputusan ini, akan dicabut sebatang tiang dari rumahnya, untuk menyulakannya pada ujung tiang itu dan supaya rumahnya dijadikan reruntuhan oleh karena hal itu.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 12, 'Maka Allah, yang sudah membuat nama-Nya diam di sana, biarlah Ia merobohkan setiap raja dan setiap bangsa, yang mengacungkan tangan untuk melanggar keputusan ini dan membinasakan rumah Allah yang di Yerusalem itu. Aku, Darius, yang mengeluarkan perintah ini. Hendaklah itu dilakukan dengan seksama."', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 13, 'Kemudian Tatnai, bupati daerah sebelah barat sungai Efrat, Syetar-Boznai dan rekan-rekan mereka berbuat dengan seksama menurut apa yang diperintahkan raja Darius.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 14, 'Para tua-tua orang Yahudi melanjutkan pembangunan itu dengan lancar digerakkan oleh nubuat nabi Hagai dan nabi Zakharia bin Ido. Mereka menyelesaikan pembangunan menurut perintah Allah Israel dan menurut perintah Koresh, Darius dan Artahsasta, raja-raja negeri Persia.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 15, 'Maka selesailah rumah itu pada hari yang ketiga bulan Adar, yakni pada tahun yang keenam zaman pemerintahan raja Darius.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 16, 'Maka orang Israel, para imam, orang-orang Lewi dan orang-orang lain yang pulang dari pembuangan, merayakan pentahbisan rumah Allah ini dengan sukaria.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 17, 'Untuk pentahbisan rumah Allah ini mereka mempersembahkan lembu jantan seratus ekor, domba jantan dua ratus ekor dan anak domba empat ratus ekor; juga kambing jantan sebagai korban penghapus dosa bagi seluruh orang Israel dua belas ekor, menurut bilangan suku Israel.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 18, 'Mereka juga menempatkan para imam pada golongan-golongannya dan orang-orang Lewi pada rombongan-rombongannya untuk melakukan ibadah kepada Allah yang diam di Yerusalem, sesuai dengan yang ada tertulis dalam kitab Musa.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 19, 'Dan pada tanggal empat belas bulan pertama mereka yang pulang dari pembuangan merayakan Paskah.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 20, 'Karena para imam dan orang-orang Lewi bersama-sama mentahirkan diri, sehingga tahirlah mereka sekalian. Demikianlah mereka menyembelih anak domba Paskah bagi semua orang yang pulang dari pembuangan, dan bagi saudara-saudara mereka, yakni para imam, dan bagi dirinya sendiri.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 21, 'Orang-orang Israel yang pulang dari pembuangan memakannya dan demikian juga setiap orang yang memisahkan diri dari kenajisan bangsa-bangsa negeri itu lalu menggabungkan diri kepada mereka, untuk berbakti kepada TUHAN, Allah Israel.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 6, 22, 'Lagipula mereka merayakan hari raya Roti Tidak Beragi dengan sukacita, tujuh hari lamanya, karena TUHAN telah membuat mereka bersukacita; Ia telah memalingkan hati raja negeri Asyur kepada mereka, sehingga raja membantu mereka dalam pekerjaan membangun rumah Allah, yakni Allah Israel.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 1, 'Kemudian dari pada semuanya itu, pada zaman pemerintahan Artahsasta, raja negeri Persia, maka berangkatlah Ezra bin Seraya bin Azarya bin Hilkia', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 2, 'bin Salum bin Zadok bin Ahitub', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 3, 'bin Amarya bin Azarya bin Merayot', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 4, 'bin Zerahya bin Uzi bin Buki', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 5, 'bin Abisua bin Pinehas bin Eleazar bin Harun, yaitu Harun imam kepala.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 6, 'Ezra ini berangkat pulang dari Babel. Ia adalah seorang ahli kitab, mahir dalam Taurat Musa yang diberikan TUHAN, Allah Israel. Dan raja memberi dia segala yang diingininya, oleh karena tangan TUHAN, Allahnya, melindungi dia.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 7, 'Juga berangkat pulang ke Yerusalem beberapa rombongan orang Israel dan imam, orang Lewi, penyanyi, penunggu pintu gerbang dan budak di bait Allah pada tahun ketujuh zaman raja Artahsasta.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 8, 'Lalu tibalah ia di Yerusalem pada bulan kelima, yakni pada tahun ketujuh zaman raja itu.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 9, 'Tepat pada tanggal satu bulan pertama ia memulai perjalanannya pulang dari Babel dan tepat pada tanggal satu bulan kelima ia tiba di Yerusalem, oleh karena tangan murah Allahnya itu melindungi dia.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 10, 'Sebab Ezra telah bertekad untuk meneliti Taurat TUHAN dan melakukannya serta mengajar ketetapan dan peraturan di antara orang Israel.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 11, 'Inilah salinan surat, yang diberikan raja Artahsasta kepada Ezra, imam dan ahli kitab itu, yang ahli dalam perkataan segala perintah dan ketetapan TUHAN bagi orang Israel:', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 12, '"Artahsasta, raja segala raja, kepada Ezra, imam dan ahli Taurat Allah semesta langit, dan selanjutnya. Maka sekarang,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 13, 'olehku telah dikeluarkan perintah, bahwa setiap orang di dalam kerajaanku yang termasuk orang Israel awam, atau para imamnya atau orang-orang Lewi, dan yang rela pergi ke Yerusalem, boleh turut pergi dengan engkau.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 14, 'Oleh karena engkau disuruh raja serta ketujuh orang penasihatnya untuk mengadakan penyelidikan mengenai Yehuda dan Yerusalem dengan berpedoman kepada hukum Allahmu yang menjadi peganganmu,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 15, 'dan untuk membawa perak dan emas, yang diberikan raja serta para penasihatnya sebagai persembahan sukarela kepada Allah Israel, yang tempat kediaman-Nya di Yerusalem,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 16, 'beserta segala perak dan emas yang akan kauperoleh di seluruh propinsi Babel, dengan persembahan sukarela yang akan dipersembahkan oleh rakyat dan para imam bagi rumah Allah mereka yang ada di Yerusalem,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 17, 'maka oleh karena itu haruslah engkau dengan seksama memakai uang itu untuk membeli lembu-lembu jantan, domba-domba jantan, anak-anak domba dengan korban sajiannya dan korban curahannya, dan haruslah semuanya itu kaupersembahkan di atas mezbah di rumah Allahmu yang ada di Yerusalem.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 18, 'Tetapi apa yang dianggap baik olehmu dan oleh saudara-saudaramu untuk diperbuat dengan perak dan emas yang selebihnya, boleh kamu perbuat sesuai dengan kehendak Allahmu.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 19, 'Hanya perlengkapan-perlengkapan yang diserahkan kepadamu untuk ibadah di rumah Allahmu, sampaikanlah itu ke hadapan Allah di Yerusalem.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 20, 'Dan yang lain yang masih diperlukan untuk rumah Allahmu, yang pembayarannya menjadi tanggunganmu, itu boleh kaubayar dari perbendaharaan kerajaan.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 21, 'Kemudian aku, raja Artahsasta, telah mengeluarkan perintah kepada semua bendahara di daerah seberang sungai Efrat, begini: segala yang diminta dari padamu oleh imam Ezra, ahli Taurat Allah semesta langit, haruslah dilaksanakan dengan seksama,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 22, 'dengan memakai perak sampai jumlah seratus talenta, gandum sampai jumlah seratus kor, anggur sampai jumlah seratus bat, minyak sampai jumlah seratus bat, dan garam tidak terbatas.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 23, 'Segala sesuatu yang berdasarkan perintah Allah semesta langit, harus dilaksanakan dengan tekun untuk keperluan rumah Allah semesta langit, supaya jangan pemerintahan raja serta anak-anaknya kena murka.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 24, 'Lagipula kami beritahukan kepadamu, bahwa tidaklah sah bila para imam, orang Lewi, penyanyi, penunggu pintu gerbang, budak di bait Allah dan para hamba rumah Allah dikenakan pajak, upeti atau bea.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 25, 'Maka engkau, hai Ezra, angkatlah pemimpin-pemimpin dan hakim-hakim sesuai dengan hikmat Allahmu yang menjadi peganganmu, supaya mereka menghakimi seluruh rakyat yang diam di daerah seberang sungai Efrat, yakni semua orang yang mengetahui hukum Allahmu; dan orang yang belum mengetahuinya haruslah kauajar.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 26, 'Setiap orang, yang tidak melakukan hukum Allahmu dan hukum raja, harus dihukum dengan seksama, baik dengan hukuman mati, maupun dengan pembuangan, dengan hukuman denda atau hukuman penjara."', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 27, 'Terpujilah TUHAN, Allah nenek moyang kita, yang dengan demikian menggerakkan hati raja, sehingga ia menyemarakkan rumah TUHAN yang ada di Yerusalem,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 7, 28, 'dan membuat aku disenangi oleh raja dan penasihat-penasihatnya serta segala pembesar raja yang berkuasa! (7-28b) Maka aku menguatkan hatiku, karena tangan TUHAN, Allahku, melindungi aku dan aku menghimpunkan dari antara orang Israel beberapa pemimpin untuk berangkat pulang bersama-sama aku.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 1, 'Inilah kepala-kepala kaum keluarga dan silsilah orang-orang yang berangkat pulang bersama-sama aku dari Babel pada zaman pemerintahan raja Artahsasta:', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 2, 'dari bani Pinehas: Gersom; dari bani Itamar: Daniel; dari bani Daud: Hatus', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 3, 'bin Sekhanya; dari bani Paros: Zakharia, dan bersama-sama dia seratus lima puluh orang laki-laki tercatat di dalam silsilah;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 4, 'dari bani Pahat-Moab: Elyoenai bin Zerahya, dan bersama-sama dia dua ratus orang laki-laki;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 5, 'dari bani Zatu: Sekhanya bin Yahaziel, dan bersama-sama dia tiga ratus orang laki-laki;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 6, 'dan dari bani Adin: Ebed bin Yonatan, dan bersama-sama dia lima puluh orang laki-laki;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 7, 'dari bani Elam: Yesaya bin Atalya, dan bersama-sama dia tujuh puluh orang laki-laki;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 8, 'dan dari bani Sefaca: Zebaja bin Mikhael, dan bersama-sama dia delapan puluh orang laki-laki;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 9, 'dan dari bani Yoab: Obaja bin Yehiel, dan bersama-sama dia dua ratus delapan belas orang laki-laki;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 10, 'dan dari bani Bani: Selomit bin Yosifya, dan bersama-sama dia seratus enam puluh orang laki-laki;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 11, 'dan dari bani Bebai: Zakharia bin Bebai, dan bersama-sama dia dua puluh delapan orang laki-laki;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 12, 'dan dari bani Azgad: Yohanan bin Hakatan, dan bersama-sama dia seratus sepuluh orang laki-laki;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 13, 'dan dari bani Adonikam: yang datang kemudian, dan inilah nama mereka: Elifelet, Yehiel dan Semaya, dan bersama-sama mereka enam puluh orang laki-laki;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 14, 'dan dari bani Bigwai: Utai dan Zabud dan bersama-sama dia tujuh puluh orang laki-laki.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 15, 'Aku menghimpunkan mereka dekat sungai yang mengalir ke Ahawa dan di sana kami berkemah tiga hari lamanya. Ketika kuselidiki mereka, ternyata ada orang-orang Israel awam dan imam-imam, tetapi tidak kudapati di antara mereka orang-orang dari bani Lewi.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 16, 'Sebab itu aku mengirim Eliezer, Ariel, Semaya, Elnatan, Yarib, Elnatan, Natan, Zakharia, Mesulam, yakni kepala-kepala kaum keluarga, dan Yoyarib dan Elnatan, yakni pengajar-pengajar,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 17, 'dengan suatu pesan untuk Ido, kepala setempat di Kasifya. Aku menaruh perkataan-perkataan ke dalam mulut mereka untuk dikatakan kepada Ido dan saudara-saudaranya, para budak di bait Allah di Kasifya itu, supaya mereka mendatangkan kepada kami orang-orang yang harus menyelenggarakan kebaktian di rumah Allah kami.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 18, 'Kemudian karena tangan murah Allah kami itu melindungi kami, didatangkanlah oleh mereka kepada kami orang-orang yang berakal budi dari bani Mahli bin Lewi bin Israel, yakni Serebya dengan anak-anak dan saudara-saudaranya, delapan belas orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 19, 'dan Hasabya beserta Yesaya, dari bani Merari, dan saudara-saudaranya dan anak-anak mereka, dua puluh orang;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 20, 'dan dari para budak di bait Allah, yang diberikan Daud dan para pembesar untuk membantu pekerjaan orang-orang Lewi, dua ratus dua puluh orang, yang masing-masing ditunjuk dengan disebut namanya.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 21, 'Kemudian di sana, di tepi sungai Ahawa itu, aku memaklumkan puasa supaya kami merendahkan diri di hadapan Allah kami dan memohon kepada-Nya jalan yang aman bagi kami, bagi anak-anak kami dan segala harta benda kami.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 22, 'Karena aku malu meminta tentara dan orang-orang berkuda kepada raja untuk mengawal kami terhadap musuh di jalan; sebab kami telah berkata kepada raja, demikian: "Tangan Allah kami melindungi semua orang yang mencari Dia demi keselamatan mereka, tetapi kuasa murka-Nya menimpa semua orang yang meninggalkan Dia."', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 23, 'Jadi berpuasalah kami dan memohonkan hal itu kepada Allah dan Allah mengabulkan permohonan kami.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 24, 'Lalu aku memilih dua belas orang pemuka imam, yakni Serebya dan Hasabya, dan bersama-sama mereka sepuluh orang dari antara saudara-saudara mereka.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 25, 'Aku menimbang bagi mereka perak, emas, dan perlengkapan-perlengkapan, yakni persembahan-persembahan khusus bagi rumah Allah kami yang dikhususkan oleh raja serta penasihat-penasihatnya dan pembesar-pembesarnya dan semua orang Israel yang ada di sana.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 26, 'Pula aku menimbang untuk menyerahkan ke tangan mereka: perak enam ratus lima puluh talenta, perlengkapan perak seharga seratus talenta, emas seratus talenta,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 27, 'dua puluh piala emas seharga seribu dirham dan dua buah perlengkapan dari pada tembaga murni yang mengkilat dan indah seperti emas.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 28, 'Dan aku berkata kepada mereka: "Kamu kudus bagi TUHAN, dan perlengkapan-perlengkapan inipun kudus, dan perak dan emas ini adalah persembahan sukarela kepada TUHAN, Allah nenek moyangmu;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 29, 'rawatlah dan jagalah itu sampai kamu dapat menimbangnya di depan para pemuka imam serta orang-orang Lewi dan para pemimpin kaum keluarga orang Israel di Yerusalem, di dalam bilik-bilik rumah TUHAN."', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 30, 'Lalu para imam dan orang-orang Lewi menerima perak dan emas dan perlengkapan-perlengkapan yang telah ditimbang itu untuk dibawa ke Yerusalem, ke rumah Allah kami.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 31, 'Kemudian berangkatlah kami dari sungai Ahawa pergi ke Yerusalem pada tanggal dua belas bulan pertama untuk berjalan ke Yerusalem, dan tangan Allah kami melindungi kami dan menghindarkan kami dari tangan musuh dan penyamun.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 32, 'Maka tibalah kami di Yerusalem. Sesudah kami tinggal di sana selama tiga hari,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 33, 'maka pada hari yang keempat ditimbanglah perak dan emas dan perlengkapan-perlengkapan itu di dalam rumah Allah kami di bawah pengawasan imam Meremot bin Uria, yang didampingi oleh Eleazar bin Pinehas, dan mereka dibantu oleh Yozabad bin Yesua dan Noaja bin Binui, orang-orang Lewi.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 34, 'Semuanya dihitung dan ditimbang kembali, dan jumlah timbangannya dibukukan.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 35, 'Pada waktu itu juga orang-orang yang telah kembali dari penawanan, yakni mereka yang pulang dari pembuangan, mempersembahkan sebagai korban bakaran kepada Allah Israel: lembu jantan dua belas ekor untuk seluruh Israel, domba jantan sembilan puluh enam ekor, anak domba tujuh puluh tujuh ekor, kambing jantan sebagai korban penghapus dosa dua belas ekor, semuanya itu sebagai korban bakaran bagi TUHAN.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 8, 36, 'Mereka menyampaikan juga surat perintah raja kepada wakil-wakil raja dan bupati-bupati daerah sebelah barat sungai Efrat, dan orang-orang itu memberi sokongan kepada bangsa kita dan kepada rumah Allah.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 1, 'Sesudah semuanya itu terlaksana datanglah para pemuka mendekati aku dan berkata: "Orang-orang Israel awam, para imam dan orang-orang Lewi tidak memisahkan diri dari penduduk negeri dengan segala kekejiannya, yakni dari orang Kanaan, orang Het, orang Feris, orang Yebus, orang Amon, orang Moab, orang Mesir dan orang Amori.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 2, 'Karena mereka telah mengambil isteri dari antara anak perempuan orang-orang itu untuk diri sendiri dan untuk anak-anak mereka, sehingga bercampurlah benih yang kudus dengan penduduk negeri, bahkan para pemuka dan penguasalah yang lebih dahulu melakukan perbuatan tidak setia itu."', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 3, 'Ketika aku mendengar perkataan itu, maka aku mengoyakkan pakaianku dan jubahku dan aku mencabut rambut kepalaku dan janggutku dan duduklah aku tertegun.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 4, 'Lalu berkumpullah kepadaku semua orang yang gemetar karena firman Allah Israel, oleh sebab perbuatan tidak setia orang-orang buangan itu, tetapi aku tetap duduk tertegun sampai korban petang.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 5, 'Pada waktu korban petang bangkitlah aku dan berhenti menyiksa diriku, lalu aku berlutut dengan pakaianku dan jubahku yang koyak-koyak sambil menadahkan tanganku kepada TUHAN, Allahku,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 6, 'dan kataku: "Ya Allahku, aku malu dan mendapat cela, sehingga tidak berani menengadahkan mukaku kepada-Mu, ya Allahku, karena dosa kami telah menumpuk mengatasi kepala kami dan kesalahan kami telah membubung ke langit.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 7, 'Dari zaman nenek moyang kami sampai hari ini kesalahan kami besar, dan oleh karena dosa kami maka kami sekalian dengan raja-raja dan imam-imam kami diserahkan ke dalam tangan raja-raja negeri, ke dalam kuasa pedang, ke dalam penawanan dan penjarahan, dan penghinaan di depan umum, seperti yang terjadi sekarang ini.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 8, 'Dan sekarang, baru saja kami alami kasih karunia dari pada TUHAN, Allah kami yang meninggalkan pada kami orang-orang yang terluput, dan memberi kami tempat menetap di tempat-Nya yang kudus, sehingga Allah kami membuat mata kami bercahaya dan memberi kami sedikit kelegaan di dalam perbudakan kami.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 9, 'Karena sungguhpun kami menjadi budak, tetapi di dalam perbudakan itu kami tidak ditinggalkan Allah kami. Ia membuat kami disayangi oleh raja-raja negeri Persia, sehingga kami mendapat kelegaan untuk membangun rumah Allah kami dan menegakkan kembali reruntuhannya, dan diberi tembok pelindung di Yehuda dan di Yerusalem.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 10, 'Tetapi sekarang, ya Allah kami, apa yang akan kami katakan sesudah semuanya itu? Karena kami telah meninggalkan perintah-Mu,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 11, 'yang Kauperintahkan dengan perantaraan hamba-hamba-Mu, para nabi itu, dengan berfirman: Negeri yang kamu masuki untuk diduduki adalah negeri yang cemar oleh karena kecemaran penduduk negeri, yakni oleh karena kekejian yang mereka lakukan dengan segala kenajisan mereka di segenap negeri itu dari ujung ke ujung.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 12, 'Jadi sekarang janganlah kamu memberikan anak-anak perempuanmu kepada anak lelaki mereka, ataupun mengambil anak-anak perempuan mereka untuk anak-anak lelakimu. Janganlah kamu mengikhtiarkan kesejahteraan dan kebahagiaan mereka untuk selama-lamanya, supaya kamu menjadi kuat, mengecap hasil tanah yang baik, dan mewariskan tanah itu kepada anak-anakmu untuk selama-lamanya.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 13, 'Sesudah semua yang kami alami oleh sebab perbuatan kami yang jahat, dan oleh sebab kesalahan kami yang besar, sedangkan Engkau, ya Allah kami, tidak menghukum setimpal dengan dosa kami, dan masih mengaruniakan kepada kami orang-orang yang terluput sebanyak ini,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 14, 'masakan kami kembali melanggar perintah-Mu dan kawin-mengawin dengan bangsa-bangsa yang keji ini? Tidakkah Engkau akan murka kepada kami sampai kami habis binasa, sehingga tidak ada yang tinggal hidup atau terluput?', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 9, 15, 'Ya TUHAN, Allah Israel, Engkau maha benar, sebab kami masih dibiarkan tinggal sebagai orang-orang yang terluput, seperti yang terjadi sekarang ini. Lihatlah, kami menghadap hadirat-Mu dengan kesalahan kami. Bahwasanya, dalam keadaan demikian tidak mungkin orang tahan berdiri di hadapan-Mu."', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 1, 'Sementara Ezra berdoa dan mengaku dosa, sambil menangis dengan bersujud di depan rumah Allah, berhimpunlah kepadanya jemaah orang Israel yang sangat besar jumlahnya, laki-laki, perempuan dan anak-anak. Orang-orang itu menangis keras-keras.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 2, 'Maka berbicaralah Sekhanya bin Yehiel, dari bani Elam, katanya kepada Ezra: "Kami telah melakukan perbuatan tidak setia terhadap Allah kita, oleh karena kami telah memperisteri perempuan asing dari antara penduduk negeri. Namun demikian sekarang juga masih ada harapan bagi Israel.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 3, 'Marilah kita sekarang mengikat perjanjian dengan Allah kita, bahwa kita akan mengusir semua perempuan itu dengan anak-anak yang dilahirkan mereka, menurut nasihat tuan dan orang-orang yang gemetar karena perintah Allah kita. Dan biarlah orang bertindak menurut hukum Taurat.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 4, 'Bangkitlah, karena hal itu adalah tugasmu. Kami akan mendampingi engkau. Kuatkanlah hatimu, dan bertindaklah!"', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 5, 'Kemudian bangkitlah Ezra dan menyuruh para pemuka imam dan orang-orang Lewi dan segenap orang Israel bersumpah, bahwa mereka akan berbuat menurut perkataan itu, maka bersumpahlah mereka.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 6, 'Sesudah itu Ezra pergi dari depan rumah Allah menuju bilik Yohanan bin Elyasib, dan di sana ia bermalam dengan tidak makan roti dan minum air, sebab ia berkabung karena orang-orang buangan itu telah melakukan perbuatan tidak setia.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 7, 'Lalu disiarkanlah pengumuman di Yehuda dan di Yerusalem kepada semua orang yang pulang dari pembuangan untuk berhimpun di Yerusalem.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 8, 'Barangsiapa dalam tiga hari tidak datang, maka menurut keputusan para pemimpin dan tua-tua segala hartanya akan disita dan ia akan dikucilkan dari jemaah yang pulang dari pembuangan.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 9, 'Lalu berhimpunlah semua orang laki-laki Yehuda dan Benyamin di Yerusalem dalam tiga hari itu, yakni dalam bulan kesembilan pada tanggal dua puluh bulan itu. Seluruh rakyat duduk di halaman rumah Allah, sambil menggigil karena perkara itu dan karena hujan lebat.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 10, 'Maka bangkitlah imam Ezra, lalu berkata kepada mereka: "Kamu telah melakukan perbuatan tidak setia, karena kamu memperisteri perempuan asing dan dengan demikian menambah kesalahan orang Israel.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 11, 'Tetapi sekarang mengakulah di hadapan TUHAN, Allah nenek moyangmu, dan lakukanlah apa yang berkenan kepada-Nya dan pisahkanlah dirimu dari penduduk negeri dan perempuan-perempuan asing itu!"', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 12, 'Lalu seluruh jemaah menjawab dan berseru dengan suara nyaring: "Sesungguhnya, adalah kewajiban kami melakukan seperti katamu itu.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 13, 'Tetapi orang-orang ini besar jumlahnya dan sekarang musim hujan, sehingga orang tidak sanggup lagi berdiri di luar. Lagipula pekerjaan itu bukan perkara sehari dua hari, karena dalam hal itu kami telah banyak melakukan pelanggaran.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 14, 'Biarlah pemimpin-pemimpin kami bertindak mewakili jemaah seluruhnya, maka setiap orang di kota-kota kami yang memperisteri perempuan asing harus datang menghadap pada waktu-waktu tertentu, dan bersama-sama mereka para tua-tua dan para hakim di tiap-tiap kota, sampai murka Allah kami yang bernyala-nyala karena perkara ini dijauhkan dari kami."', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 15, 'Hanya Yonatan bin Asael, dan Yahzeya bin Tikwa, berdiri menentang perkara itu, disokong oleh Mesulam dan Sabetai, orang Lewi itu.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 16, 'Tetapi mereka yang pulang dari pembuangan melakukannya. Maka imam Ezra memilih beberapa orang, kepala-kepala kaum keluarga, masing-masing untuk kaum keluarganya, semuanya dengan namanya disebut. Pada hari pertama bulan kesepuluh mereka bersidang untuk menyelidiki perkara itu,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 17, 'dan mereka menyelesaikan segala urusan mengenai orang yang memperisteri perempuan asing itu pada hari pertama bulan pertama.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 18, 'Di antara kaum imam yang memperisteri perempuan asing terdapat: dari bani Yesua bin Yozadak, dengan saudara-saudaranya: Maaseya, Eliezer, Yarib dan Gedalya.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 19, 'Dengan memegang tangan, mereka itu berjanji akan mengusir isteri mereka. Dan mereka mempersembahkan seekor domba jantan dari kawanan kambing domba sebagai korban penebus salah karena kesalahan mereka.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 20, 'Dari bani Imer: Hanani dan Zebaja;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 21, 'dari bani Harim: Maaseya, Elia, Semaya, Yehiel dan Uzia;', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 22, 'dan dari bani Pasyhur: Elyoenai, Maaseya, Ismael, Netaneel, Yozabad dan Elasa.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 23, 'Dari orang-orang Lewi: Yozabad, Simei, Kelaya (yakni Kelita), Petahya, Yuda dan Eliezer.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 24, 'Dari para penyanyi: Elyasib. Dari para penunggu pintu gerbang: Salum, Telem dan Uri.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 25, 'Dari orang-orang Israel yang lain: dari bani Paros: Ramya, Yezia, Malkia, Miyamin, Eleazar, Malkia dan Benaya.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 26, 'Dari bani Elam: Matanya, Zakharia, Yehiel, Abdi, Yeremot dan Elia.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 27, 'Dari bani Zatu: Elyoenai, Elyasib, Matanya, Yeremot, Zabad dan Aziza.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 28, 'Dari bani Bebai: Yohanan, Hananya, Zabai dan Altai.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 29, 'Dari bani Bani: Mesulam, Malukh, Adaya, Yasub, Seal dan Yeramot.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 30, 'Dari bani Pahat-Moab: Adna dan Kelal, Benaya, Maaseya, Matania, Bezaleel, Binui dan Manasye.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 31, 'Dari bani Harim: Eliezer, Yisia, Malkia, Semaya, Simeon,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 32, 'Benyamin, Malukh, dan Semarya.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 33, 'Dari bani Hasum: Matnai, Matata, Zabad, Elifelet, Yeremai, Manasye dan Simei.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 34, 'Dari bani Bani: Maadai, Amram, Uel,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 35, 'Benaya, Bedeya, Keluhu,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 36, 'Wanya, Meremot, Elyasib,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 37, 'Matanya, Matnai, Yaasai.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 38, 'Dari bani Binui: Simei,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 39, 'Selemya, Natan, Adaya,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 40, 'Makhnadbai, Sasai, Sarai,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 41, 'Azareel, Selemya, Semarya,', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 42, 'Salum, Amarya dan Yusuf.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 43, 'Dari bani Nebo: Yeiel, Matica, Zabad, Zebina, Yadai, Yoel dan Benaya.', 'id', 'TB'),
  ('15', 'ezr', 'Ezra', 10, 44, 'Mereka sekalian mengambil sebagai isteri perempuan asing; maka mereka menyuruh pergi isteri-isteri itu dengan anak-anaknya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 1, 1, 'Riwayat Nehemia bin Hakhalya. Pada bulan Kislew tahun kedua puluh, ketika aku ada di puri Susan,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 1, 2, 'datanglah Hanani, salah seorang dari saudara-saudaraku dengan beberapa orang dari Yehuda. Aku menanyakan mereka tentang orang-orang Yahudi yang terluput, yang terhindar dari penawanan dan tentang Yerusalem.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 1, 3, 'Kata mereka kepadaku: "Orang-orang yang masih tinggal di daerah sana, yang terhindar dari penawanan, ada dalam kesukaran besar dan dalam keadaan tercela. Tembok Yerusalem telah terbongkar dan pintu-pintu gerbangnya telah terbakar."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 1, 4, 'Ketika kudengar berita ini, duduklah aku menangis dan berkabung selama beberapa hari. Aku berpuasa dan berdoa ke hadirat Allah semesta langit,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 1, 5, 'kataku: "Ya, TUHAN, Allah semesta langit, Allah yang maha besar dan dahsyat, yang berpegang pada perjanjian dan kasih setia-Nya terhadap orang yang kasih kepada-Nya dan tetap mengikuti perintah-perintah-Nya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 1, 6, 'berilah telinga-Mu dan bukalah mata-Mu dan dengarkanlah doa hamba-Mu yang sekarang kupanjatkan ke hadirat-Mu siang dan malam bagi orang Israel, hamba-hamba-Mu itu, dengan mengaku segala dosa yang kami orang Israel telah lakukan terhadap-Mu. Juga aku dan kaum keluargaku telah berbuat dosa.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 1, 7, 'Kami telah sangat bersalah terhadap-Mu dan tidak mengikuti perintah-perintah, ketetapan-ketetapan dan peraturan-peraturan yang telah Kauperintahkan kepada Musa, hamba-Mu itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 1, 8, 'Ingatlah akan firman yang Kaupesan kepada Musa, hamba-Mu itu, yakni: Bila kamu berubah setia, kamu akan Kucerai-beraikan di antara bangsa-bangsa.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 1, 9, 'Tetapi, bila kamu berbalik kepada-Ku dan tetap mengikuti perintah-perintah-serta melakukannya, maka sekalipun orang-orang buanganmu ada di ujung langit, akan Kukumpulkan mereka kembali dan Kubawa ke tempat yang telah Kupilih untuk membuat nama-Ku diam di sana.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 1, 10, 'Bukankah mereka ini hamba-hamba-Mu dan umat-Mu yang telah Kaubebaskan dengan kekuatan-Mu yang besar dan dengan tangan-Mu yang kuat?', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 1, 11, 'Ya, Tuhan, berilah telinga kepada doa hamba-Mu ini dan kepada doa hamba-hamba-Mu yang rela takut akan nama-Mu, dan biarlah hamba-Mu berhasil hari ini dan mendapat belas kasihan dari orang ini." Ketika itu aku ini juru minuman raja.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 1, 'Pada bulan Nisan tahun kedua puluh pemerintahan raja Artahsasta, ketika menjadi tugasku untuk menyediakan anggur, aku mengangkat anggur dan menyampaikannya kepada raja. Karena aku kelihatan sedih, yang memang belum pernah terjadi di hadapan raja,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 2, 'bertanyalah ia kepadaku: "Mengapa mukamu muram, walaupun engkau tidak sakit? Engkau tentu sedih hati." Lalu aku menjadi sangat takut.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 3, 'Jawabku kepada raja: "Hiduplah raja untuk selamanya! Bagaimana mukaku tidak akan muram, kalau kota, tempat pekuburan nenek moyangku, telah menjadi reruntuhan dan pintu-pintu gerbangnya habis dimakan api?"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 4, 'Lalu kata raja kepadaku: "Jadi, apa yang kauinginkan?" Maka aku berdoa kepada Allah semesta langit,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 5, 'kemudian jawabku kepada raja: "Jika raja menganggap baik dan berkenan kepada hambamu ini, utuslah aku ke Yehuda, ke kota pekuburan nenek moyangku, supaya aku membangunnya kembali."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 6, 'Lalu bertanyalah raja kepadaku, sedang permaisuri duduk di sampingnya: "Berapa lama engkau dalam perjalanan, dan bilakah engkau kembali?" Dan raja berkenan mengutus aku, sesudah aku menyebut suatu jangka waktu kepadanya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 7, 'Berkatalah aku kepada raja: "Jika raja menganggap baik, berikanlah aku surat-surat bagi bupati-bupati di daerah seberang sungai Efrat, supaya mereka memperbolehkan aku lalu sampai aku tiba di Yehuda.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 8, 'Pula sepucuk surat bagi Asaf, pengawas taman raja, supaya dia memberikan aku kayu untuk memasang balok-balok pada pintu-pintu gerbang di benteng bait suci, untuk tembok kota dan untuk rumah yang akan kudiami." Dan raja mengabulkan permintaanku itu, karena tangan Allahku yang murah melindungi aku.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 9, 'Maka datanglah aku kepada bupati-bupati di daerah seberang sungai Efrat dan menyerahkan kepada mereka surat-surat raja. Dan raja menyuruh panglima-panglima perang dan orang-orang berkuda menyertai aku.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 10, 'Ketika Sanbalat, orang Horon, dan Tobia, orang Amon, pelayan itu, mendengar hal itu, mereka sangat kesal karena ada orang yang datang mengusahakan kesejahteraan orang Israel.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 11, 'Maka tibalah aku di Yerusalem. Sesudah tiga hari aku di sana,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 12, 'bangunlah aku pada malam hari bersama-sama beberapa orang saja yang menyertai aku. Aku tidak beritahukan kepada siapapun rencana yang akan kulakukan untuk Yerusalem, yang diberikan Allahku dalam hatiku. Juga tak ada lain binatang kepadaku kecuali yang kutunggangi.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 13, 'Demikian pada malam hari aku keluar melalui pintu gerbang Lebak, ke jurusan mata air Ular Naga dan pintu gerbang Sampah. Aku menyelidiki dengan seksama tembok-tembok Yerusalem yang telah terbongkar dan pintu-pintu gerbangnya yang habis dimakan api.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 14, 'Lalu aku meneruskan perjalananku ke pintu gerbang Mata Air dan ke kolam Raja. Karena binatang yang kutunggangi tidak dapat lalu di tempat itu,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 15, 'aku naik ke atas melalui wadi pada malam hari dan menyelidiki dengan seksama tembok itu. Kemudian aku kembali, lalu masuk melalui pintu gerbang Lebak. Demikianlah aku pulang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 16, 'Para penguasa tidak tahu ke mana aku telah pergi dan apa yang telah kulakukan, karena sampai kini aku belum memberitahukan apa-apa kepada orang Yahudi, baik kepada para imam, maupun kepada para pemuka, kepada para penguasa dan para petugas lainnya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 17, 'Berkatalah aku kepada mereka: "Kamu lihat kemalangan yang kita alami, yakni Yerusalem telah menjadi reruntuhan dan pintu-pintu gerbangnya telah terbakar. Mari, kita bangun kembali tembok Yerusalem, supaya kita tidak lagi dicela."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 18, 'Ketika kuberitahukan kepada mereka, betapa murahnya tangan Allahku yang melindungi aku dan juga apa yang dikatakan raja kepadaku, berkatalah mereka: "Kami siap untuk membangun!" Dan dengan sekuat tenaga mereka mulai melakukan pekerjaan yang baik itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 19, 'Ketika Sanbalat, orang Horon, dan Tobia, orang Amon, pelayan itu, dan Gesyem, orang Arab, mendengar itu, mereka mengolok-olokkan dan menghina kami. Kata mereka: "Apa yang kamu lakukan itu? Apa kamu mau berontak terhadap raja?"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 2, 20, 'Aku menjawab mereka, kataku: "Allah semesta langit, Dialah yang membuat kami berhasil! Kami, hamba-hamba-Nya, telah siap untuk membangun. Tetapi kamu tak punya bagian atau hak dan tidak akan diingat di Yerusalem!"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 1, 'Maka bersiaplah imam besar Elyasib dan para imam, saudara-saudaranya, lalu membangun kembali pintu gerbang Domba. Mereka mentahbiskannya dan memasang pintu-pintunya. Mereka mentahbiskannya sampai menara Mea, menara Hananeel.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 2, 'Berdekatan dengan mereka orang-orang Yerikho membangun, dan berdekatan dengan orang-orang itu Zakur bin Imri.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 3, 'Pintu gerbang Ikan dibangun oleh bani Senaa. Mereka memasang balok-balok lalu memasang pintu-pintunya dengan pengancing-pengancing dan palang-palangnya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 4, 'Berdekatan dengan mereka Meremot bin Uria bin Hakos mengadakan perbaikan, dan berdekatan dengan dia Mesulam bin Berekhya bin Mesezabeel. Berdekatan dengan dia Zadok bin Baana mengadakan perbaikan,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 5, 'dan berdekatan dengan dia orang-orang Tekoa. Hanya pemuka-pemuka mereka tidak mau memberi bahunya untuk pekerjaan tuan mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 6, 'Pintu gerbang Lama diperbaiki oleh Yoyada bin Paseah dan Mesulam bin Besoja. Mereka memasang balok-balok lalu memasang pintu-pintunya dengan pengancing-pengancing dan palang-palangnya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 7, 'Berdekatan dengan mereka Melaca, orang Gibeon, dan Yadon, orang Meronot, mengadakan perbaikan beserta orang-orang Gibeon dan Mizpa, yang berada di wilayah kekuasaan bupati daerah sebelah barat sungai Efrat.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 8, 'Berdekatan dengan mereka Uziel bin Harhaya, salah seorang tukang emas, mengadakan perbaikan, dan berdekatan dengan dia Hananya, seorang juru campur rempah-rempah. Mereka memperkokoh Yerusalem sampai tembok Lebar.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 9, 'Berdekatan dengan mereka Refaya bin Hur, penguasa setengah wilayah Yerusalem yang satu mengadakan perbaikan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 10, 'Berdekatan dengan dia Yedaya bin Harumaf mengadakan perbaikan, tepat di depan rumahnya, dan berdekatan dengan dia Hatus bin Hasabneya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 11, 'Malkia bin Harim dan Hasub bin Pahat-Moab memperbaiki bagian yang lain dan menara Perapian.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 12, 'Berdekatan dengan mereka Salum bin Halohesh, penguasa setengah wilayah Yerusalem yang lain mengadakan perbaikan bersama-sama anak-anak perempuannya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 13, 'Pintu gerbang Lebak diperbaiki oleh Hanun dan penduduk Zanoah. Mereka membangunnya kembali dan memasang pintu-pintunya dengan pengancing-pengancing dan palang-palangnya. Pula tembok diperbaiki sepanjang seribu hasta sampai pada pintu gerbang Sampah.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 14, 'Pintu gerbang Sampah diperbaiki oleh Malkia bin Rekhab, penguasa wilayah Bet-Kerem. Ia membangunnya kembali dan memasang pintu-pintunya dengan pengancing-pengancing dan palang-palangnya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 15, 'Pintu gerbang Mata Air diperbaiki oleh Salum bin Kolhoze, penguasa wilayah Mizpa. Pintu gerbang itu dibangunnya kembali, diberinya atap dan dipasangnya pintu-pintunya dengan pengancing-pengancing dan palang-palangnya. Juga diperbaikinya tembok kolam penampung air saluran, dekat taman raja sampai pada tangga-tangga yang menurun dari kota Daud.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 16, 'Di sampingnya Nehemia bin Azbuk, penguasa setengah wilayah Bet-Zur, mengadakan perbaikan sampai di depan pekuburan Daud dan sampai pada kolam buatan dan rumah para pahlawan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 17, 'Di sampingnya orang-orang Lewi mengadakan perbaikan, yakni Rehum bin Bani, dan berdekatan dengan dia Hasabya, penguasa setengah wilayah Kehila yang satu, untuk wilayahnya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 18, 'Di sampingnya saudara-saudara mereka, yakni Binui bin Henadad, penguasa setengah wilayah Kehila yang lain, mengadakan perbaikan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 19, 'Berdekatan dengan dia Ezer bin Yesua, penguasa Mizpa, memperbaiki bagian yang berikut, di depan pendakian ke gudang senjata, dekat Sudut.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 20, 'Di sampingnya Barukh bin Zabai memperbaiki bagian yang berikut, dari Sudut sampai pada pintu masuk rumah imam besar Elyasib.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 21, 'Di sampingnya Meremot bin Uria bin Hakos memperbaiki bagian yang berikut, dari pintu masuk rumah Elyasib sampai pada ujung rumah Elyasib.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 22, 'Di sampingnya para imam, orang-orang dari Lembah Yordan, mengadakan perbaikan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 23, 'Di samping mereka Benyamin dan Hasub mengadakan perbaikan di depan rumah mereka. Di samping mereka Azarya bin Maaseya bin Ananya mengadakan perbaikan di samping rumahnya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 24, 'Di sampingnya Binui bin Henadad memperbaiki bagian yang berikut, dari rumah Azarya sampai Sudut dan sampai Penjuru.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 25, 'Palal bin Uzai mengadakan perbaikan di depan Sudut dan di depan menara yang tinggi yang menonjol dari istana raja, dekat pelataran penjagaan. Di sampingnya Pedaya bin Paros mengadakan perbaikan', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 26, 'sampai di depan pintu gerbang Air, di sebelah timur, dan di depan menara yang menonjol. Adapun para budak di bait Allah tinggal di Ofel.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 27, 'Di samping Pedaya orang-orang Tekoa memperbaiki bagian yang berikut, dari depan menara besar yang menonjol itu sampai tembok Ofel.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 28, 'Mulai dari pintu gerbang Kuda para imam mengadakan perbaikan, masing-masing di depan rumahnya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 29, 'Di samping mereka Zadok bin Imer mengadakan perbaikan di depan rumahnya. Di sampingnya Semaya bin Sekhanya, penjaga pintu gerbang Timur.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 30, 'Di sampingnya Hananya bin Selemya dan Hanun, anak Zalaf yang keenam, memperbaiki bagian yang berikut. Di samping mereka Mesulam bin Berekhya mengadakan perbaikan di depan biliknya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 31, 'Di sampingnya Malkia, seorang tukang emas, mengadakan perbaikan sampai pada rumah para budak di bait Allah dan para pedagang, di depan pintu gerbang Pendaftaran dan sampai pada kamar atas di penjuru.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 3, 32, 'Lalu antara kamar atas di penjuru dan pintu gerbang Domba para tukang emas dan para pedagang mengadakan perbaikan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 1, 'Ketika Sanbalat mendengar, bahwa kami sedang membangun kembali tembok, bangkitlah amarahnya dan ia sangat sakit hati. Ia mengolok-olokkan orang Yahudi', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 2, 'dan berkata di hadapan saudara-saudaranya dan tentara Samaria: "Apa gerangan yang dilakukan orang-orang Yahudi yang lemah ini? Apakah mereka memperkokoh sesuatu? Apakah mereka hendak membawa persembahan? Apakah mereka akan selesai dalam sehari? Apakah mereka akan menghidupkan kembali batu-batu dari timbunan puing yang sudah terbakar habis seperti ini?"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 3, 'Lalu berkatalah Tobia, orang Amon itu, yang ada di dekatnya: "Sekalipun mereka membangun kembali, kalau seekor anjing hutan meloncat dan menyentuhnya, robohlah tembok batu mereka."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 4, 'Ya, Allah kami, dengarlah bagaimana kami dihina. Balikkanlah cercaan mereka menimpa kepala mereka sendiri dan serahkanlah mereka menjadi jarahan di tanah tempat tawanan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 5, 'Jangan Kaututupi kesalahan mereka, dan dosa mereka jangan Kauhapus dari hadapan-Mu, karena mereka menyakiti hati-Mu dengan sikap mereka terhadap orang-orang yang sedang membangun.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 6, 'Tetapi kami terus membangun tembok sampai setengah tinggi dan sampai ujung-ujungnya bertemu, karena seluruh bangsa bekerja dengan segenap hati.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 7, 'Ketika Sanbalat dan Tobia serta orang Arab dan orang Amon dan orang Asdod mendengar, bahwa pekerjaan perbaikan tembok Yerusalem maju dan bahwa lobang-lobang tembok mulai tertutup, maka sangat marahlah mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 8, 'Mereka semua mengadakan persepakatan bersama untuk memerangi Yerusalem dan mengadakan kekacauan di sana.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 9, 'Tetapi kami berdoa kepada Allah kami, dan mengadakan penjagaan terhadap mereka siang dan malam karena sikap mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 10, 'Berkatalah orang Yehuda: "Kekuatan para pengangkat sudah merosot dan puing masih sangat banyak. Tak sanggup kami membangun kembali tembok ini."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 11, 'Tetapi lawan-lawan kami berpikir: "Mereka tidak akan tahu dan tidak akan melihat apa-apa, sampai kita ada di antara mereka, membunuh mereka dan menghentikan pekerjaan itu."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 12, 'Ketika orang-orang Yahudi yang tinggal dekat mereka sudah sepuluh kali datang memperingatkan kami: "Mereka akan menyerang kita dari segala tempat tinggal mereka,"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 13, 'maka aku tempatkan rakyat menurut kaum keluarganya dengan pedang, tombak dan panah di bagian-bagian yang paling rendah dari tempat itu, di belakang tembok, di tempat-tempat yang terbuka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 14, 'Kuamati semuanya, lalu bangun berdiri dan berkata kepada para pemuka dan para penguasa dan kepada orang-orang yang lain: "Jangan kamu takut terhadap mereka! Ingatlah kepada Tuhan yang maha besar dan dahsyat dan berperanglah untuk saudara-saudaramu, untuk anak-anak lelaki dan anak-anak perempuanmu, untuk isterimu dan rumahmu."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 15, 'Ketika didengar musuh kami, bahwa rencana mereka sudah kami ketahui dan bahwa Allah telah menggagalkannya, maka dapatlah kami semua kembali ke tembok, masing-masing ke pekerjaannya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 16, 'Sejak hari itu sebagian dari pada anak buahku melakukan pekerjaan, dan sebagian yang lain memegang tombak, perisai dan panah dan mengenakan baju zirah, sedang para pemimpin berdiri di belakang segenap kaum Yehuda', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 17, 'yang membangun di tembok. Orang-orang yang memikul dan mengangkut melakukan pekerjaannya dengan satu tangan dan dengan tangan yang lain mereka memegang senjata.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 18, 'Setiap orang yang membangun bekerja dengan berikatkan pedang pada pinggangnya, dan di sampingku berdiri peniup sangkakala.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 19, 'Berkatalah aku kepada para pemuka dan para penguasa dan kepada orang-orang yang lain: "Pekerjaan ini besar dan luas, dan kita terpencar pada tembok, yang satu jauh dari pada yang lain.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 20, 'Dan kalau kamu mendengar bunyi sangkakala di suatu tempat, berkumpullah ke sana mendapatkan kami. Allah kita akan berperang bagi kita!"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 21, 'Demikianlah kami melakukan pekerjaan itu, sedang sebagian dari pada orang-orang memegang tombak dari merekahnya fajar sampai terbitnya bintang-bintang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 22, 'Pada waktu itu juga aku berikan perintah kepada rakyat: "Setiap orang dengan anak buahnya harus bermalam di Yerusalem, supaya mereka mengadakan penjagaan bagi kami pada malam hari, dan melakukan pekerjaannya pada siang hari."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 4, 23, 'Demikianlah aku sendiri, saudara-saudaraku, anak buahku dan para penjaga yang mengikut aku, kami semua tidak sempat menanggalkan pakaian kami. Setiap orang memegang senjata dengan tangan kanan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 1, 'Maka terdengarlah keluhan yang keras dari rakyat dan juga dari pihak para isteri terhadap sesama orang Yahudi.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 2, 'Ada yang berteriak: "Anak laki-laki dan anak perempuan kami banyak dan kami harus mendapat gandum, supaya kami dapat makan dan hidup."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 3, 'Dan ada yang berteriak: "Ladang dan kebun anggur dan rumah kami gadaikan untuk mendapat gandum pada waktu kelaparan."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 4, 'Juga ada yang berteriak: "Kami harus meminjam uang untuk membayar pajak yang dikenakan raja atas ladang dan kebun anggur kami.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 5, 'Sekarang, walaupun kami ini sedarah sedaging dengan saudara-saudara sebangsa kami dan anak-anak kami sama dengan anak-anak mereka, namun kami terpaksa membiarkan anak-anak lelaki dan anak-anak perempuan kami menjadi budak dan sudah beberapa anak perempuan kami harus membiarkan diri dimiliki orang. Kami tidak dapat berbuat apa-apa, karena ladang dan kebun anggur kami sudah di tangan orang lain."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 6, 'Maka sangat marahlah aku, ketika kudengar keluhan mereka dan berita-berita itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 7, 'Setelah berpikir masak-masak, aku menggugat para pemuka dan para penguasa. Kataku kepada mereka: "Masing-masing kamu telah makan riba dari saudara-saudaramu!" Lalu kuadakan terhadap mereka suatu sidang jemaah yang besar.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 8, 'Berkatalah aku kepada mereka: "Kami selalu berusaha sedapat-dapatnya untuk menebus sesama orang Yahudi yang dijual kepada bangsa-bangsa lain. Tetapi kamu ini justru menjual saudara-saudaramu, supaya mereka dibeli lagi oleh kami!" Mereka berdiam diri karena tidak dapat membantah.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 9, 'Kataku: "Tidaklah patut apa yang kamu lakukan itu! Bukankah kamu harus berlaku dengan takut akan Allah kita untuk menghindarkan diri dari cercaan bangsa-bangsa lain, musuh-musuh kita?', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 10, 'Juga aku dan saudara-saudaraku dan anak buahku telah membungakan uang dan gandum pada mereka. Biarlah kita hapuskan hutang mereka itu!', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 11, 'Biarlah kamu kembalikan kepada mereka hari ini juga ladang mereka, kebun anggur, kebun zaitun dan rumah mereka, pula hapuskanlah hutang mereka, yakni uang serta gandum, anggur dan minyak yang kamu tagih dari pada mereka!"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 12, 'Berkatalah mereka: "Itu akan kami kembalikan! Dan kami tidak akan menuntut apa-apa dari mereka. Kami akan lakukan tepat seperti yang engkau perintahkan!" Lalu aku memanggil para imam dan menyuruh mereka bersumpah, bahwa mereka akan menepati janji mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 13, 'Juga kukebas lipatan bajuku sambil berkata: "Demikianlah setiap orang yang tidak menepati janji ini akan dikebas Allah dari rumahnya dan hasil jerih payahnya. Demikianlah ia dikebas dan menjadi hampa!" Dan seluruh jemaah berkata: "Amin," lalu memuji-muji TUHAN. Maka rakyat berbuat sesuai dengan janji itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 14, 'Pula sejak aku diangkat sebagai bupati di tanah Yehuda, yakni dari tahun kedua puluh sampai tahun ketiga puluh dua pemerintahan Artahsasta jadi dua belas tahun lamanya, aku dan saudara-saudaraku tidak pernah mengambil pembagian yang menjadi hak bupati.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 15, 'Tetapi para bupati yang sebelumnya, yang mendahului aku, sangat memberatkan beban rakyat. Bupati-bupati itu mengambil dari mereka empat puluh syikal perak sehari untuk bahan makanan dan anggur. Bahkan anak buah mereka merajalela atas rakyat. Tetapi aku tidak berbuat demikian karena takut akan Allah.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 16, 'Akupun memulai pekerjaan tembok itu, walaupun aku tidak memperoleh ladang. Dan semua anak buahku dikumpulkan di sana khusus untuk pekerjaan itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 17, 'Duduk pada mejaku orang-orang Yahudi dan para penguasa, seratus lima puluh orang, selain mereka yang datang kepada kami dari bangsa-bangsa sekeliling kami.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 18, 'Yang disediakan sehari atas tanggunganku ialah: seekor lembu, enam ekor kambing domba yang terpilih dan beberapa ekor unggas, dan bermacam-macam anggur dengan berlimpah-limpah setiap sepuluh hari. Namun, dengan semuanya itu, aku tidak menuntut pembagian yang menjadi hak bupati, karena pekerjaan itu sangat menekan rakyat.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 5, 19, 'Ya Allahku, demi kesejahteraanku, ingatlah segala yang kubuat untuk bangsa ini.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 1, 'Ketika Sanbalat dan Tobia dan Gesyem, orang Arab itu dan musuh-musuh kami yang lain mendengar, bahwa aku telah selesai membangun kembali tembok, sehingga tidak ada lagi lobang, walaupun sampai waktu itu di pintu-pintu gerbang belum kupasang pintunya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 2, 'maka Sanbalat dan Gesyem mengutus orang kepadaku dengan pesan: "Mari, kita mengadakan pertemuan bersama di Kefirim, di lembah Ono!" Tetapi mereka berniat mencelakakan aku.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 3, 'Lalu aku mengirim utusan kepada mereka dengan balasan: "Aku tengah melakukan suatu pekerjaan yang besar. Aku tidak bisa datang! Untuk apa pekerjaan ini terhenti oleh sebab aku meninggalkannya dan pergi kepada kamu!"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 4, 'Sampai empat kali mereka mengirim pesan semacam itu kepadaku dan setiap kali aku berikan jawaban yang sama kepada mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 5, 'Lalu dengan cara yang sama untuk kelima kalinya Sanbalat mengirim seorang anak buahnya kepadaku yang membawa surat yang terbuka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 6, 'Dalam surat itu tertulis: "Ada desas-desus di antara bangsa-bangsa dan Gasymu membenarkannya, bahwa engkau dan orang-orang Yahudi berniat untuk memberontak, dan oleh sebab itu membangun kembali tembok. Lagipula, menurut kabar itu, engkau mau menjadi raja mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 7, 'Bahkan engkau telah menunjuk nabi-nabi yang harus memberitakan tentang dirimu di Yerusalem, demikian: Ada seorang raja di Yehuda! Sekarang, berita seperti itu akan didengar raja. Oleh sebab itu, mari, kita sama-sama berunding!"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 8, 'Tetapi aku mengirim orang kepadanya dengan balasan: "Hal seperti yang kausebut itu tidak pernah ada. Itu isapan jempolmu belaka!"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 9, 'Karena mereka semua mau menakut-nakutkan kami, pikirnya: "Mereka akan membiarkan pekerjaan itu, sehingga tak dapat diselesaikan." Tetapi aku justru berusaha sekuat tenaga.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 10, 'Ketika aku pergi ke rumah Semaya bin Delaya bin Mehetabeel, sebab ia berhalangan datang, berkatalah ia: "Biarlah kita bertemu di rumah Allah, di dalam Bait Suci, dan mengunci pintu-pintunya, karena ada orang yang mau datang membunuh engkau, ya, malam ini mereka mau datang membunuh engkau."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 11, 'Tetapi kataku: "Orang manakah seperti aku ini yang akan melarikan diri? Orang manakah seperti aku ini dapat memasuki Bait Suci dan tinggal hidup? Aku tidak pergi!"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 12, 'Karena kuketahui benar, bahwa Allah tidak mengutus dia. Ia mengucapkan nubuat itu terhadap aku, karena disuap Tobia dan Sanbalat.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 13, 'Untuk ini ia disuap, supaya aku menjadi takut lalu berbuat demikian, sehingga aku berdosa. Dengan demikian mereka mempunyai kesempatan untuk membusukkan namaku, sehingga dapat mencela aku.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 14, 'Ya Allahku, ingatlah bagaimana Tobia dan Sanbalat masing-masing telah bertindak! Pun tindakan nabiah Noaja dan nabi-nabi yang lain yang mau menakut-nakutkan aku.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 15, 'Maka selesailah tembok itu pada tanggal dua puluh lima bulan Elul, dalam waktu lima puluh dua hari.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 16, 'Ketika semua musuh kami mendengar hal itu, takutlah semua bangsa sekeliling kami. Mereka sangat kehilangan muka dan menjadi sadar, bahwa pekerjaan itu dilaksanakan dengan bantuan Allah kami.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 17, 'Pada masa itu pula para pemuka Yehuda mengirim banyak surat kepada Tobia, dan sebaliknya mereka menerima surat-surat dari padanya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 18, 'karena banyak orang di Yehuda mempunyai ikatan sumpah dengan dia, sebab ia adalah menantu Sekhanya bin Arah, sedang Yohanan, anaknya, mengambil anak Mesulam bin Berekhya sebagai isteri.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 6, 19, 'Juga mereka sebut-sebut segala kebaikan Tobia di mukaku dan segala perkataanku terus dibeberkan kepadanya. Pula Tobia mengirim surat-surat untuk menakut-nakutkan aku.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 1, 'Setelah tembok selesai dibangun, aku memasang pintu-pintu. Lalu diangkatlah penunggu-penunggu pintu gerbang, para penyanyi dan orang-orang Lewi.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 2, 'Pengawasan atas Yerusalem aku serahkan kepada Hanani, saudaraku, dan kepada Hananya, panglima benteng, karena dia seorang yang dapat dipercaya dan yang takut akan Allah lebih dari pada orang-orang lain.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 3, 'Berkatalah aku kepada mereka: "Pintu-pintu gerbang Yerusalem jangan dibuka sampai matahari panas terik. Dan pintu-pintunya harus ditutup dan dipalangi, sementara orang masih bertugas di tempatnya. Tempatkanlah penjaga-penjaga dari antara penduduk Yerusalem, masing-masing pada tempat-tempat penjagaan dan di depan rumahnya."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 4, 'Adapun kota itu luas dan besar, tetapi penduduknya sedikit dan rumah-rumah belum dibangun.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 5, 'Maka Allahku memberikan dalam hatiku rencana untuk mengumpulkan para pemuka, para penguasa dan rakyat, supaya mereka dicatat dalam silsilah. Lalu kudapati daftar silsilah orang-orang yang lebih dahulu berangkat pulang. Dalam daftar itu kudapati tertulis:', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 6, 'Inilah orang-orang propinsi Yehuda yang berangkat pulang dari pembuangan, yakni para tawanan, yang dahulu diangkut oleh Nebukadnezar, raja Babel, dan yang kembali ke Yerusalem dan ke Yehuda, masing-masing ke kotanya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 7, 'Mereka datang bersama-sama Zerubabel, Yesua, Nehemia, Azarya, Raamya, Nahamani, Mordekhai, Bilsan, Misperet, Bigwai, Nehum dan Baana. Inilah daftar orang-orang bangsa Israel:', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 8, 'bani Paros: dua ribu seratus tujuh puluh dua orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 9, 'bani Sefaca: tiga ratus tujuh puluh dua orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 10, 'bani Arakh: enam ratus lima puluh dua orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 11, 'bani Pahat-Moab, yakni bani Yesua dan Yoab: dua ribu delapan ratus delapan belas orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 12, 'bani Elam: seribu dua ratus lima puluh empat orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 13, 'bani Zatu: delapan ratus empat puluh lima orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 14, 'bani Zakai: tujuh ratus enam puluh orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 15, 'bani Binui: enam ratus empat puluh delapan orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 16, 'bani Bebai: enam ratus dua puluh delapan orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 17, 'bani Azgad: dua ribu tiga ratus dua puluh dua orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 18, 'bani Adonikam: enam ratus enam puluh tujuh orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 19, 'bani Bigwai: dua ribu enam puluh tujuh orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 20, 'bani Adin: enam ratus lima puluh lima orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 21, 'bani Ater, yakni bani Hizkia: sembilan puluh delapan orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 22, 'bani Hasum: tiga ratus dua puluh delapan orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 23, 'bani Bezai: tiga ratus dua puluh empat orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 24, 'bani Harif: seratus dua belas orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 25, 'bani Gibeon: sembilan puluh lima orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 26, 'orang-orang Betlehem dan Netofa: seratus delapan puluh delapan orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 27, 'orang-orang Anatot: seratus dua puluh delapan orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 28, 'orang-orang Bet-Azmawet: empat puluh dua orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 29, 'orang-orang Kiryat-Yearim, Kefira dan Beerot: tujuh ratus empat puluh tiga orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 30, 'orang-orang Rama dan Gaba: enam ratus dua puluh satu orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 31, 'orang-orang Mikhmas: seratus dua puluh dua orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 32, 'orang-orang Betel dan Ai: seratus dua puluh tiga orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 33, 'orang-orang dari Nebo yang lain: lima puluh dua orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 34, 'bani Elam, yakni Elam yang lain: seribu dua ratus lima puluh empat orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 35, 'bani Harim: tiga ratus dua puluh orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 36, 'orang-orang Yerikho: tiga ratus empat puluh lima orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 37, 'orang-orang Lod, Hadid dan Ono: tujuh ratus dua puluh satu orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 38, 'bani Senaa: tiga ribu sembilan ratus tiga puluh orang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 39, 'Inilah para imam: bani Yedaya, yakni kaum keluarga Yesua: sembilan ratus tujuh puluh tiga orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 40, 'bani Imer: seribu lima puluh dua orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 41, 'bani Pasyhur: seribu dua ratus empat puluh tujuh orang;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 42, 'bani Harim: seribu tujuh belas orang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 43, 'Inilah orang-orang Lewi: bani Yesua, yakni bani Kadmiel dan bani Hodewa; tujuh puluh empat orang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 44, 'Inilah para penyanyi: bani Asaf: seratus empat puluh delapan orang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 45, 'Inilah para penunggu pintu gerbang: bani Salum, bani Ater, bani Talmon, bani Akub, bani Hatita, bani Sobai: seratus tiga puluh delapan orang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 46, 'Inilah para budak di bait Allah: bani Ziha, bani Hasufa, bani Tabaot;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 47, 'bani Keros, bani Sia, bani Padon;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 48, 'bani Lebana, bani Hagaba, bani Salmai;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 49, 'bani Hanan, bani Gidel, bani Gahar;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 50, 'bani Reaya, bani Rezin, bani Nekoda;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 51, 'bani Gazam, bani Uza, bani Paseah;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 52, 'bani Besai, bani Meunim, bani Nefusim;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 53, 'bani Bakbuk, bani Hakufa, bani Harhur;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 54, 'bani Bazlit, bani Mehida, bani Harsa;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 55, 'bani Barkos, bani Sisera, bani Temah;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 56, 'bani Neziah, bani Hatifa.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 57, 'Inilah keturunan para hamba Salomo: bani Sotai, bani Soferet, bani Perida;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 58, 'bani Yaala, bani Darkon, bani Gidel;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 59, 'bani Sefaca, bani Hatil, bani Pokheret-Hazebaim, bani Amon.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 7, 60, 'Seluruh budak di bait Allah dan keturunan para hamba Salomo ada tiga ratus sembilan puluh dua orang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 1, '(8-2) maka serentak berkumpullah seluruh rakyat di halaman di depan pintu gerbang Air. Mereka meminta kepada Ezra, ahli kitab itu, supaya ia membawa kitab Taurat Musa, yakni kitab hukum yang diberikan TUHAN kepada Israel.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 2, '(8-3) Lalu pada hari pertama bulan yang ketujuh itu imam Ezra membawa kitab Taurat itu ke hadapan jemaah, yakni baik laki-laki maupun perempuan dan setiap orang yang dapat mendengar dan mengerti.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 3, '(8-4) Ia membacakan beberapa bagian dari pada kitab itu di halaman di depan pintu gerbang Air dari pagi sampai tengah hari di hadapan laki-laki dan perempuan dan semua orang yang dapat mengerti. Dengan penuh perhatian seluruh umat mendengarkan pembacaan kitab Taurat itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 4, '(8-5) Ezra, ahli kitab itu, berdiri di atas mimbar kayu yang dibuat untuk peristiwa itu. Di sisinya sebelah kanan berdiri Matica, Sema, Anaya, Uria, Hilkia dan Maaseya, sedang di sebelah kiri berdiri Pedaya, Misael, Malkia, Hasum, Hasbadana, Zakharia dan Mesulam.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 5, '(8-6) Ezra membuka kitab itu di depan mata seluruh umat, karena ia berdiri lebih tinggi dari semua orang itu. Pada waktu ia membuka kitab itu semua orang bangkit berdiri.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 6, '(8-7) Lalu Ezra memuji TUHAN, Allah yang maha besar, dan semua orang menyambut dengan: "Amin, amin!", sambil mengangkat tangan. Kemudian mereka berlutut dan sujud menyembah kepada TUHAN dengan muka sampai ke tanah.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 7, '(8-8) Juga Yesua, Bani, Serebya, Yamin, Akub, Sabetai, Hodia, Maaseya, Kelita, Azarya, Yozabad, Hanan, Pelaya, yang adalah orang-orang Lewi, mengajarkan Taurat itu kepada orang-orang itu, sementara orang-orang itu berdiri di tempatnya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 8, '(8-9) Bagian-bagian dari pada kitab itu, yakni Taurat Allah, dibacakan dengan jelas, dengan diberi keterangan-keterangan, sehingga pembacaan dimengerti.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 9, '(8-10) Lalu Nehemia, yakni kepala daerah itu, dan imam Ezra, ahli kitab itu, dan orang-orang Lewi yang mengajar orang-orang itu, berkata kepada mereka semuanya: "Hari ini adalah kudus bagi TUHAN Allahmu. Jangan kamu berdukacita dan menangis!", karena semua orang itu menangis ketika mendengar kalimat-kalimat Taurat itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 10, '(8-11) Lalu berkatalah ia kepada mereka: "Pergilah kamu, makanlah sedap-sedapan dan minumlah minuman manis dan kirimlah sebagian kepada mereka yang tidak sedia apa-apa, karena hari ini adalah kudus bagi Tuhan kita! Jangan kamu bersusah hati, sebab sukacita karena TUHAN itulah perlindunganmu!"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 11, '(8-12) Juga orang-orang Lewi menyuruh semua orang itu supaya diam dengan kata-kata: "Tenanglah! Hari ini adalah kudus. Jangan kamu bersusah hati!"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 12, '(8-13) Maka pergilah semua orang itu untuk makan dan minum, untuk membagi-bagi makanan dan berpesta ria, karena mereka mengerti segala firman yang diberitahukan kepada mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 13, '(8-14) Pada hari yang kedua kepala-kepala kaum keluarga seluruh bangsa, juga para imam dan orang-orang Lewi berkumpul pada Ezra, ahli hukum Taurat itu, untuk menelaah kalimat-kalimat Taurat itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 14, '(8-15) Maka didapatinya tertulis dalam hukum yang diberikan TUHAN dengan perantaraan Musa, bahwa orang Israel harus tinggal dalam pondok-pondok pada hari raya bulan yang ketujuh,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 15, '(8-16) dan bahwa di semua kota mereka dan di Yerusalem harus disampaikan berita dan pengumuman yang berbunyi: "Pergilah ke gunung, ambillah daun pohon zaitun, daun pohon minyak, daun pohon murad, daun pohon korma dan daun dari pohon-pohon yang rimbun guna membuat pondok-pondok sebagaimana tertulis."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 16, '(8-17) Maka pergilah orang mengambil daun-daun itu, lalu membuat pondok-pondok, masing-masing di atas atap rumahnya, di pekarangan mereka, juga di pelataran-pelataran rumah Allah, di lapangan pintu gerbang Air dan di lapangan pintu gerbang Efraim.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 17, '(8-18) Seluruh jemaah yang pulang dari pembuangan itu membuat pondok-pondok dan tinggal di situ. Memang sejak zaman Yosua bin Nun sampai hari itu orang Israel tidak pernah berbuat demikian. Maka diadakanlah pesta ria yang amat besar.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 8, 18, '(8-19) Bagian-bagian kitab Taurat Allah itu dibacakan tiap hari, dari hari pertama sampai hari terakhir. Tujuh hari lamanya mereka merayakan hari raya itu dan pada hari yang kedelapan ada pertemuan raya sesuai dengan peraturan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 1, 'Pada hari yang kedua puluh empat bulan itu berkumpullah orang Israel dan berpuasa dengan mengenakan kain kabung dan dengan tanah di kepala.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 2, 'Keturunan orang Israel memisahkan diri dari semua orang asing, lalu berdiri di tempatnya dan mengaku dosa mereka dan kesalahan nenek moyang mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 3, 'Sementara mereka berdiri di tempat, dibacakanlah bagian-bagian dari pada kitab Taurat TUHAN, Allah mereka, selama seperempat hari, sedang seperempat hari lagi mereka mengucapkan pengakuan dan sujud menyembah kepada TUHAN, Allah mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 4, 'Di atas tangga tempat orang-orang Lewi berdirilah Yesua, Bani, Kadmiel, Sebanya, Buni, Serebya, Bani dan Kenani. Dengan suara yang nyaring mereka berseru kepada TUHAN, Allah mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 5, 'Dan berkatalah Yesua, Kadmiel, Bani, Hasabneya, Serebya, Hodia, Sebanya dan Petahya, orang-orang Lewi itu: "Bangunlah, pujilah TUHAN Allahmu dari selama-lamanya sampai selama-lamanya! Terpujilah nama-Mu yang mulia, yang ditinggikan mengatasi segala puji dan hormat!"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 6, '"Hanya Engkau adalah TUHAN! Engkau telah menjadikan langit, ya langit segala langit dengan segala bala tentaranya, dan bumi dengan segala yang ada di atasnya, dan laut dengan segala yang ada di dalamnya. Engkau memberi hidup kepada semuanya itu dan bala tentara langit sujud menyembah kepada-Mu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 7, 'Engkaulah TUHAN, Allah yang telah memilih Abram dan membawanya keluar dari Ur-Kasdim dan memberikan kepadanya nama Abraham.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 8, 'Engkau dapati bahwa hatinya setia terhadap-Mu dan Engkau mengikat perjanjian dengan dia untuk memberikan tanah orang Kanaan, tanah orang Het, tanah orang Amori, tanah orang Feris, tanah orang Yebus dan tanah orang Girgasi kepada keturunannya. Dan Engkau telah menepati janji-Mu, karena Engkau benar.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 9, 'Engkau melihat sengsara nenek moyang kami di Mesir dan mendengar teriakan mereka di tepi Laut Teberau.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 10, 'Engkau telah memperlihatkan tanda-tanda dan mujizat-mujizat di depan Firaun dan semua pegawainya serta seluruh rakyat negerinya, karena Engkau mengetahui mereka bertindak angkuh terhadap nenek moyang kami. Dengan demikian Engkau telah memasyhurkan nama-Mu sebagaimana nyata hari ini.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 11, 'Di hadapan mereka Engkau membelah laut, sehingga mereka dapat menyeberang melalui tempat yang kering di tengah-tengah laut. Tetapi pengejar-pengejar mereka telah Kaucampakkan ke air yang dalam, seperti batu ke air yang dahsyat.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 12, 'Dengan tiang awan Engkau memimpin mereka pada siang hari dan dengan tiang api pada malam hari untuk menerangi jalan yang mereka lalui.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 13, 'Engkau telah turun ke atas gunung Sinai dan berbicara dengan mereka dari langit dan memberikan mereka peraturan-peraturan yang adil, hukum-hukum yang benar serta ketetapan-ketetapan dan perintah-perintah yang baik.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 14, 'Juga Kauberitahukan kepada mereka sabat-Mu yang kudus dan memberikan kepada mereka perintah-perintah, ketetapan-ketetapan dan hukum-Mu dengan perantaraan Musa, hamba-Mu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 15, 'Telah Kauberikan kepada mereka roti dari langit untuk menghilangkan lapar dan air Kaukeluarkan bagi mereka dari gunung batu untuk melepaskan dahaga. Pula Engkau menyuruh mereka memasuki dan menduduki negeri yang dengan mengangkat sumpah telah Kaujanjikan memberikannya kepada mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 16, 'Tetapi mereka, nenek moyang kami itu, bertindak angkuh dan bersitegang leher dan tidak patuh kepada perintah-perintah-Mu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 17, 'Mereka menolak untuk patuh dan tidak mengingat perbuatan-perbuatan yang ajaib yang telah Kaubuat di antara mereka. Mereka bersitegang leher malah berkeras kepala untuk kembali ke perbudakan di Mesir. Tetapi Engkaulah Allah yang sudi mengampuni, yang pengasih dan penyayang, yang panjang sabar dan berlimpah kasih setia-Nya. Engkau tidak meninggalkan mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 18, 'Bahkan, ketika mereka membuat anak lembu tuangan dan berkata: ?Inilah Allahmu yang menuntun engkau keluar dari Mesir!?, dan berbuat nista yang besar,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 19, 'Engkau tidak meninggalkan mereka di padang gurun karena kasih sayang-Mu yang besar. Tiang awan tidak berpindah dari atas mereka pada siang hari untuk memimpin mereka pada perjalanan, begitu juga tiang api pada malam hari untuk menerangi jalan yang mereka lalui.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 20, 'Dan Engkau memberikan kepada mereka Roh-Mu yang baik untuk mengajar mereka. Juga manna-Mu tidak Kautahan dari mulut mereka dan Engkau memberikan air kepada mereka untuk melepaskan dahaga.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 21, 'Empat puluh tahun lamanya Engkau memberikan mereka makan di padang gurun. Mereka tidak berkekurangan, pakaian mereka tidak rusak, dan kaki mereka tidak bengkak.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 22, 'Engkau menyerahkan kepada mereka kerajaan-kerajaan dan bangsa-bangsa dan membagikan itu kepada mereka sebagai daerah perbatasan, sebab mereka duduki tanah dari Sihon, raja negeri Hesbon dan tanah dari Og, raja negeri Basan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 23, 'Engkau membuat anak-anak mereka menjadi banyak seperti bintang-bintang di langit dan membawa mereka ke tanah yang Kausuruh kepada nenek moyang mereka untuk dimasuki dan diduduki.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 24, 'Lalu anak-anak itu memasuki dan menduduki tanah itu dan Engkau menundukkan di hadapan mereka penduduk tanah itu, yakni orang-orang Kanaan, dan menyerahkan orang-orang itu, baik raja-raja mereka, maupun bangsa-bangsa tanah itu, ke tangan mereka, supaya orang-orang itu diperlakukan sekehendak hati mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 25, 'Mereka merebut kota-kota yang berkubu dan tanah yang subur. Mereka merampas rumah-rumah yang penuh berisi berbagai-bagai barang baik, tempat-tempat air pahatan, kebun-kebun anggur dan kebun-kebun zaitun dan pohon-pohon buah-buahan dalam jumlah yang sangat banyak. Mereka makan dan menjadi kenyang dan gemuk. Mereka hidup mewah karena kebaikan-Mu yang besar.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 26, 'Tetapi mereka mendurhaka dan memberontak terhadap-Mu. Mereka membelakangi hukum-Mu dan membunuh nabi-nabi-Mu yang memperingatkan mereka dengan maksud membuat mereka berbalik kepada-Mu. Mereka berbuat nista yang besar.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 27, 'Lalu Engkau menyerahkan mereka ke tangan lawan-lawan mereka, yang menyesakkan mereka. Dan pada waktu kesusahan mereka berteriak kepada-Mu, lalu Engkau mendengar dari langit dan karena kasih sayang-Mu yang besar Kauberikan kepada mereka orang-orang yang menyelamatkan mereka dari tangan lawan mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 28, 'Tetapi begitu mereka mendapat keamanan, kembali mereka berbuat jahat di hadapan-Mu. Dan Engkau menyerahkan mereka ke tangan musuh-musuh mereka yang menguasai mereka. Kembali mereka berteriak kepada-Mu, dan Engkau mendengar dari langit, lalu menolong mereka berulang kali, karena kasih sayang-Mu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 29, 'Engkau memperingatkan mereka dengan maksud membuat mereka berbalik kepada hukum-Mu. Tetapi mereka bertindak angkuh, mereka tidak patuh kepada perintah-perintah-Mu dan mereka berdosa terhadap peraturan-peraturan-Mu, yang justru memberi hidup kepada orang yang melakukannya. Mereka melintangkan bahu untuk melawan, mereka bersitegang leher dan tidak mau dengar.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 30, 'Namun bertahun-tahun lamanya Engkau melanjutkan sabar-Mu terhadap mereka. Dengan Roh-Mu Engkau memperingatkan mereka, yakni dengan perantaraan para nabi-Mu, tetapi mereka tidak menghiraukannya, sehingga Engkau menyerahkan mereka ke tangan bangsa-bangsa segala negeri.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 31, 'Tetapi karena kasih sayang-Mu yang besar Engkau tidak membinasakan mereka sama sekali dan tidak meninggalkan mereka, karena Engkaulah Allah yang pengasih dan penyayang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 32, 'Sekarang, ya Allah kami, Allah yang maha besar, kuat dan dahsyat, yang berpegang pada perjanjian dan kasih setia-Nya, janganlah Kaupandang remeh segala kesusahan yang telah dialami oleh kami, oleh raja-raja kami, pemimpin-pemimpin kami, imam-imam kami, nabi-nabi kami dan nenek moyang kami, ya oleh seluruh umat-Mu, sejak zaman raja-raja Asyur sampai hari ini.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 33, 'Tetapi Engkaulah yang benar dalam segala hal yang menimpa kami, karena Engkau berlaku setia dan kamilah berbuat fasik.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 34, 'Juga raja-raja kami, pemimpin-pemimpin kami, imam-imam kami, dan nenek moyang kami tidak melakukan hukum-Mu. Mereka tidak memperhatikan perintah-perintah-Mu dan peringatan-peringatan-Mu yang Kauberikan kepada mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 35, 'Dalam kedudukan sebagai raja mereka tidak mau beribadah kepada-Mu, walaupun Engkau telah mengaruniakan kepada mereka banyak kebaikan dan telah menyediakan bagi mereka tanah yang luas dan subur. Mereka tidak berbalik dari perbuatan-perbuatan mereka yang jahat.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 36, 'Lihatlah, sekarang ini kami adalah budak. Ya, di tanah yang Kauberikan kepada nenek moyang kami untuk mengecap hasilnya dan segala kekayaannya kami ini adalah budak.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 37, 'Tanah itu menghasilkan banyak bagi raja-raja yang telah Kautetapkan atas kami karena dosa-dosa kami. Mereka itu memerintah sekehendak hati atas diri kami dan ternak kami, sehingga kami dalam kesesakan besar."', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 9, 38, 'Berdasarkan semuanya ini kami mengikat perjanjian yang teguh yang kami catat dengan dibubuhi meterai para pemimpin kami, orang-orang Lewi kami dan para imam kami.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 1, 'Yang membubuhi meterai adalah: kepala daerah Nehemia bin Hakhalya, Zedekia,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 2, 'Seraya, Azarya, Yeremia,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 3, 'Pasyhur, Amarya, Malkia,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 4, 'Hatus, Sebanya, Malukh,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 5, 'Harim, Meremot, Obaja,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 6, 'Daniel, Gineton, Barukh,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 7, 'Mesulam, Abia, Miyamin,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 8, 'Maazya, Bilgai dan Semaya. Itulah para imam.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 9, 'Sedang dari orang-orang Lewi: Yesua bin Azanya, Binui, seorang dari antara anak-anak Henadad, Kadmiel.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 10, 'Dan saudara-saudara mereka, yakni: Sebanya, Hodia, Kelita, Pelaya, Hanan,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 11, 'Mikha, Rehob, Hasabya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 12, 'Zakur, Serebya, Sebanya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 13, 'Hodia, Bani dan Beninu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 14, 'Dan dari pemimpin-pemimpin bangsa: Paros, Pahat-Moab, Elam, Zatu, Bani,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 15, 'Buni, Azgad, Bebai,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 16, 'Adonia, Bigwai, Adin,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 17, 'Ater, Hizkia, Azur,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 18, 'Hodia, Hasum, Bezai,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 19, 'Harif, Anatot, Nebai,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 20, 'Magpias, Mesulam, Hezir,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 21, 'Mesezabeel, Zadok, Yadua,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 22, 'Pelaca, Hanan, Anaya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 23, 'Hosea, Hananya, Hasub,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 24, 'Halohesh, Pilha, Sobek,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 25, 'Rehum, Hasabna, Maaseya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 26, 'Ahia, Hanan, Anan,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 27, 'Malukh, Harim dan Baana.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 28, 'Dan orang-orang yang lain, yakni: para imam dan orang-orang Lewi, para penunggu pintu gerbang, para penyanyi, para budak di bait Allah dan segala orang yang memisahkan diri dari penduduk negeri untuk patuh kepada hukum Allah, serta isteri mereka, anak-anak lelaki dan anak-anak perempuan mereka, begitu juga semua orang yang cukup dewasa untuk mengerti,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 29, 'menggabungkan diri dengan saudara-saudara mereka, yakni pemuka-pemuka mereka itu. Mereka bersumpah kutuk untuk hidup menurut hukum Allah yang diberikan dengan perantaraan Musa, hamba Allah itu, dan untuk tetap mengikuti dan melakukan segala perintah TUHAN, yakni Tuhan kami, serta segala peraturan dan ketetapan-Nya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 30, 'Pula kami tidak akan memberi anak-anak perempuan kami kepada penduduk negeri, ataupun mengambil anak-anak perempuan mereka bagi anak-anak lelaki kami.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 31, 'Dan bilamana penduduk negeri membawa barang-barang dan berbagai-bagai gandum untuk dijual pada hari Sabat, kami tidak akan membelinya dari mereka pada hari Sabat atau pada hari yang kudus. Dan kami akan membiarkan begitu saja hasil tanah pada tahun yang ketujuh dan tidak akan menagih sesuatu hutang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 32, 'Pula kami mewajibkan diri untuk memberi tiap tahun sepertiga syikal untuk ibadah di rumah Allah kami, yakni:', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 33, 'untuk roti sajian, untuk korban sajian yang tetap, untuk korban bakaran yang tetap, untuk hari-hari Sabat, bulan-bulan baru dan masa raya yang tetap, untuk persembahan-persembahan kudus dan korban-korban penghapus dosa, untuk mengadakan pendamaian bagi orang Israel serta segala pekerjaan di rumah Allah kami.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 34, 'Pula dengan membuang undi kami, yakni para imam, orang-orang Lewi dan kaum awam, menetapkan suatu cara untuk menyediakan kayu api. Kayu itu harus dibawa ke rumah Allah kami secara bergilir oleh kaum-kaum keluarga kami pada waktu-waktu tertentu setiap tahun, supaya di atas mezbah TUHAN Allah kami ada api yang menyala, seperti tertulis dalam kitab Taurat.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 35, 'Lagipula setiap tahun kami akan membawa ke rumah TUHAN hasil yang pertama dari tanah kami dan buah sulung segala pohon.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 36, 'Pun kami akan membawa ke rumah Allah kami, yakni kepada para imam yang menyelenggarakan kebaktian di rumah Allah kami, anak-anak sulung kami dan anak-anak sulung ternak kami seperti tertulis dalam kitab Taurat, juga anak-anak sulung lembu kami dan kambing domba kami.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 37, 'Dan tepung jelai kami yang mula-mula, dan persembahan-persembahan khusus kami, dan buah segala pohon, dan anggur dan minyak akan kami bawa kepada para imam, ke bilik-bilik rumah Allah kami, dan kepada orang-orang Lewi akan kami bawa persembahan persepuluhan dari tanah kami, karena orang-orang Lewi inilah yang memungut persembahan-perse persepuluhan di segala kota pertanian kami.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 38, 'Seorang imam, anak Harun, akan menyertai orang-orang Lewi itu, bila mereka memungut persembahan persepuluhan. Dan orang-orang Lewi itu akan membawa persembahan persepuluhan dari pada persembahan persepuluhan itu ke rumah Allah kami, ke bilik-bilik rumah perbendaharaan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 10, 39, 'Karena orang Israel dan orang Lewi harus membawa persembahan khusus dari pada gandum, anggur dan minyak ke bilik-bilik itu. Di situ ada perkakas-perkakas tempat kudus, pula para imam yang menyelenggarakan kebaktian, para penunggu pintu gerbang dan para penyanyi. Kami tidak akan membiarkan rumah Allah kami.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 1, 'Para pemimpin bangsa menetap di Yerusalem, sedang orang-orang lain membuang undi untuk menentukan satu dari sepuluh orang yang harus menetap di Yerusalem, kota yang kudus itu, sedang yang sembilan orang lagi tinggal di kota-kota yang lain.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 2, 'Orang-orang memuji setiap orang yang rela menetap di Yerusalem.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 3, 'Inilah kepala-kepala propinsi Yehuda yang menetap di Yerusalem, sedang di kota-kota di Yehuda setiap orang, yakni orang-orang Israel awam, para imam, orang-orang Lewi, para budak di bait Allah dan keturunan para hamba Salomo, tinggal di tanah miliknya, di kotanya sendiri.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 4, 'Di Yerusalem tinggal orang-orang dari bani Yehuda dan bani Benyamin. Dari anak-anak Yehuda: Ataya bin Uzia bin Zakharia bin Amarya bin Sefaca bin Mahalaleel dari bani Peres,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 5, 'dan Maaseya bin Barukh bin Kolhoze bin Hazaya bin Adaya bin Yoyarib bin Zakharia keturunan orang Syela.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 6, 'Semua bani Peres yang tinggal di Yerusalem berjumlah empat ratus enam puluh delapan orang yang gagah perkasa.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 7, 'Dan inilah bani Benyamin: Salu bin Mesulam bin Yoed bin Pedaya bin Kolaya bin Maaseya bin Itiel bin Yesaya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 8, 'Dan sesudah dia: Gabai, Salai: sembilan ratus dua puluh delapan orang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 9, 'Yoel bin Zikhri adalah pengawas mereka, sedang Yehuda bin Hasenua adalah wakil penguasa kota.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 10, 'Dari para imam: Yedaya bin Yoyarib, Yakhin,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 11, 'Seraya bin Hilkia bin Mesulam bin Zadok bin Merayot bin Ahitub, pemuka rumah Allah,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 12, 'dan saudara-saudara mereka yang bertugas di rumah itu: delapan ratus dua puluh dua orang. Pula Adaya bin Yeroham bin Pelalya bin Amzi bin Zakharia bin Pasyhur bin Malkia', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 13, 'dan saudara-saudaranya, kepala-kepala kaum keluarga: dua ratus empat puluh dua orang. Dan Amasai bin Asareel bin Ahzai bin Mesilemot bin Imer,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 14, 'dan saudara-saudara mereka, pahlawan-pahlawan yang gagah perkasa, seratus dua puluh delapan orang dengan Zabdiel bin Gedolim sebagai pengawas mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 15, 'Dari orang-orang Lewi: Semaya bin Hasub bin Azrikam bin Hasabya bin Buni.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 16, 'Pula Sabetai dan Yozabad, kepala-kepala orang-orang Lewi, yang mengawasi pekerjaan di luar rumah Allah.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 17, 'Lalu Matanya bin Mikha bin Zabdi bin Asaf, pemimpin yang mengangkat nyanyian syukur dalam doa, dan Bakbukya, orang kedua di antara saudara-saudaranya, dan Abda bin Samua bin Galal bin Yedutun.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 18, 'Semua orang Lewi di kota kudus ada dua ratus delapan puluh empat orang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 19, 'Para penunggu pintu gerbang: Akub dan Talmon dengan saudara-saudara mereka yang mengadakan penjagaan di pintu-pintu gerbang, berjumlah seratus tujuh puluh dua orang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 20, 'Selebihnya dari orang-orang Israel awam dan dari para imam dan orang-orang Lewi ada di semua kota Yehuda, masing-masing di tanah pusakanya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 21, 'Tetapi para budak di bait Allah tinggal di Ofel. Ziha dan Gispa adalah pemimpin para budak di bait Allah itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 22, 'Pengawas orang-orang Lewi di Yerusalem adalah Uzi bin Bani bin Hasabya bin Matanya bin Mikha dari bani Asaf, yakni para penyanyi yang menyanyi sementara berlangsung kebaktian di rumah Allah.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 23, 'Karena mengenai mereka ada perintah raja yang menetapkan peraturan untuk para penyanyi menurut keperluan setiap hari.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 24, 'Petahya bin Mesezabeel dari bani Zerah bin Yehuda diperbantukan kepada raja untuk segala urusan mengenai bangsa itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 25, 'Tentang tempat-tempat kediaman di daerah perladangan, sebagian dari bani Yehuda tinggal di Kiryat-Arba dan segala anak kotanya, di Dibon dan segala anak kotanya dan di Yekabzeel dan desa-desanya;', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 26, 'di Yesua, di Molada dan Bet-Pelet,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 27, 'di Hazar-Sual, di Bersyeba dan segala anak kotanya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 28, 'di Ziklag, di Mekhona dan segala anak kotanya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 29, 'di En-Rimon, Zora, Yarmut,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 30, 'Zanoah, Adulam dan desa-desanya, di Lakhis dan ladang-ladangnya, dan di Azeka dan segala anak kotanya. Demikianlah mereka berkampung dari Bersyeba sampai lebak Hinom.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 31, 'Dan bani Benyamin tinggal mulai dari Geba, di Mikhmas, di Aya, di Betel dan segala anak kotanya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 32, 'di Anatot, Nob dan Ananya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 33, 'di Hazor, Rama dan Gitaim,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 34, 'di Hadid, Zeboim dan Nebalat,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 35, 'di Lod dan di Ono, Lembah Tukang-tukang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 11, 36, 'Beberapa rombongan orang Lewi dari Yehuda bergabung dengan orang Benyamin.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 1, 'Inilah para imam dan orang-orang Lewi yang berangkat pulang bersama-sama Zerubabel bin Sealtiel dan Yesua: Seraya, Yeremia, Ezra,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 2, 'Amarya, Malukh, Hatus,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 3, 'Sekhanya, Rehum, Meremot,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 4, 'Ido, Ginetoi, Abia,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 5, 'Miyamin, Maaja, Bilga,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 6, 'Semaya, Yoyarib, Yedaya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 7, 'Salu, Amok, Hilkia dan Yedaya. Itulah kepala-kepala imam dan saudara-saudara mereka pada zaman Yesua.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 8, 'Dari orang-orang Lewi: Yesua, Binui, Kadmiel, Serebya, Yehuda dan Matanya. Matanya ini dan saudara-saudaranya memimpin nyanyian syukur,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 9, 'sementara Bakbukya dan Uni dan saudara-saudara mereka berdiri di hadapan mereka itu menurut kelompok-kelompok tugas.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 10, 'Yesua memperanakkan Yoyakim, dan Yoyakim memperanakkan Elyasib, dan Elyasib memperanakkan Yoyada,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 11, 'dan Yoyada memperanakkan Yonatan, dan Yonatan memperanakkan Yadua.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 12, 'Pada zaman Yoyakim yang menjadi imam adalah kepala-kepala kaum keluarga ini: Meraya, dari kaum keluarga Seraya, Hananya dari kaum keluarga Yeremia,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 13, 'Mesulam dari kaum keluarga Ezra, Yohanan dari kaum keluarga Amarya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 14, 'Yonatan dari kaum keluarga Melikhu, Yusuf dari kaum keluarga Sebanya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 15, 'Adna dari kaum keluarga Harim, Helkai dari kaum keluarga Merayot,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 16, 'Zakharia dari kaum keluarga Ido, Mesulam dari kaum keluarga Gineton,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 17, 'Zikhri dari kaum keluarga Abia, dari kaum keluarga Minyamin, Piltai dari kaum keluarga Moaja,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 18, 'Samua dari kaum keluarga Bilga, Yonatan dari kaum keluarga Semaya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 19, 'Matnai dari kaum keluarga Yoyarib, Uzi dari kaum keluarga Yedaya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 20, 'Kalai dari kaum keluarga Salai, Heber dari kaum keluarga Amok,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 21, 'Hasabya dari kaum keluarga Hilkia dan Netaneel dari kaum keluarga Yedaya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 22, 'Tentang orang-orang Lewi, para kepala kaum keluarga mereka tercatat pada zaman Elyasib, Yoyada, Yohanan dan Yadua, sedang para imam tercatat sampai pemerintahan Darius, orang Persia itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 23, 'Kepala-kepala kaum keluarga anak-anak Lewi tercatat dalam kitab sejarah sampai zaman Yohanan bin Elyasib.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 24, 'Inilah para kepala orang-orang Lewi: Hasabya, Serebya, Yesua bin Kadmiel, dan saudara-saudara mereka yang berdiri di hadapan mereka untuk menyanyikan puji-pujian dan syukur sesuai dengan perintah Daud, abdi Allah itu, kelompok di samping kelompok.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 25, 'Matanya, Bakbukya, Obaja, Mesulam, Talmon dan Akub adalah penunggu-penunggu pintu gerbang yang mengadakan penjagaan di gudang-gudang perlengkapan pada pintu-pintu gerbang.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 26, 'Mereka itu hidup pada zaman Yoyakim bin Yesua bin Yozadak dan pada zaman bupati Nehemia dan imam Ezra, ahli kitab itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 27, 'Pada pentahbisan tembok Yerusalem orang-orang Lewi dipanggil dari segala tempat mereka dan dibawa ke Yerusalem untuk mengadakan pentahbisan yang meriah dengan ucapan syukur dan kidung, dengan ceracap, gambus dan kecapi.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 28, 'Maka berkumpullah kaum penyanyi dari daerah sekitar Yerusalem, dari desa-desa orang Netofa,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 29, 'dari Bet-Gilgal, dari padang Geba dan Asmawet, karena para penyanyi itu telah mendirikan desa-desa sekitar Yerusalem.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 30, 'Para imam dan orang-orang Lewi mentahirkan dirinya, lalu mentahirkan seluruh umat itu, dan kemudian pintu-pintu gerbang dan tembok.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 31, 'Lalu aku mempersilakan para pemimpin orang Yehuda naik ke atas tembok dan kubentuk dua paduan suara yang besar. Yang satu berarak ke kanan di atas tembok ke jurusan pintu gerbang Sampah.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 32, 'Di belakangnya berjalanlah Hosaya dengan sebagian dari para pemimpin orang Yehuda,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 33, 'pula Azarya, Ezra, Mesulam,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 34, 'Yehuda, Benyamin, Semaya dan Yeremia,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 35, 'dan dari kaum imam yang memegang nafiri: Zakharia bin Yonatan bin Semaya bin Matanya bin Mikha bin Zakur bin Asaf,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 36, 'dan saudara-saudaranya, yakni: Semaya, Azareel, Milalai, Gilalai, Maai, Netaneel, Yehuda dan Hanani dengan bunyi-bunyian Daud, abdi Allah itu, sedang Ezra, ahli kitab itu berjalan di depan mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 37, 'Lalu pada pintu gerbang Mata Air mereka langsung naik tangga-tangga kota Daud, pada jalan pendakian tembok, lewat istana Daud, dan berjalan sampai pintu gerbang Air, di sebelah Timur.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 38, 'Dan paduan suara yang kedua berarak ke kiri dan aku mengikutinya dengan sebagian dari orang-orang itu melalui tembok dan menara Perapian sampai tembok Lebar.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 39, 'Lalu kami melalui pintu gerbang Efraim, pintu gerbang Lama, pintu gerbang Ikan, menara Hananeel dan menara Mea sampai pintu gerbang Domba. Mereka berhenti di pintu gerbang Penjagaan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 40, 'Kemudian kedua paduan suara itu berdiri di rumah Allah. Demikian juga aku bersama-sama sebagian dari para penguasa,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 41, 'dan para imam, yakni: Elyakim, Maaseya, Minyamin, Mikha, Elyoenai, Zakharia, Hananya dengan memegang nafiri,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 42, 'dan Maaseya, Semaya, Eleazar, Uzi, Yohanan, Malkia, Elam dan Ezer. Lalu para penyanyi memperdengarkan kidung di bawah pimpinan Yizrahya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 43, 'Pada hari itu mereka mempersembahkan korban yang besar. Mereka bersukaria karena Allah memberi mereka kesukaan yang besar. Juga segala perempuan dan anak-anak bersukaria, sehingga kesukaan Yerusalem terdengar sampai jauh.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 44, 'Pada masa itu beberapa orang diangkat untuk mengawasi bilik-bilik perbendaharaan, bilik-bilik untuk persembahan khusus, untuk hasil pertama dan untuk persembahan persepuluhan, supaya sumbangan yang menurut hukum menjadi bagian para imam dan orang-orang Lewi dikumpulkan di bilik-bilik itu sesuai dengan ladang setiap kota. Sebab Yehuda bersukacita karena para imam dan orang-orang Lewi yang bertugas.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 45, 'Karena merekalah yang melakukan tugas pelayanan bagi Allah mereka dan tugas pentahiran, demikian juga para penyanyi dan para penunggu pintu gerbang, sesuai dengan perintah Daud dan Salomo, anaknya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 46, 'Karena sudah sejak dahulu, pada zaman Daud dan Asaf, ada pemimpin-pemimpin penyanyi, ada nyanyian pujian dan nyanyian syukur bagi Allah.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 12, 47, 'Pada zaman Zerubabel dan Nehemia semua orang Israel memberikan sumbangan bagi para penyanyi dan para penunggu pintu gerbang sekadar yang perlu tiap-tiap hari dan mempersembahkan persembahan kudus kepada orang-orang Lewi. Dan orang-orang Lewi mempersembahkan persembahan kudus kepada anak-anak Harun.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 1, 'Pada masa itu bagian-bagian dari pada kitab Musa dibacakan dengan didengar oleh rakyat. Didapati tertulis dalam kitab itu, bahwa orang Amon dan orang Moab tidak boleh masuk jemaah Allah untuk selamanya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 2, 'Karena mereka tidak menyongsong orang Israel dengan roti dan air, malah mengupah Bileam melawan orang Israel supaya dikutukinya. Tetapi Allah kami mengubah kutuk itu menjadi berkat.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 3, 'Ketika mereka mendengar pembacaan Taurat itu mereka memisahkan semua peranakan dari orang Israel.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 4, 'Tetapi sebelum masa itu imam Elyasib yang diangkat untuk mengawasi bilik-bilik rumah Allah kami, dan yang mempunyai hubungan erat dengan Tobia,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 5, 'menyediakan sebuah bilik besar bagi Tobia itu. Sebelumnya orang membawa ke bilik itu korban sajian, kemenyan, perkakas-perkakas dan persembahan persepuluhan dari pada gandum, anggur dan minyak yang menjadi hak orang-orang Lewi, para penyanyi dan para penunggu pintu gerbang, dan persembahan khusus bagi para imam.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 6, 'Ketika peristiwa itu terjadi aku tidak ada di Yerusalem, karena pada tahun ketiga puluh dua pemerintahan Artahsasta, raja Babel, aku pergi menghadap raja. Tetapi sesudah beberapa waktu aku minta izin dari raja untuk pergi.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 7, 'Lalu aku tiba di Yerusalem dan melihat kejahatan yang dibuat Elyasib untuk keuntungan Tobia, sebab bagi Tobia ini telah disediakannya sebuah bilik di pelataran rumah Allah.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 8, 'Aku menjadi sangat kesal, lalu kulempar semua perabot rumah Tobia ke luar bilik itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 9, 'Kemudian kusuruh tahirkan bilik itu, sesudah itu kubawa kembali ke sana perkakas-perkakas rumah Allah, korban sajian dan kemenyan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 10, 'Juga kudapati bahwa sumbangan-sumbangan bagi orang-orang Lewi tidak pernah diberikan, sehingga orang-orang Lewi dan para penyanyi yang bertugas masing-masing lari ke ladangnya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 11, 'Aku menyesali para penguasa, kataku: "Mengapa rumah Allah dibiarkan begitu saja?" Lalu kukumpulkan orang-orang Lewi itu dan kukembalikan pada tempatnya.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 12, 'Maka seluruh orang Yehuda membawa lagi persembahan persepuluhan dari pada gandum, anggur dan minyak ke perbendaharaan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 13, 'Sebagai pengawas-pengawas perbendaharaan kuangkat imam Selemya dan Zadok, seorang ahli kitab, dan Pedaya, seorang Lewi, sedang Hanan bin Zakur bin Matanya diperbantukan kepada mereka, karena orang-orang itu dianggap setia. Mereka diserahi tugas untuk mengurus pembagian kepada saudara-saudara mereka.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 14, 'Ya Allahku, ingatlah kepadaku karena hal itu dan janganlah hapuskan segala perbuatan bakti yang telah kulakukan terhadap rumah Allahku dan segala pelayanan di dalamnya!', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 15, 'Pada masa itu kulihat di Yehuda orang-orang mengirik memeras anggur pada hari Sabat, pula orang-orang yang membawa berkas-berkas gandum dan memuatnya di atas keledai, juga anggur, buah anggur dan buah ara dan pelbagai muatan yang mereka bawa ke Yerusalem pada hari Sabat. Aku memperingatkan mereka ketika mereka menjual bahan-bahan makanan.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 16, 'Juga orang Tirus yang tinggal di situ membawa ikan dan pelbagai barang dagangan dan menjual itu kepada orang-orang Yehuda pada hari Sabat, bahkan di Yerusalem.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 17, 'Lalu aku menyesali pemuka-pemuka orang Yehuda, kataku kepada mereka: "Kejahatan apa yang kamu lakukan ini dengan melanggar kekudusan hari Sabat?', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 18, 'Bukankah nenek moyangmu telah berbuat demikian, sehingga Allah kita mendatangkan seluruh malapetaka ini atas kita dan atas kota ini? Apakah kamu bermaksud memperbesar murka yang menimpa Israel dengan melanggar kekudusan hari Sabat?"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 19, 'Kalau sudah remang-remang di pintu-pintu gerbang Yerusalem menjelang hari Sabat, kusuruh tutup pintu-pintu dan kuperintahkan supaya jangan dibuka sampai lewat hari Sabat. Dan aku tempatkan beberapa orang dari anak buahku di pintu-pintu gerbang, supaya tidak ada muatan yang masuk pada hari Sabat.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 20, 'Tetapi orang-orang yang berdagang dan berjualan rupa-rupa barang itu kemudian bermalam juga di luar tembok Yerusalem satu dua kali.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 21, 'Lalu aku memperingatkan mereka, kataku: "Mengapa kamu bermalam di depan tembok? Kalau kamu berbuat itu sekali lagi akan kukenakan tanganku kepadamu." Sejak waktu itu mereka tidak datang lagi pada hari Sabat.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 22, 'Juga kusuruh orang-orang Lewi mentahirkan dirinya dan datang menjaga pintu-pintu gerbang untuk menguduskan hari Sabat. Ya Allahku, ingatlah kepadaku juga karena hal itu dan sayangilah aku menurut kasih setia-Mu yang besar!', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 23, 'Pada masa itu juga kulihat bahwa beberapa orang Yahudi memperisteri perempuan-perempuan Asdod, perempuan-perempuan Amon atau perempuan-perempuan Moab.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 24, 'Sebagian dari anak-anak mereka berbicara bahasa Asdod atau bahasa bangsa lain itu dan tidak tahu berbicara bahasa Yahudi.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 25, 'Aku menyesali mereka, kukutuki mereka, dan beberapa orang di antara mereka kupukuli dan kucabut rambutnya dan kusuruh mereka bersumpah demi Allah, demikian: "Jangan sekali-kali kamu serahkan anak-anak perempuanmu kepada anak-anak lelaki mereka, atau mengambil anak-anak perempuan mereka sebagai isteri untuk anak-anak lelakimu atau untuk dirimu sendiri!', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 26, 'Bukankah Salomo, raja Israel, telah berbuat dosa karena hal semacam itu? Walaupun di antara begitu banyak bangsa tidak ada seorang raja seperti dia, yang dikasihi Allahnya dan diangkat oleh Allah itu menjadi raja seluruh Israel, namun diapun terbawa ke dalam dosa oleh perempuan-perempuan asing itu.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 27, 'Apakah orang harus mendengar bahwa juga kamu berbuat segala kejahatan yang besar itu, yakni berubah setia terhadap Allah kita karena memperisteri perempuan-perempuan asing?"', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 28, 'Seorang dari anak-anak Yoyada bin Elyasib, imam besar itu, adalah menantu Sanbalat, orang Horoni itu. Oleh sebab itu kuusir dia dari padaku.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 29, 'Ya Allahku, ingatlah bagaimana mereka mencemarkan jabatan imam serta perjanjian mengenai para imam dan orang-orang Lewi.', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 30, 'Kutahirkan mereka dari segala sesuatu yang asing dan kutetapkan tugas-tugas untuk para imam dan orang-orang Lewi, masing-masing dalam bidang pekerjaannya,', 'id', 'TB'),
  ('16', 'neh', 'Nehemia', 13, 31, 'pula kutetapkan suatu cara untuk menyediakan kayu api pada waktu-waktu tertentu dan untuk hasil-hasil yang pertama. Ya Allahku, ingatlah kepadaku, demi kesejahteraanku!', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 1, 'Pada zaman Ahasyweros?dialah Ahasyweros yang merajai seratus dua puluh tujuh daerah mulai dari India sampai ke Etiopia?,', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 2, 'pada zaman itu, ketika raja Ahasyweros bersemayam di atas takhta kerajaannya di dalam benteng Susan,', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 3, 'pada tahun yang ketiga dalam pemerintahannya, diadakanlah oleh baginda perjamuan bagi semua pembesar dan pegawainya; tentara Persia dan Media, kaum bangsawan dan pembesar daerah hadir di hadapan baginda.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 4, 'Di samping itu baginda memamerkan kekayaan kemuliaan kerajaannya dan keindahan kebesarannya yang bersemarak, berhari-hari lamanya, sampai seratus delapan puluh hari.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 5, 'Setelah genap hari-hari itu, maka raja mengadakan perjamuan lagi tujuh hari lamanya bagi seluruh rakyatnya yang terdapat di dalam benteng Susan, dari pada orang besar sampai kepada orang kecil, bertempat di pelataran yang ada di taman istana kerajaan.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 6, 'Di situ tirai-mirai dari pada kain lenan, mori halus dan kain ungu tua, yang terikat dengan tali lenan halus dan ungu muda bergantung pada tombol-tombol perak di tiang-tiang marmar putih, sedang katil emas dan perak ditempatkan di atas lantai pualam, marmar putih, gewang dan pelinggam.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 7, 'Minuman dihidangkan dalam piala emas yang beraneka warna, dan anggurnya ialah anggur minuman raja yang berlimpah-limpah, sebagaimana layak bagi raja.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 8, 'Adapun aturan minum ialah: tiada dengan paksa; karena beginilah disyaratkan raja kepada semua bentara dalam, supaya mereka berbuat menurut keinginan tiap-tiap orang.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 9, 'Juga Wasti, sang ratu, mengadakan perjamuan bagi semua perempuan di dalam istana raja Ahasyweros.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 10, 'Pada hari yang ketujuh, ketika raja riang gembira hatinya karena minum anggur, bertitahlah baginda kepada Mehuman, Bizta, Harbona, Bigta, Abagta, Zetar dan Karkas, yakni ketujuh sida-sida yang bertugas di hadapan raja Ahasyweros,', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 11, 'supaya mereka membawa Wasti, sang ratu, dengan memakai mahkota kerajaan, menghadap raja untuk memperlihatkan kecantikannya kepada sekalian rakyat dan pembesar-pembesar, karena sang ratu sangat elok rupanya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 12, 'Tetapi ratu Wasti menolak untuk menghadap menurut titah raja yang disampaikan oleh sida-sida itu, sehingga sangat geramlah raja dan berapi-apilah murkanya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 13, 'Maka bertanyalah raja kepada orang-orang arif bijaksana, orang-orang yang mengetahui kebiasaan zaman?karena demikianlah biasanya masalah-masalah raja dikemukakan kepada para ahli undang-undang dan hukum;', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 14, 'adapun yang terdekat kepada baginda ialah Karsena, Setar, Admata, Tarsis, Meres, Marsena dan Memukan, ketujuh pembesar Persia dan Media, yang boleh memandang wajah raja dan yang mempunyai kedudukan yang tinggi di dalam kerajaan?,tanya raja:', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 15, '"Apakah yang harus diperbuat atas ratu Wasti menurut undang-undang, karena tidak dilakukannya titah raja Ahasyweros yang disampaikan oleh sida-sida?"', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 16, 'Maka sembah Memukan di hadapan raja dan para pembesar itu: "Wasti, sang ratu, bukan bersalah kepada raja saja, melainkan juga kepada semua pembesar dan segala bangsa yang di dalam segala daerah raja Ahasyweros.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 17, 'Karena kelakuan sang ratu itu akan merata kepada semua perempuan, sehingga mereka tidak menghiraukan suaminya, apabila diceritakan orang: Raja Ahasyweros menitahkan, supaya Wasti, sang ratu, dibawa menghadap kepadanya, tetapi ia tidak mau datang.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 18, 'Pada hari ini juga isteri para pembesar raja di Persia dan Media yang mendengar tentang kelakuan sang ratu akan berbicara tentang hal itu kepada suaminya, sehingga berlarut-larutlah penghinaan dan kegusaran.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 19, 'Jikalau baik pada pemandangan raja, hendaklah dikeluarkan suatu titah kerajaan dari hadapan baginda dan dituliskan di dalam undang-undang Persia dan Media, sehingga tidak dapat dicabut kembali, bahwa Wasti dilarang menghadap raja Ahasyweros, dan bahwa raja akan mengaruniakan kedudukannya sebagai ratu kepada orang lain yang lebih baik dari padanya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 20, 'Bila keputusan yang diambil raja kedengaran di seluruh kerajaannya?alangkah besarnya kerajaan itu! ?,maka semua perempuan akan memberi hormat kepada suami mereka, dari pada orang besar sampai kepada orang kecil."', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 21, 'Usul itu dipandang baik oleh raja serta para pembesar, jadi bertindaklah raja sesuai dengan usul Memukan itu.', 'id', 'TB'),
  ('17', 'est', 'Ester', 1, 22, 'Dikirimkanlah oleh baginda surat-surat ke segenap daerah kerajaan, tiap-tiap daerah menurut tulisannya dan tiap-tiap bangsa menurut bahasanya, bunyinya: "Setiap laki-laki harus menjadi kepala dalam rumah tangganya dan berbicara menurut bahasa bangsanya."', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 1, 'Sesudah peristiwa-peristiwa ini, setelah kepanasan murka raja Ahasyweros surut, terkenanglah baginda kepada Wasti dan yang dilakukannya, dan kepada apa yang diputuskan atasnya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 2, 'Maka sembah para biduanda raja yang bertugas pada baginda: "Hendaklah orang mencari bagi raja gadis-gadis, yaitu anak-anak dara yang elok rupanya;', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 3, 'hendaklah raja menempatkan kuasa-kuasa di segenap daerah kerajaannya, supaya mereka mengumpulkan semua gadis, anak-anak dara yang elok rupanya, di dalam benteng Susan, di balai perempuan, di bawah pengawasan Hegai, sida-sida raja, penjaga para perempuan; hendaklah diberikan wangi-wangian kepada mereka.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 4, 'Dan gadis yang terbaik pada pemandangan raja, baiklah dia menjadi ratu ganti Wasti." Hal itu dipandang baik oleh raja, dan dilakukanlah demikian.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 5, 'Pada waktu itu ada di dalam benteng Susan seorang Yahudi, yang bernama Mordekhai bin Yair bin Simei bin Kish, seorang Benyamin', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 6, 'yang diangkut dari Yerusalem sebagai salah seorang buangan yang turut dengan Yekhonya, raja Yehuda, ketika ia diangkut ke dalam pembuangan oleh raja Nebukadnezar, raja Babel.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 7, 'Mordekhai itu pengasuh Hadasa, yakni Ester, anak saudara ayahnya, sebab anak itu tidak beribu bapa lagi; gadis itu elok perawakannya dan cantik parasnya. Ketika ibu bapanya mati, ia diangkat sebagai anak oleh Mordekhai.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 8, 'Setelah titah dan undang-undang raja tersiar dan banyak gadis dikumpulkan di dalam benteng Susan, di bawah pengawasan Hegai, maka Esterpun dibawa masuk ke dalam istana raja, di bawah pengawasan Hegai, penjaga para perempuan.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 9, 'Maka gadis itu sangat baik pada pemandangannya dan menimbulkan kasih sayangnya, sehingga Hegai segera memberikan wangi-wangian dan pelabur kepadanya, dan juga tujuh orang dayang-dayang yang terpilih dari isi istana raja, kemudian memindahkan dia dengan dayang-dayangnya ke bagian yang terbaik di dalam balai perempuan.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 10, 'Ester tidak memberitahukan kebangsaan dan asal usulnya, karena dilarang oleh Mordekhai.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 11, 'Tiap-tiap hari berjalan-jalanlah Mordekhai di depan pelataran balai perempuan itu untuk mengetahui bagaimana keadaan Ester dan apa yang akan berlaku atasnya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 12, 'Tiap-tiap kali seorang gadis mendapat giliran untuk masuk menghadap raja Ahasyweros, dan sebelumnya ia dirawat menurut peraturan bagi para perempuan selama dua belas bulan, sebab seluruh waktu itu digunakan untuk pemakaian wangi-wangian: enam bulan untuk memakai minyak mur dan enam bulan lagi untuk memakai minyak kasai serta lain-lain wangi-wangian perempuan.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 13, 'Lalu gadis itu masuk menghadap raja, dan segala apa yang dimintanya harus diberikan kepadanya untuk dibawa masuk dari balai perempuan ke dalam istana raja.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 14, 'Pada waktu petang ia masuk dan pada waktu pagi ia kembali, tetapi sekali ini ke dalam balai perempuan yang kedua, di bawah pengawasan Saasgas, sida-sida raja, penjaga para gundik. Ia tidak diperkenankan masuk lagi menghadap raja, kecuali jikalau raja berkenan kepadanya dan ia dipanggil dengan disebutkan namanya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 15, 'Ketika Ester?anak Abihail, yakni saudara ayah Mordekhai yang mengangkat Ester sebagai anak?mendapat giliran untuk masuk menghadap raja, maka ia tidak menghendaki sesuatu apapun selain dari pada yang dianjurkan oleh Hegai, sida-sida raja, penjaga para perempuan. Maka Ester dapat menimbulkan kasih sayang pada semua orang yang melihat dia.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 16, 'Demikianlah Ester dibawa masuk menghadap raja Ahasyweros ke dalam istananya pada bulan yang kesepuluh?yakni bulan Tebet?pada tahun yang ketujuh dalam pemerintahan baginda.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 17, 'Maka Ester dikasihi oleh baginda lebih dari pada semua perempuan lain, dan ia beroleh sayang dan kasih baginda lebih dari pada semua anak dara lain, sehingga baginda mengenakan mahkota kerajaan ke atas kepalanya dan mengangkat dia menjadi ratu ganti Wasti.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 18, 'Kemudian diadakanlah oleh baginda suatu perjamuan bagi semua pembesar dan pegawainya, yakni perjamuan karena Ester, dan baginda menitahkan kebebasan pajak bagi daerah-daerah serta mengaruniakan anugerah, sebagaimana layak bagi raja.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 19, 'Selama anak-anak dara dikumpulkan untuk kedua kalinya, Mordekhai duduk di pintu gerbang istana raja.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 20, 'Adapun Ester tidak memberitahukan asal usul dan kebangsaannya seperti diperintahkan kepadanya oleh Mordekhai, sebab Ester tetap berbuat menurut perkataan Mordekhai seperti pada waktu ia masih dalam asuhannya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 21, 'Pada waktu itu, ketika Mordekhai duduk di pintu gerbang istana raja, sakit hatilah Bigtan dan Teresh, dua orang sida-sida raja yang termasuk golongan penjaga pintu, lalu berikhtiarlah mereka untuk membunuh raja Ahasyweros.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 22, 'Tetapi perkara itu dapat diketahui oleh Mordekhai, lalu diberitahukannyala kepada Ester, sang ratu, dan Ester mempersembahkannya kepada raja atas nama Mordekhai.', 'id', 'TB'),
  ('17', 'est', 'Ester', 2, 23, 'Perkara itu diperiksa dan ternyata benar, maka kedua orang itu disulakan pada tiang. Dan peristiwa itu dituliskan di dalam kitab sejarah, di hadapan raja.', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 1, 'Sesudah peristiwa-peristiwa ini maka Haman bin Hamedata, orang Agag, dikaruniailah kebesaran oleh raja Ahasyweros, dan pangkatnya dinaikkan serta kedudukannya ditetapkan di atas semua pembesar yang ada di hadapan baginda.', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 2, 'Dan semua pegawai raja yang di pintu gerbang istana raja berlutut dan sujud kepada Haman, sebab demikianlah diperintahkan raja tentang dia, tetapi Mordekhai tidak berlutut dan tidak sujud.', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 3, 'Maka para pegawai raja yang di pintu gerbang istana raja berkata kepada Mordekhai: "Mengapa engkau melanggar perintah raja?"', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 4, 'Setelah mereka menegor dia berhari-hari dengan tidak didengarkannya juga, maka hal itu diberitahukan merekalah kepada Haman untuk melihat, apakah sikap Mordekhai itu dapat tetap, sebab ia telah menceritakan kepada mereka, bahwa ia orang Yahudi.', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 5, 'Ketika Haman melihat, bahwa Mordekhai tidak berlutut dan sujud kepadanya, maka sangat panaslah hati Haman,', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 6, 'tetapi ia menganggap dirinya terlalu hina untuk membunuh hanya Mordekhai saja, karena orang telah memberitahukan kepadanya kebangsaan Mordekhai itu. Jadi Haman mencari ikhtiar memunahkan semua orang Yahudi, yakni bangsa Mordekhai itu, di seluruh kerajaan Ahasyweros.', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 7, 'Dalam bulan pertama, yakni bulan Nisan, dalam tahun yang kedua belas zaman raja Ahasyweros, orang membuang pur?yakni undi?di depan Haman, hari demi hari dan bulan demi bulan sampai jatuh pada bulan yang kedua belas, yakni bulan Adar.', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 8, 'Maka sembah Haman kepada raja Ahasyweros: "Ada suatu bangsa yang hidup tercerai-berai dan terasing di antara bangsa-bangsa di dalam seluruh daerah kerajaan tuanku, dan hukum mereka berlainan dengan hukum segala bangsa, dan hukum raja tidak dilakukan mereka, sehingga tidak patut bagi raja membiarkan mereka leluasa.', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 9, 'Jikalau baik pada pemandangan raja, hendaklah dikeluarkan surat titah untuk membinasakan mereka; maka hamba akan menimbang perak sepuluh ribu talenta dan menyerahkannya kepada tangan para pejabat yang bersangkutan, supaya mereka memasukkannya ke dalam perbendaharaan raja."', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 10, 'Maka raja mencabut cincin meterainya dari jarinya, lalu diserahkannya kepada Haman bin Hamedata, orang Agag, seteru orang Yahudi itu,', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 11, 'kemudian titah raja kepada Haman: "Perak itu terserah kepadamu, juga bangsa itu untuk kauperlakukan seperti yang kaupandang baik."', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 12, 'Maka dalam bulan yang pertama pada hari yang ketiga belas dipanggillah para panitera raja, lalu, sesuai dengan segala yang diperintahkan Haman, ditulislah surat kepada wakil-wakil raja, kepada setiap bupati yang menguasai daerah dan kepada setiap pembesar bangsa, yakni kepada tiap-tiap daerah menurut tulisannya dan kepada tiap-tiap bangsa menurut bahasanya; surat itu ditulis atas nama raja Ahasyweros dan dimeterai dengan cincin meterai raja.', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 13, 'Surat-surat itu dikirimkan dengan perantaraan pesuruh-pesuruh cepat ke segala daerah kerajaan, supaya dipunahkan, dibunuh dan dibinasakan semua orang Yahudi dari pada yang muda sampai kepada yang tua, bahkan anak-anak dan perempuan-perempuan, pada satu hari juga, pada tanggal tiga belas bulan yang kedua belas?yakni bulan Adar?,dan supaya dirampas harta milik mereka.', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 14, 'Salinan surat itu harus diundangkan di dalam tiap-tiap daerah, lalu diumumkan kepada segala bangsa, supaya mereka bersiap-siap untuk hari itu.', 'id', 'TB'),
  ('17', 'est', 'Ester', 3, 15, 'Maka dengan tergesa-gesa berangkatlah pesuruh-pesuruh cepat itu, atas titah raja, dan undang-undang itu dikeluarkan di dalam benteng Susan. Sementara itu raja serta Haman duduk minum-minum, tetapi kota Susan menjadi gempar.', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 1, 'Setelah Mordekhai mengetahui segala yang terjadi itu, ia mengoyakkan pakaiannya, lalu memakai kain kabung dan abu, kemudian keluar berjalan di tengah-tengah kota, sambil melolong-lolong dengan nyaring dan pedih.', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 2, 'Dengan demikian datanglah ia sampai ke depan pintu gerbang istana raja, karena seorangpun tidak boleh masuk pintu gerbang istana raja dengan berpakaian kain kabung.', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 3, 'Di tiap-tiap daerah, ke mana titah dan undang-undang raja telah sampai, ada perkabungan yang besar di antara orang Yahudi disertai puasa dan ratap tangis; oleh banyak orang dibentangkan kain kabung dengan abu sebagai lapik tidurnya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 4, 'Ketika dayang-dayang dan sida-sida Ester memberitahukan hal itu kepadanya, maka sangatlah risau hati sang ratu, lalu dikirimkannyalah pakaian, supaya dipakaikan kepada Mordekhai dan supaya ditanggalkan kain kabungnya dari padanya, tetapi tidak diterimanya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 5, 'Maka Ester memanggil Hatah, salah seorang sida-sida raja yang ditetapkan baginda melayani dia, lalu memberi perintah kepadanya menanyakan Mordekhai untuk mengetahui apa artinya dan apa sebabnya hal itu.', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 6, 'Lalu keluarlah Hatah mendapatkan Mordekhai di lapangan kota yang di depan pintu gerbang istana raja,', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 7, 'dan Mordekhai menceritakan kepadanya segala yang dialaminya, serta berapa banyaknya perak yang dijanjikan oleh Haman akan ditimbang untuk perbendaharaan raja sebagai harga pembinasaan orang Yahudi.', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 8, 'Juga salinan surat undang-undang, yang dikeluarkan di Susan untuk memunahkan mereka itu, diserahkannya kepada Hatah, supaya diperlihatkan dan diberitahukan kepada Ester. Lagipula Hatah disuruh menyampaikan pesan kepada Ester, supaya pergi menghadap raja untuk memohon karunianya dan untuk membela bangsanya di hadapan baginda.', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 9, 'Lalu masuklah Hatah dan menyampaikan perkataan Mordekhai kepada Ester.', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 10, 'Akan tetapi Ester menyuruh Hatah memberitahukan kepada Mordekhai:', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 11, '"Semua pegawai raja serta penduduk daerah-daerah kerajaan mengetahui bahwa bagi setiap laki-laki atau perempuan, yang menghadap raja di pelataran dalam dengan tiada dipanggil, hanya berlaku satu undang-undang, yakni hukuman mati. Hanya orang yang kepadanya raja mengulurkan tongkat emas, yang akan tetap hidup. Dan aku selama tiga puluh hari ini tidak dipanggil menghadap raja."', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 12, 'Ketika disampaikan orang perkataan Ester itu kepada Mordekhai,', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 13, 'maka Mordekhai menyuruh menyampaikan jawab ini kepada Ester: "Jangan kira, karena engkau di dalam istana raja, hanya engkau yang akan terluput dari antara semua orang Yahudi.', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 14, 'Sebab sekalipun engkau pada saat ini berdiam diri saja, bagi orang Yahudi akan timbul juga pertolongan dan kelepasan dari pihak lain, dan engkau dengan kaum keluargamu akan binasa. Siapa tahu, mungkin justru untuk saat yang seperti ini engkau beroleh kedudukan sebagai ratu."', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 15, 'Maka Ester menyuruh menyampaikan jawab ini kepada Mordekhai:', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 16, '"Pergilah, kumpulkanlah semua orang Yahudi yang terdapat di Susan dan berpuasalah untuk aku; janganlah makan dan janganlah minum tiga hari lamanya, baik waktu malam, baik waktu siang. Aku serta dayang-dayangkupun akan berpuasa demikian, dan kemudian aku akan masuk menghadap raja, sungguhpun berlawanan dengan undang-undang; kalau terpaksa aku mati, biarlah aku mati."', 'id', 'TB'),
  ('17', 'est', 'Ester', 4, 17, 'Maka pergilah Mordekhai dan diperbuatnyalah tepat seperti yang dipesankan Ester kepadanya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 1, 'Pada hari yang ketiga Ester mengenakan pakaian ratu, lalu berdirilah ia di pelataran dalam istana raja, tepat di depan istana raja. Raja bersemayam di atas takhta kerajaan di dalam istana, berhadapan dengan pintu istana itu.', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 2, 'Ketika raja melihat Ester, sang ratu, berdiri di pelataran, berkenanlah raja kepadanya, sehingga raja mengulurkan tongkat emas yang di tangannya ke arah Ester, lalu mendekatlah Ester dan menyentuh ujung tongkat itu.', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 3, 'Tanya raja kepadanya: "Apa maksudmu, hai ratu Ester, dan apa keinginanmu? Sampai setengah kerajaan sekalipun akan diberikan kepadamu."', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 4, 'Jawab Ester: "Jikalau baik pada pemandangan raja, datanglah kiranya raja dengan Haman pada hari ini ke perjamuan yang diadakan oleh hamba bagi raja."', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 5, 'Maka titah raja: "Suruhlah Haman datang dengan segera, supaya kami memenuhi permintaan Ester." Lalu raja datang dengan Haman ke perjamuan yang diadakan oleh Ester.', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 6, 'Sementara minum anggur bertanyalah raja kepada Ester: "Apakah permintaanmu? Niscaya akan dikabulkan. Dan apakah keinginanmu? Sampai setengah kerajaan sekalipun akan dipenuhi."', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 7, 'Maka jawab Ester: "Permintaan dan keinginan hamba ialah:', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 8, 'Jikalau hamba mendapat kasih raja, dan jikalau baik pada pemandangan raja mengabulkan permintaan serta memenuhi keinginan hamba, datang pulalah kiranya raja dengan Haman ke perjamuan yang akan hamba adakan bagi raja dan Haman; maka besok akan hamba lakukan yang dikehendaki raja."', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 9, 'Pada hari itu keluarlah Haman dengan hati riang dan gembira; tetapi ketika Haman melihat Mordekhai ada di pintu gerbang istana raja, tidak bangkit dan tidak bergerak menghormati dia, maka sangat panaslah hati Haman kepada Mordekhai.', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 10, 'Tetapi Haman menahan hatinya, lalu pulanglah ia ke rumahnya dan menyuruh datang sahabat-sahabatnya dan Zeresh, isterinya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 11, 'Maka Haman menceriterakan kepada mereka itu besarnya kekayaannya, banyaknya anaknya laki-laki, dan segala kebesaran yang diberikan raja kepadanya serta kenaikan pangkatnya di atas para pembesar dan pegawai raja.', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 12, 'Lagi kata Haman: "Tambahan pula tiada seorangpun diminta oleh Ester, sang ratu, untuk datang bersama-sama dengan raja ke perjamuan yang diadakannya, kecuali aku; dan untuk besokpun aku diundangnya bersama-sama dengan raja.', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 13, 'Akan tetapi semuanya itu tidak berguna bagiku, selama aku masih melihat si Mordekhai, si Yahudi itu, duduk di pintu gerbang istana raja."', 'id', 'TB'),
  ('17', 'est', 'Ester', 5, 14, 'Lalu kata Zeresh, isterinya, dan semua sahabatnya kepadanya: "Suruhlah orang membuat tiang yang tingginya lima puluh hasta, dan persembahkanlah besok pagi kepada raja, supaya Mordekhai disulakan orang pada tiang itu; kemudian dapatlah engkau dengan bersukacita pergi bersama-sama dengan raja ke perjamuan itu." Hal itu dipandang baik oleh Haman, lalu ia menyuruh membuat tiang itu.', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 1, 'Pada malam itu juga raja tidak dapat tidur. Maka bertitahlah baginda membawa kitab pencatatan sejarah, lalu dibacakan di hadapan raja.', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 2, 'Dan di situ didapati suatu catatan tentang Mordekhai, yang pernah memberitahukan bahwa Bigtan dan Teresh, dua orang sida-sida raja yang termasuk golongan penjaga pintu, telah berikhtiar membunuh raja Ahasyweros.', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 3, 'Maka bertanyalah raja: "Kehormatan dan kebesaran apakah yang dianugerahkan kepada Mordekhai oleh sebab perkara itu?" Jawab para biduanda raja yang bertugas pada baginda: "Kepadanya tidak dianugerahkan suatu apapun."', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 4, 'Maka bertanyalah raja: "Siapakah itu yang ada di pelataran?" Pada waktu itu Haman baru datang di pelataran luar istana raja untuk memberitahukan kepada baginda, bahwa ia hendak menyulakan Mordekhai pada tiang yang sudah didirikannya untuk dia.', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 5, 'Lalu jawab para biduanda raja kepada baginda: "Itulah Haman, ia berdiri di pelataran." Maka titah raja: "Suruhlah dia masuk."', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 6, 'Setelah Haman masuk, bertanyalah raja kepadanya: "Apakah yang harus dilakukan kepada orang yang raja berkenan menghormatinya?" Kata Haman dalam hatinya: "Kepada siapa lagi raja berkenan menganugerahkan kehormatan lebih dari kepadaku?"', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 7, 'Oleh karena itu jawab Haman kepada raja: "Mengenai orang yang raja berkenan menghormatinya,', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 8, 'hendaklah diambil pakaian kerajaan yang biasa dipakai oleh raja sendiri, dan lagi kuda yang biasa dikendarai oleh raja sendiri dan yang diberi mahkota kerajaan di kepalanya,', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 9, 'dan hendaklah diserahkan pakaian dan kuda itu ke tangan seorang dari antara para pembesar raja, orang-orang bangsawan, lalu hendaklah pakaian itu dikenakan kepada orang yang raja berkenan menghormatinya, kemudian hendaklah ia diarak dengan mengendarai kuda itu melalui lapangan kota sedang orang berseru-seru di depannya: Beginilah dilakukan kepada orang yang raja berkenan menghormatinya!"', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 10, 'Maka titah raja kepada Haman: "Segera ambillah pakaian dan kuda itu, seperti yang kaukatakan itu, dan lakukanlah demikian kepada Mordekhai, orang Yahudi, yang duduk di pintu gerbang istana. Sepatah katapun janganlah kaulalaikan dari pada segala yang kaukatakan itu."', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 11, 'Lalu Haman mengambil pakaian dan kuda itu, dan dikenakannya pakaian itu kepada Mordekhai, kemudian diaraknya Mordekhai melalui lapangan kota itu, sedang ia menyerukan di depannya: "Beginilah dilakukan kepada orang yang raja berkenan menghormatinya."', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 12, 'Kemudian kembalilah Mordekhai ke pintu gerbang istana raja, tetapi Haman bergesa-gesa pulang ke rumahnya dengan sedih hatinya dan berselubung kepalanya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 13, 'Dan Haman menceritakan kepada Zeresh, isterinya, dan kepada semua sahabatnya apa yang dialaminya. Maka kata para orang arif bijaksana dan Zeresh, isterinya, kepadanya: "Jikalau Mordekhai, yang di depannya engkau sudah mulai jatuh, adalah keturunan Yahudi, maka engkau tidak akan sanggup melawan dia, malahan engkau akan jatuh benar-benar di depannya."', 'id', 'TB'),
  ('17', 'est', 'Ester', 6, 14, 'Selagi mereka itu bercakap-cakap dengan dia, datanglah sida-sida raja, lalu mengantarkan Haman dengan segera ke perjamuan yang diadakan oleh Ester.', 'id', 'TB'),
  ('17', 'est', 'Ester', 7, 1, 'Datanglah raja dengan Haman untuk dijamu oleh Ester, sang ratu.', 'id', 'TB'),
  ('17', 'est', 'Ester', 7, 2, 'Pada hari yang kedua itu, sementara minum anggur, bertanyalah pula raja kepada Ester: "Apakah permintaanmu, hai ratu Ester? Niscaya akan dikabulkan. Dan apakah keinginanmu? Sampai setengah kerajaan sekalipun akan dipenuhi."', 'id', 'TB'),
  ('17', 'est', 'Ester', 7, 3, 'Maka jawab Ester, sang ratu: "Ya raja, jikalau hamba mendapat kasih raja dan jikalau baik pada pemandangan raja, karuniakanlah kiranya kepada hamba nyawa hamba atas permintaan hamba, dan bangsa hamba atas keinginan hamba.', 'id', 'TB'),
  ('17', 'est', 'Ester', 7, 4, 'Karena kami, hamba serta bangsa hamba, telah terjual untuk dipunahkan, dibunuh dan dibinasakan. Jikalau seandainya kami hanya dijual sebagai budak laki-laki dan perempuan, niscaya hamba akan berdiam diri, tetapi malapetaka ini tiada taranya di antara bencana yang menimpa raja."', 'id', 'TB'),
  ('17', 'est', 'Ester', 7, 5, 'Maka bertanyalah raja Ahasyweros kepada Ester, sang ratu: "Siapakah orang itu dan di manakah dia yang hatinya mengandung niat akan berbuat demikian?"', 'id', 'TB'),
  ('17', 'est', 'Ester', 7, 6, 'Lalu jawab Ester: "Penganiaya dan musuh itu, ialah Haman, orang jahat ini!" Maka Hamanpun sangatlah ketakutan di hadapan raja dan ratu.', 'id', 'TB'),
  ('17', 'est', 'Ester', 7, 7, 'Lalu bangkitlah raja dengan panas hatinya dari pada minum anggur dan keluar ke taman istana; akan tetapi Haman masih tinggal untuk memohon nyawanya kepada Ester, sang ratu, karena ia melihat, bahwa telah putus niat raja untuk mendatangkan celaka kepadanya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 7, 8, 'Ketika raja kembali dari taman istana ke dalam ruangan minum anggur, maka Haman berlutut pada katil tempat Ester berbaring. Maka titah raja: "Masih jugakah ia hendak menggagahi sang ratu di dalam istanaku sendiri?" Tatkala titah raja itu keluar dari mulutnya, maka diselubungi oranglah muka Haman.', 'id', 'TB'),
  ('17', 'est', 'Ester', 7, 9, 'Sembah Harbona, salah seorang sida-sida yang di hadapan raja: "Lagipula tiang yang dibuat Haman untuk Mordekhai, orang yang menyelamatkan raja dengan pemberitahuannya itu, telah berdiri di dekat rumah Haman, lima puluh hasta tingginya." Lalu titah raja: "Sulakan dia pada tiang itu."', 'id', 'TB'),
  ('17', 'est', 'Ester', 7, 10, 'Kemudian Haman disulakan pada tiang yang didirikannya untuk Mordekhai. Maka surutlah panas hati raja.', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 1, 'Pada hari itu juga raja Ahasyweros mengaruniakan harta milik Haman, seteru orang Yahudi, kepada Ester, sang ratu, dan Mordekhai masuk menghadap raja, karena Ester telah memberitahukan apa pertalian Mordekhai dengan dia.', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 2, 'Maka raja mencabut cincin meterai yang diambil dari pada Haman, lalu diserahkannya kepada Mordekhai; dan Mordekhai diangkat oleh Ester menjadi kuasa atas harta milik Haman.', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 3, 'Kemudian Ester berkata lagi kepada raja sambil sujud pada kakinya dan menangis memohon karunianya, supaya dibatalkannya maksud jahat Haman, orang Agag itu, serta rancangan yang sudah dibuatnya terhadap orang Yahudi.', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 4, 'Maka raja mengulurkan tongkat emas kepada Ester, lalu bangkitlah Ester dan berdiri di hadapan raja,', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 5, 'serta sembahnya: "Jikalau baik pada pemandangan raja dan jikalau hamba mendapat kasih raja, dan hal ini kiranya dipandang benar oleh raja dan raja berkenan kepada hamba, maka hendaklah dikeluarkan surat titah untuk menarik kembali surat-surat yang berisi rancangan Haman bin Hamedata, orang Agag itu, yang ditulisnya untuk membinasakan orang Yahudi di dalam semua daerah kerajaan.', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 6, 'Karena bagaimana hamba dapat melihat malapetaka yang menimpa bangsa hamba dan bagaimana hamba dapat melihat kebinasaan sanak saudara hamba?"', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 7, 'Maka jawab raja Ahasyweros kepada Ester, sang ratu, serta kepada Mordekhai, orang Yahudi itu: "Harta milik Haman telah kukaruniakan kepada Ester, dan Haman sendiri telah disulakan pada tiang karena ia sudah mengacungkan tangannya kepada orang Yahudi.', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 8, 'Tuliskanlah atas nama raja apa yang kamu pandang baik tentang orang Yahudi dan meteraikanlah surat itu dengan cincin meterai raja, karena surat yang dituliskan atas nama raja dan dimeteraikan dengan cincin meterai raja tidak dapat ditarik kembali."', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 9, 'Pada waktu itu juga dipanggillah para panitera raja, dalam bulan yang ketiga?yakni bulan Siwan?pada tanggal dua puluh tiga, dan sesuai dengan segala yang diperintahkan Mordekhai ditulislah surat kepada orang Yahudi, dan kepada para wakil pemerintah, para bupati dan para pembesar daerah, dari India sampai ke Etiopia, seratus dua puluh tujuh daerah, kepada tiap-tiap daerah menurut tulisannya dan kepada tiap-tiap bangsa menurut bahasanya, dan juga kepada orang Yahudi menurut tulisan dan bahasanya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 10, 'Maka ditulislah pesan atas nama raja Ahasyweros dan dimeterai dengan cincin meterai raja, lalu dengan perantaraan pesuruh-pesuruh cepat yang berkuda, yang mengendarai kuda kerajaan yang tangkas yang diternakkan di pekudaan, dikirimkanlah surat-surat', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 11, 'yang isinya: raja mengizinkan orang Yahudi di tiap-tiap kota untuk berkumpul dan mempertahankan nyawanya serta memunahkan, membunuh atau membinasakan segala tentara, bahkan anak-anak dan perempuan-perempuan, dari bangsa dan daerah yang hendak menyerang mereka, dan untuk merampas harta miliknya,', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 12, 'pada hari yang sama di segala daerah raja Ahasyweros, pada tanggal tiga belas bulan yang kedua belas, yakni bulan Adar.', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 13, 'Salinan pesan tertulis itu harus diundangkan di tiap-tiap daerah, lalu diumumkan kepada segala bangsa, dan orang Yahudi harus bersiap-siap untuk hari itu akan melakukan pembalasan kepada musuhnya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 14, 'Maka dengan terburu-buru dan tergesa-gesa berangkatlah pesuruh-pesuruh cepat yang mengendarai kuda kerajaan yang tangkas itu, atas titah raja, dan undang-undang itu dikeluarkan di dalam benteng Susan.', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 15, 'Dan Mordekhai keluar dari hadapan raja dengan memakai pakaian kerajaan dari pada kain ungu tua dan kain lenan, dengan memakai tajuk emas yang mengagumkan serta jubah dari pada kain lenan halus dan kain ungu muda. Maka kota Susanpun bertempiksoraklah dan bersukaria:', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 16, 'orang Yahudi telah beroleh kelapangan hati dan sukacita, kegirangan dan kehormatan.', 'id', 'TB'),
  ('17', 'est', 'Ester', 8, 17, 'Demikian juga di tiap-tiap daerah dan di tiap-tiap kota, di tempat manapun titah dan undang-undang raja telah sampai, ada sukacita dan kegirangan di antara orang Yahudi, dan perjamuan serta hari gembira; dan lagi banyak dari antara rakyat negeri itu masuk Yahudi, karena mereka ditimpa ketakutan kepada orang Yahudi.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 1, 'Dalam bulan yang kedua belas?yakni bulan Adar?,pada hari yang ketiga belas, ketika titah serta undang-undang raja akan dilaksanakan, pada hari musuh-musuh orang Yahudi berharap mengalahkan orang Yahudi, terjadilah yang sebaliknya: orang Yahudi mengalahkan pembenci-pembenci mereka.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 2, 'Maka berkumpullah orang Yahudi di dalam kota-kotanya di seluruh daerah raja Ahasyweros, untuk membunuh orang-orang yang berikhtiar mencelakakan mereka, dan tiada seorangpun tahan menghadapi mereka, karena ketakutan kepada orang Yahudi telah menimpa segala bangsa itu.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 3, 'Dan semua pembesar daerah dan wakil pemerintahan dan bupati serta pejabat kerajaan menyokong orang Yahudi, karena ketakutan kepada Mordekhai telah menimpa mereka.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 4, 'Sebab Mordekhai besar kekuasaannya di dalam istana raja dan tersiarlah berita tentang dia ke segenap daerah, karena Mordekhai itu bertambah-tambah besar kekuasaannya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 5, 'Maka orang Yahudi mengalahkan semua musuhnya: mereka memukulnya dengan pedang, membunuh dan membinasakannya; mereka berbuat sekehendak hatinya terhadap pembenci-pembenci mereka.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 6, 'Di dalam benteng Susan saja orang Yahudi membunuh dan membinasakan lima ratus orang.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 7, 'Juga Parsandata, Dalfon, Aspata,', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 8, 'Porata, Adalya, Aridata,', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 9, 'Parmasta, Arisai, Aridai dan Waizata,', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 10, 'kesepuluh anak laki-laki Haman bin Hamedata, seteru orang Yahudi, dibunuh oleh mereka, tetapi kepada barang rampasan tidaklah mereka mengulurkan tangan.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 11, 'Pada hari itu juga jumlah orang-orang yang terbunuh di dalam benteng Susan disampaikan ke hadapan raja.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 12, 'Lalu titah raja kepada Ester, sang ratu: "Di dalam benteng Susan saja orang Yahudi telah membunuh dan membinasakan lima ratus orang beserta kesepuluh anak Haman. Di daerah-daerah kerajaan yang lain, entahlah apa yang diperbuat mereka. Dan apakah permintaanmu sekarang? Niscaya akan dikabulkan. Dan apakah keinginanmu lagi? Niscaya dipenuhi."', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 13, 'Lalu jawab Ester: "Jikalau baik pada pemandangan raja, diizinkanlah kiranya kepada orang Yahudi yang di Susan untuk berbuat besokpun sesuai dengan undang-undang untuk hari ini, dan kesepuluh anak Haman itu hendaklah disulakan pada tiang."', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 14, 'Rajapun menitahkan berbuat demikian; maka undang-undang itu dikeluarkan di Susan dan kesepuluh anak Haman disulakan orang.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 15, 'Jadi berkumpullah orang Yahudi yang di Susan pada hari yang keempat belas bulan Adar juga dan dibunuhnyalah di Susan tiga ratus orang, tetapi kepada barang rampasan tidaklah mereka mengulurkan tangan.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 16, 'Orang Yahudi yang lain, yang ada di dalam daerah kerajaan, berkumpul dan mempertahankan nyawanya serta mendapat keamanan terhadap musuhnya; mereka membunuh tujuh puluh lima ribu orang di antara pembenci-pembenci mereka, tetapi kepada barang rampasan tidaklah mereka mengulurkan tangan.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 17, 'Hal itu terjadi pada hari yang ketiga belas dalam bulan Adar. Pada hari yang keempat belas berhentilah mereka dan hari itu dijadikan mereka hari perjamuan dan sukacita.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 18, 'Akan tetapi orang Yahudi yang di Susan berkumpul, baik pada hari yang ketiga belas, baik pada hari yang keempat belas dalam bulan itu. Lalu berhentilah mereka pada hari yang kelima belas dan hari itu dijadikan mereka hari perjamuan dan sukacita.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 19, 'Oleh sebab itu orang Yahudi yang di pedusunan, yakni yang diam di perkampungan merayakan hari yang keempat belas bulan Adar itu sebagai hari sukacita dan hari perjamuan, dan sebagai hari gembira untuk antar-mengantar makanan.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 20, 'Maka Mordekhai menuliskan peristiwa itu, lalu mengirimkan surat-surat kepada semua orang Yahudi di seluruh daerah raja Ahasyweros, baik yang dekat baik yang jauh,', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 21, 'untuk mewajibkan mereka, supaya tiap-tiap tahun merayakan hari yang keempat belas dan yang kelima belas bulan Adar,', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 22, 'karena pada hari-hari itulah orang Yahudi mendapat keamanan terhadap musuhnya dan dalam bulan itulah dukacita mereka berubah menjadi sukacita dan hari perkabungan menjadi hari gembira, dan supaya menjadikan hari-hari itu hari perjamuan dan sukacita dan hari untuk antar-mengantar makanan dan untuk bersedekah kepada orang-orang miskin.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 23, 'Maka orang Yahudi menerima sebagai ketetapan apa yang sudah dimulai mereka melakukannya dan apa yang ditulis Mordekhai kepada mereka.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 24, 'Sesungguhnya Haman bin Hamedata, orang Agag, seteru semua orang Yahudi itu, telah merancangkan hendak membinasakan orang Yahudi dan diapun telah membuang pur?yakni undi?untuk menghancurkan dan membinasakan mereka,', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 25, 'akan tetapi ketika hal itu disampaikan ke hadapan raja, maka dititahkannyalah dengan surat, supaya rancangan jahat yang dibuat Haman terhadap orang Yahudi itu dibalikkan ke atas kepalanya. Maka Haman beserta anak-anaknya disulakan pada tiang.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 26, 'Oleh sebab itulah hari-hari itu disebut Purim, menurut kata pur. Oleh sebab itu jugalah, yakni karena seluruh isi surat itu dan karena apa yang dilihat mereka mengenai hal itu dan apa yang dialami mereka,', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 27, 'orang Yahudi menerima sebagai kewajiban dan sebagai ketetapan bagi dirinya sendiri dan keturunannya dan bagi sekalian orang yang akan bergabung dengan mereka, bahwa mereka tidak akan melampaui merayakan kedua hari itu tiap-tiap tahun, menurut yang dituliskan tentang itu dan pada waktu yang ditentukan,', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 28, 'dan bahwa hari-hari itu akan diperingati dan dirayakan di dalam tiap-tiap angkatan, di dalam tiap-tiap kaum, di tiap-tiap daerah, di tiap-tiap kota, sehingga hari-hari Purim itu tidak akan lenyap dari tengah-tengah orang Yahudi dan peringatannya tidak akan berakhir dari antara keturunan mereka.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 29, 'Lalu Ester, sang ratu, anak Abihail, menulis surat, bersama-sama dengan Mordekhai, orang Yahudi itu; surat yang kedua tentang hari raya Purim ini dituliskannya dengan segala ketegasan untuk menguatkannya.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 30, 'Lalu dikirimkanlah surat-surat kepada semua orang Yahudi di dalam keseratus dua puluh tujuh daerah kerajaan Ahasyweros, dengan kata-kata salam dan setia,', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 31, 'supaya hari-hari Purim itu dirayakan pada waktu yang ditentukan, seperti yang diwajibkan kepada mereka oleh Mordekhai, orang Yahudi itu, dan oleh Ester, sang ratu, dan seperti yang diwajibkan mereka kepada dirinya sendiri serta keturunan mereka, mengenai hal berpuasa dan meratap-ratap.', 'id', 'TB'),
  ('17', 'est', 'Ester', 9, 32, 'Demikianlah perintah Ester menetapkan perihal Purim itu, kemudian dituliskan di dalam kitab.', 'id', 'TB'),
  ('17', 'est', 'Ester', 10, 1, 'Maka raja Ahasyweros mengenakan upeti atas negeri dan daerah-daerah pesisir juga.', 'id', 'TB'),
  ('17', 'est', 'Ester', 10, 2, 'Segala perbuatannya yang hebat serta gagah dan pemberitaan yang seksama tentang kebesaran yang dikaruniakan raja kepada Mordekhai, bukankah semuanya itu tertulis di dalam kitab sejarah raja-raja Media dan Persia?', 'id', 'TB'),
  ('17', 'est', 'Ester', 10, 3, 'Karena Mordekhai, orang Yahudi itu, menjadi orang kedua di bawah raja Ahasyweros, dan ia dihormati oleh orang Yahudi serta disukai oleh banyak sanak saudaranya, sebab ia mengikhtiarkan yang baik bagi bangsanya dan berbicara untuk keselamatan bagi semua orang sebangsanya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 1, 'Ada seorang laki-laki di tanah Us bernama Ayub; orang itu saleh dan jujur; ia takut akan Allah dan menjauhi kejahatan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 2, 'Ia mendapat tujuh anak laki-laki dan tiga anak perempuan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 3, 'Ia memiliki tujuh ribu ekor kambing domba, tiga ribu ekor unta, lima ratus pasang lembu, lima ratus keledai betina dan budak-budak dalam jumlah yang sangat besar, sehingga orang itu adalah yang terkaya dari semua orang di sebelah timur.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 4, 'Anak-anaknya yang lelaki biasa mengadakan pesta di rumah mereka masing-masing menurut giliran dan ketiga saudara perempuan mereka diundang untuk makan dan minum bersama-sama mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 5, 'Setiap kali, apabila hari-hari pesta telah berlalu, Ayub memanggil mereka, dan menguduskan mereka; keesokan harinya, pagi-pagi, bangunlah Ayub, lalu mempersembahkan korban bakaran sebanyak jumlah mereka sekalian, sebab pikirnya: "Mungkin anak-anakku sudah berbuat dosa dan telah mengutuki Allah di dalam hati." Demikianlah dilakukan Ayub senantiasa.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 6, 'Pada suatu hari datanglah anak-anak Allah menghadap TUHAN dan di antara mereka datanglah juga Iblis.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 7, 'Maka bertanyalah TUHAN kepada Iblis: "Dari mana engkau?" Lalu jawab Iblis kepada TUHAN: "Dari perjalanan mengelilingi dan menjelajah bumi."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 8, 'Lalu bertanyalah TUHAN kepada Iblis: "Apakah engkau memperhatikan hamba-Ku Ayub? Sebab tiada seorangpun di bumi seperti dia, yang demikian saleh dan jujur, yang takut akan Allah dan menjauhi kejahatan."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 9, 'Lalu jawab Iblis kepada TUHAN: "Apakah dengan tidak mendapat apa-apa Ayub takut akan Allah?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 10, 'Bukankah Engkau yang membuat pagar sekeliling dia dan rumahnya serta segala yang dimilikinya? Apa yang dikerjakannya telah Kauberkati dan apa yang dimilikinya makin bertambah di negeri itu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 11, 'Tetapi ulurkanlah tangan-Mu dan jamahlah segala yang dipunyainya, ia pasti mengutuki Engkau di hadapan-Mu."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 12, 'Maka firman TUHAN kepada Iblis: "Nah, segala yang dipunyainya ada dalam kuasamu; hanya janganlah engkau mengulurkan tanganmu terhadap dirinya." Kemudian pergilah Iblis dari hadapan TUHAN.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 13, 'Pada suatu hari, ketika anak-anaknya yang lelaki dan yang perempuan makan-makan dan minum anggur di rumah saudara mereka yang sulung,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 14, 'datanglah seorang pesuruh kepada Ayub dan berkata: "Sedang lembu sapi membajak dan keledai-keledai betina makan rumput di sebelahnya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 15, 'datanglah orang-orang Syeba menyerang dan merampasnya serta memukul penjaganya dengan mata pedang. Hanya aku sendiri yang luput, sehingga dapat memberitahukan hal itu kepada tuan."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 16, 'Sementara orang itu berbicara, datanglah orang lain dan berkata: "Api telah menyambar dari langit dan membakar serta memakan habis kambing domba dan penjaga-penjaga. Hanya aku sendiri yang luput, sehingga dapat memberitahukan hal itu kepada tuan."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 17, 'Sementara orang itu berbicara, datanglah orang lain dan berkata: "Orang-orang Kasdim membentuk tiga pasukan, lalu menyerbu unta-unta dan merampasnya serta memukul penjaganya dengan mata pedang. Hanya aku sendiri yang luput, sehingga dapat memberitahukan hal itu kepada tuan."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 18, 'Sementara orang itu berbicara, datanglah orang lain dan berkata: "Anak-anak tuan yang lelaki dan yang perempuan sedang makan-makan dan minum anggur di rumah saudara mereka yang sulung,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 19, 'maka tiba-tiba angin ribut bertiup dari seberang padang gurun; rumah itu dilandanya pada empat penjurunya dan roboh menimpa orang-orang muda itu, sehingga mereka mati. Hanya aku sendiri yang luput, sehingga dapat memberitahukan hal itu kepada tuan."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 20, 'Maka berdirilah Ayub, lalu mengoyak jubahnya, dan mencukur kepalanya, kemudian sujudlah ia dan menyembah,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 21, 'katanya: "Dengan telanjang aku keluar dari kandungan ibuku, dengan telanjang juga aku akan kembali ke dalamnya. TUHAN yang memberi, TUHAN yang mengambil, terpujilah nama TUHAN!"', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 1, 22, 'Dalam kesemuanya itu Ayub tidak berbuat dosa dan tidak menuduh Allah berbuat yang kurang patut.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 2, 1, 'Pada suatu hari datanglah anak-anak Allah menghadap TUHAN dan di antara mereka datang juga Iblis untuk menghadap TUHAN.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 2, 2, 'Maka bertanyalah TUHAN kepada Iblis: "Dari mana engkau?" Lalu jawab Iblis kepada TUHAN: "Dari perjalanan mengelilingi dan menjelajah bumi."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 2, 3, 'Firman TUHAN kepada Iblis: "Apakah engkau memperhatikan hamba-Ku Ayub? Sebab tiada seorangpun di bumi seperti dia, yang demikian saleh dan jujur, yang takut akan Allah dan menjauhi kejahatan. Ia tetap tekun dalam kesalehannya, meskipun engkau telah membujuk Aku melawan dia untuk mencelakakannya tanpa alasan."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 2, 4, 'Lalu jawab Iblis kepada TUHAN: "Kulit ganti kulit! Orang akan memberikan segala yang dipunyainya ganti nyawanya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 2, 5, 'Tetapi ulurkanlah tangan-Mu dan jamahlah tulang dan dagingnya, ia pasti mengutuki Engkau di hadapan-Mu."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 2, 6, 'Maka firman TUHAN kepada Iblis: "Nah, ia dalam kuasamu; hanya sayangkan nyawanya."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 2, 7, 'Kemudian Iblis pergi dari hadapan TUHAN, lalu ditimpanya Ayub dengan barah yang busuk dari telapak kakinya sampai ke batu kepalanya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 2, 8, 'Lalu Ayub mengambil sekeping beling untuk menggaruk-garuk badannya, sambil duduk di tengah-tengah abu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 2, 9, 'Maka berkatalah isterinya kepadanya: "Masih bertekunkah engkau dalam kesalehanmu? Kutukilah Allahmu dan matilah!"', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 2, 10, 'Tetapi jawab Ayub kepadanya: "Engkau berbicara seperti perempuan gila! Apakah kita mau menerima yang baik dari Allah, tetapi tidak mau menerima yang buruk?" Dalam kesemuanya itu Ayub tidak berbuat dosa dengan bibirnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 2, 11, 'Ketika ketiga sahabat Ayub mendengar kabar tentang segala malapetaka yang menimpa dia, maka datanglah mereka dari tempatnya masing-masing, yakni: Elifas, orang Teman, dan Bildad, orang Suah, serta Zofar, orang Naama. Mereka bersepakat untuk mengucapkan belasungkawa kepadanya dan menghibur dia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 2, 12, 'Ketika mereka memandang dari jauh, mereka tidak mengenalnya lagi. Lalu menangislah mereka dengan suara nyaring. Mereka mengoyak jubahnya, dan menaburkan debu di kepala terhadap langit.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 2, 13, 'Lalu mereka duduk bersama-sama dia di tanah selama tujuh hari tujuh malam. Seorangpun tidak mengucapkan sepatah kata kepadanya, karena mereka melihat, bahwa sangat berat penderitaannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 1, 'Sesudah itu Ayub membuka mulutnya dan mengutuki hari kelahirannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 2, 'Maka berbicaralah Ayub:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 3, '"Biarlah hilang lenyap hari kelahiranku dan malam yang mengatakan: Seorang anak laki-laki telah ada dalam kandungan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 4, 'Biarlah hari itu menjadi kegelapan, janganlah kiranya Allah yang di atas menghiraukannya, dan janganlah cahaya terang menyinarinya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 5, 'Biarlah kegelapan dan kekelaman menuntut hari itu, awan-gemawan menudunginya, dan gerhana matahari mengejutkannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 6, 'Malam itu?biarlah dia dicekam oleh kegelapan; janganlah ia bersukaria pada hari-hari dalam setahun; janganlah ia termasuk bilangan bulan-bulan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 7, 'Ya, biarlah pada malam itu tidak ada yang melahirkan, dan tidak terdengar suara kegirangan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 8, 'Biarlah ia disumpahi oleh para pengutuk hari, oleh mereka yang pandai membangkitkan marah Lewiatan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 9, 'Biarlah bintang-bintang senja menjadi gelap; biarlah ia menantikan terang yang tak kunjung datang, janganlah ia melihat merekahnya fajar,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 10, 'karena tidak ditutupnya pintu kandungan ibuku, dan tidak disembunyikannya kesusahan dari mataku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 11, 'Mengapa aku tidak mati waktu aku lahir, atau binasa waktu aku keluar dari kandungan?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 12, 'Mengapa pangkuan menerima aku; mengapa ada buah dada, sehingga aku dapat menyusu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 13, 'Jikalau tidak, aku sekarang berbaring dan tenang; aku tertidur dan mendapat istirahat', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 14, 'bersama-sama raja-raja dan penasihat-penasihat di bumi, yang mendirikan kembali reruntuhan bagi dirinya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 15, 'atau bersama-sama pembesar-pembesar yang mempunyai emas, yang memenuhi rumahnya dengan perak.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 16, 'Atau mengapa aku tidak seperti anak gugur yang disembunyikan, seperti bayi yang tidak melihat terang?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 17, 'Di sanalah orang fasik berhenti menimbulkan huru-hara, di sanalah mereka yang kehabisan tenaga mendapat istirahat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 18, 'Dan para tawanan bersama-sama menjadi tenang, mereka tidak lagi mendengar suara pengerah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 19, 'Di sana orang kecil dan orang besar sama, dan budak bebas dari pada tuannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 20, 'Mengapa terang diberikan kepada yang bersusah-susah, dan hidup kepada yang pedih hati;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 21, 'yang menantikan maut, yang tak kunjung tiba, yang mengejarnya lebih dari pada menggali harta terpendam;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 22, 'yang bersukaria dan bersorak-sorai dan senang, bila mereka menemukan kubur;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 23, 'kepada orang laki-laki yang jalannya tersembunyi, yang dikepung Allah?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 24, 'Karena ganti rotiku adalah keluh kesahku, dan keluhanku tercurah seperti air.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 25, 'Karena yang kutakutkan, itulah yang menimpa aku, dan yang kucemaskan, itulah yang mendatangi aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 3, 26, 'Aku tidak mendapat ketenangan dan ketenteraman; aku tidak mendapat istirahat, tetapi kegelisahanlah yang timbul."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 1, 'Maka berbicaralah Elifas, orang Teman:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 2, '"Kesalkah engkau, bila orang mencoba berbicara kepadamu? Tetapi siapakah dapat tetap menutup mulutnya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 3, 'Sesungguhnya, engkau telah mengajar banyak orang, dan tangan yang lemah telah engkau kuatkan;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 4, 'orang yang jatuh telah dibangunkan oleh kata-katamu, dan lutut yang lemas telah kaukokohkan;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 5, 'tetapi sekarang, dirimu yang tertimpa, dan engkau kesal, dirimu terkena, dan engkau terkejut.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 6, 'Bukankah takutmu akan Allah yang menjadi sandaranmu, dan kesalehan hidupmu menjadi pengharapanmu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 7, 'Camkanlah ini: siapa binasa dengan tidak bersalah dan di manakah orang yang jujur dipunahkan?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 8, 'Yang telah kulihat ialah bahwa orang yang membajak kejahatan dan menabur kesusahan, ia menuainya juga.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 9, 'Mereka binasa oleh nafas Allah, dan lenyap oleh hembusan hidung-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 10, 'Singa mengaum, singa meraung?patahlah gigi singa-singa muda.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 11, 'Singa binasa karena kekurangan mangsa, dan anak-anak singa betina bercerai-berai.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 12, 'Suatu perkataan telah disampaikan kepadaku dengan diam-diam dan telingaku menangkap bisikannya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 13, 'waktu bermenung oleh sebab khayal malam, ketika tidur nyenyak menghinggapi orang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 14, 'Aku terkejut dan gentar, sehingga tulang-tulangku gemetar.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 15, 'Suatu roh melewati aku, tegaklah bulu romaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 16, 'Ia berhenti, tetapi rupanya tidak dapat kukenal. Suatu sosok ada di depan mataku, suara berbisik-bisik kudengar:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 17, 'Mungkinkah seorang manusia benar di hadapan Allah, mungkinkah seseorang tahir di hadapan Penciptanya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 18, 'Sesungguhnya, hamba-hamba-Nya tidak dipercayai-Nya, malaikat-malaikat-Nyap didapati-Nya tersesat,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 19, 'lebih-lebih lagi mereka yang diam dalam pondok tanah liat, yang dasarnya dalam debu, yang mati terpijat seperti gegat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 20, 'Di antara pagi dan petang mereka dihancurkan, dan tanpa dihiraukan mereka binasa untuk selama-lamanya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 4, 21, 'Bukankah kemah mereka dicabut? Mereka mati, tetapi tanpa hikmat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 1, 'Berserulah?adakah orang yang menjawab engkau? Dan kepada siapa di antara orang-orang yang kudus engkau akan berpaling?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 2, 'Sesungguhnya, orang bodoh dibunuh oleh sakit hati, dan orang bebal dimatikan oleh iri hati.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 3, 'Aku sendiri pernah melihat orang bodoh berakar, tetapi serta-merta kukutuki tempat kediamannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 4, 'Anak-anaknya selalu tidak tertolong, mereka diinjak-injak di pintu gerbang tanpa ada orang yang melepaskannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 5, 'Apa yang dituainya, dimakan habis oleh orang yang lapar, bahkan dirampas dari tengah-tengah duri, dan orang-orang yang dahaga mengingini kekayaannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 6, 'Karena bukan dari debu terbit bencana dan bukan dari tanah tumbuh kesusahan;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 7, 'melainkan manusia menimbulkan kesusahan bagi dirinya, seperti bunga api berjolak tinggi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 8, 'Tetapi aku, tentu aku akan mencari Allah, dan kepada Allah aku akan mengadukan perkaraku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 9, 'Ia melakukan perbuatan-perbuatan yang besar dan yang tak terduga, serta keajaiban-keajaiban yang tak terbilang banyaknya;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 10, 'Ia memberi hujan ke atas muka bumi dan menjatuhkan air ke atas ladang;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 11, 'Ia menempatkan orang yang hina pada derajat yang tinggi dan orang yang berdukacita mendapat pertolongan yang kuat;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 12, 'Ia menggagalkan rancangan orang cerdik, sehingga usaha tangan mereka tidak berhasil;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 13, 'Ia menangkap orang berhikmat dalam kecerdikannya sendiri, sehingga rancangan orang yang belat-belit digagalkan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 14, 'Pada siang hari mereka tertimpa gelap, dan pada tengah hari mereka meraba-raba seperti pada waktu malam.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 15, 'Tetapi Ia menyelamatkan orang-orang miskin dari kedahsyatan mulut mereka, dan dari tangan orang yang kuat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 16, 'Demikianlah ada harapan bagi orang kecil, dan kecurangan tutup mulut.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 17, 'Sesungguhnya, berbahagialah manusia yang ditegur Allah; sebab itu janganlah engkau menolak didikan Yang Mahakuasa.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 18, 'Karena Dialah yang melukai, tetapi juga yang membebat; Dia yang memukuli, tetapi yang tangan-Nya menyembuhkan pula.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 19, 'Dari enam macam kesesakan engkau diluputkan-Nya dan dalam tujuh macam engkau tidak kena malapetaka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 20, 'Pada masa kelaparan engkau dibebaskan-Nya dari maut, dan pada masa perang dari kuasa pedang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 21, 'Dari cemeti lidah engkau terlindung, dan engkau tidak usah takut, bila kemusnahan datang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 22, 'Kemusnahan dan kelaparan akan kautertawakan dan binatang liar tidak akan kautakuti.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 23, 'Karena antara engkau dan batu-batu di padang akan ada perjanjian, dan binatang liar akan berdamai dengan engkau.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 24, 'Engkau akan mengalami, bahwa kemahmu aman dan apabila engkau memeriksa tempat kediamanmu, engkau tidak akan kehilangan apa-apa.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 25, 'Engkau akan mengalami, bahwa keturunanmu menjadi banyak dan bahwa anak cucumu seperti rumput di tanah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 26, 'Dalam usia tinggi engkau akan turun ke dalam kubur, seperti berkas gandum dibawa masuk pada waktunya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 5, 27, 'Sesungguhnya, semuanya itu telah kami selidiki, memang demikianlah adanya; dengarkanlah dan camkanlah itu!"', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 1, 'Lalu Ayub menjawab:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 2, '"Ah, hendaklah kiranya kekesalan hatiku ditimbang, dan kemalanganku ditaruh bersama-sama di atas neraca!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 3, 'Maka beratnya akan melebihi pasir di laut; oleh sebab itu tergesa-gesalah perkataanku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 4, 'Karena anak panah dari Yang Mahakuasa tertancap pada tubuhku, dan racunnya diisap oleh jiwaku; kedahsyatan Allah seperti pasukan melawan aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 5, 'Meringkikkah keledai liar di tempat rumput muda, atau melenguhkah lembu dekat makanannya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 6, 'Dapatkah makanan tawar dimakan tanpa garam atau apakah putih telur ada rasanya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 7, 'Aku tidak sudi menjamahnya, semuanya itu makanan yang memualkan bagiku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 8, 'Ah, kiranya terkabul permintaanku dan Allah memberi apa yang kuharapkan!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 9, 'Kiranya Allah berkenan meremukkan aku, kiranya Ia melepaskan tangan-Nya dan menghabisi nyawaku!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 10, 'Itulah yang masih merupakan hiburan bagiku, bahkan aku akan melompat-lompat kegirangan di waktu kepedihan yang tak kenal belas kasihan, sebab aku tidak pernah menyangkal firman Yang Mahakudus.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 11, 'Apakah kekuatanku, sehingga aku sanggup bertahan, dan apakah masa depanku, sehingga aku harus bersabar?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 12, 'Apakah kekuatanku seperti kekuatan batu? Apakah tubuhku dari tembaga?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 13, 'Bukankah tidak ada lagi pertolongan bagiku, dan keselamatan jauh dari padaku?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 14, 'Siapa menahan kasih sayang terhadap sesamanya, melalaikan takut akan Yang Mahakuasa.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 15, 'Saudara-saudaraku tidak dapat dipercaya seperti sungai, seperti dasar dari pada sungai yang mengalir lenyap,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 16, 'yang keruh karena air beku, yang di dalamnya salju menjadi cair,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 17, 'yang surut pada musim kemarau, dan menjadi kering di tempatnya apabila kena panas;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 18, 'berkeluk-keluk jalan arusnya, mengalir ke padang tandus, lalu lenyap.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 19, 'Kafilah dari Tema mengamat-amatinya dan rombongan dari Syeba mengharapkannya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 20, 'tetapi mereka kecewa karena keyakinan mereka, mereka tertipu setibanya di sana.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 21, 'Demikianlah kamu sekarang bagiku, ketika melihat yang dahsyat, takutlah kamu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 22, 'Pernahkah aku berkata: Berilah aku sesuatu, atau: Berilah aku uang suap dari hartamu,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 23, 'atau: Luputkan aku dari tangan musuh, atau: Tebuslah aku dari tangan orang lalim?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 24, 'Ajarilah aku, maka aku akan diam; dan tunjukkan kepadaku dalam hal apa aku tersesat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 25, 'Alangkah kokohnya kata-kata yang jujur! Tetapi apakah maksud celaan dari pihakmu itu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 26, 'Apakah kamu bermaksud mencela perkataan? Apakah perkataan orang yang putus asa dianggap angin?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 27, 'Bahkan atas anak yatim kamu membuang undi, dan sahabatmu kamu perlakukan sebagai barang dagangan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 28, 'Tetapi sekarang, berpalinglah kepadaku; aku tidak akan berdusta di hadapanmu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 29, 'Berbaliklah, janganlah terjadi kecurangan, berbaliklah, aku pasti benar.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 6, 30, 'Apakah ada kecurangan pada lidahku? Apakah langit-langitku tidak dapat membeda-bedakan bencana?"', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 1, '"Bukankah manusia harus bergumul di bumi, dan hari-harinya seperti hari-hari orang upahan?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 2, 'Seperti kepada seorang budak yang merindukan naungan, seperti kepada orang upahan yang menanti-nantikan upahnya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 3, 'demikianlah dibagikan kepadaku bulan-bulan yang sia-sia, dan ditentukan kepadaku malam-malam penuh kesusahan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 4, 'Bila aku pergi tidur, maka pikirku: Bilakah aku akan bangun? Tetapi malam merentang panjang, dan aku dicekam oleh gelisah sampai dinihari.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 5, 'Berenga dan abu menutupi tubuhku, kulitku menjadi keras, lalu pecah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 6, 'Hari-hariku berlalu lebih cepat dari pada torak, dan berakhir tanpa harapan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 7, 'Ingatlah, bahwa hidupku hanya hembusan nafas; mataku tidak akan lagi melihat yang baik.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 8, 'Orang yang memandang aku, tidak akan melihat aku lagi, sementara Engkau memandang aku, aku tidak ada lagi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 9, 'Sebagaimana awan lenyap dan melayang hilang, demikian juga orang yang turun ke dalam dunia orang mati tidak akan muncul kembali.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 10, 'Ia tidak lagi kembali ke rumahnya, dan tidak dikenal lagi oleh tempat tinggalnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 11, 'Oleh sebab itu akupun tidak akan menahan mulutku, aku akan berbicara dalam kesesakan jiwaku, mengeluh dalam kepedihan hatiku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 12, 'Apakah aku ini laut atau naga, sehingga Engkau menempatkan penjaga terhadap aku?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 13, 'Apabila aku berpikir: Tempat tidurku akan memberi aku penghiburan, dan tempat pembaringanku akan meringankan keluh kesahku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 14, 'maka Engkau mengagetkan aku dengan impian dan mengejutkan aku dengan khayal,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 15, 'sehingga aku lebih suka dicekik dan mati dari pada menanggung kesusahanku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 16, 'Aku jemu, aku tidak mau hidup untuk selama-lamanya. Biarkanlah aku, karena hari-hariku hanya seperti hembusan nafas saja.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 17, 'Apakah gerangan manusia, sehingga dia Kauanggap agung, dan Kauperhatikan,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 18, 'dan Kaudatangi setiap pagi, dan Kauuji setiap saat?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 19, 'Bilakah Engkau mengalihkan pandangan-Mu dari padaku, dan membiarkan aku, sehingga aku sempat menelan ludahku?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 20, 'Kalau aku berbuat dosa, apakah yang telah kulakukan terhadap Engkau, ya Penjaga manusia? Mengapa Engkau menjadikan aku sasaran-Mu, sehingga aku menjadi beban bagi diriku?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 7, 21, 'Dan mengapa Engkau tidak mengampuni pelanggaranku, dan tidak menghapuskan kesalahanku? Karena sekarang aku terbaring dalam debu, lalu Engkau akan mencari aku, tetapi aku tidak akan ada lagi."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 1, 'Maka berbicaralah Bildad, orang Suah:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 2, '"Berapa lamakah lagi engkau akan berbicara begitu, dan perkataan mulutmu seperti angin yang menderu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 3, 'Masakan Allah membengkokkan keadilan? Masakan Yang Mahakuasa membengkokkan kebenaran?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 4, 'Jikalau anak-anakmu telah berbuat dosa terhadap Dia, maka Ia telah membiarkan mereka dikuasai oleh pelanggaran mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 5, 'Tetapi engkau, kalau engkau mencari Allah, dan memohon belas kasihan dari Yang Mahakuasa,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 6, 'kalau engkau bersih dan jujur, maka tentu Ia akan bangkit demi engkau dan Ia akan memulihkan rumah yang adalah hakmu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 7, 'Maka kedudukanmu yang dahulu akan kelihatan hina, tetapi kedudukanmu yang kemudian akan menjadi sangat mulia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 8, 'Bertanya-tanyalah tentang orang-orang zaman dahulu, dan perhatikanlah apa yang diselidiki para nenek moyang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 9, 'Sebab kita, anak-anak kemarin, tidak mengetahui apa-apa; karena hari-hari kita seperti bayang-bayang di bumi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 10, 'Bukankah mereka yang harus mengajari engkau dan yang harus berbicara kepadamu, dan melahirkan kata-kata dari akal budi mereka?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 11, 'Dapatkah pandan bertumbuh tinggi, kalau tidak di rawa, atau mensiang bertumbuh subur, kalau tidak di air?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 12, 'Sementara dalam pertumbuhan, sebelum waktunya disabit, layulah ia lebih dahulu dari pada rumput lain.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 13, 'Demikianlah pengalaman semua orang yang melupakan Allah; maka lenyaplah harapan orang fasik,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 14, 'yang andalannya seperti benang laba-laba, kepercayaannya seperti sarang laba-laba.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 15, 'Ia bersandar pada rumahnya, tetapi rumahnya itu tidak tetap tegak, ia menjadikannya tempat berpegang, tetapi rumah itu tidak tahan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 16, 'Ia seperti tumbuh-tumbuhan yang masih segar di panas matahari, sulurnya menjulur di seluruh taman.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 17, 'Akar-akarnya membelit timbunan batu, menyusup ke dalam sela-sela batu itu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 18, 'Tetapi bila ia dicabut dari tempatnya, maka tempatnya itu tidak mengakuinya lagi, katanya: Belum pernah aku melihat engkau!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 19, 'Demikianlah kesukaan hidupnya, dan tumbuh-tumbuhan lain timbul dari tanah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 20, 'Ketahuilah, Allah tidak menolak orang yang saleh, dan Ia tidak memegang tangan orang yang berbuat jahat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 21, 'Ia masih akan membuat mulutmu tertawa dan bibirmu bersorak-sorak.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 8, 22, 'Pembencimu akan terselubung dengan malu, dan kemah orang fasik akan tidak ada lagi."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 1, 'Tetapi Ayub menjawab:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 2, '"Sungguh, aku tahu, bahwa demikianlah halnya, masakan manusia benar di hadapan Allah?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 3, 'Jikalau ia ingin beperkara dengan Allah satu dari seribu kali ia tidak dapat membantah-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 4, 'Allah itu bijak dan kuat, siapakah dapat berkeras melawan Dia, dan tetap selamat?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 5, 'Dialah yang memindahkan gunung-gunung dengan tidak diketahui orang, yang membongkar-bangkirkannya dalam murka-Nya;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 6, 'yang menggeserkan bumi dari tempatnya, sehingga tiangnya bergoyang-goyang;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 7, 'yang memberi perintah kepada matahari, sehingga tidak terbit, dan mengurung bintang-bintang dengan meterai;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 8, 'yang seorang diri membentangkan langit, dan melangkah di atas gelombang-gelombang laut;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 9, 'yang menjadikan bintang Biduk, bintang Belantik, bintang Kartika, dan gugusan-gugusan bintang Ruang Selatan;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 10, 'yang melakukan perbuatan-perbuatan besar yang tidak terduga, dan keajaiban-keajaiban yang tidak terbilang banyaknya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 11, 'Apabila Ia melewati aku, aku tidak melihat-Nya, dan bila Ia lalu, aku tidak mengetahui.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 12, 'Apabila Ia merampas, siapa akan menghalangi-Nya? Siapa akan menegur-Nya: Apa yang Kaulakukan?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 13, 'Allah tidak menahani murka-Nya, di bawah kuasa-Nya para pembantu Rahab membungkuk;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 14, 'lebih-lebih aku, bagaimana aku dapat membantah Dia, memilih kata-kataku di hadapan Dia?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 15, 'Walaupun aku benar, aku tidak mungkin membantah Dia, malah aku harus memohon belas kasihan kepada yang mendakwa aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 16, 'Bila aku berseru, Ia menjawab; aku tidak dapat percaya, bahwa Ia sudi mendengarkan suaraku;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 17, 'Dialah yang meremukkan aku dalam angin ribut, yang memperbanyak lukaku dengan tidak semena-mena,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 18, 'yang tidak membiarkan aku bernafas, tetapi mengenyangkan aku dengan kepahitan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 19, 'Jika mengenai kekuatan tenaga, Dialah yang mempunyai! Jika mengenai keadilan, siapa dapat menggugat Dia?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 20, 'Sekalipun aku benar, mulutku sendiri akan menyatakan aku tidak benar; sekalipun aku tidak bersalah, Ia akan menyatakan aku bersalah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 21, 'Aku tidak bersalah! Aku tidak pedulikan diriku, aku tidak hiraukan hidupku!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 22, 'Semuanya itu sama saja, itulah sebabnya aku berkata: yang tidak bersalah dan yang bersalah kedua-duanya dibinasakan-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 23, 'Bila cemeti-Nya membunuh dengan tiba-tiba, Ia mengolok-olok keputusasaan orang yang tidak bersalah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 24, 'Bumi telah diserahkan ke dalam tangan orang fasik, dan mata para hakimnya telah ditutup-Nya; kalau bukan oleh Dia, oleh siapa lagi?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 25, 'Hari-hariku berlalu lebih cepat dari pada seorang pelari, lenyap tanpa melihat bahagia,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 26, 'meluncur lewat laksana perahu dari pandan, seperti rajawali yang menyambar mangsanya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 27, 'Bila aku berpikir: Aku hendak melupakan keluh kesahku, mengubah air mukaku, dan bergembira,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 28, 'maka takutlah aku kepada segala kesusahanku; aku tahu, bahwa Engkau tidak akan menganggap aku tidak bersalah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 29, 'Aku dinyatakan bersalah, apa gunanya aku menyusahkan diri dengan sia-sia?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 30, 'Walaupun aku membasuh diriku dengan salju dan mencuci tanganku dengan sabun,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 31, 'namun Engkau akan membenamkan aku dalam lumpur, sehingga pakaianku merasa jijik terhadap aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 32, 'Karena Dia bukan manusia seperti aku, sehingga aku dapat menjawab-Nya: Mari bersama-sama menghadap pengadilan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 33, 'Tidak ada wasit di antara kami, yang dapat memegang kami berdua!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 34, 'Biarlah Ia menyingkirkan pentung-Nya dari padaku, jangan aku ditimpa kegentaran terhadap Dia,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 9, 35, 'maka aku akan berbicara tanpa rasa takut terhadap Dia, karena aku tidak menyadari kesalahanku."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 1, '"Aku telah bosan hidup, aku hendak melampiaskan keluhanku, aku hendak berbicara dalam kepahitan jiwaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 2, 'Aku akan berkata kepada Allah: Jangan mempersalahkan aku; beritahukanlah aku, mengapa Engkau beperkara dengan aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 3, 'Apakah untungnya bagi-Mu mengadakan penindasan, membuang hasil jerih payah tangan-Mu, sedangkan Engkau mendukung rancangan orang fasik?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 4, 'Apakah Engkau mempunyai mata badani? Samakah penglihatan-Mu dengan penglihatan manusia?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 5, 'Apakah hari-hari-Mu seperti hari-hari manusia, tahun-tahun-Mu seperti hari-hari orang laki-laki,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 6, 'sehingga Engkau mencari-cari kesalahanku, dan mengusut dosaku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 7, 'padahal Engkau tahu, bahwa aku tidak bersalah, dan bahwa tiada seorangpun dapat memberi kelepasan dari tangan-Mu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 8, 'Tangan-Mulah yang membentuk dan membuat aku, tetapi kemudian Engkau berpaling dan hendak membinasakan aku?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 9, 'Ingatlah, bahwa Engkau yang membuat aku dari tanah liat, tetapi Engkau hendak menjadikan aku debu kembali?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 10, 'Bukankah Engkau yang mencurahkan aku seperti air susu, dan mengentalkan aku seperti keju?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 11, 'Engkau mengenakan kulit dan daging kepadaku, serta menjalin aku dengan tulang dan urat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 12, 'Hidup dan kasih setia Kaukaruniakan kepadaku, dan pemeliharaan-Mu menjaga nyawaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 13, 'Tetapi inilah yang Kausembunyikan di dalam hati-Mu; aku tahu, bahwa inilah maksud-Mu:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 14, 'kalau aku berbuat dosa, maka Engkau akan mengawasi aku, dan Engkau tidak akan membebaskan aku dari pada kesalahanku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 15, 'Kalau aku bersalah, celakalah aku! dan kalau aku benar, aku takkan berani mengangkat kepalaku, karena kenyang dengan penghinaan, dan karena melihat sengsaraku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 16, 'Kalau aku mengangkat kepalaku, maka seperti singa Engkau akan memburu aku, dan menunjukkan kembali kuasa-Mu yang ajaib kepadaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 17, 'Engkau akan mengajukan saksi-saksi baru terhadap aku, ?Engkau memperbesar kegeraman-Mu terhadap aku?dan pasukan-pasukan baru, bahkan bala tentara melawan aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 18, 'Mengapa Engkau menyebabkan aku keluar dari kandungan? Lebih baik aku binasa, sebelum orang melihat aku!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 19, 'Maka aku seolah-olah tidak pernah ada; dari kandungan ibu aku langsung dibawa ke kubur.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 20, 'Bukankah hari-hari umurku hanya sedikit? Biarkanlah aku, supaya aku dapat bergembira sejenak,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 21, 'sebelum aku pergi, dan tidak kembali lagi, ke negeri yang gelap dan kelam pekat,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 10, 22, 'ke negeri yang gelap gulita, tempat yang kelam pekat dan kacau balau, di mana cahaya terang serupa dengan kegelapan."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 1, 'Maka berbicaralah Zofar, orang Naama:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 2, '"Apakah orang yang banyak bicara tidak harus dijawab? Apakah orang yang banyak mulut harus dibenarkan?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 3, 'Apakah orang harus diam terhadap bualmu? Dan kalau engkau mengolok-olok, apakah tidak ada yang mempermalukan engkau?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 4, 'Katamu: Pengajaranku murni, dan aku bersih di mata-Mu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 5, 'Tetapi, mudah-mudahan Allah sendiri berfirman, dan membuka mulut-Nya terhadap engkau,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 6, 'dan memberitakan kepadamu rahasia hikmat, karena itu ajaib bagi pengertian. Maka engkau akan mengetahui, bahwa Allah tidak memperhitungkan bagimu sebagian dari pada kesalahanmu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 7, 'Dapatkah engkau memahami hakekat Allah, menyelami batas-batas kekuasaan Yang Mahakuasa?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 8, 'Tingginya seperti langit?apa yang dapat kaulakukan? Dalamnya melebihi dunia orang mati?apa yang dapat kauketahui?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 9, 'Lebih panjang dari pada bumi ukurannya, dan lebih luas dari pada samudera.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 10, 'Apabila Ia lewat, melakukan penangkapan, dan mengadakan pengadilan, siapa dapat menghalangi-Nya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 11, 'Karena Ia mengenal penipu dan melihat kejahatan tanpa mengamat-amatinya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 12, 'Jikalau orang dungu dapat mengerti, maka anak keledai liarpun dapat lahir sebagai manusia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 13, 'Jikalau engkau ini menyediakan hatimu, dan menadahkan tanganmu kepada-Nya;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 14, 'jikalau engkau menjauhkan kejahatan dalam tanganmu, dan tidak membiarkan kecurangan ada dalam kemahmu,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 15, 'maka sesungguhnya, engkau dapat mengangkat mukamu tanpa cela, dan engkau akan berdiri teguh dan tidak akan takut,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 16, 'bahkan engkau akan melupakan kesusahanmu, hanya teringat kepadanya seperti kepada air yang telah mengalir lalu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 17, 'Kehidupanmu akan menjadi lebih cemerlang dari pada siang hari, kegelapan akan menjadi terang seperti pagi hari.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 18, 'Engkau akan merasa aman, sebab ada harapan, dan sesudah memeriksa kiri kanan, engkau akan pergi tidur dengan tenteram;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 19, 'engkau akan berbaring tidur dengan tidak diganggu, dan banyak orang akan mengambil muka kepadamu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 11, 20, 'Tetapi mata orang fasik akan menjadi rabun, mereka tidak dapat melarikan diri lagi; yang masih diharapkan mereka hanyalah menghembuskan nafas."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 1, 'Tetapi Ayub menjawab:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 2, '"Memang, kamulah orang-orang itu, dan bersama-sama kamu hikmat akan mati.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 3, 'Akupun mempunyai pengertian, sama seperti kamu, aku tidak kalah dengan kamu; siapa tidak tahu hal-hal serupa itu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 4, 'Aku menjadi tertawaan sesamaku, aku, yang mendapat jawaban dari Allah, bila aku berseru kepada-Nya; orang yang benar dan saleh menjadi tertawaan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 5, 'Penghinaan bagi orang yang celaka, ?demikianlah pendapat orang yang hidup aman?suatu pukulan bagi orang yang tergelincir kakinya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 6, 'Tetapi amanlah kemah para perusak, dan tenteramlah mereka yang membangkitkan murka Allah, mereka yang hendak membawa Allah dalam tangannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 7, 'Tetapi bertanyalah kepada binatang, maka engkau akan diberinya pengajaran, kepada burung di udara, maka engkau akan diberinya keterangan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 8, 'Atau bertuturlah kepada bumi, maka engkau akan diberinya pengajaran, bahkan ikan di laut akan bercerita kepadamu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 9, 'Siapa di antara semuanya itu yang tidak tahu, bahwa tangan Allah yang melakukan itu;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 10, 'bahwa di dalam tangan-Nya terletak nyawa segala yang hidup dan nafas setiap manusia?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 11, 'Bukankah telinga menguji kata-kata, seperti langit-langit mencecap makanan?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 12, 'Konon hikmat ada pada orang yang tua, dan pengertian pada orang yang lanjut umurnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 13, 'Tetapi pada Allahlah hikmat dan kekuatan, Dialah yang mempunyai pertimbangan dan pengertian.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 14, 'Bila Ia membongkar, tidak ada yang dapat membangun kembali; bila Ia menangkap seseorang, tidak ada yang dapat melepaskannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 15, 'Bila Ia membendung air, keringlah semuanya; bila Ia melepaskannya mengalir, maka tanah dilandanya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 16, 'Pada Dialah kuasa dan kemenangan, Dialah yang menguasai baik orang yang tersesat maupun orang yang menyesatkan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 17, 'Dia yang menggiring menteri dengan telanjang, dan para hakim dibodohkan-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 18, 'Dia membuka belenggu yang dikenakan oleh raja-raja dan mengikat pinggang mereka dengan tali pengikat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 19, 'Dia yang menggiring dan menggeledah para imam, dan menggulingkan yang kokoh.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 20, 'Dia yang membungkamkan orang-orang yang dipercaya, menjadikan para tua-tua hilang akal.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 21, 'Dia yang mendatangkan penghinaan kepada para pemuka, dan melepaskan ikat pinggang orang kuat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 22, 'Dia yang menyingkapkan rahasia kegelapan, dan mendatangkan kelam pekat pada terang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 23, 'Dia yang membuat bangsa-bangsa bertumbuh, lalu membinasakannya, dan memperbanyak bangsa-bangsa, lalu menghalau mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 24, 'Dia menyebabkan para pemimpin dunia kehilangan akal, dan membuat mereka tersesat di padang belantara yang tidak ada jalannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 12, 25, 'Mereka meraba-raba dalam kegelapan yang tidak ada terangnya; dan Ia membuat mereka berjalan terhuyung-huyung seperti orang mabuk."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 1, '"Sesungguhnya, semuanya itu telah dilihat mataku, didengar dan dipahami telingaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 2, 'Apa yang kamu tahu, aku juga tahu, aku tidak kalah dengan kamu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 3, 'Tetapi aku, aku hendak berbicara dengan Yang Mahakuasa, aku ingin membela perkaraku di hadapan Allah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 4, 'Sebaliknya kamulah orang yang menutupi dusta, tabib palsulah kamu sekalian.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 5, 'Sekiranya kamu menutup mulut, itu akan dianggap kebijaksanaan dari padamu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 6, 'Dengarkanlah pembelaanku, dan perhatikanlah bantahan bibirku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 7, 'Sudikah kamu berbohong untuk Allah, sudikah kamu mengucapkan dusta untuk Dia?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 8, 'Apakah kamu mau memihak Allah, berbantah untuk membela Dia?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 9, 'Apakah baik, kalau Ia memeriksa kamu? Dapatkah kamu menipu Dia seperti menipu manusia?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 10, 'Kamu akan dihukum-Nya dengan keras, jikalau kamu diam-diam memihak.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 11, 'Apakah kebesaran-Nya tidak akan mengejutkan kamu dan ketakutan kepada-Nya menimpa kamu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 12, 'Dalil-dalilmu adalah amsal debu, dan perisaimu perisai tanah liat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 13, 'Diam! Aku hendak bicara, apapun yang akan terjadi atas diriku!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 14, 'Dagingku akan kuambil dengan gigiku, dan nyawaku akan kutatang dalam genggamku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 15, 'Lihatlah, Ia hendak membunuh aku, tak ada harapan bagiku, namun aku hendak membela peri lakuku di hadapan-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 16, 'Itulah yang menyelamatkan aku; tetapi orang fasik tidak akan menghadap kepada-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 17, 'Dengarkanlah baik-baik perkataanku, perhatikanlah keteranganku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 18, 'Ketahuilah, aku menyiapkan perkaraku, aku yakin, bahwa aku benar.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 19, 'Siapa mau bersengketa dengan aku? Pada saat itu juga aku mau berdiam diri dan binasa.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 20, 'Hanya janganlah Kaulakukan terhadap aku dua hal ini, maka aku tidak akan bersembunyi terhadap Engkau:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 21, 'jauhkanlah kiranya tangan-Mu dari padaku, dan kegentaran terhadap Engkau janganlah menimpa aku!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 22, 'Panggillah, maka aku akan menjawab; atau aku berbicara, dan Engkau menjawab.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 23, 'Berapa besar kesalahan dan dosaku? Beritahukanlah kepadaku pelanggaran dan dosaku itu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 24, 'Mengapa Engkau menyembunyikan wajah-Mu, dan menganggap aku sebagai musuh-Mu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 25, 'Apakah Engkau hendak menggentarkan daun yang ditiupkan angin, dan mengejar jerami yang kering?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 26, 'Sebab Engkau menulis hal-hal yang pahit terhadap aku dan menghukum aku karena kesalahan pada masa mudaku;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 27, 'kakiku Kaumasukkan ke dalam pasung, segala tindak tandukku Kauawasi, dan rintangan Kaupasang di depan tapak kakiku?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 13, 28, 'Dan semuanya itu terhadap orang yang sudah rapuh seperti kayu lapuk, seperti kain yang dimakan gegat!"', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 1, '"Manusia yang lahir dari perempuan, singkat umurnya dan penuh kegelisahan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 2, 'Seperti bunga ia berkembang, lalu layu, seperti bayang-bayang ia hilang lenyap dan tidak dapat bertahan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 3, 'Masakan Engkau menujukan pandangan-Mu kepada orang seperti itu, dan menghadapkan kepada-Mu untuk diadili?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 4, 'Siapa dapat mendatangkan yang tahir dari yang najis? Seorangpun tidak!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 5, 'Jikalau hari-harinya sudah pasti, dan jumlah bulannya sudah tentu pada-Mu, dan batas-batasnya sudah Kautetapkan, sehingga tidak dapat dilangkahinya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 6, 'hendaklah Kaualihkan pandangan-Mu dari padanya, agar ia beristirahat, sehingga ia seperti orang upahan dapat menikmati harinya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 7, 'Karena bagi pohon masih ada harapan: apabila ditebang, ia bertunas kembali, dan tunasnya tidak berhenti tumbuh.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 8, 'Apabila akarnya menjadi tua di dalam tanah, dan tunggulnya mati di dalam debu,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 9, 'maka bersemilah ia, setelah diciumnya air, dan dikeluarkannyalah ranting seperti semai.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 10, 'Tetapi bila manusia mati, maka tidak berdayalah ia, bila orang binasa, di manakah ia?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 11, 'Seperti air menguap dari dalam tasik, dan sungai surut dan menjadi kering,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 12, 'demikian juga manusia berbaring dan tidak bangkit lagi, sampai langit hilang lenyap, mereka tidak terjaga, dan tidak bangun dari tidurnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 13, 'Ah, kiranya Engkau menyembunyikan aku di dalam dunia orang mati, melindungi aku, sampai murka-Mu surut; dan menetapkan waktu bagiku, kemudian mengingat aku pula!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 14, 'Kalau manusia mati, dapatkah ia hidup lagi? Maka aku akan menaruh harap selama hari-hari pergumulanku, sampai tiba giliranku;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 15, 'maka Engkau akan memanggil, dan akupun akan menyahut; Engkau akan rindu kepada buatan tangan-Mu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 16, 'Sungguhpun Engkau menghitung langkahku, Engkau tidak akan memperhatikan dosaku;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 17, 'pelanggaranku akan dimasukkan di dalam pundi-pundi yang dimeteraikan, dan kesalahanku akan Kaututup dengan lepa.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 18, 'Tetapi seperti gunung runtuh berantakan, dan gunung batu bergeser dari tempatnya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 19, 'seperti batu-batu dikikis air, dan bumi dihanyutkan tanahnya oleh hujan lebat, demikianlah Kauhancurkan harapan manusia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 20, 'Engkau menggagahi dia untuk selama-lamanya, maka pergilah ia, Engkau mengubah wajahnya dan menyuruh dia pergi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 21, 'Anak-anaknya menjadi mulia, tetapi ia tidak tahu; atau mereka menjadi hina, tetapi ia tidak menyadarinya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 14, 22, 'Hanya tubuhnya membuat dirinya menderita, dan karena dirinya sendiri jiwanya berduka cita."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 1, 'Maka Elifas, orang Teman, menjawab:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 2, '"Apakah orang yang mempunyai hikmat menjawab dengan pengetahuan kosong, dan mengisi pikirannya dengan angin?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 3, 'Apakah ia menegur dengan percakapan yang tidak berguna, dan dengan perkataan yang tidak berfaedah?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 4, 'Lagipula engkau melenyapkan rasa takut dan mengurangi rasa hormat kepada Allah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 5, 'Kesalahanmulah yang mengajar mulutmu, dan bahasa orang licik yang kaupilih.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 6, 'Mulutmu sendirilah yang mempersalahkan engkau, bukan aku; bibirmu sendiri menjadi saksi menentang engkau.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 7, 'Apakah engkau dilahirkan sebagai manusia yang pertama, atau dijadikan lebih dahulu dari pada bukit-bukit?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 8, 'Apakah engkau turut mendengarkan di dalam musyawarah Allah dan meraih hikmat bagi dirimu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 9, 'Apakah yang kauketahui, yang tidak kami ketahui? Apakah yang kaumengerti, yang tidak terang bagi kami?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 10, 'Di antara kami juga ada orang yang beruban dan yang lanjut umurnya, yang lebih tua umurnya dari pada ayahmu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 11, 'Kurangkah artinya bagimu penghiburan Allah, dan perkataan yang dengan lemah lembut ditujukan kepadamu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 12, 'Mengapa engkau dihanyutkan oleh perasaan hatimu dan mengapa matamu menyala-nyala,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 13, 'sehingga engkau memalingkan hatimu menentang Allah, dan mulutmu mengeluarkan perkataan serupa itu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 14, 'Masakan manusia bersih, masakan benar yang lahir dari perempuan?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 15, 'Sesungguhnya, para suci-Nya tidak dipercayai-Nya, seluruh langitpun tidak bersih pada pandangan-Nya;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 16, 'lebih-lebih lagi orang yang keji dan bejat, yang menghirup kecurangan seperti air.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 17, 'Aku hendak menerangkan sesuatu kepadamu, dengarkanlah aku, dan apa yang telah kulihat, hendak kuceritakan,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 18, 'yakni apa yang diberitakan oleh orang yang mempunyai hikmat, yang nenek moyang mereka tidak sembunyikan,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 19, 'ketika hanya kepada mereka negeri itu diberikan, dan tidak ada seorang asingpun masuk ke tengah-tengah mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 20, 'Orang fasik menggeletar sepanjang hidupnya, demikian juga orang lalim selama tahun-tahun yang disediakan baginya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 21, 'Bunyi yang dahsyat sampai ke telinganya, pada masa damai ia didatangi perusak.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 22, 'Ia tidak percaya, bahwa ia akan kembali dari kegelapan: ia sudah ditentukan untuk dimakan pedang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 23, 'Ia mengembara untuk mencari makan, entah ke mana. Ia tahu, bahwa hari kegelapan siap menantikan dia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 24, 'Ia ditakutkan oleh kesesakan dan kesempitan, yang menggagahinya laksana raja yang siap menyergap.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 25, 'Karena ia telah mengedangkan tangannya melawan Allah dan berani menantang Yang Mahakuasa;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 26, 'dengan bertegang leher ia berlari-lari menghadapi Dia, dengan perisainya yang berlapis tebal.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 27, 'Mukanya telah ditutupinya dengan lemak, dan lapisan lemak dikenakannya pada pinggangnya;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 28, 'ia menetap di kota-kota yang telah hancur, di rumah-rumah yang tidak dapat didiami orang, yang ditentukan untuk tetap menjadi reruntuhan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 29, 'Ia takkan menjadi kaya dan hartanya tidak kekal, serta miliknyapun tidak bertambah-tambah di bumi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 30, 'Ia tidak akan luput dari kegelapan, tunasnya akan dilayukan oleh nyala api, dan ia akan dilenyapkan oleh nafas mulut-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 31, 'Janganlah ia percaya kepada kesia-siaan, akan tertipulah ia, karena kesia-siaan akan menjadi ganjarannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 32, 'Sebelum genap masanya, ajalnya akan sampai; dan rantingnyapun tidak akan menghijau.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 33, 'Ia seperti pohon anggur yang gugur buahnya dan seperti pohon zaitun yang jatuh bunganya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 34, 'Karena kawanan orang-orang fasik tidak berhasil, dan api memakan habis kemah-kemah orang yang makan suap.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 15, 35, 'Mereka menghamilkan bencana dan melahirkan kejahatan, dan tipu daya dikandung hati mereka."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 1, 'Tetapi Ayub menjawab:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 2, '"Hal seperti itu telah acap kali kudengar. Penghibur sialan kamu semua!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 3, 'Belum habiskah omong kosong itu? Apa yang merangsang engkau untuk menyanggah?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 4, 'Akupun dapat berbicara seperti kamu, sekiranya kamu pada tempatku; aku akan menggubah kata-kata indah terhadap kamu, dan menggeleng-gelengkan kepala atas kamu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 5, 'Aku akan menguatkan hatimu dengan mulut, dan tidak menahan bibirku mengatakan belas kasihan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 6, 'Tetapi bila aku berbicara, penderitaanku tidak menjadi ringan, dan bila aku berdiam diri, apakah yang hilang dari padaku?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 7, 'Tetapi sekarang, Ia telah membuat aku lelah dan mencerai-beraikan segenap rumah tanggaku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 8, 'sudah menangkap aku; inilah yang menjadi saksi; kekurusanku telah bangkit menuduh aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 9, 'Murka-Nya menerkam dan memusuhi aku, Ia menggertakkan giginya terhadap aku; lawanku memandang aku dengan mata yang berapi-api.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 10, 'Mereka mengangakan mulutnya melawan aku, menampar pipiku dengan cercaan, dan bersama-sama mengerumuni aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 11, 'Allah menyerahkan aku kepada orang lalim, dan menjatuhkan aku ke dalam tangan orang fasik.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 12, 'Aku hidup dengan tenteram, tetapi Ia menggelisahkan aku, aku ditangkap-Nya pada tengkukku, lalu dibanting-Nya, dan aku ditegakkan-Nya menjadi sasaran-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 13, 'Aku dihujani anak panah, ginjalku ditembus-Nya dengan tak kenal belas kasihan, empeduku ditumpahkan-Nya ke tanah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 14, 'Ia merobek-robek aku, menyerang aku laksana seorang pejuang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 15, 'Kain kabung telah kujahit pada kulitku, dan tandukku kumasukkan ke dalam debu;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 16, 'mukaku merah karena menangis, dan bulu mataku ditudungi kelam pekat,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 17, 'sungguhpun tidak ada kelaliman pada tanganku, dan doaku bersih.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 18, 'Hai bumi, janganlah menutupi darahku, dan janganlah kiranya teriakku mendapat tempat perhentian!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 19, 'Ketahuilah, sekarangpun juga, Saksiku ada di sorga, Yang memberi kesaksian bagiku ada di tempat yang tinggi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 20, 'Sekalipun aku dicemoohkan oleh sahabat-sahabatku, namun ke arah Allah mataku menengadah sambil menangis,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 21, 'supaya Ia memutuskan perkara antara manusia dengan Allah, dan antara manusia dengan sesamanya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 16, 22, 'Karena sedikit jumlah tahun yang akan datang, dan aku akan menempuh jalan, dari mana aku tak akan kembali lagi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 1, 'Semangatku patah, umurku telah habis, dan bagiku tersedia kuburan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 2, 'Sesungguhnya, aku menjadi ejekan; mataku terpaksa menyaksikan tantangan mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 3, 'Biarlah Engkau menjadi jaminanku bagi-Mu sendiri! Siapa lagi yang dapat membuat persetujuan bagiku?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 4, 'Karena hati mereka telah Kaukatupkan bagi pengertian; itulah sebabnya Engkau mencegah mereka untuk menang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 5, 'Barangsiapa mengadukan sahabatnya untuk mencari keuntungan, mata anak-anaknya akan menjadi rabun.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 6, 'Aku telah dijadikan sindiran di antara bangsa-bangsa, dan aku menjadi orang yang diludahi mukanya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 7, 'Mataku menjadi kabur karena pedih hati, segala anggota tubuhku seperti bayang-bayang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 8, 'Orang-orang yang jujur tercengang karena hal itu, dan orang yang tidak bersalah naik pitam terhadap orang fasik.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 9, 'Meskipun begitu orang yang benar tetap pada jalannya, dan orang yang bersih tangannya bertambah-tambah kuat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 10, 'Tetapi kamu sekalian, silakan datang kembali! Seorang yang mempunyai hikmat takkan kudapati di antara kamu!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 11, 'Umurku telah lalu, telah gagal rencana-rencanaku, cita-citaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 12, 'Malam hendak dijadikan mereka siang: terang segera muncul dari gelap, kata mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 13, 'Apabila aku mengharapkan dunia orang mati sebagai rumahku, menyediakan tempat tidurku di dalam kegelapan,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 14, 'dan berkata kepada liang kubur: Engkau ayahku, kepada berenga: Ibuku dan saudara perempuanku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 15, 'maka di manakah harapanku? Siapakah yang melihat adanya harapan bagiku?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 17, 16, 'Keduanya akan tenggelam ke dasar dunia orang mati, apabila kami bersama-sama turun ke dalam debu."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 1, 'Maka Bildad, orang Suah, menjawab:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 2, '"Bilakah engkau habis bicara? Sadarilah, baru kami akan bicara.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 3, 'Mengapa kami dianggap binatang? Mengapa kami bodoh dalam pandanganmu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 4, 'Engkau yang menerkam dirimu sendiri dalam kemarahan, demi kepentinganmukah bumi harus menjadi sunyi, dan gunung batu bergeser dari tempatnya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 5, 'Bagaimanapun juga terang orang fasik tentu padam, dan nyala apinya tidak tetap bersinar.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 6, 'Terang di dalam kemahnya menjadi gelap, dan pelita di atasnya padam.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 7, 'Langkahnya yang kuat terhambat, dan pertimbangannya sendiri menjatuhkan dia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 8, 'Karena kakinya sendiri menyangkutkan dia dalam jaring, dan di atas tutup pelubang ia berjalan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 9, 'Tumitnya tertangkap oleh jebak, dan ia tertahan oleh jerat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 10, 'Tali tersembunyi baginya dalam tanah, perangkap terpasang baginya pada jalan yang dilaluinya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 11, 'Kedahsyatan mengejutkan dia di mana-mana, dan mengejarnya di mana juga ia melangkah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 12, 'Bencana mengidamkan dia, kebinasaan bersiap-siap menantikan dia jatuh.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 13, 'Kulit tubuhnya dimakan penyakit, bahkan anggota tubuhnya dimakan oleh penyakit parah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 14, 'Ia diseret dari kemahnya, tempat ia merasa aman, dan dibawa kepada raja kedahsyatan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 15, 'Dalam kemahnya tinggal apa yang tidak ada sangkut pautnya dengan dia, di atas tempat kediamannya ditaburkan belerang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 16, 'Di bawah keringlah akar-akarnya, dan di atas layulah rantingnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 17, 'Ingatan kepadanya lenyap dari bumi, namanya tidak lagi disebut di lorong-lorong.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 18, 'Ia diusir dari tempat terang ke dalam kegelapan, dan ia dienyahkan dari dunia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 19, 'Ia tidak akan mempunyai anak atau cucu cicit di antara bangsanya, dan tak seorangpun yang tinggal hidup di tempat kediamannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 20, 'Atas hari ajalnya orang-orang di Barat akan tercengang, dan orang-orang di Timur akan dihinggapi ketakutan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 18, 21, 'Sungguh, demikianlah tempat kediaman orang yang curang, begitulah tempat tinggal orang yang tidak mengenal Allah."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 1, 'Tetapi Ayub menjawab:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 2, '"Berapa lama lagi kamu menyakitkan hatiku, dan meremukkan aku dengan perkataan?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 3, 'Sekarang telah sepuluh kali kamu menghina aku, kamu tidak malu menyiksa aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 4, 'Jika aku sungguh tersesat, maka aku sendiri yang menanggung kesesatanku itu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 5, 'Jika kamu sungguh hendak membesarkan diri terhadap aku, dan membuat celaku sebagai bukti terhadap diriku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 6, 'insafilah, bahwa Allah telah berlaku tidak adil terhadap aku, dan menebarkan jala-Nya atasku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 7, 'Sesungguhnya, aku berteriak: Kelaliman!, tetapi tidak ada yang menjawab. Aku berseru minta tolong, tetapi tidak ada keadilan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 8, 'Jalanku ditutup-Nya dengan tembok, sehingga aku tidak dapat melewatinya, dan jalan-jalanku itu dibuat-Nya gelap.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 9, 'Ia telah menanggalkan kemuliaanku dan merampas mahkota di kepalaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 10, 'Ia membongkar aku di semua tempat, sehingga aku lenyap, dan seperti pohon harapanku dicabut-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 11, 'Murka-Nya menyala terhadap aku, dan menganggap aku sebagai lawan-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 12, 'Pasukan-Nya maju serentak, mereka merintangi jalan melawan aku, lalu mengepung kemahku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 13, 'Saudara-saudaraku dijauhkan-Nya dari padaku, dan kenalan-kenalanku tidak lagi mengenal aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 14, 'Kaum kerabatku menghindar, dan kawan-kawanku melupakan aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 15, 'Anak semang dan budak perempuanku menganggap aku orang yang tidak dikenal, aku dipandang mereka orang asing.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 16, 'Kalau aku memanggil budakku, ia tidak menyahut; aku harus membujuknya dengan kata-kata manis.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 17, 'Nafasku menimbulkan rasa jijik kepada isteriku, dan bauku memualkan saudara-saudara sekandungku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 18, 'Bahkan kanak-kanakpun menghina aku, kalau aku mau berdiri, mereka mengejek aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 19, 'Semua teman karibku merasa muak terhadap aku; dan mereka yang kukasihi, berbalik melawan aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 20, 'Tulangku melekat pada kulit dan dagingku, dan hanya gusiku yang tinggal padaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 21, 'Kasihanilah aku, kasihanilah aku, hai sahabat-sahabatku, karena tangan Allah telah menimpa aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 22, 'Mengapa kamu mengejar aku, seakan-akan Allah, dan tidak menjadi kenyang makan dagingku?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 23, 'Ah, kiranya perkataanku ditulis, dicatat dalam kitab,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 24, 'terpahat dengan besi pengukir dan timah pada gunung batu untuk selama-lamanya!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 25, 'Tetapi aku tahu: Penebusku hidup, dan akhirnya Ia akan bangkit di atas debu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 26, 'Juga sesudah kulit tubuhku sangat rusak, tanpa dagingkupun aku akan melihat Allah,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 27, 'yang aku sendiri akan melihat memihak kepadaku; mataku sendiri menyaksikan-Nya dan bukan orang lain. Hati sanubariku merana karena rindu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 28, 'Kalau kamu berkata: Kami akan menuntut dia dan mendapatkan padanya sebab perkaranya!,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 19, 29, 'takutlah kepada pedang, karena kegeraman mendatangkan hukuman pedang, agar kamu tahu, bahwa ada pengadilan."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 1, 'Maka Zofar, orang Naama, menjawab:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 2, '"Oleh sebab itulah pikiran-pikiranku mendorong aku menjawab, karena hatiku tidak sabar lagi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 3, 'Kudengar teguran yang menghina aku, tetapi yang menjawab aku ialah akal budi yang tidak berpengertian.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 4, 'Belumkah engkau mengetahui semuanya itu sejak dahulu kala, sejak manusia ditempatkan di bumi,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 5, 'bahwa sorak-sorai orang fasik hanya sebentar saja, dan sukacita orang durhaka hanya sekejap mata?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 6, 'Walaupun keangkuhannya sampai ke langit dan kepalanya mengenai awan,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 7, 'namun seperti tahinya ia akan binasa untuk selama-lamanya; siapa yang pernah melihatnya, bertanya: Di mana dia?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 8, 'Bagaikan impian ia melayang hilang, tak berbekas, lenyap bagaikan penglihatan waktu malam.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 9, 'Ia tidak lagi tampak pada mata yang melihatnya, dan tempat kediamannya tidak melihatnya lagi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 10, 'Anak-anaknya harus mencari belas kasihan orang miskin, dan tangannya sendiri harus mengembalikan kekayaannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 11, 'Tulang-tulangnya boleh penuh tenaga orang muda, tetapi tenaga itupun akan membaringkan diri bersama dia dalam debu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 12, 'Sungguhpun kejahatan manis rasanya di dalam mulutnya, sekalipun ia menyembunyikannya di bawah lidahnya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 13, 'menikmatinya serta tidak melepaskannya, dan menahannya pada langit-langitnya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 14, 'namun berubah juga makanannya di dalam perutnya, menjadi bisa ular tedung di dalamnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 15, 'Harta benda ditelannya, tetapi dimuntahkannya lagi, Allah yang mengeluarkannya dari dalam perutnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 16, 'Bisa ular tedung akan diisapnya, ia akan dibunuh oleh lidah ular.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 17, 'Ia tidak boleh melihat batang-batang air dan sungai-sungai yang mengalirkan madu dan dadih.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 18, 'Ia harus mengembalikan apa yang diperolehnya dan tidak mengecapnya; ia tidak menikmati kekayaan hasil dagangnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 19, 'Karena ia telah menghancurkan orang miskin, dan meninggalkan mereka terlantar; ia merampas rumah yang tidak dibangunnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 20, 'Sesungguhnya, ia tidak mengenal ketenangan dalam batinnya, dan ia tidak akan terluput dengan membawa harta bendanya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 21, 'Suatupun tidak luput dari pada lahapnya, itulah sebabnya kemujurannya tidak kekal.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 22, 'Dalam kemewahannya yang berlimpah-limpah ia penuh kuatir; ia ditimpa kesusahan dengan sangat dahsyatnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 23, 'Untuk mengisi perutnya, Allah melepaskan ke atasnya murka-Nya yang menyala-nyala, dan menghujankan itu kepadanya sebagai makanannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 24, 'Ia dapat meluputkan diri terhadap senjata besi, namun panah tembaga menembus dia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 25, 'Anak panah itu tercabut dan keluar dari punggungnya, mata panah yang berkilat itu keluar dari empedunya: ia menjadi ngeri.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 26, 'Kegelapan semata-mata tersedia bagi dia, api yang tidak ditiup memakan dia dan menghabiskan apa yang tersisa dalam kemahnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 27, 'Langit menyingkapkan kesalahannya, dan bumi bangkit melawan dia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 28, 'Hasil usahanya yang ada di rumahnya diangkut, semuanya habis pada hari murka-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 20, 29, 'Itulah ganjaran Allah bagi orang fasik, milik pusaka yang dijanjikan Allah kepadanya."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 1, 'Tetapi Ayub menjawab:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 2, '"Dengarkanlah baik-baik perkataanku dan biarlah itu menjadi penghiburanmu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 3, 'Bersabarlah dengan aku, aku akan berbicara; sehabis bicaraku bolehlah kamu mengejek.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 4, 'Kepada manusiakah keluhanku tertuju? Mengapa aku tidak boleh kesal hati?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 5, 'Berpalinglah kepadaku, maka kamu akan tercengang, dan menutup mulutmu dengan tangan!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 6, 'Kalau aku memikirkannya, aku menjadi takut, dan gemetarlah tubuhku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 7, 'Mengapa orang fasik tetap hidup, menjadi tua, bahkan menjadi bertambah-tambah kuat?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 8, 'Keturunan mereka tetap bersama mereka, dan anak cucu diperhatikan mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 9, 'Rumah-rumah mereka aman, tak ada ketakutan, pentung Allah tidak menimpa mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 10, 'Lembu jantan mereka memacek dan tidak gagal, lembu betina mereka beranak dan tidak keguguran.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 11, 'Kanak-kanak mereka dibiarkan keluar seperti kambing domba, anak-anak mereka melompat-lompat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 12, 'Mereka bernyanyi-nyanyi dengan iringan rebana dan kecapi, dan bersukaria menurut lagu seruling.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 13, 'Mereka menghabiskan hari-hari mereka dalam kemujuran, dan dengan tenang mereka turun ke dalam dunia orang mati.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 14, 'Tetapi kata mereka kepada Allah: Pergilah dari kami! Kami tidak suka mengetahui jalan-jalan-Mu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 15, 'Yang Mahakuasa itu apa, sehingga kami harus beribadah kepada-Nya, dan apa manfaatnya bagi kami, kalau kami memohon kepada-Nya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 16, 'Memang, kemujuran mereka tidak terletak dalam kuasa mereka sendiri! Rancangan orang fasik adalah jauh dari padaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 17, 'Betapa sering pelita orang fasik dipadamkan, kebinasaan menimpa mereka, dan kesakitan dibagikan Allah kepada mereka dalam murka-Nya!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 18, 'Mereka menjadi seperti jerami di depan angin, seperti sekam yang diterbangkan badai.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 19, 'Bencana untuk dia disimpan Allah bagi anak-anaknya. Sebaiknya, orang itu sendiri diganjar Allah, supaya sadar;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 20, 'sebaiknya matanya sendiri melihat kebinasaannya, dan ia sendiri minum dari murka Yang Mahakuasa!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 21, 'Karena peduli apa ia dengan keluarganya sesudah ia mati, bila telah habis jumlah bulannya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 22, 'Masakan kepada Allah diajarkan orang pengetahuan, kepada Dia yang mengadili mereka yang di tempat tinggi?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 23, 'Yang seorang mati dengan masih penuh tenaga, dengan sangat tenang dan sentosa;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 24, 'pinggangnya gemuk oleh lemak, dan sumsum tulang-tulangnya masih segar.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 25, 'Yang lain mati dengan sakit hati, dengan tidak pernah merasakan kenikmatan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 26, 'Tetapi sama-sama mereka terbaring di dalam debu, dan berenga-berenga berkeriapan di atas mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 27, 'Sesungguhnya, aku mengetahui pikiranmu, dan muslihat yang kamu rancangkan terhadap aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 28, 'Katamu: Di mana rumah penguasa? Di mana kemah tempat kediaman orang-orang fasik?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 29, 'Belum pernahkah kamu bertanya-tanya kepada orang-orang yang lewat di jalan? Dapatkah kamu menyangkal petunjuk-petunjuk mereka,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 30, 'bahwa orang jahat terlindung pada hari kebinasaan, dan diselamatkan pada hari murka Allah?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 31, 'Siapa yang akan langsung menggugat kelakuannya, dan mengganjar perbuatannya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 32, 'Dialah yang dibawa ke kuburan, dan jiratnya dirawat orang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 33, 'Dengan nyaman ia ditutupi oleh gumpalan-gumpalan tanah di lembah; setiap orang mengikuti dia, dan yang mendahului dia tidak terbilang banyaknya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 21, 34, 'Alangkah hampanya penghiburanmu bagiku! Semua jawabanmu hanyalah tipu daya belaka!"', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 1, 'Maka Elifas, orang Teman, menjawab:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 2, '"Apakah manusia berguna bagi Allah? Tidak, orang yang berakal budi hanya berguna bagi dirinya sendiri.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 3, 'Apakah ada manfaatnya bagi Yang Mahakuasa, kalau engkau benar, atau keuntungannya, kalau engkau hidup saleh?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 4, 'Apakah karena takutmu akan Allah, maka engkau dihukum-Nya, dan dibawa-Nya ke pengadilan?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 5, 'Bukankah kejahatanmu besar dan kesalahanmu tidak berkesudahan?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 6, 'Karena dengan sewenang-wenang engkau menerima gadai dari saudara-saudaramu dan merampas pakaian orang-orang yang melarat;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 7, 'orang yang kehausan tidak kauberi minum air, dan orang yang kelaparan tidak kauberi makan,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 8, 'tetapi orang yang kuat, dialah yang memiliki tanah, dan orang yang disegani, dialah yang mendudukinya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 9, 'Janda-janda kausuruh pergi dengan tangan hampa, dan lengan yatim piatu kauremukkan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 10, 'Itulah sebabnya engkau dikelilingi perangkap, dan dikejutkan oleh kedahsyatan dengan tiba-tiba.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 11, 'Terangmu menjadi gelap, sehingga engkau tidak dapat melihat dan banjir meliputi engkau.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 12, 'Bukankah Allah bersemayam di langit yang tinggi? Lihatlah bintang-bintang yang tertinggi, betapa tingginya!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 13, 'Tetapi pikirmu: Tahu apa Allah? Dapatkah Ia mengadili dari balik awan-awan yang gelap?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 14, 'Awan meliputi Dia, sehingga Ia tidak dapat melihat; Ia berjalan-jalan sepanjang lingkaran langit!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 15, 'Apakah engkau mau tetap mengikuti jalan lama, yang dilalui orang-orang jahat,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 16, 'mereka yang telah direnggut sebelum saatnya, yang alasnya dihanyutkan sungai;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 17, 'mereka yang berkata kepada Allah: Pergilah dari pada kami! dan: Yang Mahakuasa dapat berbuat apa terhadap kami?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 18, 'Namun Dialah juga yang memenuhi rumah mereka dengan segala yang baik?tetapi rancangan orang fasik adalah jauh dari padaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 19, 'Hal itu dilihat oleh orang benar dan mereka bersukaria; orang yang tidak bersalah mengolok-olok mereka:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 20, 'Sungguh, lawan kami telah dilenyapkan, dan peninggalan mereka telah habis dimakan api.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 21, 'Berlakulah ramah terhadap Dia, supaya engkau tenteram; dengan demikian engkau memperoleh keuntungan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 22, 'Terimalah apa yang diajarkan mulut-Nya, dan taruhlah firman-Nya dalam hatimu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 23, 'Apabila engkau bertobat kepada Yang Mahakuasa, dan merendahkan diri; apabila engkau menjauhkan kecurangan dari dalam kemahmu,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 24, 'membuang biji emas ke dalam debu, emas Ofir ke tengah batu-batu sungai,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 25, 'dan apabila Yang Mahakuasa menjadi timbunan emasmu, dan kekayaan perakmu,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 26, 'maka sungguh-sungguh engkau akan bersenang-senang karena Yang Mahakuasa, dan akan menengadah kepada Allah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 27, 'Jikalau engkau berdoa kepada-Nya, Ia akan mengabulkan doamu, dan engkau akan membayar nazarmu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 28, 'Apabila engkau memutuskan berbuat sesuatu, maka akan tercapai maksudmu, dan cahaya terang menyinari jalan-jalanmu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 29, 'Karena Allah merendahkan orang yang angkuh tetapi menyelamatkan orang yang menundukkan kepala!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 22, 30, 'Orang yang tidak bersalah diluputkan-Nya: engkau luput karena kebersihan tanganmu."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 1, 'Tetapi Ayub menjawab:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 2, '"Sekarang ini keluh kesahku menjadi pemberontakan, tangan-Nya menekan aku, sehingga aku mengaduh.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 3, 'Ah, semoga aku tahu mendapatkan Dia, dan boleh datang ke tempat Ia bersemayam.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 4, 'Maka akan kupaparkan perkaraku di hadapan-Nya, dan kupenuhi mulutku dengan kata-kata pembelaan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 5, 'Maka aku akan mengetahui jawaban-jawaban yang diberikan-Nya kepadaku dan aku akan mengerti, apa yang difirmankan-Nya kepadaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 6, 'Sudikah Ia mengadakan perkara dengan aku dalam kemahakuasaan-Nya? Tidak, Ia akan menaruh perhatian kepadaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 7, 'Orang jujurlah yang akan membela diri di hadapan-Nya, dan aku akan bebas dari Hakimku untuk selama-lamanya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 8, 'Sesungguhnya, kalau aku berjalan ke timur, Ia tidak di sana; atau ke barat, tidak kudapati Dia;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 9, 'di utara kucari Dia, Ia tidak tampak, aku berpaling ke selatan, aku tidak melihat Dia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 10, 'Karena Ia tahu jalan hidupku; seandainya Ia menguji aku, aku akan timbul seperti emas.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 11, 'Kakiku tetap mengikuti jejak-Nya, aku menuruti jalan-Nya dan tidak menyimpang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 12, 'Perintah dari bibir-Nya tidak kulanggar, dalam sanubariku kusimpan ucapan mulut-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 13, 'Tetapi Ia tidak pernah berubah?siapa dapat menghalangi Dia? Apa yang dikehendaki-Nya, dilaksanakan-Nya juga.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 14, 'Karena Ia akan menyelesaikan apa yang ditetapkan atasku, dan banyak lagi hal yang serupa itu dimaksudkan-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 15, 'Itulah sebabnya hatiku gemetar menghadapi Dia, kalau semuanya itu kubayangkan, maka aku ketakutan terhadap Dia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 16, 'Allah telah membuat aku putus asa, Yang Mahakuasa telah membuat hatiku gemetar;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 23, 17, 'sebab bukan karena kegelapan aku binasa, dan bukan juga karena mukaku ditutupi gelap gulita."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 1, '"Mengapa Yang Mahakuasa tidak mencadangkan masa penghukuman dan mereka yang mengenal Dia tidak melihat hari pengadilan-Nya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 2, 'Ada orang yang menggeser batas tanah, yang merampas kawanan ternak, lalu menggembalakannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 3, 'Keledai kepunyaan yatim piatu dilarikannya, dan lembu betina kepunyaan seorang janda diterimanya sebagai gadai,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 4, 'orang miskin didorongnya dari jalan, orang sengsara di dalam negeri terpaksa bersembunyi semuanya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 5, 'Sesungguhnya, seperti keledai liar di padang gurun mereka keluar untuk bekerja mencari apa-apa di padang belantara sebagai makanan bagi anak-anak mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 6, 'Di ladang mereka mengambil makanan hewan, dan kebun anggur, milik orang fasik, dipetiki buahnya yang ketinggalan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 7, 'Dengan telanjang mereka bermalam, karena tidak ada pakaian, dan mereka tidak mempunyai selimut pada waktu dingin;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 8, 'oleh hujan lebat di pegunungan mereka basah kuyup, dan karena tidak ada tempat berlindung, mereka mengimpitkan badannya pada gunung batu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 9, 'Ada yang merebut anak piatu dari susu ibunya dan menerima bayi orang miskin sebagai gadai.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 10, 'Dengan telanjang mereka berkeliaran, karena tidak ada pakaian, dan dengan kelaparan mereka memikul berkas-berkas gandum;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 11, 'di antara dua petak kebun mereka membuat minyak, mereka menginjak-injak tempat pengirikan sambil kehausan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 12, 'Dari dalam kota terdengar rintihan orang-orang yang hampir mati dan jeritan orang-orang yang menderita luka, tetapi Allah tidak mengindahkan doa mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 13, 'Ada lagi golongan yang memusuhi terang, yang tidak mengenal jalannya dan tidak tetap tinggal pada lintasannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 14, 'Pada parak siang bersiaplah si pembunuh, orang sengsara dan miskin dibunuhnya, dan waktu malam ia berlaku seperti pencuri.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 15, 'Orang yang berzinah menunggu senja, pikirnya: Jangan seorangpun melihat aku; lalu dikenakannya tudung muka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 16, 'Di dalam gelap mereka membongkar rumah, pada siang hari mereka bersembunyi; mereka tidak kenal terang,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 17, 'karena kegelapan adalah pagi hari bagi mereka sekalian, dan mereka sudah biasa dengan kedahsyatan kegelapan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 18, 'Mereka hanyut di permukaan air, bagian mereka terkutuk di bumi; mereka tidak lagi pergi ke kebun anggur mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 19, 'Air salju dihabiskan oleh kemarau dan panas, demikian juga dilakukan dunia orang mati terhadap mereka yang berbuat dosa.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 20, 'Rahim ibu melupakan dia, berenga mengerumitnya, ia tidak diingat lagi: kecurangan dipatahkan seperti pohon kayu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 21, 'Ia menjarahi perempuan mandul, yang tidak beranak, dan tidak berbuat baik terhadap seorang janda,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 22, 'bahkan menyeret orang-orang perkasa dengan kekuatannya; ia bangun kembali, tetapi hidupnya tidak terjamin.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 23, 'Allah memberinya keamanan yang menjadi sandarannya, dan mengawasi jalan-jalannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 24, 'Hanya sebentar mereka meninggikan diri, lalu tidak ada lagi; mereka luruh, lalu menjadi lisut seperti segala sesuatu, mereka dikerat seperti hulu tangkai gandum.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 24, 25, 'Jikalau tidak demikian halnya, siapa berani menyanggah aku dan meniadakan perkataanku?"', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 25, 1, 'Maka Bildad, orang Suah, menjawab:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 25, 2, '"Kekuasaan dan kedahsyatan ada pada Dia, yang menyelenggarakan damai di tempat-Nya yang tinggi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 25, 3, 'Dapatkah dihitung pasukan-Nya? Dan siapakah yang tidak disinari terang-Nya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 25, 4, 'Bagaimana manusia benar di hadapan Allah, dan bagaimana orang yang dilahirkan perempuan itu bersih?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 25, 5, 'Sesungguhnya, bahkan bulanpun tidak terang dan bintang-bintangpun tidak cerah di mata-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 25, 6, 'Lebih-lebih lagi manusia, yang adalah berenga, anak manusia, yang adalah ulat!"', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 1, 'Tetapi Ayub menjawab:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 2, '"Alangkah baiknya bantuanmu kepada yang tidak kuat, dan pertolonganmu kepada lengan yang tidak berdaya!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 3, 'Alangkah baiknya nasihatmu kepada orang yang tidak mempunyai hikmat, dan pengertian yang kauajarkan dengan limpahnya!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 4, 'Atas anjuran siapakah engkau mengucapkan perkataan-perkataan itu, dan gagasan siapakah yang kaunyatakan?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 5, 'Roh-roh di bawah menggeletar, demikian juga air dan penghuninya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 6, 'Dunia orang mati terbuka di hadapan Allah, tempat kebinasaanpun tidak ada tutupnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 7, 'Allah membentangkan utara di atas kekosongan, dan menggantungkan bumi pada kehampaan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 8, 'Ia membungkus air di dalam awan-Nya, namun awan itu tidak robek.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 9, 'Ia menutupi pemandangan takhta-Nya, melingkupinya dengan awan-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 10, 'Ia telah menarik garis pada permukaan air, sampai ujung perbatasan antara terang dan gelap;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 11, 'tiang-tiang langit bergoyang-goyang, tercengang-cengang oleh hardik-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 12, 'Ia telah meneduhkan laut dengan kuasa-Nya dan meremukkan Rahab dengan kebijaksanaan-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 13, 'Oleh nafas-Nya langit menjadi cerah, tangan-Nya menembus ular yang tangkas.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 26, 14, 'Sesungguhnya, semuanya itu hanya ujung-ujung jalan-Nya; betapa lembutnya bisikan yang kita dengar dari pada-Nya! Siapa dapat memahami guntur kuasa-Nya?"', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 1, 'Maka Ayub melanjutkan uraiannya:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 2, '"Demi Allah yang hidup, yang tidak memberi keadilan kepadaku, dan demi Yang Mahakuasa, yang memedihkan hatiku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 3, 'selama nafasku masih ada padaku, dan roh Allah masih di dalam lubang hidungku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 4, 'maka bibirku sungguh-sungguh tidak akan mengucapkan kecurangan, dan lidahku tidak akan melahirkan tipu daya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 5, 'Aku sama sekali tidak membenarkan kamu! Sampai binasa aku tetap mempertahankan bahwa aku tidak bersalah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 6, 'Kebenaranku kupegang teguh dan tidak kulepaskan; hatiku tidak mencela seharipun dari pada umurku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 7, 'Biarlah musuhku mengalami seperti orang fasik, dan orang yang melawan aku seperti orang yang curang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 8, 'Karena apakah harapan orang durhaka, kalau Allah menghabisinya, kalau Ia menuntut nyawanya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 9, 'Apakah Allah akan mendengar teriaknya, jika kesesakan menimpa dia?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 10, 'Dapatkah ia bersenang-senang karena Yang Mahakuasa dan berseru kepada Allah setiap waktu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 11, 'Aku akan mengajari kamu tentang tangan Allah, apa yang dimaksudkan oleh Yang Mahakuasa tidak akan kusembunyikan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 12, 'Sesungguhnya, kamu sekalian telah melihatnya sendiri; mengapa kamu berpikir yang tidak-tidak?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 13, 'Inilah bagian orang fasik yang ditentukan Allah, dan milik pusaka orang-orang lalim yang mereka terima dari Yang Mahakuasa:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 14, 'kalau anak-anaknya bertambah banyak mereka menjadi makanan pedang, dan anak cucunya tidak mendapat cukup makan;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 15, 'siapa yang luput dari padanya, akan turun ke kubur karena wabah, dengan tidak ditangisi oleh janda mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 16, 'Jikalau ia menimbun uang seperti debu banyaknya, dan menumpuk pakaian seperti tanah liat,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 17, 'sekalipun ia yang menumpuknya, namun orang benar yang akan memakainya, dan orang yang tidak bersalah yang akan membagi-bagi uang itu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 18, 'Ia mendirikan rumahnya seperti sarang laba-laba, seperti gubuk yang dibuat penjaga.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 19, 'Sebagai orang kaya ia membaringkan diri, tetapi tidak dapat ia mengulanginya: ketika ia membuka matanya, maka tidak ada lagi semuanya itu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 20, 'Kedahsyatan mengejar dia seperti air bah, pada malam hari ia diterbangkan badai;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 21, 'angin timur mengangkatnya, lalu lenyaplah ia; ia dilemparkannya dari tempatnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 22, 'Dengan tak kenal belas kasihan Allah melempari dia, dengan cepat ia harus melepaskan diri dari kuasa-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 27, 23, 'Oleh karena dia orang bertepuk tangan, dan bersuit-suit karena dia dari tempat kediamannya."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 1, '"Memang ada tempat orang menambang perak dan tempat orang melimbang emas;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 2, 'besi digali dari dalam tanah, dan dari batu dilelehkan tembaga.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 3, 'Orang menyudahi kegelapan, dan batu diselidikinya sampai sedalam-dalamnya, di dalam kekelaman dan kelam pekat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 4, 'Orang menggali tambang jauh dari tempat kediaman manusia, mereka dilupakan oleh orang-orang yang berjalan di atas, mereka melayang-layang jauh dari manusia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 5, 'Tanah yang menghasilkan pangan, dibawahnya dibongkar-bangkir seperti oleh api.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 6, 'Batunya adalah tempat menemukan lazurit yang mengandung emas urai.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 7, 'Jalan ke sana tidak dikenal seekor burung buaspun, dan mata elang tidak melihatnya;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 8, 'binatang yang ganas tidak menginjakkan kakinya di sana dan singa tidak melangkah melaluinya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 9, 'Manusia melekatkan tangannya pada batu yang keras, ia membongkar-bangkir gunung-gunung sampai pada akar-akarnya;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 10, 'di dalam gunung batu ia menggali terowongan, dan matanya melihat segala sesuatu yang berharga;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 11, 'air sungai yang merembes dibendungnya, dan apa yang tersembunyi dibawanya ke tempat terang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 12, 'Tetapi di mana hikmat dapat diperoleh, di mana tempat akal budi?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 13, 'Jalan ke sana tidak diketahui manusia, dan tidak didapati di negeri orang hidup.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 14, 'Kata samudera raya: Ia tidak terdapat di dalamku, dan kata laut: Ia tidak ada padaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 15, 'Untuk gantinya tidak dapat diberikan emas murni, dan harganya tidak dapat ditimbang dengan perak.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 16, 'Ia tidak dapat dinilai dengan emas Ofir, ataupun dengan permata krisopras yang mahal atau dengan permata lazurit;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 17, 'tidak dapat diimbangi oleh emas, atau kaca, ataupun ditukar dengan permata dari emas tua.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 18, 'Baik gewang, baik hablur, tidak terhitung lagi; memiliki hikmat adalah lebih baik dari pada mutiara.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 19, 'Permata krisolit Etiopia tidak dapat mengimbanginya, ia tidak dapat dinilai dengan emas murni.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 20, 'Hikmat itu, dari manakah datangnya, atau akal budi, di manakah tempatnya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 21, 'Ia terlindung dari mata segala yang hidup, bahkan tersembunyi bagi burung di udara.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 22, 'Kebinasaan dan maut berkata: Hanya desas-desusnya yang sampai ke telinga kami.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 23, 'Allah mengetahui jalan ke sana, Ia juga mengenal tempat kediamannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 24, 'Karena Ia memandang sampai ke ujung-ujung bumi, dan melihat segala sesuatu yang ada di kolong langit.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 25, 'Ketika Ia menetapkan kekuatan angin, dan mengatur banyaknya air,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 26, 'ketika Ia membuat ketetapan bagi hujan, dan jalan bagi kilat guruh,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 27, 'ketika itulah Ia melihat hikmat, lalu memberitakannya, menetapkannya, bahkan menyelidikinya;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 28, 28, 'tetapi kepada manusia Ia berfirman: Sesungguhnya, takut akan Tuhan, itulah hikmat, dan menjauhi kejahatan itulah akal budi."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 1, 'Maka Ayub melanjutkan uraiannya:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 2, '"Ah, kiranya aku seperti dalam bulan-bulan yang silam, seperti pada hari-hari, ketika Allah melindungi aku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 3, 'ketika pelita-Nya bersinar di atas kepalaku, dan di bawah terang-Nya aku berjalan dalam gelap;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 4, 'seperti ketika aku mengalami masa remajaku, ketika Allah bergaul karib dengan aku di dalam kemahku;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 5, 'ketika Yang Mahakuasa masih beserta aku, dan anak-anakku ada di sekelilingku;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 6, 'ketika langkah-langkahku bermandikan dadih, dan gunung batu mengalirkan sungai minyak di dekatku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 7, 'Apabila aku keluar ke pintu gerbang kota, dan menyediakan tempat dudukku di tengah-tengah lapangan,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 8, 'maka ketika aku kelihatan, mundurlah orang-orang muda dan bangkitlah orang-orang yang sudah lanjut umurnya, lalu tinggal berdiri;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 9, 'para pembesar berhenti bicara, dan menutup mulut mereka dengan tangan;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 10, 'suara para pemuka membisu, dan lidah mereka melekat pada langit-langitnya;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 11, 'apabila telinga mendengar tentang aku, maka aku disebut berbahagia; dan apabila mata melihat, maka aku dipuji.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 12, 'Karena aku menyelamatkan orang sengsara yang berteriak minta tolong, juga anak piatu yang tidak ada penolongnya;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 13, 'aku mendapat ucapan berkat dari orang yang nyaris binasa, dan hati seorang janda kubuat bersukaria;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 14, 'aku berpakaian kebenaran dan keadilan menutupi aku seperti jubah dan serban;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 15, 'aku menjadi mata bagi orang buta, dan kaki bagi orang lumpuh;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 16, 'aku menjadi bapa bagi orang miskin, dan perkara orang yang tidak kukenal, kuselidiki.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 17, 'Geraham orang curang kuremuk, dan merebut mangsanya dari giginya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 18, 'Pikirku: Bersama-sama dengan sarangku aku akan binasa, dan memperbanyak hari-hariku seperti burung feniks.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 19, 'Akarku mencapai air, dan embun bermalam di atas ranting-rantingku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 20, 'Kemuliaanku selalu baru padaku, dan busurku kuat kembali di tanganku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 21, 'Kepadakulah orang mendengar sambil menanti, dengan diam mereka mendengarkan nasihatku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 22, 'Sehabis bicaraku tiada seorangpun angkat bicara lagi, dan perkataanku menetes ke atas mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 23, 'Orang menantikan aku seperti menantikan hujan, dan menadahkan mulutnya seperti menadah hujan pada akhir musim.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 24, 'Aku tersenyum kepada mereka, ketika mereka putus asa, dan seri mukaku tidak dapat disuramkan mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 29, 25, 'Aku menentukan jalan mereka dan duduk sebagai pemimpin; aku bersemayam seperti raja di tengah-tengah rakyat, seperti seorang yang menghibur mereka yang berkabung."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 1, '"Tetapi sekarang aku ditertawakan mereka, yang umurnya lebih muda dari padaku, yang ayah-ayahnya kupandang terlalu hina untuk ditempatkan bersama-sama dengan anjing penjaga kambing dombaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 2, 'Lagipula, apakah gunanya bagiku kekuatan tangan mereka? Mereka sudah kehabisan tenaga,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 3, 'mereka merana karena kekurangan dan kelaparan, mengerumit tanah yang kering, belukar di gurun dan padang belantara;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 4, 'mereka memetik gelang laut dari antara semak-semak, dan akar pohon arar menjadi makanan mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 5, 'Mereka diusir dari pergaulan hidup, dan orang berteriak-teriak terhadap mereka seperti terhadap pencuri.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 6, 'Di lembah-lembah yang mengerikan mereka harus diam, di dalam celah-celah tanah dan sela-sela gunung;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 7, 'di antara semak-semak mereka meraung-raung, mereka berkelompok di bawah jeruju;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 8, 'mereka itulah orang-orang bebal yang tak dikenal, yang didepak dari negeri.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 9, 'Tetapi sekarang aku menjadi sajak sindiran dan ejekan mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 10, 'Mereka mengejikan aku, menjauhkan diri dari padaku, mereka tidak menahan diri meludahi mukaku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 11, 'karena tali kemahku telah dilepaskan Allah dan aku direndahkan-Nya, dan mereka tidak mengekang diri terhadap aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 12, 'Di sebelah kananku muncul gerombolan, dikaitnya kakiku, dan dirintisnya jalan kebinasaan terhadap aku;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 13, 'mereka membongkar jalanku dan mengusahakan kejatuhanku; tidak ada yang menghalang-halangi mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 14, 'Seperti melalui tembok yang terbelah lebar mereka menyerbu, mereka datang bergelombang di tengah-tengah keruntuhan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 15, 'Kedahsyatan ditimpakan kepadaku; kemuliaanku diterbangkan seperti oleh angin, dan bahagiaku melayang hilang seperti awan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 16, 'Oleh sebab itu jiwaku hancur dalam diriku; hari-hari kesengsaraan mencekam aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 17, 'Pada waktu malam tulang-tulangku seperti digerogoti, dan rasa nyeri yang menusuk tak kunjung berhenti.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 18, 'Oleh kekerasan yang tak terlawan koyaklah pakaianku dan menggelambir sekelilingku seperti kemeja.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 19, 'Ia telah menghempaskan aku ke dalam lumpur, dan aku sudah menyerupai debu dan abu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 20, 'Aku berseru minta tolong kepada-Mu, tetapi Engkau tidak menjawab; aku berdiri menanti, tetapi Engkau tidak menghiraukan aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 21, 'Engkau menjadi kejam terhadap aku, Engkau memusuhi aku dengan kekuatan tangan-Mu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 22, 'Engkau mengangkat aku ke atas angin, melayangkan aku dan menghancurkan aku di dalam angin ribut.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 23, 'Ya, aku tahu: Engkau membawa aku kepada maut, ke tempat segala yang hidup dihimpunkan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 24, 'Sesungguhnya, masakan orang tidak akan mengulurkan tangannya kepada yang rebah, jikalau ia dalam kecelakaannya tidak ada penolongnya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 25, 'Bukankah aku menangis karena orang yang mengalami hari kesukaran? Bukankah susah hatiku karena orang miskin?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 26, 'Tetapi, ketika aku mengharapkan yang baik, maka kejahatanlah yang datang; ketika aku menantikan terang, maka kegelapanlah yang datang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 27, 'Batinku bergelora dan tak kunjung diam, hari-hari kesengsaraan telah melanda diriku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 28, 'Dengan sedih, dengan tidak terhibur, aku berkeliaran; aku berdiri di tengah-tengah jemaah sambil berteriak minta tolong.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 29, 'Aku telah menjadi saudara bagi serigala, dan kawan bagi burung unta.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 30, 'Kulitku menjadi hitam dan mengelupas dari tubuhku, tulang-tulangku mengering karena demam;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 30, 31, 'permainan kecapiku menjadi ratapan, dan tiupan serulingku menyerupai suara orang menangis."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 1, '"Aku telah menetapkan syarat bagi mataku, masakan aku memperhatikan anak dara?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 2, 'Karena bagian apakah yang ditentukan Allah dari atas, milik pusaka apakah yang ditetapkan Yang Mahakuasa dari tempat yang tinggi?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 3, 'Bukankah kebinasaan bagi orang yang curang dan kemalangan bagi yang melakukan kejahatan?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 4, 'Bukankah Allah yang mengamat-amati jalanku dan menghitung segala langkahku?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 5, 'Jikalau aku bergaul dengan dusta, atau kakiku cepat melangkah ke tipu daya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 6, 'biarlah aku ditimbang di atas neraca yang teliti, maka Allah akan mengetahui, bahwa aku tidak bersalah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 7, 'Jikalau langkahku menyimpang dari jalan, dan hatiku menuruti pandangan mataku, dan noda melekat pada tanganku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 8, 'maka biarlah apa yang kutabur, dimakan orang lain, dan biarlah tercabut apa yang tumbuh bagiku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 9, 'Jikalau hatiku tertarik kepada perempuan, dan aku menghadang di pintu sesamaku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 10, 'maka biarlah isteriku menggiling bagi orang lain, dan biarlah orang-orang lain meniduri dia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 11, 'Karena hal itu adalah perbuatan mesum, bahkan kejahatan, yang patut dihukum oleh hakim.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 12, 'Sesungguhnya, itulah api yang memakan habis, dan menghanguskan seluruh hasilku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 13, 'Jikalau aku mengabaikan hak budakku laki-laki atau perempuan, ketika mereka beperkara dengan aku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 14, 'apakah dayaku, kalau Allah bangkit berdiri; kalau Ia mengadakan pengusutan, apakah jawabku kepada-Nya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 15, 'Bukankah Ia, yang membuat aku dalam kandungan, membuat orang itu juga? Bukankah satu juga yang membentuk kami dalam rahim?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 16, 'Jikalau aku pernah menolak keinginan orang-orang kecil, menyebabkan mata seorang janda menjadi pudar,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 17, 'atau memakan makananku seorang diri, sedang anak yatim tidak turut memakannya', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 18, '?malah sejak mudanya aku membesarkan dia seperti seorang ayah, dan sejak kandungan ibunya aku membimbing dia?;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 19, 'jikalau aku melihat orang mati karena tidak ada pakaian, atau orang miskin yang tidak mempunyai selimut,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 20, 'dan pinggangnya tidak meminta berkat bagiku, dan tidak dipanaskannya tubuhnya dengan kulit bulu dombaku;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 21, 'jikalau aku mengangkat tanganku melawan anak yatim, karena di pintu gerbang aku melihat ada yang membantu aku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 22, 'maka biarlah tulang belikatku lepas dari bahuku, dan lenganku dipatahkan dari persendiannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 23, 'Karena celaka yang dari pada Allah menakutkan aku, dan aku tidak berdaya terhadap keluhuran-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 24, 'Jikalau aku menaruh kepercayaan kepada emas, dan berkata kepada kencana: Engkaulah kepercayaanku;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 25, 'jikalau aku bersukacita, karena kekayaanku besar dan karena tanganku memperoleh harta benda yang berlimpah-limpah;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 26, 'jikalau aku pernah memandang matahari, ketika ia bersinar, dan bulan, yang beredar dengan indahnya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 27, 'sehingga diam-diam hatiku terpikat, dan menyampaikan kecupan tangan kepadanya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 28, 'maka hal itu juga menjadi kejahatan yang patut dihukum oleh hakim, karena Allah yang di atas telah kuingkari.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 29, 'Apakah aku bersukacita karena kecelakaan pembenciku, dan bersorak-sorai, bila ia ditimpa malapetaka', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 30, '?aku takkan membiarkan mulutku berbuat dosa, menuntut nyawanya dengan mengucapkan sumpah serapah! ?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 31, 'Jikalau orang-orang di kemahku mengatakan: Siapa yang tidak kenyang dengan lauknya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 32, '?malah orang asingpun tidak pernah bermalam di luar, pintuku kubuka bagi musafir! ?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 33, 'Jikalau aku menutupi pelanggaranku seperti manusia dengan menyembunyikan kesalahanku dalam hatiku,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 34, 'karena aku takuti khalayak ramai dan penghinaan kaum keluarga mengagetkan aku, sehingga aku berdiam diri dan tidak keluar dari pintu!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 35, 'Ah, sekiranya ada yang mendengarkan aku! ?Inilah tanda tanganku! Hendaklah Yang Mahakuasa menjawab aku! ?Sekiranya ada surat tuduhan yang ditulis lawanku!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 36, 'Sungguh, surat itu akan kupikul, dan akan kupakai bagaikan mahkota.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 37, 'Setiap langkahku akan kuberitahukan kepada-Nya, selaku pemuka aku akan menghadap Dia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 38, 'Jikalau ladangku berteriak karena aku dan alur bajaknya menangis bersama-sama,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 39, 'jikalau aku memakan habis hasilnya dengan tidak membayar, dan menyusahkan pemilik-pemiliknya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 31, 40, 'maka biarlah bukan gandum yang tumbuh, tetapi onak, dan bukan jelai, tetapi lalang." Sekianlah kata-kata Ayub.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 1, 'Maka ketiga orang itu menghentikan sanggahan mereka terhadap Ayub, karena ia menganggap dirinya benar.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 2, 'Lalu marahlah Elihu bin Barakheel, orang Bus, dari kaum Ram; ia marah terhadap Ayub, karena ia menganggap dirinya lebih benar dari pada Allah,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 3, 'dan ia juga marah terhadap ketiga orang sahabat itu, karena mereka mempersalahkan Ayub, meskipun tidak dapat memberikan sanggahan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 4, 'Elihu menangguhkan bicaranya dengan Ayub, karena mereka lebih tua dari pada dia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 5, 'Tetapi setelah dilihatnya, bahwa mulut ketiga orang itu tidak lagi memberi sanggahan, maka marahlah ia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 6, 'Lalu berbicaralah Elihu bin Barakheel, orang Bus itu: "Aku masih muda dan kamu sudah berumur tinggi; oleh sebab itu aku malu dan takut mengemukakan pendapatku kepadamu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 7, 'Pikirku: Biarlah yang sudah lanjut usianya berbicara, dan yang sudah banyak jumlah tahunnya memaparkan hikmat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 8, 'Tetapi roh yang di dalam manusia, dan nafas Yang Mahakuasa, itulah yang memberi kepadanya pengertian.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 9, 'Bukan orang yang lanjut umurnya yang mempunyai hikmat, bukan orang yang sudah tua yang mengerti keadilan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 10, 'Oleh sebab itu aku berkata: Dengarkanlah aku, akupun akan mengemukakan pendapatku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 11, 'Ketahuilah, aku telah menantikan kata-katamu, aku telah memperhatikan pemikiranmu, hingga kamu menemukan kata-kata yang tepat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 12, 'Kepadamulah kupusatkan perhatianku, tetapi sesungguhnya, tiada seorangpun yang mengecam Ayub, tiada seorangpun di antara kamu menyanggah perkataannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 13, 'Jangan berkata sekarang: Kami sudah mendapatkan hikmat; hanya Allah yang dapat mengalahkan dia, bukan manusia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 14, 'Perkataannya tidak tertuju kepadaku, dan aku tidak akan menjawabnya dengan perkataanmu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 15, 'Mereka bingung, mereka tidak dapat memberi sanggahan lagi, mereka tidak dapat berbicara lagi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 16, 'Haruskah aku menunggu, karena mereka putus bicara, karena mereka berdiri di sana dan tidak memberi sanggahan lagi?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 17, 'Akupun hendak memberi sanggahan pada giliranku, akupun akan mengemukakan pendapatku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 18, 'Karena aku tumpat dengan kata-kata, semangat yang ada dalam diriku mendesak aku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 19, 'Sesungguhnya, batinku seperti anggur yang tidak mendapat jalan hawa, seperti kirbat baru yang akan meletup.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 20, 'Aku harus berbicara, supaya merasa lega, aku harus membuka mulutku dan memberi sanggahan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 21, 'Aku tidak akan memihak kepada siapapun dan tidak akan menyanjung-nyanjung siapapun,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 32, 22, 'karena aku tidak tahu menyanjung-nyanjung; jika demikian, maka segera Pembuatku akan mencabut nyawaku."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 1, '"Akan tetapi sekarang, hai Ayub, dengarkanlah bicaraku, dan bukalah telingamu kepada segala perkataanku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 2, 'Ketahuilah, mulutku telah kubuka, lidahku di bawah langit-langitku berbicara.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 3, 'Perkataanku keluar dari hati yang jujur, dan bibirku menyatakan dengan terang apa yang diketahui.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 4, 'Roh Allah telah membuat aku, dan nafas Yang Mahakuasa membuat aku hidup.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 5, 'Jikalau engkau dapat, jawablah aku, bersiaplah engkau menghadapi aku, pertahankanlah dirimu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 6, 'Sesungguhnya, bagi Allah aku sama dengan engkau, akupun dibentuk dari tanah liat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 7, 'Jadi engkau tak usah ditimpa kegentaran terhadap aku, tekananku terhadap engkau tidak akan berat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 8, 'Tetapi engkau telah berbicara dekat telingaku, dan ucapan-ucapanmu telah kudengar:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 9, 'Aku bersih, aku tidak melakukan pelanggaran, aku suci, aku tidak ada kesalahan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 10, 'Tetapi Ia mendapat alasan terhadap aku, Ia menganggap aku sebagai musuh-Nya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 11, 'Ia memasukkan kakiku ke dalam pasung, Ia mengawasi segala jalanku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 12, 'Sesungguhnya, dalam hal itu engkau tidak benar, demikian sanggahanku kepadamu, karena Allah itu lebih dari pada manusia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 13, 'Mengapa engkau berbantah dengan Dia, bahwa Dia tidak menjawab segala perkataanmu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 14, 'Karena Allah berfirman dengan satu dua cara, tetapi orang tidak memperhatikannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 15, 'Dalam mimpi, dalam penglihatan waktu malam, bila orang nyenyak tidur, bila berbaring di atas tempat tidur,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 16, 'maka Ia membuka telinga manusia dan mengejutkan mereka dengan teguran-teguran', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 17, 'untuk menghalangi manusia dari pada perbuatannya, dan melenyapkan kesombongan orang,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 18, 'untuk menahan nyawanya dari pada liang kubur, dan hidupnya dari pada maut oleh lembing.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 19, 'Dengan penderitaan ia ditegur di tempat tidurnya, dan berkobar terus-menerus bentrokan dalam tulang-tulangnya;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 20, 'perutnya bosan makanan, hilang nafsunya untuk makanan yang lezat-lezat;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 21, 'susutlah dagingnya, sehingga tidak kelihatan lagi, tulang-tulangnya, yang mula-mula tidak tampak, menonjol ke luar,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 22, 'sampai nyawanya menghampiri liang kubur, dan hidupnya mendekati mereka yang membawa maut.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 23, 'Jikalau di sampingnya ada malaikat, penengah, satu di antara seribu, untuk menyatakan jalan yang benar kepada manusia,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 24, 'maka Ia akan mengasihaninya dengan berfirman: Lepaskan dia, supaya jangan ia turun ke liang kubur; uang tebusan telah Kuperoleh.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 25, 'Tubuhnya mengalami kesegaran seorang pemuda, ia seperti pada masa mudanya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 26, 'Ia berdoa kepada Allah, dan Allah berkenan menerimanya; ia akan memandang wajah-Nya dengan bersorak-sorai, dan Allah mengembalikan kebenaran kepada manusia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 27, 'Ia akan bernyanyi di depan orang: Aku telah berbuat dosa, dan yang lurus telah kubengkokkan, tetapi hal itu tidak dibalaskan kepadaku.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 28, 'Ia telah membebaskan nyawaku dari jalan ke liang kubur, dan hidupku akan melihat terang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 29, 'Sesungguhnya, semuanya ini dilakukan Allah dua, tiga kali terhadap manusia:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 30, 'mengembalikan nyawanya dari liang kubur, sehingga ia diterangi oleh cahaya hidup.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 31, 'Perhatikanlah, hai Ayub, dengarkanlah aku, diamlah, akulah yang berbicara.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 32, 'Jikalau ada yang hendak kaukatakan, jawablah aku; berkatalah, karena aku rela membenarkan engkau.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 33, 33, 'Jikalau tidak, hendaklah engkau mendengarkan aku; diamlah, aku hendak mengajarkan hikmat kepadamu."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 1, 'Maka berbicaralah Elihu:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 2, '"Dengarkanlah perkataanku, kamu orang-orang yang mempunyai hikmat, berilah telinga kepadaku, kamu orang-orang yang berakal budi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 3, 'Karena telinga itu menguji kata-kata, seperti langit-langit mencecap makanan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 4, 'Biarlah kita memutuskan bagi kita sendiri apa yang adil, menentukan bersama-sama apa yang baik.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 5, 'Karena Ayub berkata: Aku benar, tetapi Allah mengambil hakku;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 6, 'kendati aku mempunyai hak aku dianggap berdusta, sekalipun aku tidak melakukan pelanggaran, lukaku tidak dapat sembuh lagi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 7, 'Siapakah seperti Ayub, yang minum hujatan terhadap Allah seperti air,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 8, 'yang mencari persekutuan dengan orang-orang yang melakukan kejahatan dan bergaul dengan orang-orang fasik?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 9, 'Karena ia telah berkata: Tidak berguna bagi manusia, kalau ia dikenan Allah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 10, 'Oleh sebab itu, kamu orang-orang yang berakal budi, dengarkanlah aku: Jauhlah dari pada Allah untuk melakukan kefasikan, dan dari pada Yang Mahakuasa untuk berbuat curang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 11, 'Malah Ia mengganjar manusia sesuai perbuatannya, dan membuat setiap orang mengalami sesuai kelakuannya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 12, 'Sungguh, Allah tidak berlaku curang, Yang Mahakuasa tidak membengkokkan keadilan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 13, 'Siapa mempercayakan bumi kepada-Nya? Siapa membebankan alam semesta kepada-Nya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 14, 'Jikalau Ia menarik kembali Roh-Nya, dan mengembalikan nafas-Nya pada-Nya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 15, 'maka binasalah bersama-sama segala yang hidup, dan kembalilah manusia kepada debu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 16, 'Jikalau engkau berakal budi, dengarkanlah ini, pasanglah telinga kepada apa yang kuucapkan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 17, 'Dapatkah pembenci keadilan memegang kekuasaan, dan apakah engkau mau mempersalahkan Dia yang adil dan perkasa,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 18, 'Dia yang berfirman kepada raja: Hai, orang dursila, kepada para bangsawan: Hai, orang fasik;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 19, 'Dia yang tidak memihak kepada para pembesar, dan tidak mengutamakan orang yang terkemuka dari pada orang kecil, karena mereka sekalian adalah buatan tangan-Nya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 20, 'Dalam sekejap mata mereka mati, ya, pada tengah malam orang dikejutkan dan binasa; mereka yang perkasa dilenyapkan bukan oleh tangan orang.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 21, 'Karena mata-Nya mengawasi jalan manusia, dan Ia melihat segala langkahnya;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 22, 'tidak ada kegelapan ataupun kelam kabut, di mana orang-orang yang melakukan kejahatan dapat bersembunyi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 23, 'Karena bagi manusia Ia tidak menentukan waktu untuk datang menghadap Allah supaya diadili,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 24, 'orang-orang yang perkasa diremukkan-Nya dengan tidak diperiksa, dan orang-orang lain diangkat-Nya ganti mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 25, 'Jadi, Ia mengetahui perbuatan mereka, dan menggulingkan mereka di waktu malam, sehingga mereka hancur lebur.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 26, 'Mereka ditampar-Nya karena kefasikan mereka, dengan dilihat orang banyak,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 27, 'karena mereka meninggalkan-Nya, dan tidak mengindahkan satupun dari pada jalan-Nya,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 28, 'sehingga mereka menyebabkan jeritan orang miskin naik ke hadapan-Nya, dan Ia mendengar jeritan orang sengsara.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 29, '?Kalau Dia berdiam diri, siapa akan menjatuhkan hukuman? Kalau Dia menyembunyikan wajah-Nya, siapa akan melihat Dia, baik itu sesuatu bangsa atau orang seorang? ?,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 30, 'supaya jangan menjadi raja orang fasik yang adalah jerat bagi orang banyak.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 31, 'Tetapi kalau seseorang berkata kepada Allah: Aku telah menyombongkan diri, tetapi aku tidak akan lagi berbuat jahat;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 32, 'apa yang tidak kumengerti, ajarkanlah kepadaku; jikalau aku telah berbuat curang, maka aku tidak akan berbuat lagi,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 33, 'menurut hematmu apakah Allah harus melakukan pembalasan karena engkau yang menolak? Jadi, engkau jugalah yang harus memutuskan, bukan aku; katakanlah apa yang engkau tahu!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 34, 'Maka orang-orang yang berakal budi dan orang yang mempunyai hikmat yang mendengarkan aku akan berkata kepadaku:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 35, 'Ayub berbicara tanpa pengetahuan, dan perkataannya tidak mengandung pengertian.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 36, 'Ah, kiranya Ayub diuji terus-menerus, karena ia menjawab seperti orang-orang jahat!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 34, 37, 'Karena ia menambahkan dosanya dengan pelanggaran, ia mengepalkan tangan di antara kami dan banyak bicara terhadap Allah."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 1, 'Maka berbicaralah Elihu:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 2, '"Inikah yang kauanggap adil dan yang kausebut: kebenaranku di hadapan Allah,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 3, 'kalau engkau bertanya: Apakah gunanya bagiku? Apakah kelebihanku bila aku berbuat dosa?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 4, 'Akulah yang akan memberi jawab kepadamu dan kepada sahabat-sahabatmu bersama-sama dengan engkau:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 5, 'Arahkan pandanganmu ke langit dan lihatlah, perhatikanlah awan-awan yang lebih tinggi dari padamu!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 6, 'Jikalau engkau berbuat dosa, apa yang akan kaulakukan terhadap Dia? Kalau pelanggaranmu banyak, apa yang kaubuat terhadap Dia?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 7, 'Jikalau engkau benar, apakah yang kauberikan kepada Dia? Atau apakah yang diterima-Nya dari tanganmu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 8, 'Hanya orang seperti engkau yang dirugikan oleh kefasikanmu dan hanya anak manusia yang diuntungkan oleh kebenaranmu.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 9, 'Orang menjerit oleh karena banyaknya penindasan, berteriak minta tolong oleh karena kekerasan orang-orang yang berkuasa;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 10, 'tetapi orang tidak bertanya: Di mana Allah, yang membuat aku, dan yang memberi nyanyian pujian di waktu malam;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 11, 'yang memberi kita akal budi melebihi binatang di bumi, dan hikmat melebihi burung di udara?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 12, 'Ketika itu orang menjerit, tetapi Ia tidak menjawab, oleh karena kecongkakan orang-orang jahat.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 13, 'Sungguh, teriakan yang kosong tidak didengar Allah dan tidak dihiraukan oleh Yang Mahakuasa.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 14, 'Lebih-lebih lagi kalau engkau berkata, bahwa engkau tidak melihat Dia, bahwa perkaramu sudah diadukan kehadapan-Nya, tetapi masih juga engkau menanti-nantikan Dia!', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 15, 'Tetapi sekarang: karena murka-Nya tidak menghukum dan Ia tidak terlalu mempedulikan pelanggaran,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 35, 16, 'maka Ayub berbesar mulut dengan sia-sia, banyak bicara tanpa pengertian."', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 1, 'Berkatalah Elihu selanjutnya:', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 2, '"Bersabarlah sebentar, aku akan mengajar engkau, karena masih ada yang hendak kukatakan demi Allah.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 3, 'Aku akan meraih pengetahuanku dari jauh dan membenarkan Pembuatku;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 4, 'karena sungguh-sungguh, bukan dusta perkataanku, seorang yang sempurna pengetahuannya menghadapi engkau.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 5, 'Ketahuilah, Allah itu perkasa, namun tidak memandang hina apapun, Ia perkasa dalam kekuatan akal budi.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 6, 'Ia tidak membiarkan orang fasik hidup, tetapi memberi keadilan kepada orang-orang sengsara;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 7, 'Ia tidak mengalihkan pandangan mata-Nya dari orang benar, tetapi menempatkan mereka untuk selama-lamanya di samping raja-raja di atas takhta, sehingga mereka tinggi martabatnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 8, 'Jikalau mereka dibelenggu dengan rantai, tertangkap dalam tali kesengsaraan,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 9, 'maka Ia memperingatkan mereka kepada perbuatan mereka, dan kepada pelanggaran mereka, karena mereka berlaku congkak,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 10, 'dan ia membukakan telinga mereka bagi ajaran, dan menyuruh mereka berbalik dari kejahatan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 11, 'Jikalau mereka mendengar dan takluk, maka mereka hidup mujur sampai akhir hari-hari mereka dan senang sampai akhir tahun-tahun mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 12, 'Tetapi, jikalau mereka tidak mendengar, maka mereka akan mati oleh lembing, dan binasa dalam kebebalan.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 13, 'Orang-orang yang fasik hatinya menyimpan kemarahan; mereka tidak berteriak minta tolong, kalau mereka dibelenggu-Nya;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 14, 'nyawa mereka binasa di masa muda, dan hidup mereka berakhir sebelum saatnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 15, 'Dengan sengsara Ia menyelamatkan orang sengsara, dengan penindasan Ia membuka telinga mereka.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 16, 'Juga engkau dibujuk-Nya keluar dari dalam kesesakan, ke tempat yang luas, bebas dari tekanan, ke meja hidanganmu yang tenang dan penuh lemak.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 17, 'Tetapi engkau sudah mendapat hukuman orang fasik sepenuhnya, engkau dicengkeram hukuman dan keadilan;', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 18, 'janganlah panas hati membujuk engkau berolok-olok, janganlah besarnya tebusan menyesatkan engkau.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 19, 'Dapatkah teriakanmu meluputkan engkau dari kesesakan, ataukah seluruh kekuatan jerih payahmu?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 20, 'Janganlah merindukan malam hari, waktu bangsa-bangsa pergi dari tempatnya.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 21, 'Jagalah dirimu, janganlah berpaling kepada kejahatan, karena itulah sebabnya engkau dicobai oleh sengsara.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 22, 'Sesungguhnya, Allah itu mulia di dalam kekuasaan-Nya; siapakah guru seperti Dia?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 23, 'Siapakah akan menentukan jalan bagi-Nya, dan siapa berani berkata: Engkau telah berbuat curang?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 24, 'Ingatlah, bahwa engkau harus menjunjung tinggi perbuatan-Nya, yang selalu dinyanyikan oleh manusia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 25, 'Semua orang melihatnya, manusia memandangnya dari jauh.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 26, 'Sesungguhnya, Allah itu besar, tidak tercapai oleh pengetahuan kita, jumlah tahun-Nya tidak dapat diselidiki.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 27, 'Ia menarik ke atas titik-titik air, dan memekatkan kabut menjadi hujan,', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 28, 'yang dicurahkan oleh mendung, dan disiramkan ke atas banyak manusia.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 29, 'Siapa mengerti berkembangnya awan, dan bunyi gemuruh di tempat kediaman-Nya?', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 30, 'Sesungguhnya, Ia mengembangkan terang-Nya di sekeliling-Nya, dan menudungi dasar laut.', 'id', 'TB'),
  ('18', 'ayb', 'Ayub', 36, 31, 'Karena dengan semuanya itu Ia mengadili bangsa-bangsa, dan juga memberi makan dengan berlimpah-limpah.', 'id', 'TB')
